\title{Transmutation of $^{16}$O and $^{20}$Ne at the Large Hadron Collider}



\author{Govert Nijs}
\affiliation{Theoretical Physics Department, CERN, CH-1211 Gen\`eve 23, Switzerland}

\author{Wilke van der Schee}
