The hidden extensions on the $E_\infty$-page can be resolved using complex Betti realization. Recall from \cref{2.1} that this is a functor $\text{Be}^\mathbb{C}:\text{SH}(\mathbb{C}) \to \text{Sp}$. For $X \in \text{SH}(\mathbb{C})$, this gives a map in homotopy
\[\pi_{s,w}^\mathbb{C}X \to \pi_s\text{Be}^\mathbb{C}X.\]
In particular, there is a map of dual Steenrod algebras $\euscr{A}^\vee_\mathbb{C} \to \euscr{A}^\vee$ sending $\bar{\xi}_i \mapsto \bar{\xi}_i^2$ and $\bar{\tau}_i \mapsto \bar{\xi}_i$. Additionally, there is an isomorphism of $\euscr{A}(1)_\mathbb{C}^\vee$-comodules
\[(B_0^\mathbb{C}(1))[\tau^{-1}] \cong B_0(1)[\tau^{\pm 1}],\]
where $B_0(1)$ is the classical Brown--Gitler comodule.
This induces a map of Ext groups
\[\text{Ext}^{s,f,w}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(k)) \to \text{Ext}_{\euscr{A}(1)^\vee}^{s,f}(B_0(k)),\]
and allows one to lift hidden extensions from the classical case in \cite{Mah81} to the $\mathbb{C}$-motivic case. 

The following is a motivic analogue of a classical result.
\begin{corollary}
\label{C-ksp}\cite[Corollary 3.31]{CQ21}
    There is an isomorphism:
    \[\textup{Ext}_{\euscr{A}(1)_\mathbb{C}^\vee}(\mathbb{M}_2^\C, B_0^\C(1)) \cong \pi^\C_{**}(\textup{ksp}).\]
\end{corollary}

\begin{proof}
     By \cref{ksp hz1}, there is an equivalence of motivic spectra
     \[\textup{ksp} \cong \textup{H}\mathbb{Z}^\mathbb{C}_1 \otimes \textup{kq},\]
     where $\textup{H}\mathbb{Z}_1^\mathbb{C}$ is the motivic spectrum constructed in \cref{motivic bg}. The K\"unneth spectral sequence for mod-2 homology collapses for $\textup{H}\mathbb{Z}_1^\mathbb{C} \otimes \textup{kq}$, giving an isomorphism
     \[\textup{H}_{**}(\text{ksp}) \cong B_0^\mathbb{C}(1) \otimes_{\mathbb{M}_2^\mathbb{C}}(\euscr{A} \modmod \euscr{A}(1))_\mathbb{C}^\vee.\]
     After a change of rings isomorphism, the $E_2$-page for the $\textbf{mASS}(\text{ksp})$ takes the form
     \[E_2 = \text{Ext}_{\euscr{A}(1)_\mathbb{C}^\vee}(B_0^\mathbb{C}(1)) \implies\pi_{**}^\mathbb{C}(\text{ksp}).\]
     This Ext group was computed by the $\textbf{aAHSS}(B_0^\mathbb{C}(1))$ and is depicted in \cref{aAHSS(B_0^C(1)) E_3=E_infty}. There are no differentials for degree reasons, so the spectral sequence collapses and gives the result.
\end{proof}
% \begin{remark}
%     Although the proof given in \cite{CQ21} implicitly uses the very effective slice results of Bachmann \cite{Bachmann-generalized}, our proof gives more detail and uses the more general result proven in \cref{ksp hz1}.
% \end{remark}
Classically, one can express the groups $\text{Ext}_{\euscr{A}(1)^\vee}(B_0(1)^{\otimes i})$ in terms of Adams covers of bo and bsp. This does not translate well to motivic homotopy theory. Over $\mathbb{C}$, Culver--Quigley \cite{CQ21} show that one cannot express the groups $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(1)^{\otimes i})$ in terms of Adams covers of kq and ksp. We show a similar result over $\mathbb{R}$ in \cref{R-aAHSS section}. Instead, there is a periodic family of groups which will determine $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(1))$ composed of Adams covers of bo, bsp, kq and ksp.

In what follows, we will use the notation defined in \cref{notation section}. For $i \geq 0$, let $Z_i^\mathbb{C}$ be the trigraded group defined as follows:
\begin{itemize}
    \item When $i \equiv 0 \, (4)$, let
    \[Z^\mathbb{C}_i = \bigoplus_{j=0}^{i/2-1}\Sigma^{4j, 2j}\mathbb{M}_2^\C[h_0] \oplus \Sigma^{2i, i}\text{Ext}_{\euscr{A}(1)_\C^\vee}(\mathbb{M}_2^\C)\]
    \item When $i \equiv 1 \, (4)$, let
    \[Z^\mathbb{C}_i = \bigoplus_{j=0}^{(i-1)/2-1}\Sigma^{4j, 2j}\mathbb{M}_2^\C[h_0] \oplus \Sigma^{2i-1, i-1}\text{Ext}_{\euscr{A}(1)_\C^\vee}(B_0^\C(1));\]
    \item When $i \equiv 2 \, (4)$, let
    \[Z^\mathbb{C}_i = \bigoplus_{j=0}^{i/2-1}\Sigma^{4j, 2j}\mathbb{M}_2^\C[h_0]  \oplus\Sigma^{2i-2, i}\mathbb{M}_2^\C \oplus \Sigma^{2i, i}\text{Ext}_{\euscr{A}(1)_\C^\vee}(B_0^\C(1))\langle 1\rangle;\]
    \item When $i \equiv 3 \, (4)$, let
    \[Z^\mathbb{C}_i = \bigoplus_{j=0}^{(i-1)/2}\Sigma^{4j, 2j}\mathbb{M}_2^\C[h_0] \oplus \Sigma^{2i-1, i}\mathbb{M}_2^\C[h_1]/(h_1^2) \oplus \Sigma^{2i+2, i+1}\text{Ext}^{***}_{\euscr{A}(1)_\C^\vee}( B_0^\C(1))\langle 2\rangle.\]
\end{itemize}

Recall that we are only interested in information up to $v_1$-torsion (see \cref{v1 torsion}).
\begin{proposition}\cite[Lemma 3.36]{CQ21}
\label{C-b0(1)^i}
    There is an isomorphism of $\euscr{A}(1)^\vee_\mathbb{C}$-comodules and $\textup{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(\mathbb{M}_2^\mathbb{C})$-modules:
    \[\frac{\textup{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(1)^{\otimes i})}{v_1\textup{-torsion}} \cong Z_i^\mathbb{C}.\]
\end{proposition}

\begin{proof}
    By applying the functor $\text{Ext}_{\euscr{A}^\vee_\mathbb{C}}\left(B_0^\mathbb{C}(1)^{\otimes i} \otimes_{\mathbb{M}_2^\mathbb{C}} -\right)$ to the cellular filtration of $B_0^\mathbb{C}(1)$, we may inductively compute these Ext groups by an \textbf{aAHSS}, where the base case was computed in \cref{C-ksp}. This spectral sequence takes the form
    \[E_1=\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(1)^{\otimes i}) \otimes_{\mathbb{M}_2^\mathbb{C}}\mathbb{M}_2^\mathbb{C}\{1, \bar{\xi}_1, \bar{\tau}_1\} \implies\text{Ext}_{\euscr{A}(1)_\mathbb{C}^\vee}(B_0^\mathbb{C}(1)^{\otimes i+1}).\]
    The differentials take the same form as those in $\textbf{aAHSS}(B_0^\mathbb{C}(1))$, namely we have $d_1(\alpha[3])=h_0\alpha[2]$ and $d_2(\alpha[2]) = h_1\alpha[0]$, where $\alpha \in \text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(1)^{\otimes i})$. For degree reasons, there is no $d_3$-differential. Hidden extensions may be obtained by comparison with the classical case, using the algebra map
    \[\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(1)^{\otimes i}) \to \text{Ext}_{\euscr{A}(1)^\vee}(B_0(1)^{\otimes i}).\]
    This resolves all hidden extensions and concludes the proof.
\end{proof}


\subsection{$\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(k))$ and the ring of cooperations}
Next, we compute $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(k))$ for all $k \geq 1$. 

\begin{thm}\cite[Theorem 3.38]{CQ21}
\label{C-b0(k) ext}
    There is an isomorphism of $\euscr{A}(1)^\vee_\mathbb{C}$-comodules and $\textup{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(\mathbb{M}_2^\mathbb{C})$-modules:
    \[\frac{\textup{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(k))}{v_1\textup{-torsion}} \cong \Sigma^{4k-4, 2k-2}Z^\mathbb{C}_{\alpha(k)} \oplus \bigoplus_{j=0}^{4k-8}\Sigma^{4j, 2j}\mathbb{M}_2^\mathbb{C}[h_0],\]
    where $\alpha(k)$ is the number of 1's in the dyadic expansion of $k$.
\end{thm}

\begin{proof}
    For notational convenience, all Ext groups in this proof will be implicitly computed modulo $v_1$-torsion. We will induce on $k$. The case of $k=1$ was shown in \cref{C-ksp}. Now, suppose the theorem is true for all $i<k$.

    Suppose that $k$ is even. \cref{ses bg} gives a short exact sequence of $\euscr{A}(1)_\mathbb{C}^\vee$-comodules
    \begin{align}
    \label{ses bg C even}
    0 \to \Sigma^{2k, k}B_0^\mathbb{C}(\tfrac{k}{2}) \to B_0^\mathbb{C}(k) \to B_1^\mathbb{C}(\tfrac{k}{2} -1) \otimes_{\mathbb{M}_2^\mathbb{C}} (\euscr{A}(1) \modmod \euscr{A}(0))_\mathbb{C}^\vee \to 0.
    \end{align} 
    Applying the functor $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(-)$ gives a long exact sequence of $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(\mathbb{M}_2^\mathbb{C})$-modules. Moreover, after killing $v_1$-torsion the connecting homomorphism is trivial, giving short exact sequences whose middle term is $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(k))$. Therefore, this Ext group decomposes into the Ext groups of the kernel and cokernel of the original short exact sequence (\ref{ses bg C even}). The kernel is handled by the inductive hypothesis: we have
    \[\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(\Sigma^{2k, k}B_0^\mathbb{C}(\tfrac{k}{2})) \cong \Sigma^{2k, k}\left(\Sigma^{2k-4, k-2}Z_{\mathbb{\alpha}(k/2)}^\mathbb{C} \oplus \bigoplus_{j=0}^{2k-8}\Sigma^{4j, 2j}\mathbb{M}_2^\mathbb{C}[h_0]\right) .\]
    We can use a change of rings isomorphism to rewrite the cokernel as
    \[\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}\left(B_1^\mathbb{C}(\tfrac{k}{2}-1) \otimes_{\mathbb{M}_2^\mathbb{C}}(\euscr{A}(1) \modmod \euscr{A}(0))_\mathbb{C}^\vee\right) \cong \text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}(B_1^\mathbb{C}(\tfrac{k}{2}-1)).\]
    Since $\euscr{A}(0)^\vee_\mathbb{C}\cong \mathbb{M}_2^\mathbb{C}[\bar{\tau}_0]/(\bar{\tau}_0^2)$ is exterior, the Ext groups in question are polynomial. Modulo $v_1$-torsion, we are only left with $h_0$-towers:
    \[\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}(B_1^\mathbb{C}(\tfrac{k}{2}-1)) \cong \bigoplus_{j=0}^{k/2-1}\Sigma^{4j, 2j}\mathbb{M}_2^\mathbb{C}[h_0].\]
    Putting these pieces together with some reindexing on the $h_0$-towers and using the fact that $\alpha(k/2)=\alpha(k)$ gives the result.

    Suppose now that $k$ is odd. Again, \cref{ses bg} gives a short exact sequence of $\euscr{A}(1)^\vee_\mathbb{C}$-comodules
    \begin{align}
    \label{ses BG C odd}
    0 \to \Sigma^{2(k-1), k-1}B_0^\mathbb{C}(\tfrac{k-1}{2}) \otimes_{\mathbb{M}_2^\mathbb{C}} B_0^\mathbb{C}(1) \to B_0^\mathbb{C}(k) \to B_1^\mathbb{C}(\tfrac{k-1}{2}-1) \otimes_{\mathbb{M}_2^\mathbb{C}} (\euscr{A}(1) \modmod \euscr{A}(0))_\mathbb{C}^\vee \to 0.
    \end{align}
    Applying the functor $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(-)$ gives a long exact sequence of $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(\mathbb{M}_2^\mathbb{C})$-modules, and as in the even case, the connecting homomorphism is trivial modulo $v_1$-torsion. Thus, the Ext group we are interested in decomposes into the Ext groups of the kernel and cokernel of \ref{ses BG C odd}. In this case, the cokernel is simpler to compute. A change of rings isomorphism gives
    \[\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}\left(B_1^\mathbb{C}(\tfrac{k-1}{2}-1) \otimes_{\mathbb{M}_2^\mathbb{C}}(\euscr{A}(1) \modmod \euscr{A}(0))_\mathbb{C}^\vee\right) \cong \text{Ext}_{\euscr{A}(0)_\mathbb{C}^\vee}(B_1^\mathbb{C}(\tfrac{k-1}{2}-1)).\]
    By the same argument as before, modulo $v_1$-torsion this Ext group consists of purely $h_0$-towers:
    \[\text{Ext}_{\euscr{A}(0)_\mathbb{C}^\vee}(B_1^\mathbb{C}(\tfrac{k-1}{2}-1)) \cong \bigoplus_{j = 0}^{(k-1)/2-1}\Sigma^{4j, 2j}\mathbb{M}_2^\mathbb{C}[h_0].\]
    The Ext group of the kernel may be computed using an algebraic Atiyah--Hirzebruch spectral sequence $\textbf{aAHSS}\left(B_0^\mathbb{C}(\tfrac{k-1}{2}) \otimes_{\mathbb{M}_2^\mathbb{C}} B_0^\mathbb{C}(1)\right)$. This has signature
    \[E_1=\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(\tfrac{k-1}{2})) \otimes_{\mathbb{M}_2^\mathbb{C}} \mathbb{M}_2^\mathbb{C}\{1, \bar{\xi}_1, \bar{\tau}_1\} \implies \text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}\left(B_0^\mathbb{C}(\tfrac{k-1}{2}) \otimes_{\mathbb{M}_2^\mathbb{C}}B_0^\mathbb{C}(1)\right).\]
    By induction, we may rewrite $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(\tfrac{k-1}{2}))$ as
    \[\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(\tfrac{k-1}{2})) \cong \Sigma^{2k-6, k-3}Z_{\alpha(k)-1}^\mathbb{C} \oplus \bigoplus_{j=0}^{2k-10}\Sigma^{4j, 2j}\mathbb{M}_2^\mathbb{C}[h_0],\]
    using that $\alpha(\tfrac{k-1}{2}) = \alpha(k)-1.$
    This splitting leads to a splitting of the $E_1$-page of the algebraic Atiyah--Hirzebruch spectral sequence, and we may analyze each summand individually. On the left-hand summand, \cref{C-b0(1)^i} implies that result of the spectral sequence is isomorphic to $\Sigma^{2k-2, k-1}Z^\mathbb{C}_{\alpha(k)}$. On the right-hand summand, the spectral sequence collapses on the $E_1$-page, giving back the original summand modulo $v_1$-torsion. Thus, after reindexing the $h_0$-towers, the Ext groups of the kernel and cokernel and right-hand side of the Ext groups assemble to give the result. 

    % \textcolor{blue}{
    % The proof now breaks into cases depending on the value of $k-1-\alpha((k-1)/2)$ modulo 4. In each case, one uses the inductive hypothesis to rewrite the group $Z_{k-1  \alpha((k-1)/2)}^\mathbb{C}$ into its prescribed summands. This splitting leads to a splitting on the $E_1$-page of the $\textbf{aAHSS}(B_0^\mathbb{C}(\tfrac{k-1}{2}) \otimes_{\mathbb{M}_2^\mathbb{C}} B_0^\mathbb{C}(1))$. On any summand consisting of $h_0$-towers, we have that $E_1=E_\infty$ as we are working modulo $v_1$-torsion. This is also the case for any $\mathbb{M}_2^\mathbb{C}$ and any $\mathbb{M}^{\mathbb{C}}_2[h_1]/(h_1)^2$ appearing in congruence classes 2 and 3, respectively. \cref{C-ksp} gives the result on any summand which is a shift of $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(\mathbb{M}_2^\mathbb{C})$. The only hidden extensions appear in congruence classes $2$ and $3$, connecting the $\mathbb{M}_2^\mathbb{C}$ and $\mathbb{M}_2^\mathbb{C}[h_1]/(h_1^2)$ to an $h_0$-tower, and are recovered by comparing with the classical case. The result follows from assembling these pieces and rewriting some of the dyadic indexing, for example by using the identity $\alpha(\tfrac{n-1}{2}) = \alpha(n)-1$.}
\end{proof}

\begin{remark}
    The above proof is where our argument differs most from the one given in \cite{CQ21}. We explain these differences here. Classically, Mahowald \cite{Mah81} showed that the groups $\text{Ext}_{\euscr{A}(1)^\vee}(B_0(k))$ can be expressed solely in terms of bo and bsp. To be precise, for a spectrum $X$, let $X^{\langle n \rangle}$ denote the $n$-th Adams cover of $X$, so that
    \[X \leftarrow X^{\langle 1 \rangle} \leftarrow X^{\langle 2 \rangle} \leftarrow X^{\langle 3 \rangle} \leftarrow \cdots\]
    is a minimal Adams resolution of $X$. Then there are isomorphisms:
    \[\frac{\text{Ext}_{\euscr{A}(1)^\vee}(B_0(k))}{v_1\text{-torsion}} \cong \left\{\begin{array}{ll}
        \text{Ext}_{\euscr{A}(1)^\vee}(\text{H}_{**}(\text{bo}^{\langle 2k - \alpha(k) \rangle})) &  k \equiv 0 \, (2),\\
        \text{Ext}_{\euscr{A}(1)^\vee}(\text{H}_{**}(\text{bsp}^{\langle 2k -\alpha(k)-1 \rangle})) & k \equiv 1 \, (2).
    \end{array} \right.
    \]
    One thing to note is that in the classical case, each of the above groups is describable by a direct sum of $h_0$-towers followed by some shift of $\text{Ext}_{\euscr{A}(1)^\vee}(\mathbb{F}_2)$. In particular, if $x \in \text{Ext}^{s,f}_{\euscr{A}(1)^\vee}(B_0(k))$ is in stem $s < 4(2k - \alpha(k))$, then $x$ does not support $h_1$-multiplication.

    The results of Culver--Quigley assert that over $\mathbb{C}$ there is an isomorphism
    \[\frac{\textup{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(k))}{v_1\text{-torsion}} \cong Z^\mathbb{C}_{2k-\alpha(k)}.\]
    However, this is not quite correct. The group $Z_{2k - \alpha(k)}^\mathbb{C}$ has classes in small stems which support $h_1$-multiplication, while the decomposition given by the short exact sequences of \cref{ses bg} do not allow for this. For example, for $k=2$ we have $2k-\alpha(k)=4-1=3$, hence Culver--Quigley claim that $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(2))$ is isomorphic to
    \[Z_3^\mathbb{C} = \mathbb{M}_2^\mathbb{C}[h_0] \oplus\Sigma^{4, 2}\mathbb{M}_2^\mathbb{C}[h_0] \oplus \Sigma^{5, 3}\mathbb{M}_2^\mathbb{C}[h_1]/(h_1^2) \oplus \Sigma^{8, 4}\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(1))\langle 2 \rangle.\]
    We see that there is a class in stem 5 which supports an $h_1$-multiplication. Alternatively, using the short exact sequence of \cref{ses bg} we see that the group $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(2))$ is isomorphic to following the direct sum:
    \[\Sigma^{8, 4}\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(1)) \oplus \text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}(B_1^\mathbb{C}(0)) \cong \Sigma^{8,4}Z_1^\mathbb{C} \oplus \mathbb{M}_2^\mathbb{C}[h_0],\]
    which agrees with the description in \cref{C-b0(1)^i}.
    This decomposition does not admit any $h_1$-multiplication in stem 5; in fact, there are no classes in stem 5. This type of difference extends to all values of $k \geq 2$, showing that the formula given in \cite[Theorem3.38]{CQ21} is incorrect.
    However, this observation is actually in line with the rest of the work done in Culver--Quigley and doesn't affect any end results. More precisely:
    \begin{enumerate}
        \item[(1)] It was shown in \cite[Lemma 3.38]{CQ21} that the groups $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(1)^{\otimes i})$ are not expressible in terms of Adams covers of kq and ksp. The purpose of the groups $Z_i^\mathbb{C}$ is exactly to account for this failure, mixing in an appropriate trigraded version of $\text{Ext}_{\euscr{A}(1)^\vee}(\text{H}_{**}(\text{bo}^{\langle i \rangle}))$ and $\text{Ext}_{\euscr{A}(1)^\vee}(\text{H}_{**}(\text{bsp}^{\langle i \rangle})).$ The difference being observed in the computation of $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{C}}(B_0^\mathbb{C}(k))$ can be accounted for by noting that this group \textit{also} cannot be expressed using just $Z_{2k-\alpha(k)}^\mathbb{C}$. Rather, we must express these groups using shifts of $Z_{\alpha(k)}^\mathbb{C}$ and an appropriate trigraded version of the $h_0$-towers found in the classical groups $\text{Ext}_{\euscr{A}(1)^\vee}(\mathbb{F}_2)$; this last term is precisely what is given by $\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}(B_1^\mathbb{C}(\tfrac{k-1}{2}))$ in the case that $k \equiv 0 \, (2),$ and by $\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}(B_1^\mathbb{C}(\tfrac{k-1}{2}-1))$ in the case that $k \equiv 1 \, (2).$
        \item[(2)] Apart from this discrepancy, the contents of \cite{CQ21} are unaffected. In particular, we will see that the $\textbf{mASS}(\text{kq} \otimes \text{kq})$ collapses on the $E_2$-page by using the same arguments as employed by Culver--Quigley.
    \end{enumerate}
\end{remark}

The following is now immediate from \cref{e2 mass}.
\begin{proposition}
    \cite[Proposition 3.41]{CQ21} The $E_2$-page of the $\textup{\textbf{mASS}}(\textup{kq} \otimes \textup{kq})$ is given, modulo $v_1$-torsion, by
    \[E_2 =\bigoplus_{k \geq 0}\textup{Ext}^{s,f,w}_{\euscr{A}(1)_\mathbb{C}^\vee}(\Sigma^{4k, 2k}B_0^\mathbb{C}(k)) \cong\bigoplus_{k \geq 0} \left(\Sigma^{4k, 2i}Z^\mathbb{C}_{\alpha(k)} \oplus \bigoplus_{j=0}^{4k-8}\Sigma^{4j, 2j}\mathbb{M}_2^\mathbb{C}[h_0]\right).\]
\end{proposition}

Recall from \cite[Theorem 2.9]{Mah81} that the \textbf{ASS}$(\text{bo} \otimes \text{bo})$ collapses on $E_2$.
\begin{thm}\cite[Cor 3.43]{CQ21}
\label{C-coop mass collapse}
    The \textup{\textbf{mASS}}$(\textup{kq} \otimes \textup{kq})$ collapses on the $E_2$-page.
\end{thm}

\begin{proof}
    Betti realization sends the \textbf{mASS}($\textup{kq} \otimes \textup{kq})$ to the \textbf{ASS}($\text{bo} \otimes \text{bo}$). At the level of $E_2$-pages, this is a map 
    \[\text{Ext}^{s,f,w}_{\euscr{A}(1)^\vee_\mathbb{C}}(\textup{H}_{**}(\textup{kq} \otimes \textup{kq})) \to \text{Ext}_{\euscr{A}(1)^\vee}^{s,f}(\text{H}_*(\text{bo} \otimes \text{bo})),\]
    obtained by inverting $\tau$ on the $E_2$-page of the \textbf{mASS}($\textup{kq} \otimes \textup{kq}$) and setting $\tau=1$. Since the $\textbf{ASS}(\text{bo} \otimes \text{bo})$ collapses on $E_2$, we must have that there are no motivic differentials where both source and target are $\tau$-torsion free. However, our description of the $E_2$-page of the $\textbf{mASS}(\textup{kq} \otimes \textup{kq})$ shows that any $\tau$-torsion class must be $h_1$-torsion free, hence is some $h_1$-tower. For degree reasons, there can be no such differentials between these towers, concluding the proof.
\end{proof}

