\subsection{Some modules over $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$}
We now introduce notation for some modules over $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$ which will appear throughout. The reader is encouraged to consult \cref{charts} to follow along with these definitions.
\begin{definition}
\label{module defs}
    Define the following $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-modules:
    \begin{itemize}
        \item Let $\euscr{D}$ denote the entire coweight $cw \equiv 1 \, (4)$ piece of $\text{Ext}_{\euscr{A}(1)_\mathbb{R}^\vee}
        (\mathbb{M}_2^\mathbb{R})$, called a \textit{big diamond} (see \cref{R-Ext(M_2) cw=1});

        \item Let $\euscr{S}$ denote the entire coweight $cw \equiv 2 \, (4)$ piece of $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$, called a \textit{big staircase} (see \cref{R-Ext(M_2) cw=2});

        \item Let $P = \mathbb{F}_2[\tau^4][\rho]$, called a \textit{$\rho$-tower}, with the obvious $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-module structure (see \cref{rho tower picture}); 

        \item Let $H = \mathbb{F}_2[\tau^4][h_0]$, called an \textit{$h_0$-tower}, with the obvious $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-module structure (see \cref{h0 tower picture});

        \item Let $PH = \mathbb{F}_2[\tau^4][\rho ,h_0]/(\rho h_0)$, called a \textit{$(\rho, h_0)$-tower}, with the obvious $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-module structure (see \cref{rho h0 tower picture});

        % \item Let $E = \mathbb{F}_2[\tau^4][h_1]$, called an \textit{$h_1$-tower}
        \item Let $D = \mathbb{F}_2[\tau^4][\rho, h_0, h_1]/(\rho^2, h_0^2, h_1^2, \rho h_0, h_0 h_1,\rho h_1 = h_0 )$, 
        called a \textit{diamond}, with the obvious $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-module structure (see \cref{diamond picture});

        \item Let $S=\mathbb{F}_2[\tau^4][h_0, h_1, t,a]/(h_1^3, t^2, a^2, h_0h_1, h_1a, ta, h_0^2t, h_1^2t$), called a \textit{staircase},  with the $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-module structure given by the relations (see \cref{staircase picture})
        \[\rho \cdot t = h_1, \quad h_1 \cdot t = \rho \cdot a,\quad h_0 \cdot t = h_1^2 = \rho^2 \cdot a, \quad\rho^2 \cdot t = 0, \quad \rho^3  \cdot a = 0;\]

        \item Let $T = \mathbb{F}_2[\tau^4][\rho]/(\rho^2),$ called a \textit{segment}, with the obvious $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-module structure (see \cref{segment picture});

        \item Let $J = \mathbb{F}_2[\tau^4][\rho ,h_0]/(\rho^3, \rho h_0)$, called a \textit{J-tower}, with the obvious $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-module structure (see \cref{J-tower picture});

        \item Let $JD = \mathbb{F}_2[\tau^4][\rho, h_0,t]/(\rho^3, t^2, \rho^2 t, \rho h_0,  h_0^2 t)$, called a \textit{$JD$-tower}, with the $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-module structure given by the relations (see \cref{JD-tower picture})
        \[\rho = h_1 t, \quad h_1 \cdot \rho t = h_0 t = \rho^2.\]
        \end{itemize}
\end{definition}

\begin{remark}
    As should be indicated by the figures in \cref{charts}, the naming of these modules is derived from their general shapes when depicted in charts.
\end{remark}

We construct now a more intricate family of modules. This module will track the behavior of the coweight $cw \equiv 0\, (4)$ piece of $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R}, \mathbb{M}_2^\mathbb{R})$ throughout the process of the coming spectral sequences.

