\section{The ring of cooperations}
\label{section-Rcoop}
In this section, we continue the inductive procedure and compute the groups $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(k))$. Then, we assemble our results to compute the ring of cooperations $\pi_{**}^\mathbb{R}(\text{kq} \otimes \text{kq})$. 

\subsection{$\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(k))$}
\label{section for b0R(k)}
The goal of this section is to compute $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(k))$. We begin with the following lemma.
\begin{lemma}
\label{lemma about b1(k)}
    There is an isomorphism of $\euscr{A}(1)^\vee_\mathbb{R}$-comodules and $\textup{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-modules:
    \[\textup{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(k)) \cong \bigoplus_{j=0}^{k}\Sigma^{4j, 2j}\mathbb{F}_2[\rho, \tau^2, h_0]/(\rho h_0).\]
\end{lemma}

\begin{proof}
    Let $C_{\euscr{A}(0)^\vee}(B_1^\mathbb{R}(k))$ denote the cobar complex computing $\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(k))$. This is a cosimplicial ring which takes the form
    \[\begin{tikzcd}
	{B_1^\mathbb{R}(k)} & {\euscr{A}(0)^\vee_\mathbb{R} \otimes B_1^\mathbb{R}(k)} & {\euscr{A}(0)^\vee_\mathbb{R} \otimes \euscr{A}(0)^\vee_\mathbb{R} \otimes B_1^\mathbb{R}(k)} & \cdots
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-2, to=1-3]
	\arrow[from=1-3, to=1-4]
    \end{tikzcd}\]
    after totalization. Since the coaction of $\euscr{A}(0)^\vee_\mathbb{R}$ on $B_1^\mathbb{R}(k)$ fixes $\rho$, all of the maps in $C_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(k))$ are $\rho$-linear. This implies that the filtration by powers of $\rho$
    \[C_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(k)) \supset \rho \cdot C_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(k)) \supset \rho^2 \cdot C_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(k)) \supset \cdots\]
    is a filtration of chain complexes. Moreover, we have the following identifications
    \[\begin{array}{ccc}
        \mathbb{M}_2^\mathbb{R}/\rho \cong \mathbb{M}_2^\mathbb{C}, & \euscr{A}(0)^\vee_\mathbb{R}/\rho = \euscr{A}(0)^\vee_\mathbb{C}, &  B_1^\mathbb{R}(k)/\rho =  B_1^\mathbb{C}(k).
    \end{array} \]
    Thus, the filtration on $C_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(k))$ gives a $\rho$-Bockstein spectral sequence (see \cref{comparison with C}) of the form:
    \[E_1 = \text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}( B_1^\mathbb{C}(k))[\rho] \implies \text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(k)).\]
    The groups $\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}(B_1^\mathbb{C}(k))$ were calculated by Culver-Quigley \cite[Remark 3.25]{CQ21}. Modulo $v_1$-torsion, we have
    \[\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}(B_1^\mathbb{C}(k)) \cong \bigoplus_{j=0}^k\Sigma^{4j, 2j}\mathbb{M}^\mathbb{C}_2[h_0].\]
    In the case of $k=0$, we have that $B_1^\mathbb{C}(0) \cong \mathbb{M}_2^\mathbb{C}$, and this $\rho$-Bockstein spectral sequence was completely determined by Hill \cite[Theorem 3.1]{Hil11}. We can rewrite the $E_1$-page as
    \[E_1 = \text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}(\mathbb{M}_2^\mathbb{C})[\rho] = \mathbb{M}_2^\mathbb{C}[h_0][\rho],\]
    with a differential $d_1(\tau) = \rho h_0$. The Liebniz rule immediately determines the end result:
    \[\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R}) \cong \mathbb{F}_2[\rho, \tau^2, h_0]/(\rho h_0).\]
    More generally, the $E_1$-page of the $\rho$-Bockstein takes the form
    \[E_1 = \bigoplus_{j=0}^k \Sigma^{4j, 2j}\mathbb{M}_2^\mathbb{C}[h_0][\rho],\]
    and the differentials can be determined using the cobar complex. In particular, there are  differentials 
    \[d_1(\Sigma^{4j, 2j}\tau) = \Sigma^{4j, 2j}(\rho h_0)\]
    for each $0 \leq j \leq k$ on the classes $\tau$ in each $H$-tower in the decomposition of $\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{C}}(B_1^\mathbb{C}(k))$. The Liebniz rule immediately determines the end result:
    \[\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(k)) \cong \bigoplus_{j=0}^k\Sigma^{4j, 2j}\mathbb{F}_2[\rho, \tau^2, h_0]/(\rho h_0),\]
    concluding the proof.
\end{proof}

