We will now use the results of \cref{b_0(1) powers proof} and the short exact sequences of motivic Brown--Gitler comodules to culminate our algebraic Atiyah--Hirzebruch program. The following result should be compared with \cite[Prop 2.6]{Mah81}, \cite[Prop 3.3]{BOSS19}, and \cref{C-b0(k) ext}.
\begin{thm}
\label{r-ext b0(k)}
    There is an isomorphism of $\euscr{A}(1)_\mathbb{R}^\vee$-comodules and $\textup{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-modules:
    \[\frac{\textup{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(k))}{v_1\textup{-torsion}} \cong \Sigma^{4k-4, 2k-2}Z_{\mathbb{\alpha}(k)}^\mathbb{R} \oplus \bigoplus_{j=0}^{4k-8}\left(\Sigma^{4j, 2j}H \oplus \Sigma^{4j, 2j-2}H\right) ,\]
    where $\alpha(k)$ is the number of 1's in the dyadic expansion of $k$.
\end{thm}

\begin{proof}
    We will induct on $k$ and use the short exact sequences of \cref{ses bg}. For $k=1$, this was shown in \cref{R-ksp}. We assume now the theorem is true for all $i<k$ and divide the proof into two cases: when $k$ is even, or when $k$ is odd.

    Suppose that $k$ is even. \cref{ses bg} provides us with a short exact sequence of $\euscr{A}(1)^\vee_\mathbb{R}$-comodules:
    \begin{align}
    \label{ses R-proof even}
    0 \to \Sigma^{2k, k}B_0^\mathbb{R}(\tfrac{k}{2}) \to B_0^\mathbb{R}(k) \to B_1^\mathbb{R}(\tfrac{k}{2} -1) \otimes (\euscr{A}(1)_\mathbb{R} \modmod \euscr{A}(0))_\mathbb{R}^\vee \to 0.
    \end{align}
    Applying $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}( -)$ gives a long exact sequence of $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R})$-modules. Moreover, after killing $v_1$-torsion the connecting homomorphism is trivial, giving a short exact sequence whose middle term is $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(k))$. Therefore, the Ext group in question decomposes into the Ext groups of the kernel and cokernel of the short exact sequence (\ref{ses R-proof even}).
    By the inductive hypothesis, we know that
    \[\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}\left(\Sigma^{2k, k}B_0^\mathbb{R}(\tfrac{k}{2})\right) \cong \Sigma^{2k, k}\left(\Sigma^{2k-4, k-2}Z_{\mathbb{\alpha}(k/2)}^\mathbb{R} \oplus \bigoplus_{j=0}^{2k-8}(\Sigma^{4j, 2j}H \oplus \Sigma^{4j, 2j-2}H)\right).\]
    A change of rings isomorphism gives an isomorphism for the right-hand side:
    \[\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}\left(B_1^\mathbb{R}(\tfrac{k}{2}-1) \otimes (\euscr{A}(1) \modmod \euscr{A}(0))^\vee_\mathbb{R}\right) \cong \text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}\left(B_1^\mathbb{R}(\tfrac{k}{2}-1)\right).\]
    The group $\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(\tfrac{k}{2}-1))$ was calculated in \cref{lemma about b1(k)}. Thus the right-hand side and left-hand side assemble to give
    \begin{align*}
        \text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(k)) \cong \Sigma^{4k-4, 2k,2}Z_{\alpha(k)}^\mathbb{R} &\oplus \bigoplus_{j=0}^{2k-8}\left(\Sigma^{4j+2k, 2j+2k}H \oplus \Sigma^{4j+4k, 2j-2+2k}H\right)   \\
         & \oplus \bigoplus_{j=0}^{k/2-1}\Sigma^{4j, 2j}\mathbb{F}_2[\rho, \tau^2, h_0](\rho h_0),
    \end{align*}
    using that $\alpha(\frac{k}{2}) = \alpha(k)$. Notice that for degree reasons, any $\rho$-divisible class coming from $\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}(\tfrac{k}{2}-1))$ is $v_1$-torsion. Combining and reindexing the $H$-towers in the second and third summands gives the result.

    Suppose now that $k$ is odd. \cref{ses bg} provides us with a different short exact sequence of $\euscr{A}(1)^\vee_\mathbb{R}$-comodules:
    \begin{align}
    \label{ses R-proof odd}
        0 \to \Sigma^{2(k-1), k-1}B_0^\mathbb{R}(\tfrac{k-1}{2}) \otimes B_0^\mathbb{R}(1) \to B_0^\mathbb{R}(k) \to B_1^\mathbb{R}(\tfrac{k-1}{2}-1) \otimes (\euscr{A}(1) \modmod \euscr{A}(0))_\mathbb{R}^\vee \to 0.
    \end{align}
    Again, modulo $v_1$-torsion the connecting homomorphism in the long exact sequence obtained by applying $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(-)$ is trivial, giving a short exact sequence whose middle term is $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(k)).$ We proceed by analyzing the Ext groups of the kernel and cokernel of the short exact sequence (\ref{ses R-proof odd}). A change of rings isomorphism gives the right-hand side:
    \[\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}\left(B_1^\mathbb{R}(\tfrac{k-1}{2}-1) \otimes (\euscr{A}(1) \modmod \euscr{A}(0))^\vee_\mathbb{R}\right) \cong \text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}\left(B_1^\mathbb{R}(\tfrac{k-1}{2}-1)\right).\]
    The group $\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}\left(B_1^\mathbb{R}(\tfrac{k-1}{2}-1)\right)$ was calculated in \cref{lemma about b1(k)}. To calculate the left-hand side, we can use the $\textbf{aAHSS}\left(B_0^\mathbb{R}(\tfrac{k-1}{2}) \otimes B_0^\mathbb{R}(1)\right)$. This spectral sequence is obtained by applying the functor $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}\left(B_0^\mathbb{R}(\tfrac{k-1}{2}) \otimes -\right)$ to the cellular filtration for $B_0^\mathbb{R}(1)$ and has signature
    \[E_1 = \text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}\left(B_0^\mathbb{R}(\tfrac{k-1}{2})\right) \otimes \mathbb{M}_2^\mathbb{R}\{[1], [\bar{\xi}_1], [\bar{\tau}_1]\} \implies \text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}\left(B_0^\mathbb{R}(\tfrac{k-1}{2}) \otimes B_0^\mathbb{R}(1)\right).\]
    By the inductive hypothesis, we have an isomorphism modulo $v_1$-torsion
    \begin{align}
    \label{aAHSS in R-B0k proof}
    \text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}\left(B_0^\mathbb{R}(\tfrac{k-1}{2})\right) \cong \Sigma^{2k-6, k-3}Z_{\alpha(k)-1}^\mathbb{R} \oplus \bigoplus_{j=0}^{2k-10}\left(\Sigma^{4j, 2j}H \oplus \Sigma^{4j, 2j-2}H\right),
    \end{align}
    using that $\alpha(\tfrac{k-1}{2}) = \alpha(k)-1$. This splitting descends to a splitting of the spectral sequence, and we may analyze each summand of (\ref{aAHSS in R-B0k proof}) individually. The left-hand summand is handled by \cref{b_0(1) powers proof}, as it is isomorphic to the $\textbf{aAHSS}\left(\Sigma^{2k-6, k-3}B_0^\mathbb{R}(1)^{\otimes \alpha(k)}\right)$, so we have a summand of $\Sigma^{2k-2, k-1}Z_{\alpha(k)}^\mathbb{R}$ in $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}\left(B_0^\mathbb{R}(\tfrac{k-1}{2}) \otimes B_0^\mathbb{R}(1)\right)$. The algebraic Atiyah--Hirzebruch spectral sequence on the right-hand summand collases on $E_2$. The remaining classes in Adams filtration 0 are $v_1$-torsion, and so the result is isomorphic to the original right-hand summand. Thus, we have an isomorphism:
    \begin{align*}
    \Sigma^{2(k-1), k-1}\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}\left(B_0^\mathbb{R}(\tfrac{k-1}{2}) \otimes B_0^\mathbb{R}(1)\right)\\ \cong\Sigma^{2(k-1), k-1}\left( \Sigma^{2k-2, k-1}Z^\mathbb{R}_{\alpha(k)} \oplus \bigoplus_{j=0}^{2k-10}\left(\Sigma^{4j, 2j}H \oplus \Sigma^{4j, 2j-2}H\right)\right).
    \end{align*}
    Assembling the right-hand side and left-hand side gives
    \begin{align*}
        \text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(k)) \cong \Sigma^{4k-4,2k-2} Z^\mathbb{R}_{\alpha(k)} &\oplus\bigoplus_{j=0}^{2k-10}\left(\Sigma^{4j+2(k-1), 2j+k-1}H \oplus \Sigma^{4j+2(k-1), 2j-2+k-1}H\right) \\
        &\oplus \bigoplus_{j=0}^{(k-1)/2-1}\Sigma^{4j, 2j}\mathbb{F}_2[\rho, \tau^2, h_0]/(\rho h_0).
    \end{align*}
    As before, for degree reasons, any $\rho$-divisible class coming from $\text{Ext}_{\euscr{A}(0)^\vee_\mathbb{R}}(B_1^\mathbb{R}\left(\tfrac{k-1}{2}-1)\right)$ is $v_1$-torsion. Combining and reindexing the $H$-towers in the second and third summands gives the result.
\end{proof} 

