%     Similar to the case over $\mathbb{C}$, the group $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(k))$ is very close, but not quite equivalent, to $Z_{2k -\alpha(k)}^\mathbb{R}$.
% \end{remark}

\subsection{The ring of cooperations}
In this subsection only, all results are implicitly computed modulo $v_1$-torsion. We assemble our results to compute the ring of cooperations $\pi_{**}^\mathbb{R}(\textup{kq} \otimes \textup{kq})$. First, our computation in \cref{r-ext b0(k)} gives the following:
\begin{corollary}
\label{describe e2}
    The $E_2$-page of the \textup{\textbf{mASS}}$(\textup{kq} \otimes \textup{kq})$ is given by
    \[E_2 = \bigoplus_{k \geq 0}\textup{Ext}^{s,f,w}_{\euscr{A}(1)_\mathbb{R}^\vee}(\Sigma^{4k, 2k}B_0^\mathbb{R}(k)) \cong \bigoplus_{k \geq 0}\left(\Sigma^{4k-4, 2k-2}Z_{\mathbb{\alpha}(k)}^\mathbb{R} \oplus \bigoplus_{j=0}^{4k-8}\left(\Sigma^{4j, 2j}H \oplus \Sigma^{4j, 2j-2}H\right)\right).\]
\end{corollary}
\begin{proof}
    The left hand equality, which is true even in the presence of $v_1$-torsion, is the content of \cref{e2 mass}. The right hand isomorphism follows from \cref{r-ext b0(k)}.
\end{proof}

We now arrive at our main result.

\begin{thm}
\label{main}
    The \textup{\textbf{mASS}}$(\textup{kq} \otimes \textup{kq})$ collapses on the $E_2$-page.
\end{thm}

\begin{proof}
    There is a base change functor
    \[-\otimes\mathbb{C}:\text{SH}(\mathbb{R}) \to \text{SH}(\mathbb{C})\]
    which induces a highly structured morphism with the $\mathbb{C}$-motivic Adams spectral sequence for $\pi_{**}^\mathbb{C}(\textup{kq} \otimes \textup{kq})$. In particular, \cite[Corollary 3.43]{CQ21} implies that there can be no differentials in the $\textbf{mASS}(\textup{kq} \otimes \textup{kq})$ with both the source and target being $\tau$-free. However, by \cref{describe e2} we see that every class on the $E_2$-page is $\tau^4$-periodic. Hence there can be no differentials and the spectral sequence collapses..
\end{proof}

\begin{remark}
\label{n-line over R}
    One may now use the ideas of \cref{n-line} to study the kq-resolution one filtration at a time. The $n$-line of the kq-resolution may be computed by a motivic Adams spectral sequence taking the form
    \[E_2 = \bigoplus_{I\in \mathcal{I}_n}\Sigma^{4|I|, 2|I|}\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(B_0^\mathbb{R}(I)) \implies \pi_{*+n, *}^\mathbb{R}(\textup{kq} \otimes \overline{\textup{kq}}^{\otimes n}).\]    
    This spectral sequences collapses for the same reasons given above. Note that although there is an algebra structure on the $E_1$-page, the individual $n$-lines do not carry any ring structure, as $\text{kq} \otimes \overline{\text{kq}}^{\otimes n}$ is not a ring spectrum. These computation do present the $n$-line as a module over the 0-line, given by $\text{Ext}_{\euscr{A}(1)^\vee_\mathbb{R}}(\mathbb{M}_2^\mathbb{R}, \mathbb{M}_2^\mathbb{R}).$

    Determining the differentials in the kq-resolution is much more difficult. By complex Betti realization, we can deduce much of the behavior of the complex $\textup{kq}$-resolution from the bo-resolution (see \cref{C-betti kq res}). However, there is information in the real $\textup{kq}$-resolution which is both $\rho$-torsion and $v_1$-periodic that is not detected by these methods. We plan to analyze the real $\textup{kq}$-resolution in future work using a combination of these methods and $C_2$-equivariant homotopy theory.
\end{remark}


