\centering
\includegraphics[width=0.35\linewidth, trim=3.9cm 0cm 3.9cm 0.5cm]{fig1_updated_b.pdf}
\caption{{\mx} layered architecture showing different agent types, Universal Message Bus, and supporting layers}
