		\begin{minipage}{0.65\textwidth}
			\centering
			\subfloat[Legend of symbols used for the images given above.]{
				\label{fig:node_key}
				\centering
				\includegraphics[width=\linewidth,height=8cm,keepaspectratio]{images/discussion/key.pdf}
