\section{Logarithmic return process derivations}
\subsection{The variance of a certain O-U process} \label{app:mut_var}
A zero-mean-reverting Ornstein-Uhlenbeck (OU) process driven by a Lévy process is described by the following stochastic differential equation:
\begin{equation*}
    d\mu_t=-\theta\mu_t dt+dL_t
\end{equation*}
The term \( \sigma_L^2 = E\left[L_t^2\right]/t \) represents the per-unit-time variance of the Lévy process. The initial value of \( \mu_t \) is \( \mu_0 \), that is, \( \mu_t = \mu_0 \) when \( t = 0 \). Derive the time-dependent variance formula for this process \( \mu_t \).
\begin{equation*}
    \mathrm{Var}\left(\mu_t\right)=\frac{\sigma_L^2}{2\theta}\left(1-e^{-2\theta t}\right)
\end{equation*}

Proof: Step 1, Solve the stochastic differential equation for \( \mu_t \) using the integrating factor method. The solution can be expressed as:
\begin{equation*}
    \mu_t=\mu_0e^{-\theta t}+\int_{0}^{t}e^{-\theta\left(t-s\right)} dL_s
\end{equation*}
It's well known that:
\begin{equation*}
    \mathrm{Var}\left(\mu_t\right)=E\left[\mu_t^2\right]-\left(E\left[\mu_t\right]\right)^2
\end{equation*}
Step 2, Compute \( \mathrm{E}\left[\mu_t^2\right] \) and \( \mathrm{E}\left[\mu_t\right] \) separately:
\begin{equation*}
    E\left[\mu_t\right]=E\left[\mu_0e^{-\theta t}+\int_{0}^{t}e^{-\theta\left(t-s\right)} d L_s\right]=\mu_0e^{-\theta t}+\int_{0}^{t}e^{-\theta\left(t-s\right)} E\left[dL_s\right]=\mu_0e^{-\theta t}
\end{equation*}
Continue to calculate $\mathrm{E}\left[\mu_t^2\right]$, substitute the expression of $\mu_t$, we have:
\begin{equation*}
    E\left[\mu_t^2\right]=E\left[\left(\mu_0e^{-\theta t}+\int_{0}^{t}e^{-\theta\left(t-s\right)} d L_s\right)^2\right]
\end{equation*}
Expanding the expression, we have:
\begin{equation*}
    E\left[\mu_t^2\right]=E\left[\mu_0^2e^{-2\theta t}+2\mu_0e^{-\theta t}\int_{0}^{t}e^{-\theta\left(t-s\right)} d L_s+\left(\int_{0}^{t}e^{-\theta\left(t-s\right)} d L_s\right)^2\right]
\end{equation*}
Since the increments of the Lévy process are independent with zero mean (\( \mathrm{E}\left[dL_s\right] = 0 \)), the cross-term in the above expression vanishes, yielding:
\begin{equation}
    E\left[\mu_t^2\right]=\mu_0^2e^{-2\theta t}+E\left[\left(\int_{0}^{t}e^{-\theta\left(t-s\right)} d L_s\right)^2\right] \label{eq:emu2}
\end{equation}
According to the properties of stochastic integrals, we have:
\begin{equation*}
    E\left[\left(\int_{0}^{t}e^{-\theta\left(t-s\right)} d\ L_s\right)^2\right]=\int_{0}^{t}\int_{0}^{t}{e^{-\theta\left(t-s\right)}e^{-\theta\left(t-u\right)}E\left[dL_sdL_u\right]}
\end{equation*}
As $L_t$ carries the properties of Lévy process:
\begin{equation*}
    E\left[dL_sdL_u\right]=\sigma_L^2\delta\left(s-u\right) ds du
\end{equation*}
where \( \delta \) denotes the Dirac delta function, the integral simplifies to:
\begin{equation*}
    E\left[\left(\int_{0}^{t}e^{-\theta\left(t-s\right)} d\ L_s\right)^2\right]=\sigma_L^2\int_{0}^{t}e^{-2\theta\left(t-s\right)} ds
\end{equation*}
Calculate the integrals, we have
\begin{equation*}
    \int_{0}^{t}e^{-2\theta\left(t-s\right)} ds=e^{-2\theta t}\int_{0}^{t}e^{2\theta s} ds=e^{-2\theta t}\left[\frac{e^{2\theta s}}{2\theta}\right]_0^t=e^{-2\theta t}\left(\frac{e^{2\theta t}-1}{2\theta}\right)=\frac{1-e^{-2\theta t}}{2\theta}
\end{equation*}
Therefore:
\begin{equation*}
    E\left[\left(\int_{0}^{t}e^{-\theta\left(t-s\right)} d\ L_s\right)^2\right]=\sigma_L^2\frac{1-e^{-2\theta t}}{2\theta}
\end{equation*}
Substitute into \eqref{eq:emu2}, we have:
\begin{equation*}
    E\left[\mu_t^2\right]=\mu_0^2e^{-2\theta t}+\sigma_L^2\frac{1-e^{-2\theta t}}{2\theta}
\end{equation*}
Step 3, combining the above two items, we have:
\begin{equation*}
    \mathrm{Var}\left(\mu_t\right)=E\left[\mu_t^2\right]-\left(E\left[\mu_t\right]\right)^2=\mu_0^2e^{-2\theta t}+\sigma_L^2\frac{1-e^{-2\theta t}}{2\theta}-\mu_0^2e^{-2\theta t}=\sigma_L^2\frac{1-e^{-2\theta t}}{2\theta}
\end{equation*}
Rearrange, we obtain:
\begin{equation*}
    \mathrm{Var}\left(\mu_t\right)=\frac{\sigma_L^2}{2\theta}\left(1-e^{-2\theta t}\right)
\end{equation*}
\begin{flushright}
Q.E.D.
\end{flushright}
\subsection{The variance of logarithmic return}  \label{app:logarithmic_ret_var}
The temporal evolution of log-returns follows the process:
\begin{equation}
    \ln{\left(\frac{S_t}{S_0}\right)}=\frac{\mu_0}{\theta}\left(1-e^{-\theta t}\right)+\frac{1}{\theta}\int_{0}^{t}{\left(1-e^{-\theta\left(t-u\right)}\right)dL_u}-\frac{1}{2}\sigma^2t+\sigma W_t \label{eq:logret_expression}
\end{equation}
Prove that the variance of logarithmic return is the following:
\begin{equation*}
    \mathrm{Var}\left[\ln{\left(\frac{S_t}{S_0}\right)}\right]=\sigma^2t+\frac{\sigma_L^2}{\theta^2}\left[t-\frac{2}{\theta}\left(1-e^{-\theta t}\right)+\frac{1}{2\theta}\left(1-e^{-2\theta t}\right)\right]
\end{equation*}
Where:
\begin{itemize}
    \item $W_t$: The standard Brownian motion.
    \item $\sigma_L^2$: \( \sigma_L^2 = \text{E}\left[L_t^2\right]/t \) represents the per-unit-time variance of the Lévy process. and $\sigma_L^2 := \lim_{t\rightarrow0} \frac{\text{E}[L_t^2]}{t}$
    \item $\mu_t$: A zero-mean O-U process driven by a Lévy process is described by the stochastic differential equation: $d\mu_t = -\theta \mu_t dt + dL_t$
    \item \( L_t \): A zero-mean, finite second-moment Lévy process with symmetric distribution.
\end{itemize}
In addition, it's under the assumption that the Lévy process driving the drift term is independent of the Wiener process in the geometric Brownian motion component.

Proof: Step 1, decompose the log-return process in \eqref{eq:logret_expression} into four components, where the variance is exclusively determined by the stochastic terms (second and fourth terms). Define:
\begin{equation*}
    \mathrm{A}_\mathrm{t}=\frac{1}{\theta}\int_{0}^{t}{\left(1-e^{-\theta\left(t-u\right)}\right)dL_u}
\end{equation*}
Given the independence between the Lévy process driving the drift term and the Wiener process in the geometric Brownian motion component, we derive:
\begin{equation}
    \mathrm{Var}\left[\ln{\left(\frac{S_t}{S_0}\right)}\right]=\mathrm{Var}\left(\mathrm{A}_\mathrm{t}\right)+\sigma^2t
\end{equation}
Step 2, We compute \( \mathrm{Var}\left(\mathrm{A}_\mathrm{t}\right) \) by applying the isometry property of Lévy integrals, define:
\begin{equation*}
    B\left(u\right)=\frac{1-e^{-\theta\left(t-u\right)}}{\theta}
\end{equation*}
We have:
\begin{equation*}
    \mathrm{Var}\left[A_t\right]=E\left[\left(\int_{0}^{t}{B\left(u\right)dL_u}\right)^2\right]=\int_{0}^{t}{B\left(u\right)^2\sigma_L^2du}
\end{equation*}
where \( \sigma_L^2 = \text{E}\left[L_t^2\right]/t \) denotes the per-unit-time variance of the Lévy process. Substituting and expanding yields:
\begin{equation*}
    \mathrm{Var}\left[A_t\right]=\sigma_L^2\int_{0}^{t}{\left(\frac{1-e^{-\theta\left(t-u\right)}}{\theta}\right)^2du}
\end{equation*}
By substituting \( s = t - u \) and changing the integration variable (where \( u \) ranges from 0 to \( t \), corresponding to \( s \) from \( t \) to 0), we obtain:
\begin{equation*}
    \mathrm{Var}\left[A_t\right]=\sigma_L^2\int_{0}^{t}{\left(\frac{1-e^{-\theta s}}{\theta}\right)^2ds}=\frac{\sigma_L^2}{\theta^2}\int_{0}^{t}{\left(1-e^{-\theta s}\right)^2ds}
\end{equation*}
Expand the integrand:
\begin{equation*}
    \left(1-e^{-\theta s}\right)^2=1-2e^{-\theta s}+e^{-2\theta s}
\end{equation*}
After integrating term by term, we obtain:
\begin{equation*}
    \int_{0}^{t}{\left(1-e^{-\theta s}\right)^2ds}=t-\frac{2}{\theta}\left(1-e^{-\theta t}\right)+\frac{1}{2\theta}\left(1-e^{-2\theta t}\right)
\end{equation*}
Therefore:
\begin{equation*}
    \mathrm{Var}\left[A_t\right]=\frac{\sigma_L^2}{\theta^2}\left[t-\frac{2}{\theta}\left(1-e^{-\theta t}\right)+\frac{1}{2\theta}\left(1-e^{-2\theta t}\right)\right]
\end{equation*}
Combining with the variance from the Brownian motion term, we obtain:
\begin{equation*}
    \mathrm{Var}\left[\ln{\left(\frac{S_t}{S_0}\right)}\right]=\sigma^2t+\frac{\sigma_L^2}{\theta^2}\left[t-\frac{2}{\theta}\left(1-e^{-\theta t}\right)+\frac{1}{2\theta}\left(1-e^{-2\theta t}\right)\right]
\end{equation*}
\begin{flushright}
Q.E.D.
\end{flushright}

\subsection{Quasi-Sharpe ratio asymptotic value} \label{app:quasi_sharpe}
The quasi-Sharpe ratio formula based on the expected log-return and standard deviation is given by:
\begin{equation*}
\mathrm{QuasiSharpe}\left(t\right)=\mathrm{\mathrm{QS}}\left(t\right)=\frac{\mu_0\cdot\frac{1-e^{-\theta t}}{\theta}-\frac{1}{2}\sigma^2t}{\sqrt{\sigma^2t+\frac{\sigma_L^2}{\theta^2}\left(t-\frac{2}{\theta}\left(1-e^{-\theta t}\right)+\frac{1}{2\theta}\left(1-e^{-2\theta t}\right)\right)}}
\end{equation*}
As \( t \rightarrow 0^+ \), prove the following equality:
\begin{gather*}
    \lim_{t\rightarrow0^+}{\mathrm{QS}}\left(t\right)=0 \\
    \mathrm{QS}\left(t\right)\sim\left(\frac{\mu_0-\frac{1}{2}\sigma^2}{\sigma}\right)\cdot\sqrt t
\end{gather*}
Proof: Observe that as \( t \rightarrow 0^+ \), both the numerator and denominator approach 0, resulting in an indeterminate form. We investigate its asymptotic behavior near \( t \rightarrow 0^+ \) through Taylor expansion. First, expand the fractional component of the numerator:
\begin{equation*}
    \frac{1-e^{-\theta t}}{\theta}=t-\frac{1}{2}\theta t^2+\mathcal{O}\left(t^3\right)
\end{equation*}
Therefore, the expected log-return represented by the numerator is:
\begin{equation*}
    E\left[\ln{\left(S_t/S_0\right)}\right]=\left(\mu_0-\frac{1}{2}\sigma^2\right)t-\frac{1}{2}\mu_0\theta t^2+\mathcal{O}\left(t^3\right)
\end{equation*}
Expand the variance term in the denominator by decomposing it as follows:
\begin{gather*}
    1-e^{-\theta t}=\theta\ t-\frac{1}{2}\theta^2t^2+\mathcal{O}\left(t^3\right) \\
    1-e^{-2\theta t}=2\theta t-2\theta^2t^2+\mathcal{O}\left(t^3\right)
\end{gather*}
Substitute into the variance equation:
\begin{gather*}
    \mathrm{Var}\left[\ln{\left(S_t/S_0\right)}\right]=\sigma^2t+\frac{\sigma_L^2}{\theta^2}\left[t-\frac{2}{\theta}\left(\theta t-\frac{1}{2}\theta^2t^2\right)+\frac{1}{2\theta}\left(2\theta t-2\theta^2t^2\right)+\mathcal{O}\left(t^3\right)\right]\\
    \mathrm{Var}=\sigma^2t+\frac{\sigma_L^2}{\theta^2}\left(t-\left(2t-\theta t^2\right)+\left(t-\theta t^2\right)+\mathcal{O}\left(t^3\right)\right)=\sigma^2t+\frac{\sigma_L^2}{\theta^2}\left(0+0+\mathcal{O}\left(t^3\right)\right)=\sigma^2t+\mathcal{O}\left(t^3\right)\\
    \mathrm{Var}\left[\ln{\left(S_t/S_0\right)}\right]=\sigma^2t+\mathcal{O}\left(t^3\right)
\end{gather*}
The square root of above is:
\begin{equation*}
\sqrt{\mathrm{Var}\left[\ln{\left(S_t/S_0\right)}\right]}=\sigma\sqrt t+\mathcal{O}\left(t^{5/2}\right)
\end{equation*}
Substitute into the quasi-Sharpe ratio equation:
\begin{equation*}
    \mathrm{QS}\left(t\right)=\frac{\left(\mu_0-\frac{1}{2}\sigma^2\right)t-\frac{1}{2}\mu_0\theta t^2+\mathcal{O}\left(t^3\right)}{\sigma\sqrt t+\mathcal{O}\left(t^{5/2}\right)}=\frac{\mu_0 - \frac{1}{2} \sigma^2}{\sigma} \sqrt{t} - \frac{1}{2} \frac{\mu_0 \theta}{\sigma} t^{3/2} + \mathcal{O}(t^{5/2})
\end{equation*}
\begin{flushright}
Q.E.D.
\end{flushright}


\subsection{The maximum of the logarithmic-return mean process}  \label{app:max_main}
The log-return process is described by following:
\begin{equation*}
    E\left[R_t\right]=\mu_0\frac{1-e^{-\theta t}}{\theta}-\frac{\sigma^2}{2}t
\end{equation*}
Prove that, the maximum is obtained when t is:
\begin{equation*}
    t=-\frac{1}{\theta}\ln{\left(\frac{\sigma^2}{2\mu_0}\right)}
\end{equation*}
With the maximum being:
\begin{equation*}
    E\left[R_t\right]_{max}=\frac{\mu_0}{\theta}+\frac{\sigma^2}{2\theta}\ln{\left(\frac{\sigma^2}{2e\mu_0}\right)}
\end{equation*}
Proof:The results demonstrate that when \( t = 0 \), the expected return is zero. The expected return initially increases with \( t \), reaches a maximum, and subsequently decreases. The first term of the expression is a concave function of \( t \), while the second term is linear, resulting in an overall concave function with global maximum. We now derive this extrema by differentiating \( \text{E}\left[R_t\right] \) with respect to \( t \):
\begin{equation*}
    \frac{d}{dt}E\left[R_t\right]=\frac{\mu_0}{\theta}\cdot\frac{d}{dt}\left(1-e^{-\theta t}\right)-\frac{\sigma^2}{2}
\end{equation*}
and:
\begin{equation*}
    \frac{d}{dt}\left(1-e^{-\theta t}\right)=\theta\ e^{-\theta t}
\end{equation*}
Therefore:
\begin{equation*}
    \frac{d}{dt}E\left[R_t\right]=\mu_0e^{-\theta t}-\frac{\sigma^2}{2}
\end{equation*}
Setting the above expression equal to zero yields:
\begin{equation*}
    \mu_0e^{-\theta t}=\frac{\sigma^2}{2}
\end{equation*}
Solve it, we have:
\begin{equation*}
    t=-\frac{1}{\theta}\ln{\left(\frac{\sigma^2}{2\mu_0}\right)}
\end{equation*}
The equation further reveals that to ensure \( t \geq 0 \) (and thus maintain mathematical meaningfulness), the condition \( \frac{\sigma^2}{2\mu_0} < 1 \) must hold, which equivalently implies:
\begin{equation*}
    \mu_0>\frac{\sigma^2}{2}
\end{equation*}
This implies that the initial drift acting as a shock must be sufficiently large—specifically, large relative to the volatility—to be economically meaningful. We now substitute the derived time value \( t^* \) that maximizes the expected return into the mean return formula. Substituting \( t = -\frac{1}{\theta}\ln{\left(\frac{\sigma^2}{2\mu_0}\right)} \), the left-hand term becomes:
\begin{equation*}
    \mu_0\frac{1-e^{-\theta t}}{\theta}=\mu_0\frac{1-\frac{\sigma^2}{2\mu_0}}{\theta}=\mu_0\frac{\frac{2\mu_0-\sigma^2}{2\mu_0}}{\theta}=\frac{2\mu_0-\sigma^2}{2\theta}
\end{equation*}
The right-hand term:
\begin{equation*}
    -\frac{\sigma^2}{2}t=-\frac{\sigma^2}{2}\cdot\left(-\frac{1}{\theta}\ln{\left(\frac{\sigma^2}{2\mu_0}\right)}\right)=\frac{\sigma^2}{2\theta}\ln{\left(\frac{\sigma^2}{2\mu_0}\right)}
\end{equation*}
Combining these terms yields the maximum expected return:
\begin{equation*}
    E\left[R_t\right]_{max}=\frac{\mu_0}{\theta}+\frac{\sigma^2}{2\theta}\ln{\left(\frac{\sigma^2}{2e\mu_0}\right)}
\end{equation*}
\begin{flushright}
Q.E.D.
\end{flushright}



