	\caption{State trajectory after the optimization for $\lambda=10$ on $n_g$=125 grid points in three-dimensional extended input/state space.}
	\label{fig:xTraj_reg}
\end{figure}

\textbf{Remark.} The regularization technique leads to the stabilization of the local poles due to its relocation effect on data points in both LMs:
