\subsection{Mixed Hodge modules}
\label{sec:prelim_MHM}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Another key player involves
Mixed Hodge modules
% , but we will presents things in a streamlined fashion. These
were introduced in \cite{Saito:1989,Saito:1990}. See \cite[\S
14]{Peters/Steenbrink:2008} for a modern treatment. Denote the derived category of
bounded complexes of mixed Hodge modules on $X$ by $D^b(\operatorname{MHM}(X))$.
This category admits a \emph{duality functor}. Specifically, by abuse of notation, it
may be identified with the duality functor $\mathbb{D}_X(-)$ on the derived category
of filtered $D$-modules underlying mixed Hodge modules \cite[\S
2.4]{Saito:1988}. There are the \emph{($p$-th) graded de Rham functors} (which are
exact functors):
%\sandor{This seems to be missing a word or two}
\begin{displaymath}
  \operatorname{gr}^F_p \operatorname{DR}_X \colon D^b(\operatorname{MHM}(X)) \to
  D^b_{\operatorname{coh}}(X). 
\end{displaymath}
The duality functor $\mathbb{D}_X(-)$ commutes with $\operatorname{gr}^F_p\operatorname{DR}_X$; in
particular (see \cite[\S 2.4]{Saito:1988}),
\begin{displaymath}
  \sR\sHom  ( \operatorname{gr}^F_p
  \operatorname{DR}_X (E) , \omega^\kdot_X)[- \dim X] \simeq \operatorname{gr}^F_{-p}
  \operatorname{DR}_X  \mathbb{D}_X(E)[- \dim X]. 
\end{displaymath}
%
% The graded de Rham functors enjoy the following compatibility with proper morphisms
% $f \colon Y \to X$; specifically, there is a commutative diagram,
%\begin{displaymath}
%  https://q.uiver.app/#
%    \begin{tikzcd}
%        {D^b(\operatorname{MHM}(Y))} & {D^b_{\operatorname{coh}}(Y)} \\
%        {D^b(\operatorname{MHM}(X))} & {D^b_{\operatorname{coh}}(X)}
%        \arrow["{\operatorname{gr}^F_p \operatorname{DR}_Y}"', from=1-1, to=1-2]
%        \arrow["{f^{\operatorname{MHM}}_\ast}"', from=1-1, to=2-1]
%        \arrow["{\sR f_\ast}", from=1-2, to=2-2]
%        \arrow["{\operatorname{gr}^F_p \operatorname{DR}_X}"', from=2-1, to=2-2]
%    \end{tikzcd}
%  \end{displaymath}
There are two objects in $D^b(\operatorname{MHM}(X))$ central to the definitions of
singularities we study, namely, $\mathbb{Q}^H_X [\dim X]$ and the intersection
complex $\mathcal{IC}_X^H$, see \cite[\S 4.5]{Saito:1990}. We remark that our notation is different from loc.\ cit.\ which uses the notation $\mathcal{IC}_X \mathbb{Q}^H$. There is a
composition
\begin{equation}
  \label{eq:intersection_composition}
  \gamma_X \colon \mathbb{Q}^H_X [\dim X] \to \mathcal{H}^0 (\mathbb{Q}^H_X [\dim X])
  \to \mathcal{IC}_X^H \simeq \operatorname{gr}^W_{\dim X} (\mathcal{H}^0
  (\mathbb{Q}^H_X [\dim X])) 
\end{equation}
where $\operatorname{gr}^W$ refers to a graded piece with respect to the weight filtration (see loc.\ cit.). By
\cite[Theorem 4.2]{Saito:2000}, there is an isomorphism
\begin{displaymath}
  \underline{\Omega}^p_X \simeq \operatorname{gr}^F_{-p} \operatorname{DR}_X
  (\mathbb{Q}^H_X [\dim X])[p- \dim X] \simeq \operatorname{gr}^F_{-p}
  \operatorname{DR}_X (\mathbb{Q}^H_X [p]). 
\end{displaymath}
This leads to the \emph{intersection Du~Bois complexes} (see \cite[\S
9]{Popa/Shen/DucVo:2024}),
\begin{displaymath}
  \mathcal{I} \underline{\Omega}^p_X := \operatorname{gr}^F_{-p} \operatorname{DR}_X
  (\mathcal{IC}_X^H [p- \dim X]). 
\end{displaymath}
Taking the composition of $\gamma_X$ with its dual gives the following morphisms:
%in $D^b(\operatorname{MHM}(X))$,
\begin{displaymath}
  \mathbb{Q}^H_X [\dim X] \to  \mathcal{IC}_X^H \to (\mathbb{D}_X
  (\mathbb{Q}^H_X [\dim X]))(-\dim X),
\end{displaymath}
where we use the self-duality relation
$\mathbb{D}_X (\mathcal{IC}_X^H)\simeq \mathcal{IC}_X^H (\dim X)$. Here, $(t)$ is the
$t$-th Tate twist of $M$ (at the level of filtered $D$-modules this is simply a shift
down by $t$, that is, $F_{\kdot} (M)(t) = F_{\kdot-t} M$), cf.~\cite[Eq.\
4.5.13]{Saito:1990}. Finally, applying the functors
$\operatorname{gr}^F_{-p} \operatorname{DR}_X$ give us the following morphisms in
$D^b_{\operatorname{coh}}(X)$:
\begin{equation}
  \label{eq:intro_mhm_composition}
  \underline{\Omega}^p_X \to \mathcal{I} \Omega^p_X \to \sR\sHom (
  \underline{\Omega}^{\dim X-p}_X ,   \omega^\kdot_X)[-\dim X]. 
\end{equation}
To simplify notation, we follow \cite[Eq.\ (3.K.1)]{Kovacs:2025} and use
\begin{equation}
  \label{eq:intro_irrationality_complex_pth}
  \Irr^p_X\colon=\sR\sHom( \underline{\Omega}^{\dim X-p}_X ,
  \omega^\kdot_X)[-\dim X]
\end{equation}
as well as, $\widetilde{\Irr}^p_X := \mathcal{H}^0 (\Irr^p_X)$. Here, $\Irr^p_X$ is
the shifted associated graded quotient of the \emph{irrationality complex of $X$},
which is denoted by $\Irr^\kdot_X$ (see \cite[\S 3.K]{Kovacs:2025}). Up to
isomorphism of filtered complexes on $X$, we have
\begin{displaymath}
  \Irr^{\kdot}_X \simeq \sR\sHom(\sR  \epsilon_\ast
  \underline{\Omega}^\kdot_{X_\kdot}, \omega^\kdot_X ) [-2\dim X]. 
\end{displaymath}
Note that the $2\dim X$ shift is necessary, because of taking the dual and the
inherent shift in $\omega^\kdot_x$. For a longer explanation see
\cite[Remark~3.12]{Kovacs:2025}.
% \See \cite[V.3.6(5)]{Guillen/NavarroAznar/Pascual-Gainza/Puerta:1988} where
% $\epsilon\colon X_{\kdot}\to X$ is the cubical hyperresolution in \Cref{sec:prelim_DB}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Singularities}
\label{sec:prelim_singularities}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Next we consider the singularities we are interested in.
%% To keep things brief, we refer the reader to \Cref{sec:intro} for a highlight on
%% recent development about the notions we study below.
Following \eqref{eq:intro_mhm_composition} and
\eqref{eq:intro_irrationality_complex_pth}, there exist a composition of natural
morphisms given by
\begin{equation}
  \label{eq:1}
  \underline{\Omega}^p_X \to \mathcal{I} \Omega^p_X \to \sR\sHom(
  \underline{\Omega}^{\dim X-p}_X , \omega^\kdot_X)[-\dim X] \simeq \Irr^p_X. 
\end{equation}
%There is a barrage of new singularities arising from ideas in \Cref{sec:prelim_MHM}
%and the composition above. However, we confine ourselves to the following;
For $m\geq 0$, we say that $X$ has
\begin{itemize}
\item \emph{pre-$m$-rational singularities} if $\mathcal{H}^j (\Irr^p_X) = 0$ for all
  $0\leq p \leq m$ and $j>0$,
\item \emph{pre-$m$-Du~Bois singularities} if
  $\mathcal{H}^j (\underline{\Omega}^p_X) = 0$ for all $0\leq p \leq m$ and $j>0$,
\end{itemize}
These (and their variants) were first studied in \cite[Definition
1.1]{Shen/Venkatesh/Vo:2023}, with further variants appearing in \cite[Definition
4.2]{Kovacs:2025}. Observe that we say `pre-$m$-' as opposed to `pre-$k$-' like the
case of loc.\ cit. This follows the convention of \cite[\S 4]{Kovacs:2025} as
`$k$-rational' is often used to refer to points defined over a base field
$k$. Moreover, our definition for pre-$m$-rational singularities is equivalent to
that of \cite[Definition 1.1]{Shen/Venkatesh/Vo:2023} by using the irrationality
complex of $X$ (see \eqref{eq:intro_irrationality_complex_pth}). An important fact is
that a normal variety over $\mathbb{C}$ having pre-$m$-rational singularities implies
that it has pre-$m$-Du~Bois singularities. This is \cite[Theorem
B]{Shen/Venkatesh/Vo:2023} (see also \cite[Theorem 1.4]{Kovacs:2025}).

