Next we show that pre-$m$-rational singularities can be defined in terms of the
intersection Du Bois complexes, a fact that is essentially contained in
\cite{Popa/Shen/DucVo:2024} and \cite{Dirks/Olano/Raychaudhury:2025}.

\begin{lemma}
    \label{lem:pre_m_rational_via_intersection_db_isomorphism}
    Let $X$ be a normal variety over $\mathbb{C}$. Then the following are equivalent
    for any $m\geq 0$:
    \begin{enumerate}
    \item\label{item:1} $X$ has pre-$m$-rational singularities
    \item\label{item:2}
      $\mathcal{H}^0(\mathcal{I}\underline{\Omega}^p_X) \xrightarrow{ntrl.}
      \mathcal{I}\underline{\Omega}^p_X$ is an isomorphism for all $0\leq p \leq m$.
    \end{enumerate}
\end{lemma}

\begin{proof}
  From \cite[Lemma 9.4]{Popa/Shen/DucVo:2024}, $X$ having pre-$m$-rational
  singularities ensures that
  $\underline{\Omega}^p_X \xrightarrow{ntrl.} \mathcal{I}\underline{\Omega}^p_X$ is
  an isomorphism for all $0\leq p \leq m$. However, \cite[Theorem
  B]{Shen/Venkatesh/Vo:2023} (or \cite[Theorem 1.4]{Kovacs:2025}) tells us that $X$
  must also have pre-$m$-Du~Bois singularities. Therefore,
  $\mathcal{H}^0 (\underline{\Omega}^p_X) \xrightarrow{ntrl.} \underline{\Omega}^p_X$
  is an isomorphism for all $0\leq p \leq m$, and hence
  $\mathcal{H}^0(\mathcal{I}\underline{\Omega}^p_X) \xrightarrow{ntrl.}
  \mathcal{I}\underline{\Omega}^p_X$ is an isomorphism for all $0\leq p \leq m$.

  Conversely, assume that
  $\mathcal{H}^0(\mathcal{I}\underline{\Omega}^p_X) \xrightarrow{ntrl.}
  \mathcal{I}\underline{\Omega}^p_X$ is an isomorphism for all $0\leq p \leq m$. We
  will use induction on $m$ and start with the base case $m=0$. By \cite[(8.4.1) \&
  Proposition 8.2]{Kebekus/Schnell:2021}, we know that
  $\mathcal{I}\underline{\Omega}^0_X \xrightarrow{ntrl.} \sR f_\ast
  \mathcal{O}_{\widetilde{X}}$ is an isomorphism where $f\colon \widetilde{X}\to X$
  is a strong log resolution. We have
  $\mathcal{O}_X \simeq f_\ast \mathcal{O}_{\widetilde{X}}$ because $X$ is
  normal. Hence, \eqref{item:2} implies that
  $\mathcal{O}_X \xrightarrow{ntrl.} \sR f_\ast \mathcal{O}_{\widetilde{X}}$ is an
  isomorphism, and so $X$ has rational singularities.

  Next, assume that the desired claim holds for $0\leq p \leq m-1$, i.e., that $X$
  has pre-$(m-1)$-rational singularities. Then it also has pre-$(m-1)$-Du~Bois
  singularities (e.g.\ see \cite[Theorem B]{Shen/Venkatesh/Vo:2023} or \cite[Theorem
  1.4]{Kovacs:2025}). Furthermore,
  $\mathcal{H}^0 (\underline{\Omega}^m_X) \xrightarrow{ntrl.}
  \mathcal{H}^0(\mathcal{I}\underline{\Omega}^m_X)$ is an isomorphism by
  \Cref{lem:Kebekus_Schnell}, so the top and right arrows, and hence the diagonal
  arrow in the following diagram are isomorphisms,
  \[
    \xymatrix{%
      \mathcal{H}^0 (\underline{\Omega}^m_X) \ar[r]^-\simeq \ar[rd]^\simeq \ar[d] &
      \mathcal{H}^0(\mathcal{I}\underline{\Omega}^m_X) \ar[d]^\simeq \\
      \underline{\Omega}^m_X \ar[r] & \mathcal{I}\underline{\Omega}^m_X. }
  \]
  It follows that the natural morphism
  $\mathcal{H}^0 (\underline{\Omega}^m_X) \xrightarrow{ntrl.}
  \underline{\Omega}^m_X$ has a left inverse, and then $X$ has pre-$m$-Du~Bois
  singularities by \cite[Theorem 10.8]{Kovacs:2025}. Therefore,
  $\mathcal{H}^0 (\underline{\Omega}^m_X) \xrightarrow{ntrl.}
  \underline{\Omega}^m_X$ is actually an isomorphism, and hence
  $\underline{\Omega}^m_X \xrightarrow{ntrl.} \mathcal{I} \underline{\Omega}^m_X$
  must also be an isomorphism. Then $X$ has pre-$m$-rational singularities by
  \cite[Remark's 4.8(4) \& 5.2]{Dirks/Olano/Raychaudhury:2025}, which completes the
  proof.
\end{proof}

\begin{theorem}
    \label{thm:splitting_via_irr_complex}
    Let $X$ be a normal variety over $\mathbb{C}$. Then the following are equivalent
    for any $m\geq 0$:
    \begin{enumerate}
        \item \label{thm:splitting_via_irr_complex1} $X$ has pre-$m$-rational singularities
        \item \label{thm:splitting_via_irr_complex2}
          $\mathcal{H}^0(\mathcal{I}\underline{\Omega}^p_X) \xrightarrow{ntrl.}
          \mathcal{I}\underline{\Omega}^p_X$ has a left inverse for each
          $0\leq p \leq m$, and
        \item \label{thm:splitting_via_irr_complex3}
          $\widetilde{\Irr}^p_X \xrightarrow{ntrl.} \Irr^p_X$ has a left inverse for
          each $0\leq p \leq m$.
    \end{enumerate}
\end{theorem}

\begin{proof}
  From \Cref{lem:pre_m_rational_via_intersection_db_isomorphism}, we know that
  $\eqref{thm:splitting_via_irr_complex1}\implies
  \eqref{thm:splitting_via_irr_complex2}$, whereas
  $\eqref{thm:splitting_via_irr_complex1} \implies
  \eqref{thm:splitting_via_irr_complex3}$ is straightforward by the definition of
  pre-$m$-rational singularities.

  Next, we show that
  $\eqref{thm:splitting_via_irr_complex2}\implies
  \eqref{thm:splitting_via_irr_complex1}$ by induction on $m$.

  By \cite[8.4.1 \& Proposition 8.2]{Kebekus/Schnell:2021}, we know that
  $\mathcal{I}\underline{\Omega}^0_X \xrightarrow{ntrl.} \sR f_\ast
  \mathcal{O}_{\widetilde{X}}$ is an isomorphism where $f\colon \widetilde{X}\to X$
  is a strong log resolution. We have
  $\mathcal{O}_X \simeq f_\ast \mathcal{O}_{\widetilde{X}}$ because $X$ is
  normal. Hence, our hypothesis implies that
  $\mathcal{O}_X \xrightarrow{ntrl.} \sR f_\ast \mathcal{O}_{\widetilde{X}}$ splits,
  and so $X$ has rational singularities by \cite[Theorem 1]{Kovacs:2000}.

  Next assume that $m\geq 1$ and choose a $p$, such that $0\leq p \leq m$. Then
  $\mathcal{H}^0( \mathcal{I}\underline{\Omega}^p_X) \xrightarrow{ntrl.}
  \mathcal{I}\underline{\Omega}^p_X$ admits a left inverse. Applying the functor
  $\sR\sHom(- , \omega^\kdot_X)$ gives a composition
    \begin{displaymath}
      \sR\sHom( \mathcal{H}^0 (\mathcal{I}\underline{\Omega}^p_X ), \omega^\kdot_X)
      \to \sR\sHom( \mathcal{I}\underline{\Omega}^p_X, \omega^\kdot_X) \to
      \sR\sHom(\mathcal{H}^0 (\mathcal{I}\underline{\Omega}^p_X ) , \omega^\kdot_X) 
    \end{displaymath}
    which is an isomorphism (in the derived category). In particular, we see that
    \begin{equation}
        \label{eq:pre_k_rational_dualized1}
        \sR\sHom( \mathcal{I}\underline{\Omega}^p_X, \omega^\kdot_X) \to
        \sR\sHom(\mathcal{H}^0 (\mathcal{I}\underline{\Omega}^p_X ) , \omega^\kdot_X) 
    \end{equation}
    is surjective on cohomology sheaves. However, \cite[Conjecture
    10.1]{Popa/Shen/DucVo:2024} coupled with \cite[Theorem 1.1]{Kovacs:2025} and
    \cite[Theorem 10.3]{Popa/Shen/DucVo:2024}, ensures that
    \eqref{eq:pre_k_rational_dualized1} must also be injective on cohomology sheaves
    (cf.~the comments after \cite[Corollary 1.3]{Kovacs:2025}).  It follows that
    \eqref{eq:pre_k_rational_dualized1} is an isomorphism and hence, after dualizing
    once more, we conclude that
    $\mathcal{H}^0(\mathcal{I}\underline{\Omega}^p_X) \xrightarrow{ntrl.}
    \mathcal{I}\underline{\Omega}^p_X$ is an isomorphism. Then
    \Cref{lem:pre_m_rational_via_intersection_db_isomorphism} implies that $X$ has
    pre-$m$-rational singularities, which completes the proof of this implication.

    Lastly we need to check that
    $\eqref{thm:splitting_via_irr_complex3} \implies
    \eqref{thm:splitting_via_irr_complex2}$. Let $0\leq p \leq m$ and consider the diagram,
    % Suppose $\alpha,\beta$ are respectively the inverses of
    % $\widetilde{\Irr}^p_X \xrightarrow{ntrl.} \Irr^p_X$ and
    % $\mathcal{H}^0(\mathcal{I}\underline{\Omega}^p_X) \xrightarrow{ntrl}
    % \widetilde{\Irr}^p_X$. Note $\beta$ exists via
    % \Cref{lem:Kebekus_Schnell}. Consider the composition
    % \begin{displaymath}
    %   \mathcal{H}^0(\mathcal{I}\underline{\Omega}^p_X) \xrightarrow{ntrl.}
    %   \mathcal{I}\underline{\Omega}^p_X \xrightarrow{ntrl.} \Irr^p_X
    %   \xrightarrow{\alpha} \widetilde{\Irr}^p_X \xrightarrow{\beta}
    %   \mathcal{H}^0(\mathcal{I}\underline{\Omega}^p_X). 
    % \end{displaymath}
