\begin{corollary}
    \label{cor:finite_cover_pre_m_rational}
    Let $f\colon Y \to X$ be a finite surjective morphism of normal varieties. If $Y$
    has pre-$m$-rational singularities, then so does $X$.
\end{corollary}

\begin{proof}
  First, we will show that there is a natural morphism of Hodge modules
  $\mathcal{IC}_X^H \to f_\ast\mathcal{IC}_Y^H$. We have the following natural
  morphism in $D^b(\operatorname{MHM}(X))$
  \begin{displaymath}
    \mathbb{Q}^H_X [\dim X] \to f_\ast \mathbb{Q}^H_Y [\dim Y].
  \end{displaymath}
  As $f$ is finite, $f_\ast\colon D^b(\operatorname{MHM}(Y)) \to D^b(\operatorname{MHM}(X))$ is $t$-exact, i.e., if $M \in \operatorname{MHM}(Y)$, then $f_\ast M \in \operatorname{MHM}(X)$. So, we get the following by taking $\mathcal{H}^0$ on both sides
  \begin{displaymath}
    \mathcal{H}^0(\mathbb{Q}^H_X [\dim X]) \to f_\ast \mathcal{H}^0(\mathbb{Q}^H_Y
    [\dim Y]). 
  \end{displaymath}
  If we take $\operatorname{gr}^W_{\dim X}$ on both sides, this commutes with
  $f_\ast$ because of the weight spectral sequence (see \cite[Theorem
  4.13]{Kebekus/Schnell:2021} or \cite[Proposition 2.15]{Saito:1990}). Thus, we get a
  natural map
  \begin{displaymath}
    \mathcal{IC}_X^H \simeq \operatorname{gr}^W_{\dim X}
    (\mathcal{H}^0(\mathbb{Q}^H_X [\dim X])) \to f_\ast \operatorname{gr}^W_{\dim
      X}(\mathcal{H}^0(\mathbb{Q}^H_Y [\dim Y])) \simeq f_\ast\mathcal{IC}_Y^H, 
  \end{displaymath}
  which fits in the following commutative diagram
  \begin{displaymath}
