\begin{defi}[Bisectorial operators]
An operator $T\in\mathcal{K}(V)$ is called \textit{bisectorial of angle} $\omega\in(0,\frac{\pi}{2})$, if its $S$-spectrum \eqref{Eq_S_spectrum} is contained in the closed double sector
\begin{equation*}
\sigma_S(T)\subseteq\overline{D_\omega},
\end{equation*}
and for every $\varphi\in(\omega,\frac{\pi}{2})$ there is
\begin{equation}\label{Eq_SL_estimate}
C_\varphi:=\sup\limits_{s\in\mathbb{R}^{n+1}\setminus(D_\varphi\cup\{0\})}|s|\Vert S_L^{-1}(s,T)\Vert<\infty.
\end{equation}
\end{defi}

Next, we define the class of functions for which the following $\omega$-functional calculus is defined.

\begin{defi}\label{defi_N0}
For every $\theta\in(0,\pi)$ let $D_\theta$ be the double sector from \eqref{Eq_Domega}. Then we define the function space
\begin{equation}\label{Eq_N0}
\mathcal{N}^0(D_\theta):=\bigg\{f\in\mathcal{N}(D_\theta)\;\bigg|\;\exists\alpha>0,\,C_\alpha\geq 0: |f(s)|\leq\frac{C_\alpha|s|^\alpha}{1+|s|^{2\alpha}}\bigg\}.
\end{equation}
\end{defi}

Note that this class is a little smaller than the one in \cite[Definition 3.1]{CMS24}. However, in view of the characterization in Theorem~\ref{thm_Quadratic_estimates}, it is enough to consider these classes of functions. In accordance to \cite[Definition 3.5]{CMS24}, we define for those functions the so called \textit{$\omega$-functional calculus}.

\begin{defi}[$\omega$-functional calculus]
Let $T\in\mathcal{K}(V)$ be bisectorial of angle $\omega\in(0,\frac{\pi}{2})$. Then for every $f\in\mathcal{N}^0(D_\theta)$ we define the \textit{$\omega$-functional calculus}
\begin{equation}\label{Eq_omega_functional_calculus}
f(T):=\frac{1}{2\pi}\int_{\partial D_\varphi\cap\mathbb{C}_J}S_L^{-1}(s,T)ds_Jf(s),
\end{equation}
where $\varphi\in(\omega,\theta)$ and $J\in\mathbb{S}$ are arbitrary and the integral \eqref{Eq_omega_functional_calculus} is independent of that choice.
\end{defi}

Note, the the path integral \eqref{Eq_omega_functional_calculus} is understood in the sense
\begin{equation}\label{Eq_omega_parametrized}
f(T)=\frac{1}{2\pi}\sum\limits_\pm\int_{-\infty}^\infty S_L^{-1}(re^{\pm J\varphi},T)\frac{\mp\sgn(r)e^{\pm J\varphi}}{J}f(re^{\pm J\varphi})dr.
\end{equation}
According to \cite[Theorem~3.11]{CMS24}, this $\omega$-functional calculus now satisfies the important product rule
\begin{equation}\label{Eq_Product_rule}
(gf)(T)=g(T)f(T),\qquad g,f\in\mathcal{N}^0(D_\theta),
\end{equation}
which can now be used to enlarge the class of functions \eqref{Eq_N0} for which the functional calculus $f(T)$ is defined. Principally it is possible to allow left and right slice hyperholomorphic functions which are polynomially growing at zero and at infinity, see \cite[Proposition 5.2]{CMS24} and \cite[Definition 4.7]{RIGHT}. However, in this paper we will only concentrate on the following classes of bounded intrinsic functions.

\begin{defi}\label{defi_Ninfty}
For every $\theta\in(0,\frac{\pi}{2})$ let $D_\theta$ be the double sector from \eqref{Eq_Domega}. Then we define the function space of bounded, intrinsic functions
\begin{equation*}
\mathcal{N}^\infty(D_\theta):=\big\{f\in\mathcal{N}(D_\theta)\;\big|\;f\text{ is bounded}\big\}.
\end{equation*}
\end{defi}

In the fashion of \cite[Definition 5.3]{CMS24}, we can then define for those functions the $H^\infty$-functional calculus.

\begin{defi}[$H^\infty$-functional calculus]\label{defi_Hinfty_functional_calculus}
Let $T\in\mathcal{K}(V)$ be injective and bisectorial of angle $\omega\in(0,\frac{\pi}{2})$. Then for every $f\in\mathcal{N}^\infty(D_\theta)$, we define the \textit{$H^\infty$-functional calculus}
\begin{equation}\label{Eq_Hinfty_functional_calculus}
f(T):=e(T)^{-1}(ef)(T),
\end{equation}
where $e(s):=\frac{s}{1+s^2}\in\mathcal{N}^0(D_\theta)$ and the corresponding operator $e(T)$ via \eqref{Eq_omega_functional_calculus} is injective.
\end{defi}

Finally we recall the definition of the adjoint operator in the Clifford setting

\begin{defi}
For every $T\in\mathcal{K}(V)$ with $\overline{\dom}(T)=V$, we define the \textit{adjoint operator} $T^*\in\mathcal{K}(V)$ as the unique operator with the property
\begin{equation*}
\langle T^*w,v\rangle=\langle w,Tv\rangle,\qquad v\in\dom(T),w\in\dom(T^*),
\end{equation*}
and with the domain
\begin{equation*}
\dom(T^*):=\big\{w\in V\;\big|\;\exists v_w\in V: \langle v_w,v\rangle=\langle w,Tv\rangle,\,v\in\dom(T)\big\}.
\end{equation*}
\end{defi}

An important result, which we will need in the sequel, is regarding the $S$-spectrum and the $S$-functional calculus of the adjoint operator. For a proof see \cite{ADJOINT}.

\begin{thm}\label{thm_Adjoint_omega_functional_calculus}
Let $V$ be a Hilbert module and $T\in\mathcal{K}(V)$ be injective and bisectorial of angle $\omega\in(0,\frac{\pi}{2})$. Then also $T^*$ is injective and bisectorial of the same angle $\omega$. Moreover, for every $f\in\mathcal{N}^\infty(D_\theta)$, $\theta\in(\omega,\frac{\pi}{2})$, the $H^\infty$-functional calculus \eqref{Eq_Hinfty_functional_calculus} of $T^*$ connects to the one for $T$ in the sense
\begin{equation*}
f(T^*)=f(T)^*.
\end{equation*}
\end{thm}

\section{Quadratic estimates}\label{sec_Quadratic_estimates}

In the previous section we have now introduced the main definitions regarding the $H^\infty$-functional calculus and the spaces of slice hyperholomorphic functions that we will use. In this section, we will leverage these facts to prove the main results of this paper, which are the characterization of bounded operators defined via the $H^\infty$-functional calculus. \medskip

It is clear from the definition of the $\omega$-functional calculus \eqref{Eq_omega_functional_calculus}, that every $f\in\mathcal{N}^0(D_\theta)$, the operator $f(T)$ is bounded and everywhere defined. This section investigates the question, what happens to the boundedness of the operator $f(T)$, for bounded functions $f\in\mathcal{N}^\infty(D_\theta)$, defined via the unbounded $H^\infty$-functional calculus \eqref{Eq_Hinfty_functional_calculus}. 

\medskip
The central outcome of this section is Theorem~\ref{thm_Quadratic_estimates}, which characterizes the operators $T: \dom(T) \subset V \to V $ for which the functional calculus $f(T)$ is bounded. This theorem is established in the context where $V$ is a Hilbert module. To prove this theorem, we first need to establish several preparatory results.

\begin{lem}\label{lem_Convergence_lemma}
Let $T\in\mathcal{K}(V)$ be bisectorial of angle $\omega\in(0,\frac{\pi}{2})$, and $(f_n)_n\in\mathcal{N}^0(D_\theta)$, for some $\theta\in(\omega,\frac{\pi}{2})$, with
\begin{equation}\label{Eq_Convergence_lemma_boundedness}
M:=\sup\limits_{n\in\mathbb{N}}\Vert f_n\Vert_\infty<\infty\qquad\text{and}\qquad M':=\sup\limits_{n\in\mathbb{N}}\Vert f_n(T)\Vert<\infty.
\end{equation}
Moreover, we assume that there converges
\begin{equation}\label{Eq_Convergence_lemma_convergence}
\lim\limits_{n\rightarrow\infty}f_n=:f,\quad\text{uniformly on compact subsets of }D_\theta.
\end{equation}
Then there is $f\in\mathcal{N}^\infty(D_\theta)$, its $H^\infty$-functional calculus $f(T)\in\mathcal{B}(V)$ is a bounded operator, and there converges
\begin{equation*}
\lim\limits_{n\rightarrow\infty}f_n(T)v=f(T)v,\qquad v\in V.
\end{equation*}
\end{lem}

\begin{proof}
First of all, due to the convergence \eqref{Eq_Convergence_lemma_convergence} and the boundedness \eqref{Eq_Convergence_lemma_boundedness}, there clearly is
\begin{equation*}
|f(s)|=\lim\limits_{n\rightarrow\infty}|f_n(s)|\leq\lim\limits_{n\rightarrow\infty}\Vert f_n\Vert_\infty\leq M,\qquad s\in D_\theta.
\end{equation*}
Since the convergence \eqref{Eq_Convergence_lemma_convergence} is uniform on compact subsets, the limit function is also holomorphic, i.e. we have proven $f\in\mathcal{N}^\infty(D_\theta)$. Let us now consider the regularizer function $e(s)=\frac{s}{1+s^2}$, from Definition~\ref{defi_Hinfty_functional_calculus}. It can now easily be checked that
\begin{equation}\label{Eq_Convergence_lemma_2}
|e(s)|=\frac{|s|}{|1+s^2|}\leq\frac{1}{\cos(\theta)}\frac{|s|}{1+|s|^2},\qquad s\in D_\theta.
\end{equation}
Since $f,(f_n)_n$ are bounded, there is then clearly $ef,(ef_n)_n\in\mathcal{N}^0(D_\theta)$. Consider now some arbitrary $0<a\leq b<\infty$ and $\varphi\in(\omega,\theta)$. Then with the help of the parametrized integral \eqref{Eq_omega_parametrized} and the bound \eqref{Eq_SL_estimate} of the resolvent operator, we can estimate the difference
\begin{align*}
\Vert(ef)&(T)-(ef_n)(T)\Vert \\
&=\frac{1}{2\pi}\bigg\Vert\sum\limits_\pm\int_{-\infty}^\infty S_L^{-1}(re^{\pm J\varphi},T)\frac{\mp\sgn(r)e^{\pm J\varphi}}{J}\big((ef)(re^{\pm J\varphi})-(ef_n)(re^{\pm J\varphi})\big)dr\bigg\Vert \\
&\leq\frac{C_\varphi}{2\pi}\sum_\pm\int_{-\infty}^\infty\big|(ef)(re^{\pm J\varphi})-(ef_n)(re^{\pm J\varphi})\big|\frac{dr}{|r|} \\
&\leq\frac{C_\varphi}{2\pi\cos(\theta)}\sum_\pm\int_{-\infty}^\infty\frac{\big|f(re^{\pm J\varphi})-f_n(re^{\pm J\varphi})\big|}{1+r^2}dr \\
&\leq\frac{2C_\varphi}{\pi\cos(\theta)}\bigg(\int_{(0,a)\cup(b,\infty)}\frac{2M}{1+r^2}dr+\sup\limits_{s\in\overline{D_\varphi},a\leq|s|\leq b}|f(s)-f_n(s)|\int_a^b\frac{1}{1+r^2}dr\bigg).
\end{align*}
On the right hand side we can now use the locally uniform convergence \eqref{Eq_Convergence_lemma_convergence}, to obtain
\begin{equation*}
\limsup\limits_{n\rightarrow\infty}\Vert(ef)(T)-(ef_n)(T)\Vert\leq\frac{4MC_\varphi}{\pi\cos(\theta)}\int_{(0,a)\cup(b,\infty)}\frac{1}{1+r^2}dr.
\end{equation*}
Since moreover $0<a\leq b<\infty$ were arbitrary and the left hand side is independent of $a$ and $b$, we can send $a\rightarrow 0^+$ and $b\rightarrow\infty$, to get
\begin{equation}\label{Eq_Convergence_lemma_3}
\limsup\limits_{n\rightarrow\infty}\Vert(ef)(T)-(ef_n)(T)\Vert\leq\frac{4MC_\varphi}{\pi\cos(\theta)}\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}\int_{(0,a)\cup(b,\infty)}\frac{1}{1+r^2}dr=0.
\end{equation}
By the product rule \eqref{Eq_Product_rule} of the $\omega$-functional calculus, we have
\begin{equation*}
(ef_n)(T)=f_n(T)e(T).
\end{equation*}
However, also for the function $f\in\mathcal{N}^\infty(D_\theta)$, we can use the commutation between $e(T)$ and $(ef)(T)$ from \cite[Corollary~3.18~iii)]{CMS24}, as well as the definition \eqref{Eq_Hinfty_functional_calculus} of the $H^\infty$-functional calculus, to also obtain
\begin{equation*}
(ef)(T)=e(T)^{-1}e(T)(ef)(T)=e(T)^{-1}(ef)(T)e(T)=f(T)e(T).
\end{equation*}
Using these two product rules, the convergence \eqref{Eq_Convergence_lemma_3} becomes
\begin{equation}\label{Eq_Convergence_lemma_4}
\lim\limits_{n\rightarrow\infty}\Vert f(T)w-f_n(T)w\Vert=0,\qquad w\in\ran(e(T)).
\end{equation}
As a direct consequence of this convergence, we obtain from \eqref{Eq_Convergence_lemma_boundedness} the norm estimate
\begin{equation}\label{Eq_Convergence_lemma_5}
\Vert f(T)w\Vert=\lim\limits_{n\rightarrow\infty}\Vert f_n(T)w\Vert\leq\lim\limits_{n\rightarrow\infty}\Vert f_n(T)\Vert\Vert w\Vert\leq M'\Vert w\Vert,\qquad w\in\ran(e(T)).
\end{equation}
Let now $v\in V$. Since
\begin{equation*}
\ran(e(T))=\ran\big(T(1+T^2)^{-1}\big)=\dom(T)\cap\ran(T)
\end{equation*}
is dense in $V$ by \cite[Theorem 3.5]{RIGHT}, there exists a sequence $(v_m)_m\in\ran(e(T))$, which approximates $v=\lim_{m\rightarrow\infty}v_m$. Due to the boundedness \eqref{Eq_Convergence_lemma_5}, also $(f(T)v_m)_m$ is a Cauchy sequence, and hence convergent. Since $f(T)$ is closed, this implies $v\in\dom(f(T))$. Hence we have proven that $\dom(f(T))=V$, and by the closed graph theorem then $f(T)\in\mathcal{B}(V)$. \medskip

Finally, in order to extend the convergence \eqref{Eq_Convergence_lemma_4} to all $v\in V$, we once more use the approximating sequence $(v_m)_m\in\ran(e(T))$ from above. With this sequence, we can estimate
\begin{align*}
\Vert f_n(T)v-f(T)v\Vert&\leq\Vert f_n(T)\Vert\Vert v-v_m\Vert+\Vert f_n(T)v_m-f(T)v_m\Vert+\Vert f(T)\Vert\Vert v_m-v\Vert \\
&\leq(M'+\Vert f(T)\Vert)\Vert v-v_m\Vert+\Vert f_n(T)v_m-f(T)v_m\Vert.
\end{align*}
Since we know that there converges \eqref{Eq_Convergence_lemma_4}, in the limit $n\rightarrow\infty$ this inequality then reduces to
\begin{equation*}
\limsup\limits_{n\rightarrow\infty}\Vert f_n(T)v-f(T)v\Vert\leq(M'+\Vert f(T)\Vert)\Vert v-v_m\Vert.
\end{equation*}
Since $m\in\mathbb{N}$ was chosen arbitrary and the left hand side is independent of $m$, we can also send $m\rightarrow\infty$, and get
\begin{equation*}
\lim\limits_{n\rightarrow\infty}\Vert f_n(T)v-f(T)v\Vert=0,\qquad v\in V. \qedhere
\end{equation*}
\end{proof}

\begin{thm}\label{thm_fab_approximation}
Let $T\in\mathcal{K}(V)$ be bisectorial of angle $\omega\in(0,\frac{\pi}{2})$ and $f\in\mathcal{N}^0(D_\theta)$, $\theta\in(\omega,\frac{\pi}{2})$. Let us define for every $0<a\leq b<\infty$ the function
\begin{equation}\label{Eq_fab}
f_{a,b}(s):=\int_{(-b,-a)\cup(a,b)}f(ts)\frac{dt}{t},\qquad s\in D_\theta.
\end{equation}
Then there is $f_{a,b}\in\mathcal{N}^0(D_\theta)$, and its $\omega$-functional calculus \eqref{Eq_omega_functional_calculus} admits the representation
\begin{equation}\label{Eq_fab_representation}
f_{a,b}(T)=\int_{(-b,-a)\cup(a,b)}f(tT)\frac{dt}{t}.
\end{equation}
Moreover, with the constant $f_{0,\infty}:=\int_{-\infty}^\infty f(t)\frac{dt}{t}$, there converges
\begin{equation}\label{Eq_fab_convergence}
\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}f_{a,b}(T)v=f_{0,\infty}v,\qquad v\in V.
\end{equation}
\end{thm}

\begin{proof}
Since the domain of integration $(-a,-b)\cup(a,b)$ is bounded, it is clear that the integral \eqref{Eq_fab} gives an intrinsic function $f_{a,b}$. In order to show that $f_{a,b}\in\mathcal{N}^0(D_\theta)$, we estimate
\begin{equation}\label{Eq_fab_approximation_1}
|f_{a,b}(s)|\leq\int_{(-b,-a)\cup(a,b)}|f(ts)|\frac{dt}{|t|}\leq 2C_\alpha\int_a^b\frac{|ts|^\alpha}{1+|ts|^{2\alpha}}\frac{dt}{t}.
\end{equation}
Using now the maximum value
\begin{equation}\label{Eq_fab_approximation_3}
\sup\limits_{t>0}\frac{t^\alpha|ts|^\alpha}{(1+t^{2\alpha})(1+|ts|^{2\alpha})}=\frac{|s|^\alpha}{(1+|s|^\alpha)^2}\leq\frac{|s|^\alpha}{1+|s|^{2\alpha}},
\end{equation}
which is attained at $t=|s|^{-\frac{1}{2}}$, we can further estimate \eqref{Eq_fab_approximation_1} by
\begin{equation*}
|f_{a,b}(s)|\leq\frac{2C_\alpha|s|^\alpha}{1+|s|^{2\alpha}}\int_a^b\frac{1+t^{2\alpha}}{t^\alpha}\frac{dt}{t},\qquad s\in D_\theta.
\end{equation*}
Since $0<a\leq b<\infty$, the integral is finite and we have shown that $f_{a,b}\in\mathcal{N}^0(D_\theta)$. The representation \eqref{Eq_fab_representation} then follows directly from the definition of the $\omega$-functional calculus
\begin{align}
f_{a,b}(T)&=\frac{1}{2\pi}\int_{\partial D_\varphi\cap\mathbb{C}_J}S_L^{-1}(s,T)ds_Jf_{a,b}(s) \notag \\
&=\frac{1}{2\pi}\int_{(-b,-a)\cup(a,b)}\int_{\partial D_\varphi\cap\mathbb{C}_J}S_L^{-1}(s,T)ds_Jf(ts)\frac{dt}{t} \notag \\
&=\frac{1}{2\pi}\int_{(-b,-a)\cup(a,b)}\int_{\partial D_\varphi\cap\mathbb{C}_J}S_L^{-1}(s,tT)ds_Jf(s)\frac{dt}{t}=\int_{(-b,-a)\cup(a,b)}f(tT)\frac{dt}{t}, \label{Eq_fab_approximation_4}
\end{align}
where in the third equation we substituted $s\to\frac{s}{t}$ and used the identity
\begin{equation}\label{Eq_fab_approximation_2}
\frac{1}{t}S_L^{-1}\Big(\frac{s}{t},T\Big)=S_L^{-1}(s,tT),\qquad s\in D_\theta,\,t\in\mathbb{R}\setminus\{0\}.
\end{equation}
For the convergence \eqref{Eq_fab_convergence}, we will verify the assumptions of Lemma~\ref{lem_Convergence_lemma} for the functions $f_{a,b}$. To do so, we continue estimating \eqref{Eq_fab_approximation_1} in a different way, namely as
\begin{equation*}
|f_{a,b}(s)|\leq 2C_\alpha\int_0^\infty\frac{|ts|^\alpha}{1+|ts|^{2\alpha}}\frac{dt}{t}=\frac{C_\alpha\pi}{\alpha},\qquad s\in D_\theta.
\end{equation*}
which shows that the first supremum in \eqref{Eq_Convergence_lemma_boundedness} is finite. The more challenging part is the finiteness of the second supremum in \eqref{Eq_Convergence_lemma_boundedness}. To prove this, let us first show that the constant $f_{0,\infty}:=\int_{-\infty}^\infty f(t)\frac{dt}{t}$ can be written as
\begin{equation}\label{Eq_fab_approximation_5}
f_{0,\infty}=\int_{-\infty}^\infty f(ts)\frac{dt}{t},\qquad s\in D_\theta.
\end{equation}
If we write $s=re^{J\varphi}$ for some $r>0$, $J\in\mathbb{S}$, $\varphi\in I_\theta$, we can substitute $t\rightarrow\frac{t}{r}$, and rewrite
\begin{equation*}
\int_{-\infty}^\infty f(ts)\frac{dt}{t}=\int_{-\infty}^\infty f(tre^{J\varphi})\frac{dt}{t}=\int_{-\infty}^\infty f(te^{J\varphi})\frac{dt}{t}=\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}\bigg(\int_{-b}^{-a}+\int_a^b\bigg)f(te^{J\varphi})\frac{dt}{t}.
\end{equation*}
Using now the Cauchy theorem, we can change the integration path according to \medskip

