\begin{equation}\label{Eq_fab_approximation_6}
\int_{-\infty}^\infty f(ts)\frac{dt}{t}=\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}\bigg(\int_{-be^{J\varphi}}^{-b}+\int_{-b}^{-a}+\int_{-a}^{-ae^{J\varphi}}+\int_{ae^{J\varphi}}^a+\int_a^b+\int_b^{be^{J\varphi}}\bigg)\frac{f(p)}{p}dp.
\end{equation}
In the limit $b\rightarrow\infty$, the first integral in \eqref{Eq_fab_approximation_6} converges as
\begin{equation*}
\bigg|\int_{-be^{J\varphi}}^{-b}\frac{f(p)}{p}dp\bigg|=\bigg|\int_0^\varphi f(-be^{J\phi})d\phi\bigg|\leq\frac{C_\alpha b^\alpha|\varphi|}{1+b^{2\alpha}}\overset{b\rightarrow\infty}{\longrightarrow}0.
\end{equation*}
Analogously, there also vanish the third, fourth and sixth integral in \eqref{Eq_fab_approximation_6}, namely
\begin{equation*}
\lim\limits_{a\rightarrow 0^+}\int_{-a}^{-ae^{J\varphi}}\frac{f(p)}{p}dp=0,\qquad\lim\limits_{a\rightarrow 0^+}\int_{ae^{J\varphi}}^a\frac{f(p)}{p}dp=0,\qquad\lim\limits_{b\rightarrow\infty}\int_b^{be^{J\varphi}}\frac{f(p)}{p}dp=0.
\end{equation*}
These four vanishing limits, reduce the equation \eqref{Eq_fab_approximation_6} to the stated representation \eqref{Eq_fab_approximation_5}
\begin{equation*}
\int_{-\infty}^\infty f(ts)\frac{dt}{t}=\int_{-\infty}^\infty\frac{f(p)}{p}dp=f_{0,\infty}.
\end{equation*}
With respect to the constant $f_{0,\infty}$, we now split the function $f_{a,b}$ in \eqref{Eq_fab} into the three parts
\begin{equation}\label{Eq_fab_approximation_7}
f_{a,b}(s)=\underbrace{\frac{f_{0,\infty}(as)^2}{1+(as)^2}-\int_{-a}^af(ts)\frac{dt}{t}}_{=:f_{a,b}^{(1)}(s)}+\underbrace{\int_{-b}^bf(ts)\frac{dt}{t}-\frac{f_{0,\infty}(bs)^2}{1+(bs)^2}}_{=:f_{a,b}^{(2)}(s)}+\underbrace{\frac{f_{0,\infty}(b^2-a^2)s^2}{(1+(as)^2)(1+(bs)^2)}}_{=:f_{a,b}^{(3)}(s)}.
\end{equation}
Using the upper bounds \eqref{Eq_Convergence_lemma_2} and a similar estimate as in \eqref{Eq_fab_approximation_1}, we obtain
\begin{align}
|f_{a,b}^{(1)}(s)|&\leq\frac{|f_{0,\infty}||as|^2}{|1+(as)^2|}+2C_\alpha\int_0^a\frac{|ts|^\alpha}{1+|ts|^{2\alpha}}\frac{dt}{t} \notag \\
&\leq\frac{|f_{0,\infty}||as|^2}{\cos(\theta)(1+|as|^2)}+2C_\alpha\int_0^a|ts|^\alpha\frac{dt}{t} \notag \\
&=\frac{|f_{0,\infty}||as|^2}{\cos(\theta)(1+|as|^2)}+\frac{2C_\alpha|as|^\alpha}{\alpha}\leq\Big(\frac{|f_{0,\infty}|}{\cos(\theta)}+\frac{2C_\alpha}{\alpha}\Big)|as|^{\min\{\alpha,2\}},\qquad |s|\leq\frac{1}{a}. \label{Eq_fab_approximation_12}
\end{align}
Moreover, we can use the representation \eqref{Eq_fab_approximation_5} of $f_{0,\infty}$ to rewrite $f_{a,b}^{(1)}(s)$ as
\begin{equation*}
f_{a,b}^{(1)}(s)=\frac{f_{0,\infty}(as)^2}{1+(as)^2}-f_{0,\infty}+\int_{\mathbb{R}\setminus(-a,a)}f(ts)\frac{dt}{t}=-\frac{f_{0,\infty}}{1+(as)^2}+\int_{\mathbb{R}\setminus(-a,a)}f(ts)\frac{dt}{t}.
\end{equation*}
Consequently, we can analogously to \eqref{Eq_fab_approximation_12}, also estimate $f_{a,b}^{(1)}(s)$ by
\begin{align}
|f_{a,b}^{(1)}(s)|&\leq\frac{|f_{0,\infty}|}{|1+(as)^2|}
+2C_\alpha\int_a^\infty\frac{|ts|^\alpha}{1+|ts|^{2\alpha}}\frac{dt}{t} \notag \\
&\leq\frac{|f_{0,\infty}|}{\cos(\theta)(1+|as|^2)}
+2C_\alpha\int_a^\infty\frac{1}{|ts|^\alpha}\frac{dt}{|t|} \notag \\
&=\frac{|f_{0,\infty}|}{\cos(\theta)(1+|as|^2)}+\frac{2C_\alpha}{\alpha|as|^\alpha}\leq\Big(\frac{|f_{0,\infty}|}{\cos(\theta)}+\frac{2C_\alpha}{\alpha}\Big)\frac{1}{|as|^{\min\{\alpha,2\}}},\qquad|s|\geq\frac{1}{a}. \label{Eq_fab_approximation_13}
\end{align}
The two estimates \eqref{Eq_fab_approximation_12} and \eqref{Eq_fab_approximation_13} now on the one hand show that $f_{a,b}^{(1)}\in\mathcal{N}^0(S_\theta)$, and if we choose some arbitrary $\varphi\in(\omega,\theta)$ and $J\in\mathbb{S}$, it can also be used to estimate the operator norm of $f_{a,b}^{(1)}(T)$ by
\begin{align}
\Vert f_{a,b}^{(1)}(T)\Vert&=\frac{1}{2\pi}\bigg\Vert\sum\limits_\pm\int_{-\infty}^\infty S_L^{-1}(re^{\pm J\varphi},T)\frac{\mp\sgn(r)e^{\pm J\varphi}}{J}f_{a,b}^{(1)}(re^{\pm J\varphi})dr\bigg\Vert \notag \\
&\leq\frac{C_\varphi}{2\pi}\sum\limits_\pm\int_{-\infty}^\infty|f_{a,b}^{(1)}(re^{\pm J\varphi})|\frac{dr}{|r|} \notag \\
&\leq\frac{C_\varphi}{\pi}\Big(\frac{|f_{0,\infty}|}{\cos(\theta)}+\frac{2C_\alpha}{\alpha}\Big)\bigg(\int_{-\frac{1}{a}}^{\frac{1}{a}}|ar|^{\min\{\alpha,2\}}\frac{dr}{|r|}+\int_{\mathbb{R}\setminus(-\frac{1}{a},\frac{1}{a})}\frac{1}{|ar|^{\min\{\alpha,2\}}}\frac{dr}{|r|}\bigg) \notag \\
&=\frac{2C_\varphi}{\pi\min\{\alpha,2\}}\Big(\frac{|f_{0,\infty}|}{\cos(\theta)}+\frac{2C_\alpha}{\alpha}\Big). \label{Eq_fab_approximation_8}
\end{align}
Analogously, we show that $f_{a,b}^{(2)}\in\mathcal{N}^0(S_\theta)$, and that the operator norm of $f_{a,b}^{(2)}(T)$ is bound by
\begin{equation}\label{Eq_fab_approximation_9}
\Vert f_{a,b}^{(2)}(T)\Vert\leq\frac{2C_\varphi}{\pi\min\{\alpha,2\}}\Big(\frac{|f_{0,\infty}|}{\cos(\theta)}+\frac{2C_\alpha}{\alpha}\Big).
\end{equation}
Finally, for the function $f_{a,b}^{(3)}$ in \eqref{Eq_fab_approximation_7}, it is clear that $f_{a,b}^{(3)}\in\mathcal{N}^0(S_\theta)$. By the polynomial functional calculus \cite[Theorem 3.16]{CMS24}, we can explicitly write the operator $f_{a,b}^{(3)}(T)$ as
\begin{align*}
f_{a,b}^{(3)}(T)&=f_{0,\infty}(b^2-a^2)T^2(1+a^2T^2)^{-1}(1+b^2T^2)^{-1} \\
&=f_{0,\infty}\big((1+a^2T^2)^{-1}-(1+b^2T^2)^{-1}\big) \\
&=f_{0,\infty}\Big(\frac{1}{a^2}Q_{\frac{J}{a}}[T]^{-1}-\frac{1}{b^2}Q_{\frac{J}{b}}[T]^{-1}\Big),
\end{align*}
where in the last line we used the pseudo resolvent operator \eqref{Eq_Qs} and some arbitrary imaginary unit $J\in\mathbb{S}$. In this representation we can now use the norm bound \cite{RIGHT}, for example with the arbitrary angle $\varphi\in(\omega,\theta)$ from above, to estimate
\begin{equation}\label{Eq_fab_approximation_10}
\Vert f_{a,b}^{(3)}(T)\Vert\leq|f_{0,\infty}|\bigg(\frac{1}{a^2}\frac{2C_\varphi^2}{\frac{1}{a^2}}+\frac{1}{b^2}\frac{2C_\varphi^2}{\frac{1}{b^2}}\bigg)=4|f_{0,\infty}|C_\varphi^2.
\end{equation}
If we now combine the three estimates \eqref{Eq_fab_approximation_8}, \eqref{Eq_fab_approximation_9} and \eqref{Eq_fab_approximation_10}, we end up with the estimate of the full operator
\begin{equation*}
\Vert f_{a,b}(T)\Vert\leq\frac{4C_\varphi}{\pi\min\{\alpha,2\}}\Big(\frac{|f_{0,\infty}|}{\cos(\theta)}+\frac{2C_\alpha}{\alpha}\Big)+4|f_{0,\infty}|C_\varphi^2.
\end{equation*}
Since the right hand side is independent of $0<a\leq b<\infty$, we have proven the finiteness of the second supremum in \eqref{Eq_Convergence_lemma_boundedness}. \medskip

Finally, with the representation \eqref{Eq_fab_approximation_5} of the constant $f_{0,\infty}$, we can estimate
\begin{align*}
|f_{a,b}(s)-f_{0,\infty}|&=\bigg|\int_{-a}^af(ts)\frac{dt}{t}+\int_{\mathbb{R}\setminus(-b,b)}f(ts)\frac{dt}{t}\bigg| \\
&\leq 2C_\alpha\int_0^a\frac{|ts|^\alpha}{1+|ts|^{2\alpha}}\frac{dt}{t}+2C_\alpha\int_b^\infty\frac{|ts|^\alpha}{1+|ts|^{2\alpha}}\frac{dt}{t} \\
&=\frac{2C_\alpha}{\alpha}\Big(\arctan(|as|^\alpha)+\frac{\pi}{2}-\arctan(|bs|^\alpha)\Big),\qquad s\in D_\theta.
\end{align*}
Hence we conclude that there converges
\begin{equation*}
\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}f_{a,b}(s)=f_{0,\infty},\quad\text{uniformly on compact subsets of }D_\theta.
\end{equation*}
Hence, all the assumptions of Lemma~\ref{lem_Convergence_lemma} are satisfied and there follows the convergence
\begin{equation*}
\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}f_{a,b}(T)v=f_{0,\infty}(T)v=f_{0,\infty}v,\qquad v\in V,
\end{equation*}
where in the last equation we used that the $H^\infty$-functional calculus $f_{0,\infty}(T)$ of the constant function is the multiplication with the respective constant $f_{0,\infty}$, see \cite[Theorem 5.9]{CMS24}.
\end{proof}

\begin{lem}\label{lem_fg_estimates}
Let $T\in\mathcal{K}(V)$ be bisectorial of angle $\omega\in(0,\frac{\pi}{2})$ and $f,g\in\mathcal{N}^0(D_\theta)$, $\theta\in(\omega,\frac{\pi}{2})$. Then there holds the following estimates: \medskip

\begin{enumerate}
\item[i)] $\Vert f(tT)g(\tau T)\Vert\leq\frac{C_\theta C_\alpha}{\alpha}\Vert g\Vert_\infty$,\hspace{1.45cm} $t,\tau\in\mathbb{R}\setminus\{0\}$; \medskip

\item[ii)] $\int_{-\infty}^\infty\Vert f(tT)g(\tau T)\Vert\frac{dt}{|t|}\leq\frac{C_\theta C_\alpha C_\beta\pi}{2\alpha\beta}$,\qquad $\tau\in\mathbb{R}\setminus\{0\}$; \medskip

\item[iii)] For every function $\Psi\in L^2(\mathbb{R},\frac{dt}{|t|})$, there is
\begin{equation}\label{Eq_fg_estimate}
\int_{-\infty}^\infty\bigg(\int_{-\infty}^\infty\Vert f(tT)g(\tau T)\Vert|\Psi(t)|\frac{dt}{|t|}\bigg)^2\frac{d\tau}{|\tau|}\leq\Big(\frac{C_\theta C_\alpha C_\beta\pi}{2\alpha\beta}\Big)^2\int_{-\infty}^\infty|\Psi(t)|^2\frac{dt}{|t|}.
\end{equation}
\end{enumerate}
Here $C_\theta\geq 0$ is the constant from \eqref{Eq_SL_estimate}, and $\alpha>0$, $C_\alpha\geq 0$ (resp. $\beta>0$, $C_\beta\geq 0$) are the constants from Definition~\ref{defi_N0} of the function $f$ (resp. $g$).
\end{lem}

\begin{proof}
Before we start with the actual proof of i), ii), and iii), let us first note that for every fixed $t\in\mathbb{R}\setminus\{0\}$, the estimate \eqref{Eq_fab_approximation_3} shows that the function $s\mapsto f(ts)$ is an element in $\mathcal{N}^0(D_\theta)$. The $\omega$-functional calculus \eqref{Eq_omega_functional_calculus} of this function is then given by
\begin{equation}\label{Eq_fg_estimates_3}
f(t\,\cdot\,)(T)=\frac{1}{2\pi}\int_{\partial D_\varphi\cap\mathbb{C}_J}S_L^{-1}(s,T)ds_Jf(ts)=\frac{1}{2\pi}\int_{\partial D_\varphi\cap\mathbb{C}_J}S_L^{-1}(s,tT)ds_Jf(s)=f(tT),
\end{equation}
where in the second equation we substituted $s\mapsto\frac{s}{t}$ and used the identity \eqref{Eq_fab_approximation_2}. \medskip

i)\;\;First, we use the representation \eqref{Eq_fg_estimates_3} and the product rule \eqref{Eq_Product_rule}, to combine the functions
\begin{equation*}
f(tT)g(\tau T)=f(t\,\cdot\,)(T)g(\tau\,\cdot\,)(T)=\big(f(t\,\cdot\,)g(\tau\,\cdot\,)\big)(T).
\end{equation*}
For some arbitrary $\varphi\in(\omega,\theta)$, we can now use the parametrized formula \eqref{Eq_omega_parametrized} of the $\omega$-functional calculus, to estimate
\begin{align}
\Vert f(tT)g(\tau T)\Vert&=\frac{1}{2\pi}\bigg\Vert\sum\limits_\pm\int_{-\infty}^\infty S_L^{-1}(re^{\pm J\varphi},T)\frac{\mp\sgn(r)e^{\pm J\varphi}}{J}f(tre^{\pm J\varphi})g(\tau re^{\pm J\varphi})dr\bigg\Vert \notag \\
&\leq\frac{C_\varphi}{2\pi}\sum\limits_\pm\int_{-\infty}^\infty|f(tre^{\pm J\varphi})||g(\tau re^{\pm J\varphi})|\frac{dr}{|r|} \label{Eq_fg_estimates_1} \\
&\leq\frac{C_\varphi C_\alpha}{2\pi}\Vert g\Vert_\infty\sum\limits_\pm\int_{-\infty}^\infty\frac{|tr|^\alpha}{1+|tr|^{2\alpha}}\frac{dr}{|r|}=\frac{C_\varphi C_\alpha}{\alpha}\Vert g\Vert_\infty. \notag
\end{align}
Since it is clear by \eqref{Eq_SL_estimate} that $\varphi\mapsto C_\varphi$ is monotone decreasing, we can take the limit $\varphi\rightarrow\theta$ of the right hand side, and obtain the stated inequality i). \medskip

ii)\;\;Using the second line in the inequality \eqref{Eq_fg_estimates_1}, and integrate it over $\int_{-\infty}^\infty\frac{dt}{|t|}$, gives
\begin{align*}
\int_{-\infty}^\infty\Vert f(tT)g(\tau T)\Vert\frac{dt}{|t|}&\leq\frac{C_\varphi}{2\pi}\sum\limits_\pm\int_{-\infty}^\infty\int_{-\infty}^\infty|f(tre^{\pm J\varphi})||g(\tau re^{\pm J\varphi})|\frac{dr}{|r|}\frac{dt}{|t|} \\
&\leq\frac{C_\varphi C_\alpha C_\beta}{2\pi}\sum\limits_\pm\int_{-\infty}^\infty\int_{-\infty}^\infty\frac{|tr|^\alpha|\tau r|^\beta}{(1+|tr|^{2\alpha})(1+|\tau r|^{2\beta})}\frac{dr}{|r|}\frac{dt}{|t|} \\
&=\frac{C_\varphi C_\alpha C_\beta}{\alpha}\int_{-\infty}^\infty\frac{|\tau r|^\beta}{1+|\tau r|^{2\beta}}\frac{dr}{|r|}=\frac{C_\varphi C_\alpha C_\beta\pi}{2\alpha\beta}.
\end{align*}
Taking again the limit $\varphi\rightarrow\theta$, gives the estimate ii). \medskip

iii) Using Hölder's inequality together and the already proven inequality ii), gives
\begin{align*}
\int_{-\infty}^\infty\bigg(\int_{-\infty}^\infty&\Vert f(tT)g(\tau T)\Vert|\Psi(t)|\frac{dt}{|t|}\bigg)^2\frac{d\tau}{|\tau|} \\
&\leq\int_{-\infty}^\infty\bigg(\int_{-\infty}^\infty\Vert f(tT)g(\tau T)\Vert\frac{dt}{|t|}\bigg)\bigg(\int_{-\infty}^\infty\Vert f(tT)g(\tau T)\Vert|\Psi(t)|^2\frac{dt}{|t|}\bigg)\frac{d\tau}{|\tau|} \\
&\leq\frac{C_\theta C_\alpha C_\beta\pi}{2\alpha\beta}\int_{-\infty}^\infty\int_{-\infty}^\infty\Vert f(tT)g(\tau T)\Vert\frac{d\tau}{|\tau|}|\Psi(t)|^2\frac{dt}{|t|} \\
&\leq\Big(\frac{C_\theta C_\alpha C_\beta\pi}{2\alpha\beta}\Big)^2\int_0^\infty|\Psi(t)|^2\frac{dt}{|t|}. \qedhere
\end{align*}
\end{proof}

\begin{prop}\label{prop_f_infty_estimate}
Let $T\in\mathcal{K}(V)$ be injective and bisectorial of angle $\omega\in(0,\frac{\pi}{2})$. Then for every $g\in\mathcal{N}^0(D_\theta)$, $\theta\in(\omega,\frac{\pi}{2})$, there exists a constant $C_g\geq 0$, such that
\begin{equation}\label{Eq_f_infty_estimate}
\int_{-\infty}^\infty\Vert g(tT)f(T)v\Vert^2\frac{dt}{|t|}\leq C_g^2\Vert f\Vert_\infty^2\int_{-\infty}^\infty\Vert g(tT)v\Vert^2\frac{dt}{|t|},\qquad f\in\mathcal{N}^0(D_\theta),\,v\in V.
\end{equation}
\end{prop}

\begin{proof}
Since the opposite cases are trivial, we will assume $g\not\equiv 0$ and
\begin{equation}\label{Eq_f_infty_estimate_3}
\int_{-\infty}^\infty\Vert g(tT)v\Vert^2\frac{dt}{|t|}<\infty.
\end{equation}
Let us fix $0<a\leq b<\infty$, and with $e(s)=\frac{s}{1+s^2}$, we consider the function $(eg^2)_{a,b}$ from \eqref{Eq_fab}. Using the representation \eqref{Eq_fab_representation} of $(eg^2)_{a,b}(T)$, we then estimate
\begin{align*}
\int_{-\infty}^\infty\Vert g(tT)(eg^2)_{a,b}(T)f(T)v&\Vert^2\frac{dt}{|t|}=\int_{-\infty}^\infty\bigg\Vert g(tT)\int_{(-b,-a)\cup(a,b)}(eg^2)(\tau T)\frac{d\tau}{\tau}f(T)v\bigg\Vert^2\frac{dt}{|t|} \\
&\leq\int_{-\infty}^\infty\bigg(\int_{(-b,-a)\cup(a,b)}\Vert g(tT)g(\tau T)\Vert\Vert(eg)(\tau T)f(T)v\Vert\frac{d\tau}{|\tau|}\bigg)^2\frac{dt}{|t|} \\
&\leq\frac{C_\theta^2\Vert f\Vert_\infty^2}{\cos^2(\theta)}\int_{-\infty}^\infty\bigg(\int_{(-b,-a)\cup(a,b)}\Vert g(tT)g(\tau T)\Vert\Vert g(\tau T)v\Vert\frac{d\tau}{|\tau|}\bigg)^2\frac{dt}{|t|},
\end{align*}
where in the last line we commuted $g(\tau T)$ and $f(T)$, which is allowed by \cite[Corollary 3.18]{CMS24}, and used Lemma~\ref{lem_fg_estimates}~i) together with \eqref{Eq_Convergence_lemma_2}, in order to estimates $e(\tau T)f(T)$. Using now also the inequality \eqref{Eq_fg_estimate} with the function $\Psi(\tau)=\Vert g(\tau T)v\Vert\mathds{1}_{(-b,-a)\cup(a,b)}(\tau)$, we furthermore get
\begin{equation}\label{Eq_f_infty_estimate_1}
\int_{-\infty}^\infty\Vert g(tT)(eg^2)_{a,b}(T)f(T)v\Vert^2\frac{dt}{|t|}\leq\Big(\frac{C_\theta^2C_\beta^2\pi}{2\cos(\theta)\beta^2}\Big)^2\Vert f\Vert_\infty^2\int_{(-b,-a)\cup(a,b)}\Vert g(\tau T)v\Vert^2\frac{d\tau}{|\tau|}.
\end{equation}
Let us now choose two monotone sequences $a_n\rightarrow 0^+$, $b_n\rightarrow\infty$. Then by \eqref{Eq_fab_convergence}, there converges
\begin{equation}\label{Eq_f_infty_estimate_2}
\lim\limits_{n\rightarrow\infty}g(tT)(eg^2)_{a_n,b_n}(T)f(T)v=g(tT)(eg^2)_{0,\infty}f(T)v,\qquad t\in\mathbb{R}\setminus\{0\}.
\end{equation}
In order to show that this limit converges also in $L^2(\mathbb{R},\frac{dt}{|t|})$, we analogously to \eqref{Eq_f_infty_estimate_1} show that for any $m\geq n$ there holds the estimate
\begin{align*}
\int_{-\infty}^\infty\Vert g(tT)&\big((eg^2)_{a_n,b_n}(T)-(eg^2)_{a_m,b_m}(T)\big)f(T)v\Vert^2\frac{dt}{|t|} \\
&\leq\Big(\frac{C_\theta^2C_\beta^2\pi}{2\cos(\theta)\beta^2}\Big)^2\Vert f\Vert_\infty^2\int_{(-b_m,-b_n)\cup(-a_n,-a_m)\cup(a_m,a_n)\cup(b_n,b_m)}\Vert g(\tau T)v\Vert^2\frac{d\tau}{|\tau|}.
\end{align*}
Since $\int_{-\infty}^\infty\Vert g(\tau T)v\Vert^2\frac{d\tau}{|\tau|}<\infty$ is finite by the assumption \eqref{Eq_f_infty_estimate_3}, this estimate shows that the sequence of mappings
\begin{equation*}
t\mapsto g(tT)(eg^2)_{a_n,b_n}(T)f(T)v,
\end{equation*}
is a Cauchy-sequence in the space $L^2(\mathbb{R},\frac{dt}{|t|})$. Consequently, this sequence converges in $L^2(\mathbb{R},\frac{dt}{|t|})$ to its pointwise limit \eqref{Eq_f_infty_estimate_2}. In particular there converges the $L^2$-norms
\begin{equation}\label{Eq_f_infty_estimate_4}
\lim\limits_{n\rightarrow\infty}\int_{-\infty}^\infty\Vert g(tT)(eg^2)_{a_n,b_n}(T)f(T)v\Vert^2\frac{dt}{|t|}=(eg^2)_{0,\infty}^2\int_{-\infty}^\infty\Vert g(tT)f(T)v\Vert^2\frac{dt}{|t|}.
\end{equation}
Performing now the limit $n\rightarrow\infty$ in \eqref{Eq_f_infty_estimate_1}, and considering that the limit of the left hand side is given by \eqref{Eq_f_infty_estimate_4}, we get
\begin{align*}
(eg^2)_{0,\infty}^2\int_{-\infty}^\infty\Vert g(tT)f(T)v\Vert^2\frac{dt}{|t|}&\leq\Big(\frac{C_\theta^2C_\beta^2\pi}{2\cos(\theta)\beta^2}\Big)^2\Vert f\Vert_\infty^2\lim\limits_{n\rightarrow\infty}\int_{(-b_n,-a_n)\cup(a_n,b_n)}\Vert g(\tau T)v\Vert^2\frac{d\tau}{|\tau|} \\
&=\Big(\frac{C_\theta^2C_\beta^2\pi}{2\cos(\theta)\beta^2}\Big)^2\Vert f\Vert_\infty^2\int_{-\infty}^\infty\Vert g(\tau T)v\Vert^2\frac{d\tau}{|\tau|}.
\end{align*}
Finally, since we assumed $g\not\equiv 0$ and since $g(t)\in\mathbb{R}$ because $g$ is intrinsic, the value
\begin{equation*}
(eg^2)_{0,\infty}=\int_{-\infty}^\infty\frac{g(t)^2}{1+t^2}dt>0,
\end{equation*}
from \eqref{Eq_fab_approximation_5}, is positive, and we have proven \eqref{Eq_f_infty_estimate} with the constant $C_g=\frac{C_\theta^2C_\beta^2\pi}{2\cos(\theta)\beta^2(eg^2)_{0,\infty}}$.
\end{proof}

\begin{lem}\label{lem_Psieps}
Let $\Psi:\mathbb{R}\rightarrow V$ be a continuous function. Then for every $\varepsilon>0$ there exists a Borel measurable function $\Psi_\varepsilon:\mathbb{R}\rightarrow V$, such that for every $t\in\mathbb{R}$, there is \medskip

\begin{enumerate}
\item[i)] $\Vert\Psi_\varepsilon(t)\Vert=\Vert\Psi(t)\Vert$, \medskip

\item[ii)] $\Vert\Psi(t)\Vert^2\leq(1+\varepsilon)\Sc\langle\Psi(t),\Psi_\varepsilon(t)\rangle$.
\end{enumerate}
\end{lem}

\begin{proof}
It is clear that for every $t\in\mathbb{R}$ there is
\begin{equation*}
\Vert\Psi(t)\Vert=\sup_{\Vert v\Vert=1}|\Sc\langle\Psi(t),v\rangle|.
\end{equation*}
Hence there exists some $v_t\in V$, with
\begin{equation}\label{Eq_Psieps_1}
\Vert v_t\Vert=1\qquad\text{and}\qquad\Vert\Psi(t)
\Vert\leq\Big(1+\frac{\varepsilon}{2}\Big)|\Sc\langle\Psi(t),v_t\rangle|.
\end{equation}
Let us consider $I_0:=\big\{t\in\mathbb{R}\;\big|\;\Psi(t)=0\big\}$, and define
\begin{equation}\label{Eq_Psieps_2}
\Psi_\varepsilon(t):=0,\qquad t\in I_0.
\end{equation}
Then it is clear that the assertions i), ii) are satisfied for every $t\in I_0$. \medskip

Next, consider $t\in\mathbb{R}\setminus I_0$. First, we can rewrite the inequality \eqref{Eq_Psieps_1} as
\begin{equation*}
\frac{|\Sc\langle\Psi(t),v_t\rangle|}{\Vert\Psi(t)\Vert}\geq\frac{1}{1+\frac{\varepsilon}{2}}.
\end{equation*}
Since $\Psi$ is continuous, also the mapping $t'\mapsto\frac{|\Sc\langle\Psi(t'),v_t\rangle|}{\Vert\Psi(t')\Vert}$ is continuous on the open set $\mathbb{R}\setminus I_0$. Hence, there exists some $\delta_t>0$, such that
\begin{equation*}
\frac{|\Sc\langle\Psi(t'),v_t\rangle|}{\Vert\Psi(t')\Vert}\geq\frac{1}{1+\varepsilon},\qquad t'\in(t-\delta_t,t+\delta_t).
\end{equation*}
Now, the sets $(t-\delta_t,t+\delta_t)$, $t\in\mathbb{R}\setminus I_0$, form an open cover of $\mathbb{R}\setminus I_0$. Since $\mathbb{R}\setminus I_0$ is a Lindelöf space, there exists a countable subcover
\begin{equation*}
\mathbb{R}\setminus I_0=\bigcup\nolimits_{n\in\mathbb{N}}(t_n-\delta_{t_n},t_n+\delta_{t_n}).
\end{equation*}
Setting now
\begin{equation*}
I_1:=(t_1-\delta_{t_1},t_1+\delta_{t_1})\qquad\text{and}\qquad I_n:=(t_n-\delta_{t_n},t_n+\delta_{t_n})\setminus\bigcup\nolimits_{k=1}^{n-1}I_k,\qquad n\geq 2,
\end{equation*}
we obtain a family of disjoint Borel sets, with the property
\begin{equation*}
I=\biguplus\nolimits_{n=1}^\infty I_n\qquad\text{and}\qquad\Vert\Psi(t)\Vert\leq(1+\varepsilon)|\Sc\langle\Psi(t),v_{t_n}\rangle|,\qquad t\in I_n.
\end{equation*}
If we now define
\begin{equation*}
\Phi_\varepsilon(t):=\Vert\Psi(t)\Vert v_{t_n},\qquad t\in I_n,
\end{equation*}
this function satisfies
\begin{equation*}
\Vert\Phi_\varepsilon(t)\Vert=\Vert\Psi(t)\Vert\qquad\text{and}\qquad\Vert\Psi(t)\Vert^2\leq(1+\varepsilon)|\Sc\langle\Psi(t),\Phi_\varepsilon(t)\rangle|,\qquad t\in I_n.
\end{equation*}
If we now choose
\begin{equation}\label{Eq_Psieps_4}
\Psi_\varepsilon(t):=\sgn\big(\Sc\langle\Psi(t),\Phi_\varepsilon(t)\rangle\big)\Phi_\varepsilon(t),\qquad t\in I_n,
\end{equation}
this function $\Psi_\varepsilon(t)$ satisfies both stated properties i), ii). \medskip

Altogether, since $\mathbb{R}=I_0\uplus\biguplus_{n=1}^\infty I_n$, we have defined in \eqref{Eq_Psieps_2} and \eqref{Eq_Psieps_4} the function $\Psi_\varepsilon$ for every $t\in(0,\infty)$ and the lemma is proven.
\end{proof}

Consider now the group $\mathbb{Z}_2=\{-1,1\}$ equipped with the classical multiplication of real numbers and the discrete topology, i.e. the topology where every subset of $\{-1,1\}$ is open. Then the $\mathbb{Z}$-fold direct product
\begin{equation}\label{Eq_G}
G:=\{-1,1\}^\mathbb{Z}=\big\{(a_k)_{k\in\mathbb{Z}}\;\big|\;a_k\in\{-1,1\}\big\}
\end{equation}
is a compact topological group by Tychonoff's theorem. Moreover, we denote by $\mu$ the normalised Haar measure on $G$, i.e. the unique measure measure $\mu$, defined on the Borel $\sigma$-algebra of $G$, with the properties
\begin{equation}\label{Eq_Haar_measure}
\mu(G)=1\qquad\text{and}\qquad\mu(aB)=\mu(B),\qquad a\in G,\,B\subseteq G\text{ Borel set}.
\end{equation}
The upcoming Lemma~\ref{Haar_measure_orthonormality} now proves that the projectors $p_n:G\rightarrow\{-1,1\}$, defined by
\begin{equation}\label{Eq_Projector}
p_n(a):=a_n,\qquad a=(a_k)_k\in G,
\end{equation}
form an orthonormal system with respect to the Haar measure $\mu$. For the sake of completeness, we will also give a proof of this statement.

\begin{lem}\label{Haar_measure_orthonormality}
Let $G$ be as in \eqref{Eq_G} and $\mu$ the Haar measure from \eqref{Eq_Haar_measure}. Then the projectors \eqref{Eq_Projector} satisfy the orthonormality condition
\begin{equation}\label{Eq_Projector_orthonormality}
\int_Gp_n(a)p_m(a)d\mu(a)=\delta_{n,m},\qquad n,m\in\mathbb{Z}.
\end{equation}
\end{lem}

\begin{proof}
Let us define for every $n\in\mathbb{N}$ the sets
\begin{equation*}
A_n:=\big\{a\in G\;\big|\;a_n=1\big\}\qquad\text{and}\qquad B_n:=\big\{a\in G\;\big|\;a_n=-1\big\}.
\end{equation*}
With the characteristic functions $\mathds{1}_{A_n}$ and $\mathds{1}_{B_n}$ of these sets, we are able to write the projector $p_n$ as the difference
\begin{equation*}
p_n=\mathds{1}_{A_n}-\mathds{1}_{B_n},
\end{equation*}
and consequently the product of two projectors as
\begin{equation*}
p_np_m=(\mathds{1}_{A_n}-\mathds{1}_{B_n})(\mathds{1}_{A_m}-\mathds{1}_{B_m})=\mathds{1}_{A_n\cap A_m}-\mathds{1}_{A_n\cap B_m}-\mathds{1}_{B_n\cap A_m}+\mathds{1}_{B_n\cap B_m}.
\end{equation*}
This means that the integral \eqref{Eq_Projector_orthonormality} writes as
\begin{align}
\int_Gp_np_md\mu&=\mu(A_n\cap A_m)-\mu(A_n\cap B_m)-\mu(B_n\cap A_m)+\mu(B_n\cap B_m) \notag \\
&=\mu\big((A_n\cap A_m)\uplus(B_n\cap B_m)\big)-\mu\big((A_n\cap B_m)\uplus(B_n\cap A_m)\big) \notag \\
&=\mu\big\{a\in G\;\big|\;a_n=a_m\big\}-\mu\big\{a\in G\;\big|\;a_n\neq a_m\big\}. \label{Eq_Projector_orthonormality_1}
\end{align}
In the case $n=m$, the right hand side of \eqref{Eq_Projector_orthonormality_1} reduces to
\begin{equation*}
\int_Gp_np_md\mu=\mu\big\{a\in G\;\big|\;a_n=a_n\big\}-\mu\big\{a\in G\;\big|\;a_n\neq a_n\big\}=\mu(G)-\mu(\emptyset)=1.
\end{equation*}
In the case $n\neq m$, we choose the special element $e=(e_k)_k\in G$ with
\begin{equation*}
e_k:=\begin{cases} -1, & k=m, \\ 1, & k\neq m, \end{cases},\qquad k\in\mathbb{Z},
\end{equation*}
and rewrite the first set on the right hand side of \eqref{Eq_Projector_orthonormality_1} as
\begin{align*}
\big\{a\in G\;\big|\;a_n=a_m\big\}&=e\big\{e^{-1}a\;\big|\;a\in G,\,a_n=a_m\big\}=e\big\{b\in G\;\big|\;(eb)_n=(eb)_m\big\} \\
&=e\big\{b\in G\;\big|\;b_n=-b_m\big\}=e\big\{b\in G\;\big|\;b_n\neq b_m\big\}.
\end{align*}
With this representation of the set and the property \eqref{Eq_Haar_measure} of the Haar measure, the right hand side of \eqref{Eq_Projector_orthonormality_1} vanishes, as
\begin{align*}
\int_Gp_np_md\mu&=\mu\big(e\big\{b\in G\;\big|\;b_n\neq b_m\big\}\big)-\mu\big\{a\in G\;\big|\;a_n\neq a_m\big\} \\
&=\mu\big\{b\in G\;\big|\;b_n\neq b_m\big\}-\mu\big\{a\in G\;\big|\;a_n\neq a_m\big\}=0. \qedhere
\end{align*}
\end{proof}

Based on the preparatory results above, we are now in a position to prove our main result, which is the characterization of boundedness of the Clifford $H^\infty$- functional calculus.

\begin{thm}\label{thm_Quadratic_estimates}
Let $V$ be a Hilbert module and $T\in\mathcal{K}(V)$ be injective and bisectorial of angle $\omega\in(0,\frac{\pi}{2})$. Then for every $\theta\in(\omega,\frac{\pi}{2})$, the following statements are equivalent: \medskip

\begin{enumerate}
\item[i)] There exists some $c\geq 0$, such that for every $f\in\mathcal{N}^\infty(D_\theta)$ there is $f(T)\in\mathcal{B}(V)$ and
\begin{equation}\label{Eq_Bounded_Hinfty}
\Vert f(T)\Vert\leq c\Vert f\Vert_\infty;
\end{equation}

\item[ii)] For some/each $0\neq g\in\mathcal{N}^0(D_\theta)$, there exist constants $c_g,d_g>0$, such that
\begin{equation}\label{Eq_Quadratic_estimates}
c_g\Vert v\Vert\leq\bigg(\int_{-\infty}^\infty\Vert g(tT)v\Vert^2\frac{dt}{|t|}\bigg)^{\frac{1}{2}}\leq d_g\Vert v\Vert,\qquad v\in V.
\end{equation}

\item[iii)] For some/each $0\neq g\in\mathcal{N}^0(D_\theta)$, there exist constants $\widetilde{c}_g,\widetilde{d}_g\geq 0$, such that
\begin{subequations}\label{Eq_Quadratic_estimates_T_Tstar}
\begin{align}
\bigg(\int_{-\infty}^\infty\Vert g(tT)v\Vert^2\frac{dt}{|t|}\bigg)^{\frac{1}{2}}&\leq\widetilde{c}_g\Vert v\Vert,\qquad v\in V, \label{Eq_Quadratic_estimates_T} \\
\bigg(\int_{-\infty}^\infty\Vert g(tT^*)v\Vert^2\frac{dt}{|t|}\bigg)^{\frac{1}{2}}&\leq\widetilde{d}_g\Vert v\Vert,\qquad v\in V. \label{Eq_Quadratic_estimates_Tstar}
\end{align}
\end{subequations}
\end{enumerate}
\end{thm}

\begin{proof}
For the implication $i)\Rightarrow iii)$ let $0\neq g\in\mathcal{N}^0(D_\theta)$ be arbitrary, and $v\in V$. Then for every $n\in\mathbb{N}$, there is
\begin{align}
\int_{(-2^n,-2^{-n})\cup(2^{-n},2^n)}\Vert g(tT)v\Vert^2\frac{dt}{|t|}&=\sum_{k=-n}^{n-1}\int_{(-2^{k+1},-2^k)\cup(2^k,-2^{k+1})}\Vert g(tT)v\Vert^2\frac{dt}{|t|} \notag \\
&=\sum_{k=-n}^{n-1}\int_{(-2,-1)\cup(1,2)}\Vert g(t2^kT)v\Vert^2\frac{dt}{|t|}. \label{Eq_Quadratic_estimates_2}
\end{align}
Using the group $G$ in \eqref{Eq_G}, the Haar measure \eqref{Eq_Haar_measure}, and the projectors \eqref{Eq_Projector_orthonormality}, we can use the orthonormality \eqref{Eq_Projector_orthonormality}, to write the sum on the right hand side of \eqref{Eq_Quadratic_estimates_2} as
\begin{align*}
\sum\limits_{k=-n}^{n-1}\Vert g(t2^kT)v\Vert^2&=\sum\limits_{k,l=-n}^{n-1}\int_Gp_k(a)p_l(a)d\mu(a)\Sc\big\langle g(t2^kT)v,g(t2^lT)v\big\rangle \\
&=\int_G\Sc\bigg\langle\sum\limits_{k=-n}^{n-1}p_k(a)g(t2^kT)v,\sum\limits_{l=-n}^{n-1}p_l(a)g(t2^lT)v\bigg\rangle d\mu(a) \\
&=\int_G\bigg\Vert\sum\limits_{k=-n}^{n-1}p_k(a)g(t2^kT)v\bigg\Vert^2d\mu(a) \\
&=\int_G\bigg\Vert\bigg(\sum\limits_{k=-n}^{n-1}p_k(a)g(t2^k\,\cdot\,)\bigg)(T)v\bigg\Vert^2d\mu(a),
\end{align*}
where in the last equation we used the identity $g(t2^kT)=g(t2^k\,\cdot\,)(T)$ from \eqref{Eq_fg_estimates_3} as well as the linearity of the $\omega$-functional calculus. In this form we can now use the assumed boundedness of the $H^\infty$-functional calculus \eqref{Eq_Bounded_Hinfty} with the function $f(s)=\sum_{k=-n}^{n-1}p_k(a)g(t2^ks)$, to estimate
\begin{equation}\label{Eq_Quadratic_estimates_1}
\sum\limits_{k=-n}^{n-1}\Vert g(t2^kT)v\Vert^2\leq c^2\int_G\bigg\Vert\sum\limits_{k=-n}^{n-1}p_k(a)g(t2^k\,\cdot\,)\bigg\Vert_\infty^2d\mu(a)\Vert v\Vert^2.
\end{equation}
For every $a\in G$, $t\in\mathbb{R}\setminus\{0\}$ and $s\in D_\theta$, we can now estimate the $\Vert\cdot\Vert_\infty$-norm in \eqref{Eq_Quadratic_estimates_1} by
\begin{equation*}
\bigg|\sum\limits_{k=-n}^{n-1}p_k(a)g(t2^ks)\bigg|\leq\sum\limits_{k=-n}^{n-1}|g(t2^ks)|\leq C_\beta\sum\limits_{k=-\infty}^\infty\frac{|t2^ks|^\beta}{1+|t2^ks|^{2\beta}}.
\end{equation*}
Choosing now $k_0\in\mathbb{Z}$ such that $|ts|\in[2^{k_0},2^{k_0+1}]$, we can split up the sum to further estimate
\begin{align*}
\bigg|\sum\limits_{k=-n}^{n-1}p_k(a)g(t2^ks)\bigg|&\leq C_\beta\sum\limits_{k=-\infty}^{-k_0-1}|t2^ks|^\beta+C_\beta\sum\limits_{k=-k_0}^\infty\frac{1}{|t2^ks|^\beta} \\
&\leq C_\beta\sum\limits_{k=-\infty}^{-k_0-1}(2^{k+k_0+1})^\beta+C_\beta\sum\limits_{k=-k_0}^\infty\frac{1}{(2^{k+k_0})^\beta}=\frac{2C_\beta}{1-2^{-\beta}}.
\end{align*}
Since this estimate is true for every $s\in D_\theta$, and since $\mu(G)=1$ by \eqref{Eq_Haar_measure}, it turns \eqref{Eq_Quadratic_estimates_1} into
\begin{equation*}
\sum\limits_{k=-n}^{n-1}\Vert g(t2^kT)v\Vert^2\leq c^2\int_G\frac{4C_\beta^2}{(1-2^{-\beta})^2}d\mu(a)\Vert v\Vert^2=\frac{4c^2C_\beta^2}{(1-2^{-\beta})^2}\Vert v\Vert^2.
\end{equation*}
Plugging this now into \eqref{Eq_Quadratic_estimates_2}, gives
\begin{equation*}
\int_{(-2^n,-2^{-n})\cup(2^{-n},2^n)}\Vert g(tT)v\Vert^2\frac{dt}{|t|}\leq\int_{(-2,-1)\cup(1,2)}\frac{4c^2C_\beta^2}{(1-2^{-\beta})^2}\Vert v\Vert^2\frac{dt}{|t|}=\frac{8\ln(2)c^2C_\beta^2}{(1-2^{-\beta})^2}\Vert v\Vert^2.
\end{equation*}
Since this is true for every $n\in\mathbb{N}$, we can take the limit $n\rightarrow\infty$ and obtain the first inequality \eqref{Eq_Quadratic_estimates_T}, namely
\begin{equation}\label{Eq_Quadratic_estimates_3}
\int_{-\infty}^\infty\Vert g(tT)v\Vert^2\frac{dt}{|t|}\leq\frac{8\ln(2)c^2C_\beta^2}{(1-2^{-\beta})^2}\Vert v\Vert^2.
\end{equation}
For the second inequality \eqref{Eq_Quadratic_estimates_T_Tstar}, we note that by Theorem~\ref{thm_Adjoint_omega_functional_calculus} and \eqref{Eq_Bounded_Hinfty}, there is
\begin{equation*}
\Vert g(T^*)\Vert=\Vert g(T)^*\Vert=\Vert g(T)\Vert\leq c\Vert g\Vert_\infty.
\end{equation*}
This means that the assumption \eqref{Eq_Bounded_Hinfty} is also satisfied for the adjoint operator $T^*$. In the same way as for $T$ in \eqref{Eq_Quadratic_estimates_3}, we can now also derive the estimate
\begin{equation*}
\int_{-\infty}^\infty\Vert g(tT^*)v\Vert^2\frac{dt}{|t|}\leq\frac{8\ln(2)c^2C_\beta}{(1-2^{-\beta})^2}\Vert v\Vert^2.
\end{equation*}
Next, let us prove the implication $\text{\grqq}ii)\Rightarrow i)\text{\grqq}$, and let $0\neq g\in\mathcal{N}^0(D_\theta)$ be the one function for which \eqref{Eq_Quadratic_estimates} is satisfied. In a \textit{first step} we will verify \eqref{Eq_Bounded_Hinfty} for $f\in\mathcal{N}^0(D_\theta)$. We know from Proposition~\ref{prop_f_infty_estimate}, that there exists some constant $C_g\geq 0$, such that
\begin{equation*}
\int_{-\infty}^\infty\Vert g(tT)f(T)v\Vert^2\frac{dt}{|t|}\leq C_g^2\Vert f\Vert_\infty^2\int_{-\infty}^\infty\Vert g(tT)v\Vert^2\frac{dt}{|t|}.
\end{equation*}
Thus, with the given inequality \eqref{Eq_Quadratic_estimates} for the vector $f(T)v$, we then get
\begin{equation*}
c_g^2\Vert f(T)v\Vert^2\leq\int_{-\infty}^\infty\Vert g(tT)f(T)v\Vert^2\frac{dt}{|t|}\leq C_g^2\Vert f\Vert_\infty^2\int_{-\infty}^\infty\Vert g(tT)v\Vert^2\frac{dt}{|t|}\leq C_g^2d_g^2\Vert f\Vert_\infty^2\Vert v\Vert^2.
\end{equation*}
Since this estimate is true for every $v\in V$, we conclude
\begin{equation}\label{Eq_Quadratic_estimates_4}
\Vert f(T)\Vert\leq\frac{C_gd_g}{c_g}\Vert f\Vert_\infty,\qquad f\in\mathcal{N}^0(D_\theta).
\end{equation}
In the \textit{second step} we will extend \eqref{Eq_Quadratic_estimates_4} to all $f\in\mathcal{N}^\infty(D_\theta)$. To do so, let us consider for every $0<\alpha\leq 1$ the function
\begin{equation*}
e_\alpha(s):=\begin{cases} \frac{s^\alpha}{(1+s^2)^\alpha}, & \text{if }\Sc(s)>0, \\ \frac{(-s)^\alpha}{(1+s^2)^\alpha}, & \text{if }\Sc(s)<0, \end{cases} \qquad s\in D_\theta.
\end{equation*}
Then there clearly is $e_\alpha\in\mathcal{N}^0(D_\theta)$, and since $f$ is bounded, also $e_\alpha f\in\mathcal{N}^0(D_\theta)$. This means, that from the already proven inequality \eqref{Eq_Quadratic_estimates_4}, we get
\begin{equation}\label{Eq_Quadratic_estimates_5}
\Vert(e_\alpha f)(T)\Vert\leq\frac{C_gd_g}{c_g}\Vert e_\alpha f\Vert_\infty\leq\frac{C_gd_g}{c_g\cos(\theta)}\Vert f\Vert_\infty,
\end{equation}
where in the second inequality, we used \eqref{Eq_Convergence_lemma_2} to obtain the uniform upper bound
\begin{equation*}
|e_\alpha(s)f(s)|\leq\frac{\Vert f\Vert_\infty|s|^\alpha}{|1+s^2|^{\alpha}}\leq\frac{\Vert f\Vert_\infty|s|^\alpha}{\cos^\alpha(\theta)(1+|s|^2)^\alpha}\leq\frac{\Vert f\Vert_\infty}{2^\alpha\cos^\alpha(\theta)}\leq\frac{\Vert f\Vert_\infty}{\cos(\theta)},\qquad s\in D_\theta.
\end{equation*}
Next, it follows from a convergence result due to Vitali \cite[Proposition 5.1.1]{Haase}, that there converges $\lim_{\alpha\rightarrow 0^+}e_\alpha(s)=1$, uniformly on compact subsets of $D_\theta$. This means that from Lemma~\ref{lem_Convergence_lemma}, we then conclude $f(T)\in\mathcal{B}(V)$, as well as the strong convergence
\begin{equation*}
\lim\limits_{\alpha\rightarrow 0^+}(e_\alpha f)(T)v=f(T)v,\qquad v\in V.
\end{equation*}
In particular, using this convergence together with \eqref{Eq_Quadratic_estimates_5}, also $f(T)$ satisfies the norm estimate
\begin{equation*}
\Vert f(T)v\Vert=\lim\limits_{\alpha\rightarrow 0^+}\Vert(e_\alpha f)(T)v\Vert\leq\frac{C_gd_g}{c_g\cos(\theta)}\Vert f\Vert_\infty.
\end{equation*}
For the implication $\text{\grqq}ii)\Rightarrow iii)\text{\grqq}$ let us fix $0\neq g\in\mathcal{N}^0(D_\theta)$ and consider some arbitrary $v\in V$. Then we know from Lemma~\ref{lem_Psieps} with $\Psi(t)=g(tT^*)v$, that for every $\varepsilon>0$ there exists some $\Psi_\varepsilon:\mathbb{R}\rightarrow V$, with
\begin{equation*}
\Vert\Psi_\varepsilon(t)\Vert=\Vert g(tT^*)v\Vert\qquad\text{and}\qquad\Vert g(tT^*)v\Vert^2\leq(1+\varepsilon)\Sc\big\langle g(tT^*)v,\Psi_\varepsilon(t)\big\rangle,\qquad t\in\mathbb{R}.
\end{equation*}
From the assumed lower bound in \eqref{Eq_Quadratic_estimates}, there then follows the estimate
\begin{align}
\int_{-\infty}^\infty\Vert g(tT^*)v\Vert^2\frac{dt}{|t|}&\leq(1+\varepsilon)\int_{-\infty}^\infty\Sc\big\langle g(tT^*)v,\Psi_\varepsilon(t)\big\rangle\frac{dt}{|t|}=(1+\varepsilon)\int_{-\infty}^\infty\Sc\big\langle v,g(tT)\Psi_\varepsilon(t)\big\rangle\frac{dt}{|t|} \notag \\
&=(1+\varepsilon)\Sc\bigg\langle v,\underbrace{\int_{-\infty}^\infty g(tT)\Psi_\varepsilon(t)\frac{dt}{|t|}}_{=:w}\bigg\rangle\leq(1+\varepsilon)\Vert v\Vert\Vert w\Vert. \label{Eq_Quadratic_estimates_7}
\end{align}
Moreover, for this vector $w$, we can now apply the inequality \eqref{Eq_fg_estimate}, to get an estimate between the two quadratic integrals
\begin{align}
\int_{-\infty}^\infty\Vert g(\tau T)w\Vert^2\frac{d\tau}{|\tau|}&=\int_{-\infty}^\infty\bigg\Vert g(\tau T)\int_{-\infty}^\infty g(tT)\Psi_\varepsilon(t)\frac{dt}{|t|}\bigg\Vert^2\frac{d\tau}{|\tau|} \notag \\
&\leq\Big(\frac{C_\theta C_\beta^2\pi}{2\beta^2}\Big)^2\int_{-\infty}^\infty\Vert\Psi_\varepsilon(t)\Vert^2\frac{dt}{|t|} \notag \\
&=\Big(\frac{C_\theta C_\beta^2\pi}{2\beta^2}\Big)^2\int_{-\infty}^\infty\Vert g(tT^*)v\Vert^2\frac{dt}{|t|}. \label{Eq_Quadratic_estimates_8}
\end{align}
Applying now first the estimate \eqref{Eq_Quadratic_estimates_8} and then \eqref{Eq_Quadratic_estimates_7}, gives
\begin{align*}
\bigg(\int_{-\infty}^\infty\Vert g(\tau T)w\Vert^2\frac{d\tau}{|\tau|}\bigg)^{\frac{1}{2}}\bigg(\int_{-\infty}^\infty\Vert g(tT^*)v\Vert^2\frac{dt}{|t|}\bigg)^{\frac{1}{2}}&\leq\frac{C_\theta C_\beta^2\pi}{2\beta^2}\int_{-\infty}^\infty\Vert g(tT^*)v\Vert^2\frac{dt}{|t|} \\
&\leq\frac{(1+\varepsilon)C_\theta C_\beta^2\pi}{2\beta^2}\Vert v\Vert\Vert w\Vert.
\end{align*}
Using now also the lower bound of the quadratic estimate for $w$ in \eqref{Eq_Quadratic_estimates_T}, then gives
\begin{equation*}
\bigg(\int_{-\infty}^\infty\Vert g(tT^*)v\Vert^2\frac{dt}{|t|}\bigg)^{\frac{1}{2}}\leq\frac{(1+\varepsilon)C_\theta C_\beta^2\pi}{2\beta^2c_g}\Vert v\Vert.
\end{equation*}
Finally, for the implication $\text{\grqq}iii)\Rightarrow ii)\text{\grqq}$ let us fix $0\neq g\in\mathcal{N}^0(D_\theta)$ and consider some arbitrary $v\in V$. It then follows from Theorem~\ref{thm_fab_approximation}, as well as the representation \eqref{Eq_fab_approximation_4} of $g_{a,b}^2(T)$, that
\begin{equation*}
(g^2)_{0,\infty}v=\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}g_{a,b}^2(T)v=\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}\int_{(-b,-a)\cup(a,b)}g^2(tT)v\frac{dt}{t}.
\end{equation*}
Taking now the scalar part of the inner product of this equation with the vector $v$, then gives
\begin{align*}
(g^2)_{0,\infty}\Vert v\Vert^2&=\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}\int_{(-b,-a)\cup(a,b)}\Sc\langle g^2(tT)v,v\rangle\frac{dt}{t} \\
&=\lim\limits_{\substack{a\rightarrow 0^+ \\ b\rightarrow\infty}}\int_{(-b,-a)\cup(a,b)}\Sc\langle g(tT)v,g(tT^*)v\rangle\frac{dt}{t} \\
&\leq\int_{-\infty}^\infty\Vert g(tT)v\Vert\Vert g(tT^*)v\Vert\frac{dt}{|t|} \\
&\leq\bigg(\int_{-\infty}^\infty\Vert g(tT)v\Vert^2\frac{dt}{|t|}\bigg)^{\frac{1}{2}}\bigg(\int_{-\infty}^\infty\Vert g(tT^*)v\Vert^2\frac{dt}{|t|}\bigg)^{\frac{1}{2}},
\end{align*}
where in the last line we used Hölder's inequality. In this form we can now use the assumed quadratic estimate \eqref{Eq_Quadratic_estimates_Tstar}, to get the stated lower bound in \eqref{Eq_Quadratic_estimates}
\begin{equation*}
\frac{(g^2)_{0,\infty}}{\widetilde{d}_g}\Vert v\Vert\leq\bigg(\int_{-\infty}^\infty\Vert g(tT)v\Vert^2\frac{dt}{|t|}\bigg)^{\frac{1}{2}}. \qedhere
\end{equation*}
\end{proof}

\section{Concluding remarks on applications and research directions}

Unlike complex holomorphic function theory, the noncommutative setting of the Clifford algebra allows multiple notions of hyperholomorphicity for vector fields. Consequently, different spectral theories emerge, each based on the concept of spectrum that relies on distinct Cauchy kernels. The spectral theory based on the $S$-spectrum was inspired by quaternionic quantum mechanics (see \cite{BF}), is associated with slice hyperholomorphicity, and began its development in 2006. A comprehensive introduction can be found in \cite{CGK}, with further explorations done in \cite{ACS2016,AlpayColSab2020,ColomboSabadiniStruppa2011}. Applications on fractional powers of operators are investigated in \cite{CGdiffusion2018,CG18,FJBOOK,JONAMEM,JONADIRECT} and some results from classical interpolation theory, see \cite{BERG_INTER,BRUDNYI_INTER,Ale_INTER,TRIEBEL}, have been recently extended into this setting \cite{COLSCH}. In order to fully appreciate the spectral theory on the $S$-spectrum, we recall that it applies to sets of noncommuting operators, for example with the identification $(T_1,...,T_{2^n})\leftrightarrow T=\sum_AT_Ae_A$ it can be seen as a theory for several operators. Extending complex spectral theory to vector operators broadens its applicability to various areas of research fields such as: \medskip

\textit{Quaternionic formulation of quantum mechanics.} The interest in spectral theory for quaternionic operators is motivated by the 1936 paper \cite{BF} on the logic of quantum mechanics by G. Birkhoff, J. von Neumann. There, the authors showed that Schrödinger equation can be written basically in the complex or in the quaternionic setting, see also the book of Adler \cite{adler}. \medskip

\textit{Vector analysis.} The gradient operator with nonconstant coefficients in $n$ dimensions, represents various physical laws, such as Fourier's law for heat propagation and Fick's law for mass transfer diffusion. This can be expressed as
\begin{equation*}
T=\sum_{i=1}^ne_ia_i(x)\partial_{x_i},\qquad x\in\Omega,
\end{equation*}
and is associated with various boundary conditions, as discussed in \cite{CMS24}. Here, $e_1,\dots,e_n$ represent the imaginary units of the Clifford algebra $\mathbb{R}_n$, and the coefficients $a_1,\dots,a_n$ are assumed to belong to $C^1(\overline{\Omega})$ and satisfy appropriate bounds. \medskip

\textit{Differential geometry.} Let $(M,g)$ be a Riemannian manifold of dimension $n$, and $U$ a coordinate neighbourhood of $M$. In this neighbourhood, we can find an orthonormal frame of vector fields $E_1,\dots,E_n$, such that the Dirac operator on $(U,g)$ can be expressed as the $\mathcal{C}^\infty(U,\mathcal{H})$ differential operator
\begin{equation}\label{Eq_Dirac_manifold}
\mathcal{D}=\sum_{i=1}^ne_i\nabla_{E_i}^\tau,
\end{equation}
where $\nabla_{E_i}^\tau$ denotes the covariant derivative with respect to the vector field $E_i$. For more details see the book \cite{DiracHarm}. As a special case the paper \cite{DIRACHYPSPHE} considers the Dirac operator in hyperbolic and spherical spaces, where \eqref{Eq_Dirac_manifold} takes the explicit forms
\begin{equation*}
\mathcal{D}_H=x_n\sum_{i=1}^ne_i\partial_{x_i}-\frac{n-1}{2}e_n\qquad\text{and}\qquad\mathcal{D}_S=(1+|x|^2)\sum_{i=1}^ne_i\partial_{x_i}-nx,
\end{equation*}
where for $\mathcal{D}_H$ we pick $(x_1,...,x_{n-1},x_n)\in\mathbb{R}^{n-1}\times\mathbb{R}^+$ and $(x_1,...,x_n)\in\mathbb{R}^n$ for $\mathcal{D}_S$, respectively. \medskip

\textit{Hypercomplex analysis.} The well-known Dirac operator and its conjugate
\begin{equation*}
D=\partial_{x_0}+\sum_{i=1}^ne_i\partial_{x_i}\qquad\text{and}\qquad\overline{D}=\partial_{x_0}-\sum_{i=1}^ne_i\partial_{x_i},
\end{equation*}
are widely investigated in \cite{DSS} as well as in \cite{DiracHarm}. Slice hyperholomorphic functions can also be viewed as functions in the kernel of the global operator
\begin{equation*}
G=|\Im(x)|^2\partial_{x_0}+\Im(x)\sum_{i=1}^nx_i\partial_{x_i},
\end{equation*}
introduced in \cite{6Global}, where $\Im(x)=x_1e_1+\dots+x_ne_n$. For integers $\alpha,\beta,m$, the operators of the Dirac fine structure on the $S$-spectrum are defined as
\begin{equation*}
T_{\alpha,m}=D^\alpha(D\overline{D})^m\qquad\text{and}\qquad\widetilde{T}_{\beta,m}=\overline{D}^\beta(D\overline{D})^m.
\end{equation*}
The fine structures on the $S$-spectrum constitute a set of function spaces and their related functional calculi. These structures have been introduced and studied in recent works \cite{polypolyFS,CDPS1,Fivedim,Polyf1,Polyf2}, while their respective $H^\infty$-versions are investigated in \cite{MILANJPETER,MPS23}. \medskip

The $H^\infty$-functional calculi also have a broader context in the recently introduced fine structures on the $S$-spectrum. These are function spaces of nonholomorphic functions derived from the Fueter-Sce extension theorem, which connects slice hyperholomorphic and axially monogenic functions, the two main notions of holomorphicity in the Clifford setting. The connection is established through powers of the Laplace operator in a higher dimension, see \cite{Fueter,TaoQian1,Sce} and also the translation \cite{ColSabStrupSce}. \medskip

It is important to highlight that in the hypercomplex setting there exists another spectral theory based on the monogenic spectrum, which was initiated by Jefferies, McIntosh and J. Picton-Warlow in \cite{JM}. This theory is founded on monogenic functions, which are functions in the kernel of the Dirac operator, and their associated Cauchy formula (see \cite{DSS} for a comprehensive treatment). The monogenic spectral theory, based on monogenic functions \cite{DSS}, has been extensively developed and is well described in the seminal books \cite{JBOOK} and \cite{TAOBOOK}. These texts provide an in-depth exploration of the theory, with particular emphasis on the $H^\infty$-functional calculus in the monogenic setting. \medskip

