\section{Some quick consequences of the bumpy metric theorem}\label{sec: bumpy metric}

We need to make use of the following observation about the bumpy metric theorem, which is known to experts. In what follows, $\mathcal G$ will denote the Fr\'echet manifold of $C^\infty$ Riemannian metrics on our compact, boundary-less smooth manifold $M$.

\begin{proposition}\label{prop: bumpy metric}
    For each $T > 0$, there exists an open-dense subset of $\mathcal G$ for which there are only finitely many geodesics which close by time $T$.
\end{proposition}

This follows from the classical result of \cite{abraham1970bumpy,anosov1983generic} with some minor adaptations. We will first show how this result holds for $C^k$ metrics and then use an argument in \cite{white2017bumpy} to transfer it to $C^\infty$ metrics.

Let $ \mathcal G^k$ denote the space of $C^k$ Riemannian metrics on $M$ with $k \in \N$ or $k = \infty$. For $r > 0$, let
\[
     \mathcal G_r^k = \{g \in  \mathcal G^k : \inj(M,g) > r \}
\]
denote the subset of $C^k$ metrics with injectivity radius larger than $r$. We observe that:
\begin{enumerate}
    \item $ \mathcal G_r^k$ is an open subset of $ \mathcal G^k$.
    \item Since $M$ is compact, $ \mathcal G^k = \bigcup_{r > 0}  \mathcal G_r^k$.
\end{enumerate}
It follows almost immediately that:

\begin{lemma}\label{lem: injectivity radius}
    Let $k \in \N$ or $k = \infty$. Suppose $U \subset  \mathcal G^k$ and that $U \cap  \mathcal G_r^k$ is open and dense in $ \mathcal G_r^k$ for each $r > 0$. Then $U$ is open and dense in $ \mathcal G^k$.
\end{lemma}


\begin{proof}
    We see $U$ is open in $ \mathcal G^k$ by writing
    \[
        U = \bigcup_{r > 0} U \cap  \mathcal G_r^k.
    \]
    We see $U$ is dense by considering a nonempty open subset $V \subset  \mathcal G^k$ and noting $V \cap  \mathcal G^k_r$ is nonempty for some $r > 0$. Since $U \cap  \mathcal G^k_r$ is dense in $ \mathcal G^k_r$, $U \cap V \cap  \mathcal G_r^k$ is nonempty, and hence so is $U \cap V$.
\end{proof}

{
Recall, a \emph{Jacobi field} $J$ along a geodesic is solves
\[
    \frac{D^2}{dt^2} J + R(J,\gamma')\gamma' = 0,
\]
where $R$ is the Riemann curvature tensor and $\frac{D^2}{dt^2}$ is the second covariant derivative with respect to the parameter $t$ of the geodesic. Jacobi fields are the vector fields generated by a variation of a geodesic.}

\begin{lemma}\label{lem: open-dense bumpy metric}
    The set of metrics in $ \mathcal G^k$ for which there exist no closed geodesics of period in $(0,T]$ which admit nontrivial smooth Jacobi fields is open and dense.
\end{lemma}

\begin{proof}
    Let $U \subset  \mathcal G^k$ denote the set of metrics for which no closed geodesics of period in $(0,T]$ admit nontrivial Jacobi fields. By the classical bumpy metric theorem \cite{abraham1970bumpy,anosov1983generic}, $U$ is residual and hence dense in $ \mathcal G^k$. By the lemma, it suffices to show $U \cap  \mathcal G_r^k$ is open in $ \mathcal G_r^k$ for each $r > 0$.

    Let $E_r \subset  \mathcal G^k_r \times (0,T] \times S^*M$ denote the problematic set
    \[
        E_r = \{(g,t,x,\xi) : \Phi^t_g(x,\xi) = (x,\xi) \text{ and } \rank (I - d\Phi_g^t) > 1 \},
    \]
    where here $S^*M$ is the quotient of $T^*M \setminus 0$ by the action of $\R_+$ by scalar multiplication, where $\Phi^t_g$ denotes the time-$t$ unit-speed geodesic flow on $S^*M$. $U \cap  \mathcal G_r^k$ is the complement of the image of $E_r$ via the projection onto $ \mathcal G^k_r$. Since the injectivity radii of metrics in $ \mathcal G_r^k$ are greater than $r$, there are no closed geodesics of period $r$ (actually $2r$) or less. Hence
    \[
        E_r \subset  \mathcal G^k_r \times [r,T] \times S^*M.
    \]

    Provided the metrics have sufficiently many continuous derivatives, and since the rank function is lower semi-continuous, $E_r$ is a closed subset of $ \mathcal G_r^k \times [r,T] \times S^*M$.
    Let $\pi$ denote the projection $ \mathcal G_r^k \times [r,T] \times S^*M \to  \mathcal G_r^k$. Since $[r,T] \times S^*M$ is compact, $\pi$ is a closed map and hence $\pi E_r$ is closed in $ \mathcal G_r^k$, hence $U \cap  \mathcal G_r^k$ is open in $ \mathcal G_r^k$.
\end{proof}

This section's proposition follows from Lemma \ref{lem: open-dense bumpy metric} and the following observation of White \cite{white2017bumpy}. We include a short proof for the sake of completeness.

\begin{lemma}
    Let $U \subset  \mathcal G^k$ be such that $U \cap  \mathcal G^j$ is open and dense in $ \mathcal G^j$ for all $j \geq k$. Then, $U \cap \mathcal G$ is open and dense in $\mathcal G$.
\end{lemma}

\begin{proof}
    We will use two facts:
    \begin{enumerate}
        \item The collection of all of the open sets of $ \mathcal G^j$ for $j \geq k$ form a basis for the $C^\infty$ topology on $\mathcal G$.
        \item $\mathcal G$ is dense in $ \mathcal G^j$ for each $j \geq k$.
    \end{enumerate}
    Clearly $U$ is open in $\mathcal G$, so it suffices to show it is dense. Suppose $V$ is any nonempty open neighborhood in $\mathcal G$, say containing an element $g$. By (1) there exists $j \geq k$ and an open neighborhood $V'$ of $g$ in $ \mathcal G^j$ with $V' \cap \mathcal G \subset V$. Now, $V' \cap U$ is open and nonempty in $ \mathcal G^j$ since $U \cap  \mathcal G^j$ is open and dense in $C^j$. By (2), there exists $g' \in \mathcal G$ with $g' \in V' \cap U$. In particular, $g' \in V \cap U$, as desired.
\end{proof}

\section{Geodesics and two useful perturbations of the metric}\label{sec: perturbation}
In this section, we introduce two distinct types of metric perturbations that will be employed in our proof. First, we construct a perturbation of the metric within the same isometry class as the original metric, which allows us to locally perturb the embedding of the submanifold.
\subsection{Perturbing the embedding of the submanifold} \label{sec: perturbation 1}
Fix a metric $g \in \mathcal G$. Let $\mathcal I(g)$ denote the set of all smooth Riemannian metrics in the same isometry class as $g$. As a consequence of the Arzel\`a-Ascoli theorem, $\mathcal I(g)$ is a closed subset of $\mathcal G$, and hence is completely metrizable in its own right. We can then consider residual subsets of $\mathcal I(g)$.

We will consider a class of perturbations generated by diffeomorphisms on $M$. The resulting metric perturbation will result in a metric that is in the same isometry class as the original. This might seem fruitless initially, but it allows us to effectively perturb the embedding of $\Sigma$ into $M$ while preserving the geometry of $M$. 

Before constructing our perturbations, consider a diffeomorphism $\kappa : M \to M$. $\kappa$ induces a canonical transformation $\tau : T^*M \to T^*M$ which can be written in canonical local coordinates as
\[
    \tau(x,\xi) = (\kappa(x), d\kappa(x)^{-t} \xi),
\]
where $d\kappa(x)^{-t}$ denote the inverse-transpose of the Jacobian matrix $d\kappa(x)$. 

\begin{proposition}
    Let $g$ be a Riemannian metric on $M$, let $\kappa : M \to M$ be a diffeomorphism and let $\tau : T^*M \to T^*M$ be the associated canonical transformation. If $g' = \kappa^* g$, then
    \[
        p_{g'} = p_g \circ \tau
    \]
    where $p_g$ and $p_{g'}$ are as in \eqref{eq: p_g}. It follows that $d\tau H_{p_{g'}} = H_{p_g}$, and that $\tau$ takes orbits of the geodesic flow on $(M,g')$ to orbits of the geodesic flow on $(M,g)$, and vice-versa.
\end{proposition}

\begin{proof}
    We note
    \begin{align*}
        p_g(\tau(x,\xi)) &= p_g(\kappa(x), d\kappa(x)^{-t} \xi) \\
        &= \sum_{i,j} g^{ij}(\kappa(x)) (d\kappa(x)^{-t} \xi)_i (d\kappa(x)^{-t} \xi)_j \\
        &= \sum_{i,j,k,\ell} g^{ij}(\kappa(x)) [d\kappa(x)^{-t}]_{i,k} [d\kappa(x)^{-t}]_{j,\ell} \xi_k \xi_\ell \\
        &= \sum_{k,\ell} \left[ d\kappa(x)^t g(\kappa(x)) d\kappa(x) \right]^{-1}_{k,\ell} \xi_k \xi_\ell \\
        &= \sum_{k,\ell} {g'}^{k\ell}(x) \xi_k \xi_\ell \\
        &= p_{g'}(x,\xi).
    \end{align*}
    Since $d\tau$ is a linear symplectomorphism $T_{(x,\xi)} T^*M \to T_{\tau(x,\xi)} T^*M$, we have, for each vector $v \in T_{(x,\xi)} T^*M$, and where $\sigma$ denotes the symplectic form on $T^*M$,
    \[
        \sigma(H_{p_{g'}}, v) = dp_{g'}(v) = dp_g (d\tau(v)) = \sigma(H_{p_g}, d\tau(v)) = \sigma(d\tau^{-1} H_{p_g}, v),
    \]
    from which the second part of the proposition follows. The third part follows quickly.
\end{proof}

We construct our perturbations as follows. Fix a smooth vector field $X$ on $M$ and consider the pullback
\[
    g_X = \exp(X)^*g
\]
of $g$ through the time-$1$ flow $\exp(X)$. Note, $\exp(X) : (M,g_X) \to (M,g)$ is an isometry by construction, and hence $g_X \in \mathcal I(g)$. Hence, to study $\Sigma$ in $(M,g_X)$, it suffices to study $\exp(X)(\Sigma)$ in the original space $(M,g)$. Since we will be studying the conormal bundle, we will also need to consider the induced canonical transformation
\[
    \tau_X(x,\xi) = (\exp(X)(x), (d\exp(X)(x))^{-t}\xi).
\]
We illustrate this situation with the commutative diagrams
\begin{equation}\label{eq: commutative diagrams}
    \begin{tikzcd}
        & \Sigma \arrow[dl] \arrow[rd] \\
        (M,g_X) \arrow[rr,"\exp(X)"] & & (M,g)
    \end{tikzcd}
    \qquad
    \begin{tikzcd}
        T^*M \arrow[r,"\tau_X"] \arrow[d] & T^*M \arrow[d] \\
        M \arrow[r,"\exp(X)"] & M
    \end{tikzcd}
\end{equation}
where the arrow $\Sigma \to (M,g)$ is not the embedding we started with.
By the proposition above, $\tau_X$ preserves the orbits of the geodesic flow between $(M,g_X)$ and $(M,g)$.



\begin{proposition} \label{prop: perturbation}
    Fix a metric $g \in \mathcal G$. About each point in $M$, there exists an open neighborhood $U \subset M$ and a smooth parametrization of vector fields
    \[
        F : \R^{n + n^2} \to \mathcal X(M)
    \]
    on $M$ for which $F(0) = 0$ and, for each $(x,\xi) \in \dot T^*U$
    \[
        \tau_{F}(x,\xi) : \R^{n + n^2} \to T^*M
    \]
    has full-rank differential for $(a,b)$ on a neighborhood of the origin.
\end{proposition}

\begin{proof}
    Fix $(x_0, \xi_0) \in \dot T^*M$ and consider local coordinates about $x_0$. Let $\chi$ be a smooth cutoff function on $M$ which vanishes outside the local coordinate patch and is identically $1$ on an open neighborhood $U$ of $x_0$. Given $a \in \R^n$ and $b \in \R^{n^2}$, we define
    \[
        F(a,b) = \chi(x) \sum_{j = 1}^n \left(a_j + \sum_{i = 1}^n x_i b_{ij} \right) \frac{\partial}{\partial x_j}.
    \]

For $x$ in a neighborhood of $x_0$,
$$
F(a,b)(x) 
=
\sum_{j=1}^n
\bigl(
  a_j 
  + 
  \sum_{i=1}^n b_{ij}\,x_i
\bigr)
\,\frac{\partial}{\partial x_j},
$$
where $a=(a_1,\dots,a_n)\in\mathbb{R}^n$ and $b=(b_{ij})\in\mathbb{R}^{n^2}.$ 
The ODE for $x(t)\in\mathbb{R}^n$ is
$$
\frac{d}{dt}x_j(t)
=
a_j +\sum_{i=1}^n b_{ij}\,x_i(t),
\quad
x(0)=x.
$$

Let $X(t)=(x_1(t),\dots,x_n(t))^T$, $A=(a_1,\dots,a_n)^T$, and let $B$ be the $n\times n$ matrix with $(B)_{j,i}=b_{ij}$. Then
\[
\frac{d}{dt}X(t) = A + B\,X(t).
\]
Its general solution is
\[
X(t)
=
e^{tB}\,x
+
\biggl(\int_0^t e^{(t-s)B}\,ds\biggr)\,A.
\]
At time $1$,
\[
X(1)
=
e^{B}\,x
+
\bigl(\int_0^1 e^{(1-s)B}\,ds\bigr)\,A
=:
e^{B}\,x + T(B)\,A.
\]

\medskip

Hence the basepoint of the flow is
\[
y = \exp(F(a,b))(x)
=
e^{B}\,x + T(B)\,A.
\]
The derivative w.r.t.\ $x$ is
\[
d\,\exp(F(a,b))(x) = e^B,
\quad
\Longrightarrow
\quad
(d\,\exp(F(a,b))(x))^{-t} = e^{-\,B^t}.
\]
Therefore,
\[
\eta 
=
\bigl(d\,\exp(F(a,b))(x)\bigr)^{-t}\,\xi
=
e^{-\,B^t}\,\xi,
\]
and the map on phase space is
\[
\tau_{F(a,b)}(x,\xi)
=
\bigl(e^B x + T(B)\,A,e^{-B^t}\,\xi\bigr).
\]

We evaluate the derivative of the map $ \tau_{F(a,b)}(x,\xi) $ at the point $ ((a,b),(x,\xi)) = ((0,0),(x,\xi)) $. The derivative is expressed in the usual block matrix form as follows:

\[
d_{(a,b)} \tau_{F(a,b)}(x,\xi) \bigg|_{\substack{(a,b) = (0,0) \\ (x,\xi) \text{ fixed}}} 
= 
\begin{pmatrix}
\left. \dfrac{\partial y}{\partial a} \right|_{(0,0)} & \left. \dfrac{\partial y}{\partial b} \right|_{(0,0)} \\
\left. \dfrac{\partial \eta}{\partial a} \right|_{(0,0)} & \left. \dfrac{\partial \eta}{\partial b} \right|_{(0,0)}
\end{pmatrix},
\]
where $ y = \exp(F(a,b))(x) $ and $ \eta = \left( d\,\exp(F(a,b))(x) \right)^{-t} \xi $.

    At $ (a,b) = (0,0) $, the map $ y $ depends linearly on $ a $ with a coefficient matrix equal to the identity matrix. Therefore,
    \[
    \left. \dfrac{\partial y}{\partial a} \right|_{(0,0)} = I_n.
    \]
    The component $ \eta $ does not depend on $ a $ at first order, hence 
    \[
    \left. \dfrac{\partial \eta}{\partial a} \right|_{(0,0)} = 0_{n \times n}.
    \]

It then suffices to show that the lower-right block of $d_{(a,b)}\tau_{F(a,b)}$ has full-rank.
At $(a,b)=(0,0)$, we have $B^t=0$, so
\[
\left.\frac{\partial \eta}{\partial b_{ij}}\right|_{(0,0)}
= -\,E_{i,j}\,\xi
= -\,\xi_j\,\mathbf{e}_i.
\]
In matrix form, the $(i,(k,\ell))$-entry of the $n\times n^2$ block is
\[
\begin{cases}
-\xi_\ell, & \text{if } i=k,\\
0,         & \text{otherwise}.
\end{cases}
\]
Hence the lower-right block is
\[
\begin{pmatrix}
-\xi_1 & 0 & \cdots & 0
 & -\xi_2 & 0 & \cdots & 0
 & \cdots
 & -\xi_n & 0 & \cdots & 0 \\[6pt]
0 & -\xi_1 & \cdots & 0
 & 0 & -\xi_2 & \cdots & 0
 & \cdots
 & 0 & -\xi_n & \cdots & 0 \\[6pt]
\vdots & & \ddots & 
 & & & & & 
 & & & & \\[6pt]
0 & 0 & \cdots & -\xi_1
 & 0 & 0 & \cdots & -\xi_2
 & \cdots
 & 0 & 0 & \cdots & -\xi_n
\end{pmatrix},
\]
which clearly has full rank as long as $\xi\neq 0.$ 
\end{proof}
{

\subsection{A Conformal Perturbation} 

{
We now construct a conformal perturbation of the metric that will allow us to make any small prescribed perturbation of the terminal data of integral curves of $\frac 1 2 H_{p}$ in $T^*M$, provided these integral curves do not close.

We first work locally. Consider a bounded, open, convex neighborhood of the unit line segment $[0,1] \times \{0\}$ in $\R^n$, and on it a Riemannian metric $g$ for which
\begin{equation}\label{eq: fermi conditions}
	g_{ij}(x) = \begin{bmatrix}
		1 + O(|x'|^2) & 0 \\
		0 & I + O(|x'|^2)
	\end{bmatrix}
	\qquad \text{ where } x = (x_1, x').
\end{equation}
One should think of the metric as having been obtained from Fermi coordinates about a geodesic segment $[0,1] \times \{0\}$. We consider a scaling
\[
	g(\epsilon;x) = g(\epsilon(x - e_1) + e_1)
\]
of the metric, where $e_1 = (1,0,\ldots,0) \in \R^n$, where $0 \leq \epsilon \leq 1$. Note, the scaled metric also satisfies the condition \eqref{eq: fermi conditions}, except that a factor of $\epsilon^2$ precedes the errors. From now on, we will implicitly include this scaling into the metric, even if its inclusion is not indicated by the notation.

Let $(x,\xi)$ be the corresponding canonical local coordinates for the cotangent bundle over our chart, and 
consider the symbol
\[
	p_g(x,\xi) = g^{ij}(x) \xi_i \xi_j
\]
and the associated Hamiltonian vector field
\[
	\frac 1 2 H_{p_g} = \frac 1 2 \left( \frac{\partial p}{\partial \xi_i} \frac{\partial}{\partial x^i} - \frac{\partial p}{\partial x^i} \frac{\partial}{\partial \xi_i} \right).
\]
Note, the curve $(x(t), \xi(t)) = (te_1, e_1)$ is the unique integral curve starting at $(0, e_1)$. 

We are interested in studying the effect of conformal perturbations of the metric---and hence of the Hamiltonian vector field---on the integral curve with the same initial data. We start by taking our choice of open set $U \subset \R^n$ for which
\[
	U \cap ([0,1] \times \{0\}) = (0,1) \times \{0\}.
\]
Then, we take a smooth function $f$ supported in $U$ and consider the associated conformal perturbation
\[
	g(\epsilon,s;x) = \frac{1}{1 + sf(x)} g(\epsilon;x) \qquad \text{and} \qquad p_{g(\epsilon,s)}(x,\xi) = (1 + sf(x)) p_g(x,\xi).
\]
For each $s$, let $(x(s;t), \xi(s;t))$ be the integral curve for $\frac 1 2 H_{(1 + sf)p}$ with $(x(s,0), \xi(s,0)) = (0,e_1)$. 
We wish to describe
\[
	\left. \frac \partial {\partial s_j} \right|_{s = 0} (x(s,t), \xi(s,t)).
\]
To do so, we write down Hamilton's equations
\begin{align*}
	\dot x^i &= \frac 1 2 (1 + sf) \frac{\partial p}{\partial \xi_i} \\
	\dot \xi_i &= - \frac 1 2 (1 + sf) \frac{\partial p}{\partial x^i} - \frac 1 2 p s \frac{\partial f}{\partial x^i},
\end{align*}
from which we obtain, at $s = 0$,
\begin{equation*}
\begin{split}
	\frac{\partial}{\partial t} \frac{\partial x^i}{\partial s} &= \frac 1 2 f \frac {\partial p} {\partial \xi_i} + \frac 1 2 \left( \frac {\partial^2 p} {\partial x^j \partial \xi_i} \frac{\partial x^j}{\partial s} + \frac {\partial^2 p} {\partial \xi_j \partial \xi_i} \frac{\partial \xi_j}{\partial s} \right) 
	\\
	\frac{\partial}{\partial t} \frac{\partial \xi_i}{\partial s} &= - \frac 1 2 f \frac{\partial p}{\partial x^i} - \frac 1 2 \left( \frac{\partial^2 p}{\partial x^j \partial x^i} \frac{\partial x^j}{\partial s} + \frac{\partial^2 p}{\partial \xi_j \partial x^i} \frac{\partial \xi_j}{\partial s} \right) - \frac 1 2 p \frac{\partial f}{\partial x^i}
\end{split}
\end{equation*}
which simplifies, by repeated application of \eqref{eq: fermi conditions} and by noting $p = 1$, to
\begin{equation} \label{eq: perturbed hamilton equations}
	\begin{split}
		\frac{\partial}{\partial t} \frac{\partial x^i}{\partial s} &= f \xi_i + \frac{\partial \xi_i}{\partial s} \\
		\frac{\partial}{\partial t} \frac{\partial \xi_i}{\partial s} &= - \frac 1 2 \frac{\partial^2 p}{\partial x^j \partial x^i} \frac{\partial x^j}{\partial s} - \frac 1 2 \frac{\partial f}{\partial x^i}
	\end{split}
\end{equation}
with initial data
\begin{equation}\label{eq: perturbed initial data}
	\frac{\partial x}{\partial s} = \frac{\partial \xi}{\partial s} = 0 \qquad \text{ at $t = 0$.}
\end{equation}

We consider two kinds of functions $f$. The first adjusts the distance between the ends of the geodesic.

\begin{lemma} Taking everything as above, let $f$ be a smooth function supported on the coordinate patch but not at $0$ nor $t_0 e_1$, and
\[
	\frac{\partial f}{\partial x^i}(te_1) = 0 \qquad \text{ for each $t \in [0,t_0]$ and $i \geq 2$.}
\]
Then,
\begin{align*}
	\frac{\partial x}{\partial s} &= \frac 1 2 \left( \int_0^{t} f(ue_1) \, du \right) e_1 \\
	\frac{\partial \xi}{\partial s} &= -\frac 1 2 \frac{\partial f}{\partial x^1}(te_1) e_1.
\end{align*}
\end{lemma}

\begin{proof}
One checks directly that the solution in the statement solves \eqref{eq: perturbed hamilton equations} with the initial data
\[
	\frac{\partial x}{\partial s} = \frac{\partial \xi}{\partial s} = 0 \qquad \text{ at $t = 0$.}
\]
The lemma follows by uniqueness.
\end{proof}

The second kind of perturbation adjusts the trajectory of the geodesic, and is the more important of the two. For this, we use functions $f$ of the kind where $f(te_1) = 0$ for each $t$. The solution to \eqref{eq: perturbed hamilton equations} and \eqref{eq: perturbed initial data}.

We wish to, if not solve, then estimate the solution to \eqref{eq: perturbed hamilton equations} with initial data $\frac{\partial x}{\partial s} = 0$ and $\frac{\partial \xi}{\partial s} = 0$ at $t = 0$ for arbitrarily small $\epsilon > 0$. In the $\epsilon = 0$ limit, the pesky $\frac{\partial^2 p}{\partial x^i \partial x^j}$ term vanishes and we have an explicit solution
\begin{equation}\label{eq: idealized solution}
	\begin{split}
		\frac{\partial \tilde x}{\partial s} &= - \frac 1 2 \int_0^t (t - u) \nabla f(ue_1) \, du  \\
		\frac{\partial \tilde \xi}{\partial s} &= - \frac 1 2 \int_0^t \nabla f(ue_1) \, du.
	\end{split}
\end{equation}
The next lemma shows the true solution is not too far from this one if $\epsilon > 0$ is small enough.

\begin{lemma}
	Let $f$ be a smooth function supported in $U$ for which $f(te_1) = 0$ for each $t$. Then, with $\tilde x$ and $\tilde \xi$ as in \eqref{eq: idealized solution}, we have
	\[
		\left|\frac{\partial x}{\partial s} - \frac{\partial \tilde x}{\partial s} \right| = O(\epsilon^2) \qquad \text{ and } \qquad \left|\frac{\partial \xi}{\partial s} - \frac{\partial \tilde \xi}{\partial s} \right| = O(\epsilon^2)
	\]
	uniformly for $t \in [0,1]$.
\end{lemma}

\begin{proof}
Set
\[
	u = \frac{\partial x}{\partial s} - \frac{\partial \tilde x}{\partial s} \qquad \text{ and } \qquad v = \frac{\partial \xi}{\partial s} - \frac{\partial \tilde \xi}{\partial s},
\]
let $\nabla^2_x p$ denote the Hessian matrix of $p$ in the $x$-variables only,
and note $u$ and $v$ solve the nearly Hamiltonian system
\[
	\begin{split}
		u' &= v \\
		v' &= - \frac 1 2 \nabla_x^2 p \frac{\partial x}{\partial s} - \frac 1 2 u,
	\end{split}
\]
with $u = v = 0$ at $t = 0$. Now, consider the energy
\[
	E(t) = \frac 1 2 |u(t)|^2 + |v(t)|^2
\]
and note
\begin{align*}
	E' &= \langle u, u' \rangle + 2 \langle v, v' \rangle = - \left\langle v, \nabla_x^2 p \frac{\partial x}{\partial s} \right\rangle,
\end{align*}
and hence
\[
	|E'| \leq \sup_{t \in [0,1]} \|\nabla_x^2 p\| \left| \frac{\partial x}{\partial s} \right| |v| \leq a b \epsilon^2 \sqrt{E} \leq \frac{1}{2} \left( ab \epsilon^4 + ab E \right)
\]
where $a$ and $b$ are constants for which
\[
	\|\nabla_x^2 p\| \leq a \epsilon^2 \qquad \text{ and } \qquad \left|\frac{\partial x}{\partial s} \right| \leq b
\]
for each $t \in [0,1]$ and $0 < \epsilon < 1$. By Gr\"onwall's inequality, and since $E(0) = 0$,
\[
	E(t) \leq \epsilon^4 
	e^{\frac{ab}{2} t} \qquad \text{ for $t \in [0,1]$}.
\]
The lemma follows.
\end{proof}

Next, we consider a $(2n - 1)$-parameter family of perturbations. Let $h_1, h_2, h_3$ all be smooth functions supported in $U$ satisfying the following conditions. For $h_1$, we assert
\[
	\frac{\partial h_1}{\partial x^i}(te_1) = 0 \qquad \text{for each $t \in [0,1]$ and $i \geq 2$}
\]
and
\[
	\frac 1 2 \int_0^1 h_1(te_1) \, dt = 1.
\]
For $h_2$ and $h_3$, we assert
\begin{equation}\label{eq: direction-changing perturbation}
	-\frac 1 2 \int_0^1 h_2(te_1) \, dt = 1 \qquad \text{ and } \qquad -\frac 1 2 \int_0^1 (1 - t) h_2(te_1) \, dt = 0
\end{equation}
and
\[
	-\frac 1 2 \int_0^1 h_3(te_1) \, dt = 0 \qquad \text{ and } \qquad -\frac 1 2 \int_0^1 (1 - t) h_3(te_1) \, dt = 1.
\]
Then, consider the function
\begin{equation}\label{eq: final conformal perturbation}
	f_s(x) = s_1 h_1(x) + \sum_{i = 2}^n s_i x_i h_2(x) + \sum_{i = 2}^n s_{i+n-1} x_{i} h_3(x)
\end{equation}
for $s = (s_1, \ldots, s_{2n-1}) \in \R^{2n-1}$ along with the corresponding perturbation
\[
	(1 + f_s)p
\]
of the symbol. Combined with the previous lemmas, we obtain:

\begin{lemma} With $f_s$ as above, set $p_s(x,\xi) = (1 + f_s(x))p(x,\xi)$, and let $(x(\epsilon,s;t), \xi(\epsilon,s;t))$ be the family of integral curves to the Hamiltonian vector field $\frac 1 2 H_{p_s}$ with initial conditions
\[
	(x(\epsilon,s;0), \xi(\epsilon,s;0)) = (0,e_1).
\]
Then,
\[
	D_s (x,\xi) = \begin{bmatrix}
		I_n & 0 \\
		0 & 0 \\
		0 & I_{n-1}
	\end{bmatrix}
	+ O(\epsilon^2) \qquad \text{ at $s = 0$, $t = 1$} 
\]
\end{lemma}

We note that the geometer's geodesic flow for the metric $g$, i.e. the flow along the Hamiltonian vector field $\tfrac 1 2 H_{p}$, is homogeneous in the sense that
\begin{equation}\label{eq: flow homogeneity}
	\exp(\tfrac 1 2 H_{p})(0, \tau e_1) = (\tau e_1, \tau e_1),
\end{equation}
and hence
\[
	\left.\frac{\partial}{\partial \tau}\right|_{\tau = 1} \exp(\tfrac 1 2 H_{p})(0, \tau e_1) = (e_1, e_1).
\]
Combining this observation with the previous lemma yields:

\begin{lemma} \label{lem: local full rank}
	With $f_s$ as above, we have
	\[
		D_{\xi_1,s} \exp\big(\tfrac 1 2 H_{(1 + f_s)p}\big)(0,\xi_1 e_1) = \begin{bmatrix}
			* & I_{n} & 0 \\
			1 & 0 & 0 \\
			0 & 0 & I_{n-1}
		\end{bmatrix} + O(\epsilon^2).
	\]
	at $(\xi_1,s) = (1,0)$. That is, $\exp(\frac 1 2 H_{(1 + f_s)p})(0,\xi_1 e_1)$ has surjective differential at $(\xi_1,s) = (1,0)$ for all sufficiently small $\epsilon > 0$.
\end{lemma}

We are ready to transfer this lemma to our manifold.

\begin{proposition}\label{prop: conformal perturbation}
Suppose $(x_0, \xi_0) \in \dot T^*M$ satisfies
\begin{equation}\label{eq: non-closed condition}
	\exp(\tfrac t 2 H_p)(x_0, \xi_0) \neq (x_0, \xi_0) \qquad \text{ for all } t \in (0,1].
\end{equation}
Then, there exists an open neighborhood $U$ in $M$, an open neighborhood $S$ of the origin in $\R^{2n-1}$, and a smooth function $(s,x) \mapsto f_s(x)$ on $S \times U$ whose $x$-support is contained in $U$, such that
\[
	\exp(\tfrac 1 2 H_{(1 + f_s)p})(x_0, \tau\xi_0)
\]
has surjective differential $\R^{1 + (2n-1)} \to T_{(y_0,\eta_0)}T^*M$ at $(\tau,s) = (1,0)$, where
\[
	(y_0,\eta_0) = \exp(\tfrac 1 2 H_p)(x_0, \xi_0).
\]
\end{proposition}

\begin{proof}
	Let $\gamma(t)$ be the geodesic in $M$ traced by the spacial component of the integral curve $\exp(\frac t 2 H_p)(x_0, \xi_0)$. The condition \eqref{eq: non-closed condition} ensures $\gamma$ intersects itself only finitely many times. The argument is perhaps a routine Riemannian geometry exercise, so we just sketch the steps.
First, since $\gamma$ is locally an embedding about each point and $[0,1]$ is compact, pairs of times $t \neq t'$ in $[0,1]$ at which $\gamma(t) = \gamma(t')$ are separated by a positive distance. If there are infinitely many such pairs, one takes a convergent sequence $(t_k, t_k') \to (t,t')$ and notes $t \neq t'$. Since $\gamma(t_k) = \gamma(t_k')$ for each $k$, we deduce $\gamma'(t) = \pm \gamma'(t')$. If the sign is positive, it contradicts \eqref{eq: non-closed condition}. If the sign is negative, the geodesic is ill-defined at $\frac{t + t'}{2}$.

	Since $\gamma$ has finitely many self-intersections, there exists $\epsilon > 0$ for which $\gamma : (1 - \epsilon, 1) \to M$ does not intersect $\gamma([0,1-\epsilon] \cup \{1\})$. Select Fermi normal coordinates about the geodesic segment $\gamma([1-\epsilon,1])$ satisfying \eqref{eq: fermi conditions}. Consider an open neighborhood $U$ intersecting $\gamma$ only along the segment $\gamma((1 - \epsilon, 1))$. Any perturbation of the metric supported in $U$ will leave $(x(1 - \epsilon), \xi(1 - \epsilon))$ unchanged. The lemma follows after taking $\epsilon > 0$ small, rescaling the interval $[1-\epsilon,1]$ to $[0,1]$, using \eqref{eq: flow homogeneity}, and Lemma \ref{lem: local full rank}.
\end{proof}
}

