\section{Generic submanifolds have no closed normal geodesics}\label{sec: no closed normal}

{
The main proposition of this section shows that, for most metrics, an embedded submanifold intersects no closed geodesics conormally.

\begin{proposition}\label{prop: generically no conormal closed geodesics}
    For each $T > 0$, there exists an open-dense set of metrics $g$ such that, for each $(x,\xi) \in \dot N^*\Sigma$ with $p_g(x,\xi) \leq T$ and for each $t \in (0,1]$,
    \[
        \exp(\tfrac t 2 H_{p_g})(x,\xi) \neq (x,\xi).
    \]
\end{proposition}

Taking the countable intersection over $T \in \N$ yields a residual set of metrics for which the proposition holds without constraints on $p_g(x,\xi)$, but this is not what we need here.

Our starting point is Proposition \ref{prop: bumpy metric}, which gives an open-dense set, say $\mathcal G_T$, of metrics for which there are only finitely many $(x,\xi) \in \dot T^*M$ with $p_g(x,\xi) \leq T$ and
\[
    \exp(\tfrac t 2 H_{p_g})(x,\xi) = (x,\xi).
\]
We first argue:

\begin{lemma}
    The exceptional set of metrics $g$ for which there exists $(x,\xi) \in \dot N^* \Sigma$ with $p_g(x,\xi) \leq T$ and
    \[
        \exp(\tfrac t 2 H_{p_g})(x,\xi) = (x,\xi) \qquad \text{ for some } t \in (0,1]
    \]
    is closed in $\mathcal G$, and hence also in $\mathcal G_T$.
\end{lemma}

\begin{proof}
    Consider the exceptional set $E \subset \mathcal G \times (0,1] \times \dot N^*\Sigma$ of elements $(g,t,x,\xi)$ for which
    \[
        p_g(x,\xi) \leq T, \qquad \text{ and } \qquad \exp(\tfrac t 2 H_{p_g})(x,\xi) = (x,\xi).
    \]
    Let $\pi : E \to G$ be the standard projection. We claim $\pi(E)$ is closed. Consider a sequence of metrics $g_n \in \pi(E)$ that converges to $g \in \mathcal G$. Let $(g_n, t_n, x_n, \xi_n) \in E$ be some element in $E$ that projects to $g_n$. Let $C$ be a constant for which
    \[
        p_{g_n} \leq C p_g \qquad \text{ for each } n \in \N,
    \]
    and note that since $p_{g_n}(x_n, \xi_n) \leq T$ for each $n$,
    \[
        p_g(x_n, \xi_n) \leq C T \qquad \text{ for each $n \in \N$}.
    \]
    Refine the sequence so that $(x_n, \xi_n) \to (x,\xi) \in N^*\Sigma$ and note
    \[
        p_g(x,\xi) = \lim_{n \to \infty} p_{g_n}(x_n, \xi_n) \leq T.
    \]
    Next, let $\epsilon > 0$ bound the injectivity radii of $g_n$ and $g$ from below, and note that if
    \[
        \exp(\tfrac {t_n} 2 H_{p_{g_n}})(x_n, \xi_n) = (x_n, \xi_n),
    \]
    then $t_n p_{g_n}(x_n, \xi_n) \geq \epsilon$. From this, we conclude
    \[
        t_n \in [\tfrac \epsilon T, 1] \qquad \text{ and } p_{g_n}(x_n, \xi_n) \geq \epsilon.
    \]
    We refine our sequence further so that $t_n$ converges to $t \in [\tfrac \epsilon T, 1]$, and note in particular that
    \[
        t \in (0,1] \qquad \text{ and } \qquad 0 < p_g(x,\xi) \leq T.
    \]
    Finally, $\exp(\frac t 2 H_{p_g})(x,\xi) = (x,\xi)$ too, and we conclude $g \in \pi(E)$, as desired.
\end{proof}

Secondly, we will use the perturbation introduced in Section \ref{sec: perturbation 1} to show:

\begin{lemma}
    The exceptional set of metrics $g$ for which there exists $(x,\xi) \in \dot N^* \Sigma$ with $p_g(x,\xi) \leq T$ and
    \[
        \exp(\tfrac t 2 H_{p_g})(x,\xi) = (x,\xi) \qquad \text{ for some } t \in (0,1]
    \]
    has dense complement in $\mathcal G_T$.
\end{lemma}

Once proved, the two lemmas complete the proof of Proposition \ref{prop: generically no conormal closed geodesics}.

\begin{proof}
    Fix $g \in \mathcal G_T$ and let
    \begin{multline*}
        \Gamma_T = \{(x,\xi) \in \dot T^*M : 0 < p_g(x,\xi) \leq T \\
        \text{ and } \exp(\tfrac t 2 H_{p_g})(x,\xi) = (x,\xi) \text{ for some $t \in (0,1]$}\}.
    \end{multline*}
    Note, $\Gamma_T$ is the finite disjoint union of $2$-dimensional connected components, and $\Gamma_T \cap \dot N^*\Sigma$ is a disjoint union of $1$-dimensional connected components, each of which lies tangent to the radial vector field in the fiber of $\dot T^*M$. Let $x_0 \in M$ be the projection of such a component to $M$. Consider the parametrized family of vector fields $F : \R^{n + n^2} \to \mathcal X(M)$ centered at $x_0$ as in Proposition \ref{prop: perturbation}. By the proposition and Thom's transversality theorem, there is a residual set of parameters $(a,b) \in \R^{n + n^2}$ for which $\tau_{F(a,b)}(\dot N^*\Sigma)$ intersects $\Gamma_T$ transversally. If the intersection is nonempty, it has dimension $1$, and yet
    \[
        2n = \dim T^*M = \dim(\dot N^*\Sigma) + \dim(\Gamma_T) - 1 = n + 1,
    \]
    which is an absurdity for $n \geq 2$. Hence, for most $(a,b)$, the intersection is empty. By the discussion preceding Proposition \ref{prop: perturbation}, the pullback metric
    \[
        \exp(F(a,b))^*g
    \]
    admits no intersection of $\dot N^*\Sigma$ and $\Gamma_T$ at $x_0$ for a dense set of $(a,b) \in \R^{n + n^2}$. Note, $\exp(F(a,b))^*g$ is in the same isometry class as $g$, and hence is also a member of $\mathcal G_T$, and can be made close to $g$ provide $(a,b)$ is close to the origin. We are done after repeating the procedure for each of the finitely many sites of intersection.
\end{proof}
}

