\section{Proof of Theorem \ref{thm: main}}\label{sec: proof of main}

{

Let $\mathcal G_T$ denote the set of metrics $g$ for which there are only finitely many geodesics that close by time $T$. Proposition \ref{prop: bumpy metric} ensures $\mathcal G_T$ is open-dense in the full space of metrics $\mathcal G$. Let $\mathcal G_T' \subset \mathcal G_T$ denote the subset of metrics for which there are no covectors $(x,\xi) \in \dot N^*\Sigma$ such that
\[
    p_g(x,\xi) \leq T \qquad \text{ and } \qquad \exp(\tfrac t 2 H_{p_g})(x,\xi) = (x,\xi) \text{ for some $t \in (0,1]$}.
\]
Proposition \ref{prop: generically no conormal closed geodesics} ensures $\mathcal G_T'$ is open-dense in $\mathcal G_T$, and hence also open-dense in $\mathcal G$. The next proposition concerns the set $\mathcal G_T'' \subset \mathcal G_T'$ of metrics for which
\[
    \exp(\tfrac 1 2 H_{p_g}) : \dot N^*\Sigma \to T^*M \text{ is transversal to } \dot N^*\Sigma \cap p_g^{-1}[0,\tfrac T 4],
\]
as required by Theorem \ref{thm: main}. 

\begin{proposition}\label{prop: almost there}
    The set of metrics $\mathcal G_T''$ is residual in $\mathcal G_T'$, and hence residual in $\mathcal G$.
\end{proposition}

Before we prove this last proposition, we first see how it implies Theorem \ref{thm: main}.

\begin{proof}[Proof of Theorem \ref{thm: main}]
    The countable intersection
    \[
        \bigcap_{N \in \N} \mathcal G_N''
    \]
    is also residual in $\mathcal G$. Furthermore, for each metric in the intersection,
    \[
        \exp(\tfrac 1 2 H_{p_g}) : \dot N^*\Sigma \to T^*M \text{ is transversal to } \dot N^*\Sigma,
    \]
    as desired.
\end{proof}
}

To prove Proposition \ref{prop: almost there}, we require a lemma that will take the perturbations we have established in Section \ref{sec: perturbation} and produce the desired residual set of metrics. We defer the proof until the end of this section.

\begin{lemma}\label{lem: machinery} Let $B$ be a Baire space, $X$ and $Y$ smooth manifolds, and $Z \subset Y$ an embedded submanifold. Let
\[
	\Phi : B \to C^\infty(X,Y)
\]
be a continuous map. Suppose for each $(b_0,x_0) \in B \times X$ for which $\Phi(b)$ is non-transversal to $Z$ at $x_0$, there exists a neighborhood $S$ of the origin in $\R^n$, an open neighborhood $U$ of $b_0$, and a continuous map $\beta : U \times S \to B$ such that:
\begin{enumerate}
	\item $\beta(b,0) = b$ for each $b \in U$.
	\item If $\Psi(b,s,x) = \Phi(\beta(b,s))x$, then $b \mapsto \Psi(b,\cdot, \cdot)$ is a continuous mapping $U \to C^\infty(S \times X, Y)$.
	\item $(s,x) \mapsto \Psi(b_0,s,x)$ is transversal to $Z$ at $(0,x_0)$.
\end{enumerate}
Then, $\{ b \in B : \Phi(b) \text{ is transversal to } Z \}$ is residual in $B$.
\end{lemma}

{
We are now ready to prove Proposition \ref{prop: almost there}.

\begin{proof}[Proof of Proposition \ref{prop: almost there}] 
