	\section{Introduction and Statements}\label{sec:intro}

For $N\geq 2$, the system $\mathcal{I}=\big\{ f_1,f_2,\ldots,f_N \big\}$ on $\mathbb{R}^d$ is called an \texttt{iterated function system (IFS)}, if each $f_i$ is a contraction map on $\mathbb{R}^d$ for $i\in \{1,2,\ldots, N\}$. Hutchinson \cite{Hutchinson} proved that there exists a unique non-empty compact set $A\subset \mathbb{R}^d$ such that 
$$A=\bigcup_{i=1}^{N}f_i(A).$$ 
Let $\mathbf{p}=(p_1,p_2,\dots,p_N)$ be a probability vector. Hutchinson \cite{Hutchinson} also proved that there exists a unique Borel probability measure $\mu$ supported on $A$ such that 
$$\mu(B)=\sum_{i=1}^{N}p_{i}\mu(f_{i}^{-1}(B))$$
for all Borel sets $B\subset \mathbb{R}^d$. The set $A$ is called the \texttt{attractor} of IFS $\mathcal{I}$ and the measure $\mu$ is known as the \texttt{stationary measure} corresponding to IFS $\mathcal{I}$ with the probability vector $\mathbf{p}$. 

    This paper focuses on the dimension theory of self-similar IFSs on the line. The IFS $\mathcal{I}$ is called a \texttt{self-similar iterated function system} on $\mathbb{R}$ if each $f_{i}:\mathbb{R}\to \mathbb{R}$ is a similarity map for $i\in\{1,2,\dots,N\}$, i.e.
$f_i(x)=r_ix+c_i$ where $0<|r_{i}|<1$ and $c_{i}\in \mathbb{R}$. Then, the attractor $A$ is called a \texttt{self-similar set} corresponding to the self-similar IFS $\mathcal{I}$. The stationary measure $\mu$ is known as the \texttt{self-similar measure} corresponding to the self-similar IFS $\mathcal{I}$ with probability vector $\mathbf{p}=(p_1,p_2,\dots,p_N)$. For later purposes, let us recall the definition of the Hausdorff dimension here.

Let $F\subseteq \mathbb{R}^d$. We say that $\{U_{i}\}_{i=1}^\infty$ is a $\delta$ cover of $F$ if $F\subset \bigcup\limits_{i=1}^{\infty}U_{i}$ and $0 <|U_{i}|\leq \delta$ for each ${i}$, where $|U_i|$ denotes the diameter of the set $U_i$. For each $\delta>0$ and $s\geq 0$, we define
		$$\mathcal{H}_{\delta}^{s}(F):=\inf\Big\{\sum_{i=1}^{\infty}|U_{i}|^{s} : \{U_{i}\} \text{ is a }\delta\text{-cover of }F\Big\}\text{ and }\mathcal{H}^{s}(F):=\lim_{\delta\to 0+}\mathcal{H}_{\delta}^{s}(F).$$
		We call $\mathcal{H}^{s}(F)$ the \texttt{$s$-dimensional Hausdorff measure} of the set $F$. Using this, the \texttt{Hausdorff dimension} of the set $F$ is defined by 
		$$\dim_{H}(F)=\inf\{s\geq 0 : \mathcal{H}^{s}(F)=0\}.$$
For the basic properties, we refer the reader to Falconer's book \cite{Falconer1990}. Another widely used dimension concept is the box-counting (or Minkowski) dimension; however, Falconer \cite{Falconer1989} pointed out that these dimension concepts are equal for self-similar sets, so we omit them.

For a Borel probability measure $\mu$ in $\mathbb{R}^d$, the \texttt{lower- and upper local dimension} of the measure $\mu$ at the point $x\in \mathbb{R}^d$ defined as $$\underline{d}_{\mu}(x)=\liminf_{r\to 0}\frac{\log \mu(B(x,r))}{\log r},\quad \overline{d}_{\mu}(x)=\limsup_{r\to 0}\frac{\log \mu(B(x,r))}{\log r},$$
  where $B(x,r)$ denotes the open ball of radius $r$ with center $x$. %The lower- and upper Hausdorff dimensions of the measure $\mu$ are defined as 
%$$\underline{\dim}_{H}(\mu)=\inf\{\dim_{H}(A): \mu(A)>0\},\ \overline{\dim}_{H}(\mu)=\inf\{\dim_{H}(A): \mu(\mathbb{R}^{d}\setminus A)=0\}.$$
%The relation between the Hausdorff dimension of the measure and the local dimension of the measure is as follows:
%$$\underline{\dim}_{H}(\mu)={\text{ess}\inf} \underline{d}_{\mu}(x)\quad \text{and}\quad \overline{\dim}_{H}(\mu)=\text{ess}\sup \underline{d}_{\mu}(x),$$
%see Przytycki and Urba\'nski \cite[Section~7.6]{PU10}. 
We say that the measure $\mu$ is \texttt{exact dimensional} if there is a constant $c$ such that $\underline{d}_{\mu}(x)=\overline{d}_{\mu}(x)=c$ for $\mu$-almost every $x\in \mathbb{R}^d$. We will denote this value by $\dim_{H}(\mu)$. Feng and Hu \cite{FengandHu} proved that every self-similar measure $\mu$ is exact dimensional. For further properties of the dimension of measures, see Przytycki and Urba\'nski \cite[Section~7.6]{PU10}.

Let us define the \texttt{similarity dimension} for the self-similar IFS $\mathcal{I}$ to be the unique number $s_{0}\in \mathbb{R}$ such that $$\sum_{i=1}^{N}|r_{i}|^{s_0}=1.$$ Furthermore, the quantities 
$$h_{\mathbf{p}}=-\sum_{i=1}^{N}p_{i}\log p_{i}\quad \text{and}\quad \chi(\mathbf{p})=-\sum_{i=1}^{N}p_i\log |r_{i}|$$
are known respectively as the \texttt{entropy} and the \texttt{Lyapunov exponent} of the self-similar measure $\mu$ corresponding to the self-similar IFS $\mathcal{I}$ with probability vector $\mathbf{p}$. It is well known that 
$$\dim_{H}(A)\leq \min\{1,s_0\} \quad \text{and}\quad \dim_{H}(\mu)\leq \min\bigg\{1, \frac{h_{\mathbf{p}}}{\chi(\mathbf{p})}\bigg\}$$ 
regardless of any further assumptions. However, equalities appear in the above expressions under some suitable separation conditions.

\begin{theorem}[Hutchinson \cite{Hutchinson}, Cawley and Mauldin \cite{CaMa}]
    Let the self-similar IFS $\mathcal{I}$ on $\mathbb{R}$. If $\mathcal{I}$ satisfies the \texttt{open set condition (OSC)}, that is, there is a nonempty and bounded open set $O\subset \mathbb{R}^d$ with $f_i(O) \subset O$ and $ f_i(O)\cap f_j(O)= \emptyset $ for $i\ne j \in \{1,2,\dots, N\}$, then
   \begin{equation}\label{eq:nodrop}\dim_{H}(A)= s_0 \quad \text{and}\quad \dim_{H}(\mu)= \frac{h_{\mathbf{p}}}{\chi(\mathbf{p})},\end{equation}
   where $A$ is the self-similar attractor of the self-similar IFS $\mathcal{I}$ and $\mu$ is the self-similar measure corresponding to the self-similar IFS $\mathcal{I}$ with probability vector $\mathbf{p}$.
\end{theorem}

Hochman \cite{Hochman2014} introduced the Exponential Separation Condition for the self-similar IFSs, which is a much weaker separation condition than the OSC. We say that the self-similar IFS $\mathcal{I}$ on $\mathbb{R}$ satisfies the \texttt{Exponential Separation Condition (ESC)} if there exists a constant $\eta>0$ such that for infinitely many values of $n\in \mathbb{N}$ for all $i_1,\ldots,i_n,j_1,\ldots,j_n\in \{1,\ldots, N\}$ with $(i_1,\ldots,i_n)\ne(j_1,\ldots,j_n)$ and $r_{i_1}\cdots r_{i_n}=r_{j_1}\cdots r_{j_n}$, we have 
   $$|f_{i_1}\circ\cdots\circ f_{i_n}(0)-f_{j_1}\circ \cdots\circ f_{j_n}(0)|\geq {\eta}^{n}.$$ 
In a proper sense, the exponential separation is a typical property for self-similar IFSs. For example, suppose the contraction ratios and translations are analytic maps of some one-dimensional parameter, and the system is not degenerate. In that case, ESC holds out of a zero-dimensional set of exceptional parameters. In particular, for fixed contraction ratios with $\max_{i\neq j}\{|r_i|+|r_j|\}<1$, the dimension of translation vectors $(c_i)_{i=1}^N\in\mathbb{R}^N$, for which $\mathcal{I}$ does not satisfy ESC, is at most $N-1$, see \cite[Corollary~6.8.12]{BSS23}\footnote{We note that the assumption $\max_{i\neq j}\{|r_i|+|r_j|\}<1$ is missing incorrectly in the statement.}. Hochman \cite{Hochman2014} proved the following groundbreaking result for the dimension theory of self-similar IFSs.

\begin{theorem}\label{MainHochmanresult}[Hochman~\cite{Hochman2014}]
    If the self-similar IFS $\mathcal{I}$ on $\mathbb{R}$ satisfies the ESC, then 
    \begin{equation}\label{eq:nodrop2}\dim_{H}(A)=\min\{1,s_0\} \quad \text{and}\quad \dim_{H}(\mu)=\min\left\{1,\frac{h_{\mathbf{p}}}{\chi(\mathbf{p})}\right\}.\end{equation}
\end{theorem}

The ESC implies that the self-similar IFS $\mathcal{I}$ has no exact overlap, i.e. there are no finite sequences of symbols $(i_1,\ldots,i_n)\ne(j_1,\ldots,j_m)$ such that $f_{i_1}\circ\cdots\circ f_{i_n}\equiv f_{j_1}\circ \cdots\circ f_{j_m}$. When exact overlaps exist, a better bound can be obtained by considering the number of exact overlaps. Lau and Ngai \cite{LauNgai} and Zerner \cite{Zerner} introduced the Weak Separation Condition (WSC), which allows exact overlaps. Still, the not-exactly overlapping maps must be relatively far from each other, comparable with the contraction ratios of the maps. This allows us to calculate the dimension of the attractor as a limit of the similarity dimensions of higher iterates. In some special cases, when the contraction ratios are reciprocals of integers, it is possible to calculate the dimension of the corresponding self-similar measures, see Ruiz \cite{Ruiz}.

The situation becomes significantly more difficult if the overlapping structure of the self-similar IFS $\mathcal{I}$ is complicated, for instance, when some of the maps of the IFS share the same fixed point. Let $(t_i)_{i=1}^N\in\mathbb{R}^N$ be a vector with pairwise different entries. For every $i\in\{1,\ldots,N\}$, let $n_i\geq1$ be an integer. For every $j\in\{1,\ldots,n_i\}$, let $\lambda_{i,j}\in(0,1)$. Consider the following self-similar IFS on the real line:
	\begin{equation}\label{eq:mainIFS}\mathcal{S}=\{f_{i,j}(x)=\lambda_{i,j}x+t_{i}(1-\lambda_{i,j})\}_{1\leq i\leq N, 1\leq j\leq n_i}.\end{equation}
If $n_i\geq2$ for some $i$, then the maps $f_{i,j}$ and $f_{i,j'}$ with $j\neq j'$ share the same fixed point, which causes many exact overlaps, for example $f_{i,j}\circ f_{i,j'}\equiv f_{i,j'}\circ f_{i,j}$. Furthermore, if $\frac{\log\lambda_{i,j}}{\log\lambda_{i,j'}}\notin\mathbb{Q}$ then the IFS $\mathcal{S}$ does satisfy the WSC, see Fraser \cite{FrasernoWSC}, and if $\frac{\log\lambda_{i,j}}{\log\lambda_{i,j'}}=\frac{p}{q}\in\mathbb{Q}$ then it causes further exact overlaps, since composing $f_{i,j'}$ with itself $p$-times and composing $f_{i,j}$ with itself $q$-times result the same map.

The first author has already studied the dimension theory of such systems previously. The first author in \cite{Barany1} and with Szv\'ak in \cite{BS2021} studied the Hausdorff dimension of the attractor of the special case $\{\lambda_{1,1}x,\lambda_{1,2}x,\lambda_{2,1}x+1\}$. They showed that if $\lambda_{1,1}+\lambda_{2,1}<1$ then for Lebesgue almost every $\lambda_{1,2}\in(0,\lambda_{1,1})$ the dimension of the attractor is $\min\{1,s\}$, where $s$ is the unique root of the equation
$$\lambda_{1,1}^{s}+\lambda_{1,2}^s-\lambda_{1,1}^s\lambda_{1,2}^s+\lambda_{2,1}^s=1.$$
Moreover, in  \cite{BS2021}, the first author and Szv\'ak gave a formula for the dimension of self-similar measures corresponding to that IFS for Lebesgue almost every parameters under the technical assumption that $0<\lambda_{1,1},\lambda_{1,2},\lambda_{2,1}<1/9$. Further generalisations can be found in \cite{Barany2, Barany4corner}.

In this paper, we extend significantly the dimension result for such systems. For simplicity, let us introduce the following notations: let $L=\sum_{i=1}^Nn_i$ be the number of maps in $\mathcal{S}$, let $\underline{\lambda}=(\lambda_{i,j})_{1\leq i\leq N,1\leq j\leq n_i}$ be the $L$-dimensional vector formed by the contraction ratios, and let $\underline{t}=(t_i)_{1\leq i\leq N}$ be the vector formed by the fixed points. To emphasize the dependence on the the parameters, we may write $\mathcal{S}_{\underline{\lambda},\underline{t}}$ for the system defined in \eqref{eq:mainIFS}, $A_{\underline{\lambda},\underline{t}}$ for the attractor of $\mathcal{S}_{\underline{\lambda},\underline{t}}$ and $\mu_{\underline{\lambda},\underline{t}}^{\mathbf{p}}$ for the self-similar measure corresponding to the IFS $\mathcal{S}_{\underline{\lambda},\underline{t}}$ and probability vector $\mathbf{p}$. Our main result on the dimension of self-similar measures is the following:

\begin{theorem}\label{thm:main} Let $\mathcal{S}_{\underline{\lambda},\underline{t}}$ be a self-similar IFS as in \eqref{eq:mainIFS}. There exists a set $\mathbf{E}\subset(0,1)^{L}$ with $\dim_H(\mathbf{E})\leq L-1$ such that for every $\underline{\lambda}\in(0,1)^{L}\setminus\mathbf{E}$ there exists a set $\mathbf{F}\subset\mathbb{R}^N$ with $\dim_H(\mathbf{F})\leq N-1$ such that for every $\underline{t}\in\mathbb{R}^N\setminus\mathbf{F}$ the following holds: for every probability vector $\mathbf{p}=(p_{i,j})_{1\leq i\leq N, 1\leq j\leq n_i}$ 
	$$\dim_{H}(\mu_{\underline{\lambda},\underline{t}}^{\mathbf{p}})=\min\bigg\{1, \frac{-\sum_{i=1}^{N}\sum_{j=1}^{n_i}p_{i,j}\log(p_{i,j})+\Phi(\mathbf{p})}{-\sum_{i=1}^{N}\sum_{j=1}^{n_i}p_{i,j}\log(\lambda_{i,j})}\bigg\},$$
		where 
        \begin{equation}\label{eq:phip}
        \Phi(\mathbf{p})=\sum_{l=1}^{N}\sum_{m=1}^{n_{l}}\sum_{k=0}^{\infty}\sum_{q=0}^{k}\binom{k}{q}(p_{l,m})^{q+1}\left(\sum_{\substack{j=1\\j\neq m}}^{n_l}p_{l,j}\right)^{k-q}\bigg(1-\sum_{j=1}^{n_l}p_{l,j}\bigg)\log\left(\frac{q+1}{k+1}\right).
        \end{equation}
\end{theorem}

This result significantly strengthens the previous result of the first author and Szv\'ak \cite[Theorem~1.2]{BS2021}. Although the expression $\Phi(\mathbf{p})$ is tedious, it has a simple heuristic. It measures the proportion of the symbol that appears first in the first block, which is formed by the maps sharing the same fixed point. Namely, suppose $X_{1}, X_{2},\dots$ are independent and identically distributed random variables such that $\mathbb{P}(X_r=(i,j))=p_{i,j}$ for all $i\in\{1,\dots, N\}$ and $j\in \{1,2,\dots,n_i\}$. Let $k_{i,j}:=\min\{r\geq 1: X_r\notin\{(i,1),\ldots,(i,n_i)\} \}$, and let $Y_{i,j}:=\#\{1\leq r\leq k_{i,j}-1: X_r=(i,j)\}$ for all $j\in \{1,2,\dots,n_i\}.$ Then, the quantity $\Phi(\mathbf{p})$ can be written in the form 
$$\Phi(\mathbf{p})= \mathbb{E}\bigg(\log\bigg(\frac{Y_{X_1}}{k_{X_1}-1}\bigg)\bigg).$$ 

Next, we state a similar result for the dimension of the attractor of $\mathcal{S}_{\underline{\lambda},\underline{t}}$.

\begin{theorem}\label{dimattractor}
  Let $\mathcal{S}_{\underline{\lambda},\underline{t}}$ be a self-similar IFS as in \eqref{eq:mainIFS}. There exists a set $\mathbf{E}\subset(0,1)^{L}$ with $\dim_H(\mathbf{E})\leq L-1$ such that for every $\underline{\lambda}\in(0,1)^{L}\setminus\mathbf{E}$ there exists a set $\mathbf{F}\subset\mathbb{R}^N$ with $\dim_H(\mathbf{F})\leq N-1$ such that for every $\underline{t}\in\mathbb{R}^N\setminus\mathbf{F}$,
  $$\dim_H(A_{\underline{\lambda},\underline{t}})=\min\{1,s_0\},$$ where $A_{\underline{\lambda},\underline{t}}$ is the attractor of $\mathcal{S}_{\underline{\lambda},\underline{t}}$ and $s_0$ is the unique solution of the equation
  \begin{equation}\label{eq:dimatt}
  \sum_{i=1}^N\prod_{j=1}^{n_i}(1-(\lambda_{i,j})^{s_0})=N-1.
  \end{equation}
\end{theorem}

This significantly strengthens the previous results in \cite{Barany1, Barany2, Barany4corner, BS2021}.

\section{Applications and discussion}

\subsection{Typical self-similar systems} Before we prove our main result, Theorem~\ref{thm:main}, we show some applications of it. First, we show that the assumption $\max_{i\neq j}\{|r_i|+|r_j|\}<1$ in \cite[Corollary~6.8.12]{BSS23} can be strengthened.

\begin{theorem}\label{thm:main2}
    Let $\mathcal{I}=\{f_i(x)=r_ix+c_i\}_{i=1}^N$ be a self-similar IFS. Then there exists a set $\mathbf{E}\subset(0,1)^{N}$ with $\dim_H(\mathbf{E})\leq N-1$ such that for every $(r_{i})_{i=1}^N\in(0,1)^{N}\setminus\mathbf{E}$ there exists a set $\mathbf{F}\subset\mathbb{R}^N$ with $\dim_H(\mathbf{F})\leq N-1$ such that for every $(c_i)_{i=1}^N\in\mathbb{R}^N\setminus\mathbf{F}$ the following holds: for every self-similar measure $\mu$ corresponding to the self-similar IFS $\mathcal{I}$ and the probability vector $\mathbf{p}=(p_{i})_{i=1}^{N}$
		$$\dim_{H}(\mu)=\min\bigg\{1, \frac{-\sum_{i=1}^{N}p_{i}\log(p_{i})}{-\sum_{i=1}^{N}p_{i}\log(r_{i})}\bigg\}.$$
\end{theorem}

\begin{proof}
    Since $n_i=1$ for every $i=1,\ldots,N$, it is easy to see that the expression $\Phi(\mathbf{p})$ in Theorem~\ref{thm:main} equals $0$. Thus, the claim follows.
\end{proof}

\subsection{Estimating the \texorpdfstring{$\Phi(\mathbf{p})$}{Φ(p)}} Now, we will establish a bound for $\Phi(\mathbf{p})$, which might be helpful in estimating from below the Hausdorff dimension of self-similar measures with common fixed point structure.

\begin{proposition}\label{lem:lowerbound} Let $\mathbf{p}=(p_{i,j})_{1\leq i\leq N, 1\leq j\leq n_i}$ be a probability vector and let $\Phi(\mathbf{p})$ be defined as in \eqref{eq:phip}. Then
	$$\Phi(\mathbf{p}) \geq \sum_{l=1}^{N}\sum_{m=1}^{n_{l}}p_{l,{m}} \log \bigg(p_{l,{m}}+\sum_{\substack{i\ne l\\ i=1}}^{N}\sum_{j=1}^{n_i}p_{i,j}\bigg).$$
\end{proposition}
\begin{proof}
Let us recall the representation of $\Phi(\mathbf{p})$ from Section~\ref{sec:intro}. Suppose $X_{1},X_{2},\dots$ is i.i.d. such that $\mathbb{P}(X_r=(i,j))=p_{i,j}$ for all  $i\in\{1,\dots,N\}$ and $j\in \{1,2,\dots,n_i\}$. Let $k_{i,j}:=\min\{r\geq 1: X_r\notin\{(i,1),\ldots,(i,n_i)\} \},$ and let $Y_{i,j}:=\#\{1\leq r\leq k_i-1: X_r=(i,j)\}$ for all $j\in \{1,2,\dots,n_i\}.$ Then, the quantity $\Phi(\mathbf{p})$ can be written in the following form 
	$$ \Phi(\mathbf{p})= \mathbb{E}\bigg(\log\bigg(\frac{Y_{X_1}}{k_{X_1}-1}\bigg)\bigg)=\sum_{l=1}^{N}\sum_{m=1}^{n_{l}}p_{l,{m}} \mathbb{E}\bigg(\log\bigg(\frac{Y_{l,m}}{k_{l,m}-1}\bigg) \bigg| X_{1}=(l,m)\bigg),$$ where
	\begin{align*}
	&\mathbb{E}\bigg(\log\bigg(\frac{Y_{l,m}}{k_{l,m}-1}\bigg) \bigg| X_{1}=(l,m)\bigg)\\
    &\quad\quad= \sum_{k=0}^{\infty}\sum_{q=0}^{k}\binom{k}{q}p_{l,m}^q\left(\sum_{\substack{j=1\\j\neq m}}^{n_l}p_{l,j}\right)^{k-q}\bigg(1-\sum_{j=1}^{n_l}p_{l_j}\bigg)\log\bigg(\frac{q+1}{k+1}\bigg).
	\end{align*}
Clearly,
\begin{align*}
\mathbb{E}\bigg(\log\bigg(\frac{Y_{l,m}}{k_{l,m}-1}\bigg) \bigg| X_{1}=(l,m)\bigg)&=\mathbb{E}\bigg(-\log\bigg(\frac{k_{l,m}-1}{Y_{l,m}}\bigg) \bigg| X_{1}=(l,m)\bigg)\\
&\geq -\log \mathbb{E}\bigg(\frac{k_{l,m}-1}{Y_{l,m}} \bigg| X_{1}=(l,m)\bigg),
\end{align*}
where we used Jensen's inequality. Then
\begin{align*}
\mathbb{E}\bigg(\frac{k_l-1}{Y_{X_r}}| X_{1}=l_m\bigg)&=\sum_{k=0}^{\infty}\sum_{q=0}^{k}\binom{k}{q}p_{l,m}^q\left(\sum_{\substack{j=1\\j\neq m}}^{n_l}p_{l,j}\right)^{k-q}\bigg(1-\sum_{j=1}^{n_l}p_{l,j}\bigg)\frac{k+1}{q+1}\\
&=\sum_{k=0}^{\infty}\sum_{q=0}^{k}\binom{k+1}{q+1}p_{l,m}^{q}\left(\sum_{\substack{j=1\\j\neq m}}^{n_l}p_{l,j}\right)^{k-q}\bigg(1-\sum_{j=1}^{n_l}p_{l,j}\bigg)\\
&=\sum_{k=1}^{\infty}\bigg(1-\sum_{j=1}^{n_l}p_{l,j}\bigg)\frac{1}{p_{l,m}}\left(\bigg(\sum_{j=1}^{n_l}p_{l_j}\bigg)^{k}-\bigg(\sum_{\substack{j=1\\j\ne m}}^{n_l}p_{l_j}\bigg)^{k}\right)\\
&=\bigg(1-\sum_{j=1}^{n_l}p_{l_j}\bigg)\frac{1}{p_{l,m}}\bigg(\frac{\sum_{j=1}^{n_l}p_{l,j}}{1-\sum_{j=1}^{n_l}p_{l,j}}-\frac{\sum_{j=1,j\ne m}^{n_l}p_{l,j}}{1-\sum_{j=1,j\ne m}^{n_l}p_{l,j}}\bigg)\\
&=\left(1-\sum_{\substack{j=1\\j\ne m}}^{n_l}p_{l,j}\right)^{-1}=\left(p_{l,{m}}+\sum_{\substack{i\ne l\\ i=1}}^{N}\sum_{j=1}^{n_i}p_{i,j}\right)^{-1}
\end{align*}
Thus, from the above, we have 
$$\mathbb{E}\bigg(\log\bigg(\frac{Y_{l,m}}{k_{l,m}-1}\bigg) \bigg| X_{1}=(l,m))\bigg)\geq \log \bigg(p_{l,{m}}+\sum_{\substack{i\ne l\\ i=1}}^{N}\sum_{j=1}^{n_i}p_{i,j}\bigg).$$ This implies that 
$$\Phi(\mathbf{p}) \geq \sum_{l=1}^{N}\sum_{m=1}^{n_{l}}p_{l,{m}} \log \bigg(p_{l,{m}}+\sum_{\substack{i\ne l\\ i=1}}^{N}\sum_{j=1}^{n_i}p_{i,j}\bigg).$$
This completes the proof.
\end{proof}


\subsection{Generalised 4-corner set} Using Theorem~\ref{thm:main}, we can also calculate the Hausdorff dimension of self-affine measures supported on the generalised $4$-corner set. Let 
\begin{equation}\label{eq:IFS4corner}
\begin{array}{cc}
F_{1}(x,y)=(\gamma_{1,1}x,\lambda_{1,1}y), &F _{2}(x,y)=(\gamma_{1,2}x,\lambda_{2,1}y+(1-\lambda_{2,1})),\\ 
F_{3}(x,y)=(\gamma_{2,1}x+(1-\gamma_{2,1}),\lambda_{1,2}y), &F_{4}(x,y)=(\gamma_{2,2}x+(1-\gamma_{2,2}),\lambda_{2,2}y+(1-\lambda_{2,2}))
\end{array}
\end{equation}
be a self-affine IFS on $\mathbb{R}^2$ such that 
\begin{equation}\label{eq:cond4corner}
\left.\begin{array}{c}
0<\gamma_{i,j},\lambda_{i,j}\text{ for }i=1,2, j=1,2,\\
\gamma_{1,1}+\gamma_{2,1}\leq 1,\ \gamma_{1,2}+\gamma_{2,2}\leq 1,\ \lambda_{1,1}+\lambda_{2,1}\leq1,\ \lambda_{1,2}+\lambda_{2,2}\leq1,\\
\min\{\gamma_{1,2}+\gamma_{2,1},\lambda_{1,2}+\lambda_{2,1}\}\leq1\text{ and }\min\{\gamma_{1,1}+\gamma_{2,2},\lambda_{1,1}+\lambda_{2,2}\}\leq1.
\end{array}\right\}
\end{equation}
The conditions in \eqref{eq:cond4corner} guarantee that the IFS $\{F_1,F_2,F_3,F_4\}$ satisfies the rectangular open set condition. In particular, $F_i((0,1)^2)\subset(0,1)^2$ and $F_i((0,1)^2)\cap F_j((0,1)^2)=\emptyset$ for every $i\neq j\in\{1,2,3,4\}$. We call the attractor $C=\bigcup_{i=1}^4F_i(C)$ of $\{F_1,\ldots,F_4\}$ the generalized 4-corner set. In \cite{Barany4corner}, the first author studied the box-counting dimension of the 4-corner set for Lebesgue typical parameters. Now, we determine the Hausdorff dimension of self-affine measures supported on $C$ for typical parameters in a certain sense, and the Hausdorff dimension of the generalised 4-corner set in a region of parameters.

Let $\mathbf{p}=(p_1,\ldots,p_4)$ be a probability vector, and let
\begin{align*}
\chi_x(\mathbf{p})&=-p_1\log\gamma_{1,1}-p_2\log\gamma_{1,2}-p_3\log\gamma_{2,1}-p_4\log\gamma_{2,2},\\
\chi_y(\mathbf{p})&=-p_1\log\lambda_{1,1}-p_2\log\lambda_{2,1}-p_3\log\lambda_{1,2}-p_4\log\lambda_{2,2}.
\end{align*}

\begin{theorem}\label{thm:4corner} Let $\{F_1,F_2,F_3,F_4\}$ be a self-affine IFS as in \eqref{eq:IFS4corner}. There exist sets $\mathbf{E}_x,\mathbf{E}_y\subset(0,1)^{4}$ with $\dim_H(\mathbf{E}_x),\dim_H(\mathbf{E}_y)\leq 3$ such that for every $(\gamma_{i,j})_{i=1,j=1}^{2,2}\in(0,1)^{4}\setminus\mathbf{E}_x$ and $(\lambda_{i,j})_{i=1,j=1}^{2,2}\in(0,1)^{4}\setminus\mathbf{E}_y$ with \eqref{eq:cond4corner} the following holds: for every self-affine measure $\mu$ corresponding to the IFS $\{F_1,F_2,F_3,F_4\}$ and the probability vector $\mathbf{p}=(p_{1},p_2,p_3,p_4)$
		$$\dim_{H}(\mu)=\begin{cases}
		    \dfrac{h_{\mathbf{p}}+\Phi_x(\mathbf{p})}{\chi_x(\mathbf{p})}-\dfrac{\Phi_x(\mathbf{p})}{\chi_y(\mathbf{p})} & \text{if }\chi_y(\mathbf{p})\geq\chi_x(\mathbf{p})\geq h_{\mathbf{p}}+\Phi_x(\mathbf{p})\\[10pt]
           1+\dfrac{h_{\mathbf{p}}-\chi_x(\mathbf{p})}{\chi_y(\mathbf{p})} & \text{if }\chi_y(\mathbf{p}),h_{\mathbf{p}}+\Phi_x(\mathbf{p})\geq\chi_x(\mathbf{p}), \\[10pt]
            \dfrac{h_{\mathbf{p}}+\Phi_y(\mathbf{p})}{\chi_y(\mathbf{p})}-\dfrac{\Phi_y(\mathbf{p})}{\chi_x(\mathbf{p})} & \text{if }\chi_x(\mathbf{p})\geq\chi_y(\mathbf{p})\geq h_{\mathbf{p}}+\Phi_y(\mathbf{p}),\\[10pt]
            1+\dfrac{h_{\mathbf{p}}-\chi_y(\mathbf{p})}{\chi_x(\mathbf{p})} & \text{if }\chi_x(\mathbf{p}),h_{\mathbf{p}}+\Phi_y(\mathbf{p})\geq\chi_y(\mathbf{p}),
		\end{cases}$$
		where \begin{align*}
		    \Phi_x(\mathbf{p})&=\sum_{k=0}^{\infty}\sum\limits_{q=0}^{k}\binom{k}{q}(p_3+p_4)\left(p_{1}^{q+1}p_{2}^{k-q}+p_2^{q+1}p_1^{k-q}\right)\log(\frac{q+1}{k+1})\\
            &\quad\quad+\sum_{k=0}^{\infty}\sum\limits_{q=0}^{k}\binom{k}{q}(p_1+p_2)\left(p_{3}^{q+1}p_{4}^{k-q}+p_4^{q+1}p_3^{k-q}\right)\log(\frac{q+1}{k+1}),
            \end{align*}
and
\begin{align*}
		    \Phi_y(\mathbf{p})&=\sum_{k=0}^{\infty}\sum\limits_{q=0}^{k}\binom{k}{q}(p_2+p_4)\left(p_{1}^{q+1}p_{3}^{k-q}+p_3^{q+1}p_1^{k-q}\right)\log(\frac{q+1}{k+1})\\
            &\quad\quad+\sum_{k=0}^{\infty}\sum\limits_{q=0}^{k}\binom{k}{q}(p_1+p_3)\left(p_{2}^{q+1}p_{4}^{k-q}+p_4^{q+1}p_2^{k-q}\right)\log(\frac{q+1}{k+1}).
\end{align*}
	\end{theorem}

\begin{proof}
    This is a direct consequence of Theorem~\ref{thm:main} and Feng and Hu's theorem \cite[Theorem~2.11]{FengandHu}.
\end{proof}

Theorem~\ref{thm:4corner} allows us to calculate the Hausdorff dimension of the generalised 4-corner set on a certain region of parameters. Let us further suppose that 
\begin{equation}\label{eq:cond4corner+}
\lambda_{1,1}\leq \gamma_{1,1},\ \lambda_{2,2}\leq\gamma_{2,2},\ \lambda_{1,2}\leq\gamma_{2,1}\text{ and }\lambda_{2,1}\leq\gamma_{1,2}.
\end{equation}
This implies that $\chi_x(\mathbf{p})\leq\chi_y(\mathbf{p})$ for any probability vector $\mathbf{p}$. Consider the probability vector
$$
p_1=\gamma_{1,1}\lambda_{1,1}^{s-1},\ p_2=\gamma_{1,2}\lambda_{2,1}^{s-1},\ p_3=\gamma_{2,1}\lambda_{1,2}^{s-1}\text{ and }p_4=\gamma_{2,2}\lambda_{2,2}^{s-1},
$$
where $s$ is the unique solution of the equation $\sum_{i=1}^2\gamma_{i,i}\lambda_{i,i}^{s-1}+\gamma_{i,3-i}\lambda_{3-i,i}^{s-1}=1$. It is well known that $\dim_HC\leq s$, see for example Falconer and Miao \cite{FalMia2007}. Thus, it is enough to show that the corresponding self-affine measure $\mu$ has Hausdorff dimension $s=1+\frac{h_{\mathbf{p}}-\chi_x(\mathbf{p})}{\chi_y(\mathbf{p})}$. For that, it is enough to verify that $h_{\mathbf{p}}+\Phi_x(\mathbf{p})\geq\chi_x(\mathbf{p})$ by Theorem~\ref{thm:4corner}. Lemma~\ref{lem:lowerbound} implies that this holds if
\begin{multline}\label{eq:suff}
\gamma_{1,1}\lambda_{1,1}^{s-1}\log(\frac{1-\gamma_{1,2}\lambda_{2,1}^{s-1}}{\lambda_{1,1}^{s-1}})+\gamma_{1,2}\lambda_{2,1}^{s-1}\log(\frac{1-\gamma_{1,1}\lambda_{1,1}^{s-1}}{\lambda_{2,1}^{s-1}})\\
+\gamma_{2,1}\lambda_{1,2}^{s-1}\log(\frac{1-\gamma_{2,2}\lambda_{2,2}^{s-1}}{\lambda_{1,2}^{s-1}})+\gamma_{2,2}\lambda_{2,2}^{s-1}\log(\frac{1-\gamma_{2,1}\lambda_{1,2}^{s-1}}{\lambda_{2,2}^{s-1}})>0.
\end{multline}
One can check numerically that a small neighborhood of the parameters $\gamma_{1,1}=\gamma_{2,2}=0.8$, $\gamma_{1,2}=\gamma_{2,1}=0.1$, $\lambda_{1,1}=\lambda_{2,2}=0.45$ and $\lambda_{2,1}=\lambda_{1,2}=0.09$ satisfy all three assumptions \eqref{eq:cond4corner}, \eqref{eq:cond4corner+} and \eqref{eq:suff}. For a visual representation of the generalised 4-corner set, see Figure~\ref{fig1}.

