First, we define a subsystem of the IFS $\mathcal{S}$, which is exponentially separated for almost every parameter. Without loss of generality, we assume that $\lambda_{l,1}\geq \max_{2\leq j\leq n_{l}}\{\lambda_{l,j}\}$ for all $1\leq l\leq N$. Define
\begin{align*}
    &\mathcal{W}_0=\{(1,1), (2,1),\dots, (N,1)\}\\&
\mathcal{W}_1=\bigcup_{l=1}^{N}\bigg\{\bigcup_{m=1\&m\ne l}^{N}\{(m,2)(l,1),(m,3)(l,1),\dots,(m,{n_m})(l,1)\}\bigg\}\\& 
\mathcal{W}_k=\bigcup_{l=1}^{N}\bigg\{\bigcup_{j=2}^{n_l}\bigcup_{\substack{\mathbf{i}=(i^{0},{m_0})(i^{1},{m_1})(i^{2},{m_2})\dots (i^{k-1},{m_{k-1}})\in \mathcal{W}_{k-1}\\i^{0}\ne l\vee j\leq m_{0} }}\{(l,{j})\mathbf{i}\}\bigg\} \quad~ \text{for}~k\geq 2.
\end{align*}
We define $$\mathcal{U}_{k}=\bigcup_{i=0}^{k}\mathcal{W}_{i}.$$
By using the symbols of the set $\mathcal{U}_{k}$, we define a self-similar IFS as follows 
$$\mathcal{S}_{k}:=\{f_{\mathbf{i}}: \mathbf{i}\in \mathcal{U}_k\}.$$ 
Let $\mathcal{U}_{k}^{\mathbb{N}}$ denote the set of all infinite sequences of symbols from the set $\mathcal{U}_{k}$. The set of all sequences of length $n$ is denoted by $\mathcal{U}_{k}^{n}$. Let $\mathcal{U}_{k}^{*}=\bigcup_{n\in\mathbb{N}}\mathcal{U}_{k}^{n}$.
Now, we define an operator associated with the similarity dimension of the IFS $\mathcal{S}_{k}$ as follows
$$\Phi_{k}(s)=\sum_{\mathbf{i}\in \mathcal{U}_{k}}\lambda_{\mathbf{i}}^{s}.$$
For each $k\geq 0$, there exists a unique $s_k\in \mathbb{R}$ such that $\Phi_{k}(s_k)=1.$ One can see that the sequence $\{s_{k}\}$ is a monotonically increasing sequence.
\begin{lemma}\label{DimformulaforCFS}
  Let $s_{k}$ be defined as above. Then the limit $\lim_{k\to \infty}s_{k}=\tilde{s}$ exists and $\tilde{s}$ is the unique solution of the following equation
  \begin{equation}\label{formulamdim}
\sum_{i=1}^N\prod_{j=1}^{n_i}(1-\lambda_{i,j}^{{s}})=N-1.
  \end{equation}
\end{lemma}
\begin{proof}
For each $k\geq 1$, we have 
$$\Phi_{k}(s)=\sum_{j=1}^{N}\lambda_{j,1}^{s}+\sum_{j=1}^{N}\lambda_{j,1}^{s}\bigg(\sum_{l=1}^{k}\Psi_{l}^{(j,1)}\bigg),$$
where 
$$
\Psi_{l}^{(j,1)}=\sum_{\substack{\mathbf{i}=(i_0,k_0)(i_1,k_1)(i_2,k_2)\dots(i_l,k_l)\in \mathcal{W}_{l}\\(i_l,k_l)=(j,1)}}\frac{\lambda_{\mathbf{i}}^s}{\lambda_{j,1}^s}.
$$
Furthermore, we can write 
$$\Psi_{l}^{(j,1)}=\sum_{k=1}^{N}\sum_{i=2}^{n_k}{}^{(k,i)}\Psi_{l}^{(j,1)},$$ where $${}^{(k,i)}\Psi_{l}^{(j,1)}=\sum_{\substack{\mathbf{i}=(i_0,k_0)(i_1,k_1)(i_2,k_2)\dots(i_l,k_l)\in \mathcal{W}_{l}\\  (i_0,k_0)=(k,i)\& (i_l,k_l)=(j,1)}}\frac{\lambda_{\mathbf{i}}^s}{\lambda_{j,1}^s} \quad \text{for} \quad 2\leq i\leq n_{k}.$$
One can observe that 
\begin{equation}\label{Length1}
{}^{(k,i)}\Psi_{1}^{(j,1)}=(1-\delta_{kj})\lambda_{k,i}^{s} \quad \text{for}\quad 1\leq k,j\leq N~\text{and}~2\leq i\leq n_{k}.   
\end{equation}

and for $l\geq 2$, we have 
\begin{equation}\label{selfrelation}
{}^{(k,i)}\Psi_{l}^{(j,1)}=\lambda_{k,i}^s\bigg(\Psi_{l-1}^{(j,1)}-\sum_{m=2}^{i-1}{}^{(k,m)}\Psi_{l-1}^{(j,1)}\bigg).  
\end{equation}
Now, we define some notations as follows
$$a_{l}^{m}=\sum_{2\leq k_0<k_1<\dots<k_{l-1}\leq n_m}\lambda_{m,k_0}^{s}\lambda_{m,k_1}^{s}\dots \lambda_{m,k_{l-1}}^{s} \quad \text{for}\quad l\geq 1~\text{and}~1\leq m\leq N.$$
Thus, for $l\geq 2$, we have 
\begin{align}\label{eq:relation}
\Psi_{l}^{(j,1)}&=\sum_{k=1}^{N}\sum_{i=2}^{n_k}{}^{(k,i)}\Psi_{l}^{(j,1)}\nonumber\\&=\sum_{k=1}^{N}\sum_{i=2}^{n_k}\lambda_{k,i}^s\bigg(\Psi_{l-1}^{(j,1)}-\sum_{m=2}^{i-1}{}^{(k,m)}\Psi_{l-1}^{(j,1)}\bigg)\nonumber\\&=\sum_{k=1}^{N}\bigg(a_{1}^{k}\Psi_{l-1}^{(j,1)}- \sum_{m=2}^{n_k-1}\sum_{i=m+1}^{n_k}\lambda_{k,i}^s {}^{(k,m)}\Psi_{l-1}^{(j,1)}\bigg)
\end{align}
W.L.O.G. we assume that $n_1\leq n_2\leq \dots\leq n_N$. Applying relation \ref{selfrelation} in \eqref{eq:relation} $n$ times, where $1\leq n\leq n_1-1$ and $l\geq n +1$, we have 
\begin{align}
 \Psi_{l}^{(j,1)}= \sum_{k=1}^{N} \bigg(\sum_{m=1}^{n}(-1)^{m-1} a_{m}^{k}\Psi_{l-m}^{(j,1)}+(-1)^n \sum_{2\leq m_0<m_1<\dots<m_{n}\leq n_k}\lambda_{k,m_n}^{s}\lambda_{k,m_{n-1}}^{s}\dots \lambda_{k,m_{1}}^{s} {}^{(k,m_0)}\Psi_{l-n}^{(j,1)}\bigg)  
\end{align}
By taking $n=l-1$ and using \eqref{Length1} in the above, we get 
\begin{align}\label{1ststep}
 \Psi_{l}^{(j,1)}= \sum_{k=1}^{N} \bigg(\sum_{m=1}^{l-1}(-1)^{m-1} a_{m}^{k}\Psi_{l-m}^{(j,1)}+(-1)^{l-1} a_{l}^{k}(1-\delta_{kj})\bigg)  
\end{align}
for all $2\leq l\leq n_1$. If $n_{i}<n_{i+1}$ for some $i\geq 1$, then we again apply relation \ref{selfrelation} in \eqref{eq:relation} $n$ times, where $n_i\leq n\leq n_{i+1}-1$ and $l\geq n +1$, we have 
\begin{align}
 \Psi_{l}^{(j,1)}&= \sum_{k=1}^{i}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k} \Psi_{l-m}^{(j,1)}\nonumber\\&+\sum_{k={i+1}}^{N} \bigg(\sum_{m=1}^{n}(-1)^{m-1} a_{m}^{k}\Psi_{l-m}^{(j,1)}+(-1)^n \sum_{2\leq m_0<m_1<\dots<m_{n}\leq n_k}\lambda_{k,m_n}^{s}\lambda_{k,m_{n-1}}^{s}\dots \lambda_{k,m_{1}}^{s} {}^{(k,m_0)}\Psi_{l-n}^{(j,1)}\bigg)  
\end{align}
Again by taking $n=l-1$ and using \eqref{Length1} in the above, we get 
\begin{align}\label{2ststep}
 \Psi_{l}^{(j,1)}= \sum_{k=1}^{i}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k} \Psi_{l-m}^{(j,1)}+\sum_{k=i+1}^{N} \bigg(\sum_{m=1}^{l-1}(-1)^{m-1} a_{m}^{k}\Psi_{l-m}^{(j,1)}+(-1)^{l-1} a_{l}^{k}(1-\delta_{kj})\bigg)  
\end{align}
for all $n_{i}+1\leq l\leq n_{i+1}$.
Similarly, by applying relation \ref{selfrelation} in \eqref{eq:relation}, for $l\geq n_N+1$, we get 
\begin{equation}\label{linearrecurrence}
\Psi_{l}^{(j,1)}=\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k} \Psi_{l-m}^{(j,1)}.   
\end{equation}
 Let $\mathcal{N}=n_N$. Then the characteristic polynomial of the linear recurrence relation \ref{linearrecurrence} is $$x^\mathcal{N}=\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k} x^{\mathcal{N}-m}.$$
The convergence of the series $\sum_{l=1}^{\infty} \Psi_{l}^{(j,1)}$ for each $j\in \{1,2,\dots,N\}$ depends on the roots of the characteristic polynomial of relation \ref{linearrecurrence}. Moreover, for each $j\in \{1,2,\dots, N\}$ the series  $\sum_{l=1}^{\infty} \Psi_{l}^{(j,1)}$ is convergent if and only if the roots of the characteristic polynomial are strictly less than $1$. The roots of a polynomial depend continuously on the coefficients of the polynomial. One can notice that all the characteristic polynomial coefficients tend to $0$ as $s$ tends to $\infty$, except the coefficient of $x^{\mathcal{N}}$. This implies that all the roots go to $0$ as $s$ tends to $\infty$. Thus, there exists a $\delta>0$ such that for all $s\in (\delta,\infty)$, the series $\sum_{l=1}^{\infty} \Psi_{l}^{(j,1)}$ is convergent  for each $j\in \{1,2,\dots,N\}$. Let $\delta$ be the infimum of all $s$ such that the desired series is convergent.
We define 
$$\Phi(s)=\sum_{j=1}^{N}\lambda_{j,1}^{s}+\sum_{j=1}^{N}\lambda_{j,1}^{s}\bigg(\sum_{l=1}^{\infty}\Psi_{l}^{(j,1)}\bigg)\quad \text{for} \quad s\in (\delta,\infty).$$
There exists a unique $\tilde{s}\in (\delta,\infty)$ such that $\Phi(\tilde{s})=1.$ Also, one can see that the sequence $s_{k}$ is monotonic increasing and bounded above by $\tilde{s}$. This implies that $\lim_{k \to \infty}s_{k}$ exists. It is easy to see that $\lim_{k \to \infty}s_{k}=\sup_{k}\{s_k\}=\tilde{s}$. Now, it only remains to show that $\tilde{s}$ satisfies \ref{formulamdim}.\par 
Let $\Psi^{(j,1)}=\sum_{l=1}^{\infty}\Psi_{l}^{(j,1)}.$ Then, by using \ref{linearrecurrence}, we have 
\begin{align*}
   \Psi^{(j,1)}&=\sum_{l=1}^{\infty}\Psi_{l}^{(j,1)}= \sum_{l=1}^{\mathcal{N}}\Psi_{l}^{(j,1)}+\sum_{l=\mathcal{N}+1}^{\infty}\Psi_{l}^{(j,1)}\\&= \sum_{l=1}^{\mathcal{N}}\Psi_{l}^{(j,1)}+\sum_{l=\mathcal{N}+1}^{\infty}\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k} \Psi_{l-m}^{(j,1)}\\&=\sum_{l=1}^{\mathcal{N}}\Psi_{l}^{(j,1)}+\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k} \sum_{l=\mathcal{N}+1}^{\infty} \Psi_{l-m}^{(j,1)}\\&=\sum_{l=1}^{\mathcal{N}}\Psi_{l}^{(j,1)}+\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k} \sum_{l=\mathcal{N}+1-m}^{\infty} \Psi_{l}^{(j,1)}\\&=\sum_{l=1}^{\mathcal{N}}\Psi_{l}^{(j,1)}+\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k} \bigg(\Psi^{(j,1)}-\sum_{l=1}^{\mathcal{N}-m} \Psi_{l}^{(j,1)}\bigg).
\end{align*}
This implies that 
\begin{equation}\label{eq:sum}
\Psi^{(j,1)}=\frac{\sum_{l=1}^{\mathcal{N}}\Psi_{l}^{(j,1)}+\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m} a_{m}^{k}\sum_{l=1}^{\mathcal{N}-m} \Psi_{l}^{(j,1)}}{1+\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m} a_{m}^{k}}
\end{equation}
Now, we need to evaluate the expression $\sum_{l=1}^{\mathcal{N}}\Psi_{l}^{(j,1)}$. By using \eqref{1ststep}, \eqref{2ststep} and \eqref{linearrecurrence}, we get 
\begin{align}\label{eq:fintestep}
&\sum_{l=1}^{\mathcal{N}}\Psi_{l}^{(j,1)}\nonumber\\&= \Psi_{1}^{(j,1)}+\sum_{l=2}^{n_1}\Psi_{l}^{(j,1)}+ \sum_{i=1}^{N-1}\sum_{l=n_{i}+1}^{n_{i+1}} \Psi_{l}^{(j,1)}\nonumber\\&= \sum_{k=1}^{N}a_{1}^{k}(1-\delta_{kj})+\sum_{l=2}^{n_1}\bigg(\sum_{k=1}^{N} \bigg(\sum_{m=1}^{l-1}(-1)^{m-1} a_{m}^{k}\Psi_{l-m}^{(j,1)}+(-1)^{l-1} a_{l}^{k}(1-\delta_{kj})\bigg) \bigg)\nonumber\\&+\sum_{i=1}^{N-1}\sum_{l=n_{i}+1}^{n_{i+1}}\bigg(\sum_{k=1}^{i}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k} \Psi_{l-m}^{(j,1)}+\sum_{k=i+1}^{N} \bigg(\sum_{m=1}^{l-1}(-1)^{m-1} a_{m}^{k}\Psi_{l-m}^{(j,1)}+(-1)^{l-1} a_{l}^{k}(1-\delta_{kj})\bigg)\bigg)\nonumber\\&= \sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k}\sum_{l=1}^{\mathcal{N}-m} \Psi_{l}^{(j,1)}+ \sum_{k=1}^{N}a_{1}^{k}(1-\delta_{kj})+ \sum_{k=1}^{N}\bigg(\sum_{l=2}^{n_1}(-1)^{l-1} a_{l}^{k}(1-\delta_{kj})\bigg)\nonumber\\&+\sum_{i=1}^{N-1}\sum_{k=i+1}^{N}\bigg(\sum_{l=n_{i}+1}^{n_{i+1}}(-1)^{l-1} a_{l}^{k}(1-\delta_{kj})\bigg)
\end{align}
By \eqref{eq:fintestep} and \eqref{eq:sum}, we get
\begin{align}\label{eq:exactsum}
\Psi^{(j,1)}&=\frac{\sum_{k=1}^{N}a_{1}^{k}(1-\delta_{kj})+ \sum_{k=1}^{N}\bigg(\sum_{l=2}^{n_1}(-1)^{l-1} a_{l}^{k}(1-\delta_{kj})\bigg)}{1+\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m} a_{m}^{k}}\nonumber\\&+\frac{\sum_{i=1}^{N-1}\sum_{k=i+1}^{N}\bigg(\sum_{l=n_{i}+1}^{n_{i+1}}(-1)^{l-1} a_{l}^{k}(1-\delta_{kj})\bigg)}{1+\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m} a_{m}^{k}}\nonumber\\&=\frac{\sum_{\substack{k=1\\k\ne j}}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k}}{1+\sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m} a_{m}^{k}}. 
\end{align}
Now, we apply \eqref{eq:exactsum} in the expression $\Phi(\tilde{s})=1$, we get
\begin{align}\label{eq:dimmain}
\sum_{j=1}^{N}\lambda_{j,1}^{\tilde{s}}+\sum_{j=1}^{N}\lambda_{j,1}^{\tilde{s}}\bigg(\sum_{m=1}^{n_j}(-1)^{m} a_{m}^{j}\bigg)+ \sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k}=1.
\end{align}
One can see that 
\begin{align*}
 \prod_{k=1}^{n_i}\big(x-\lambda_{i,k}^{\tilde{s}}\big)=x^{n_i}-\sum_{m=1}^{n_i}(-1)^{m-1}\sum_{1\leq j_1<j_2<\dots<j_m} \lambda_{i,j_1}^{\tilde{s}}\lambda_{i,j_2}^{\tilde{s}}\dots \lambda_{i,j_m}^{\tilde{s}} x^{n_i-m}   \end{align*}
for $i\in \{1,2,\dots,N\}$. By putting $x=1$ in the above equation and then add it for each $i\in \{1,2,\dots,N\}$, we get
$$\sum_{j=1}^{N}\lambda_{j,1}^{\tilde{s}}+\sum_{j=1}^{N}\lambda_{j,1}^{\tilde{s}}\bigg(\sum_{m=1}^{n_j}(-1)^{m} a_{m}^{j}\bigg)+ \sum_{k=1}^{N}\sum_{m=1}^{n_k}(-1)^{m-1} a_{m}^{k}=N-\sum_{i=1}^{N}\prod_{k=1}^{n_i}\big(1-\lambda_{i,k}^{\tilde{s}}\big).$$
Thus, by \eqref{eq:dimmain} we get
$$\sum_{i=1}^{N}\prod_{k=1}^{n_i}\big(1-\lambda_{i,k}^{\tilde{s}}\big)=N-1.$$ 
Moreover, $\tilde{s}$ is the unique solution of the above equation because the function $F(s)=N-\sum_{i=1}^{N}\prod_{k=1}^{n_i}\big(1-\lambda_{i,k}^{{s}}\big)$ is a decreasing function for $s>0$ and $F(0)=N\geq 2$. This completes the proof.
\end{proof}
\begin{proposition}\label{ESCforsubsystem}
  Let $A_{k}$ be the attractor of the IFS $\mathcal{S}_k$.
  Then, for all parameters $\underline{\lambda}\in [\epsilon, 1-\epsilon]^{L}\setminus\tilde{\mathbf{E}}$ and $\underline{\mathbf{t}}\in \mathcal{F}\setminus \mathbf{F}$, we have 
  $$\dim_{H}(A_k)=\min\{1,s_k\}.$$
Moreover,   $\min\{1,\tilde{s}\}\leq \dim_{H}(A)$ for all parameters $\underline{\lambda}\in [\epsilon, 1-\epsilon]^{L}\setminus\tilde{\mathbf{E}}$ and $\underline{\mathbf{t}}\in \mathcal{F}\setminus \mathbf{F}$.
\end{proposition}
\begin{proof} Let $\mathbf{i}\in \mathcal{U}_{k}^{n}$. Then, one can can easily see that $\mathbf{i}\in \Sigma^{*}$ and $|\mathbf{i}|\in \{n,\dots,n(k+1)\}$ with respect to the symbols of the IFS $\mathcal{S}$. Now, we define a set as follows
\begin{align*}
    \tilde{B}_{n}=\bigg\{(\mathbf{i},\mathbf{j})\in \mathcal{U}_{k}^{n}\times\mathcal{U}_{k}^{n}: \exists~ (l,m)\in \mathbf{i}~\text{but}~(l,m)\notin \mathbf{j}~\text{or}~\exists~ (l,m)\in \mathbf{j}~\text{but}~(l,m)\notin \mathbf{i}\\~\text{for some}~l\in\{1,2,\dots,N\}\bigg\}.
\end{align*}
Then, by using the same idea as in Proposition \ref{ExpectionE2}, there exists a set $\tilde{E}_{2}\subset [\epsilon, 1-\epsilon]^L$ with $\dim_{H}(\tilde{E}_2)\leq L-1$ such that for all  $\underline{\lambda}\in [\epsilon, 1-\epsilon]^L\setminus \tilde{E}_{2},$  $\exists~~ \eta>0, \exists~\tilde{N}\in \mathbb{N}, \forall~n\geq \tilde{N}, \forall~ (\mathbf{i},\mathbf{j})\in (\mathcal{U}_{k}^{n}\times\mathcal{U}_{k}^{n})\cap \tilde{B}_{n}$ we have 
$$ 
  |\lambda_{\mathbf{i}}-\lambda_{\mathbf{j}}|> {\eta}^{n(k+1)}.$$
After that using the idea of Corollary \ref{Descrofmoreblock}, and above estimate for $|\lambda_{\mathbf{i}}-\lambda_{\mathbf{j}}|$, we get 
 $$\text{either}\quad\#_{(i,j)}(\mathbf{i})=\#_{(i,j)}(\mathbf{j}) ~\quad \text{or}\quad |\lambda_{\mathbf{i}}- \lambda_{\mathbf{j}}|\geq (\eta^{\tilde{N}})^{n(k+1)}\quad \forall \quad \underline{\lambda}\in [\epsilon, 1-\epsilon]^L\setminus \tilde{E}_{2}.$$  
 This implies that for all $\underline{\lambda}\in [\epsilon, 1-\epsilon]^L\setminus \tilde{E}_{2}$, if $(\mathbf{i},\mathbf{j})\in \mathcal{U}_{k}^{n}\times\mathcal{U}_{k}^{n}$ with $\lambda_{\mathbf{i}}=\lambda_{\mathbf{j}}$, then 
 $$\#_{(i,j)}(\mathbf{i})=\#_{(i,j)}(\mathbf{j}).$$
This also implies that $|\mathbf{i}|=|\mathbf{j}|\in \{n,\dots,n(k+1)\}$ with respect to the symbols of the IFS $\mathcal{S}$. The set $\tilde{\mathbf{E}}$ is defined by $\tilde{\mathbf{E}}=\mathbf{E}\cup \tilde{E}_2$. Let $(\mathbf{i},\mathbf{j})\in \mathcal{U}_{k}^{n}\times\mathcal{U}_{k}^{n}$ with $\mathbf{i}\ne\mathbf{j}$ and $\lambda_{\mathbf{i}}=\lambda_{\mathbf{j}}$. Then by Proposition \ref{ESC for gerenalsystem} for all $\underline{\lambda}\in [\epsilon, 1-\epsilon]^{L}\setminus\tilde{\mathbf{E}}$ and $\underline{\mathbf{t}}\in \mathcal{F}\setminus \mathbf{F}$, we have 
\begin{align*}
\text{either}\quad  \mathbf{i}~ \text{and}~ \mathbf{j}~ \text{have same block structure} \quad \text{or}\quad |\Pi(\mathbf{i})-\Pi(\mathbf{j})|\geq (\eta^{\tilde{N}})^{n(k+1)}.
\end{align*}
But by the symbols defining the IFS $\mathcal{S}_k$, it is clear that if $\mathbf{i}\ne\mathbf{j}\in \mathcal{U}_{k}^{n}$, then $\mathbf{i}$ and $\mathbf{j}$ can not have same block structure. This implies that for each $k\geq 1$, the IFS $\mathcal{S}_k$ satisfies the ESC for all parameters $\underline{\lambda}\in [\epsilon, 1-\epsilon]^{L}\setminus\tilde{\mathbf{E}}$ and $\underline{\mathbf{t}}\in \mathcal{F}\setminus \mathbf{F}$. Thus by Theorem \ref{MainHochmanresult}, we get 
 $$\dim_{H}(A_k)=\min\{1,s_k\} \quad \forall~\underline{\lambda}\in [\epsilon, 1-\epsilon]^{L}\setminus\tilde{\mathbf{E}}~\text{and}~ \underline{\mathbf{t}}\in \mathcal{F}\setminus \mathbf{F}$$
 where $s_k$ is the similarity dimension of the IFS $\mathcal{S}_k$. Since $A_k\subset A ~\forall~ k\geq 1$ and by using Lemma \ref{DimformulaforCFS}, we get $$\min\{1,\tilde{s}\}\leq \dim_{H}(A)$$ for all parameters $\underline{\lambda}\in [\epsilon, 1-\epsilon]^{L}\setminus\tilde{\mathbf{E}}$ and $\underline{\mathbf{t}}\in \mathcal{F}\setminus \mathbf{F}$. This completes the proof.
 \end{proof}

