\section{Proof of Pointwise Incoherence Inequality}
\label{appendix:proof-pointwise-incoherence-ineq}

Theorem~\ref{theorem:incoherence-inequality} states that :
\[
\forall \gen, \forall d \in \Descr,\quad \Inc_\gen(d) \leq 2 \times \Err_\gen(d).
\]

%\todo{Postpone proof to appendix?}
% Thomas : If we have the place I think it is good to keep it since it is not too long or complex.
\begin{proof}
Let $\gen$ be an input generation system and let $d\in \Descr$.
Let $\ProgRV^d_1, \ProgRV^d_2 \overset{iid}{\sim} \coder(d)$ represent two independently sampled programs from $\coder$ output distribution for task $d$ and let $X \sim \gen(d)$ represent an input sampled from $\gen$ for task $d$.

For every sample $\omega \in \SampleSpace$, let $f_1 = \sem{\ProgRV^d_1(\omega)}$, $f_2 = \sem{\ProgRV^d_2(\omega)}$ and $x = X(\omega)$ be the corresponding outcomes of $\sem{\ProgRV^d_1}, \sem{\ProgRV^d_2}$ and $X$. Then we have the following implication
\begin{equation*}
    f_1(x) \neq f_2(x) \implies (f_1(x) \neq \gtfun{d}(x) \lor f_2(x) \neq \gtfun{d}(x)).
\end{equation*}
Taking corresponding probabilistic events
\begin{align*}
    &E_{\ProgRV^d_1,\ProgRV^d_2} := \{\sem{\ProgRV^d_1}(X)\neq\sem{\ProgRV^d_2}(X)\} \\
    &E_{\ProgRV^d_1,\gtfun{d}} := \{\sem{\ProgRV^d_1}(X)\neq \gtfun{d}(X)\} \\
    &E_{\ProgRV^d_2,\gtfun{d}} := \{\sem{\ProgRV^d_2}(X)\neq \gtfun{d}(X)\}
\end{align*}
We thus have
\begin{equation*}
    E_{\ProgRV^d_1,\ProgRV^d_2} \subseteq E_{\ProgRV^d_1,\gtfun{d}} \cup E_{\ProgRV^d_2,\gtfun{d}}.
\end{equation*}
Therefore
\begin{align*}
    \Prob(E_{\ProgRV^d_1,\ProgRV^d_2}) & \leq \Prob(E_{\ProgRV^d_1,\gtfun{d}} \cup E_{\ProgRV^d_2,\gtfun{d}}) \\
    & \leq \Prob(E_{\ProgRV^d_1,\gtfun{d}}) + \Prob(E_{\ProgRV^d_2,\gtfun{d}}).
\end{align*}
Since by definition, $\Inc_\gen(d) = \Prob(E_{\ProgRV^d_1,\ProgRV^d_2})$ and $\Err_\gen(d) = \Prob(E_{\ProgRV^d_1,\gtfun{d}}) = \Prob(E_{\ProgRV^d_2,\gtfun{d}})$.
We thus obtain
\[
\Inc_\gen(d) \leq 2 \times \Err_\gen(d).
\]

\end{proof}

\section{Estimation of Incoherence and Error}
\label{appendix:estimation-inc-err}

\subsection{Monte Carlo Estimation of Pointwise Error}
\label{appendix:estimation-inc-err:monte-carlo-estimation-err}

Given $\coder$ a code generation system and provided $\gen$ an input generation system, when the ground truth implementation $\gtfun{d}$ is available, we can estimate the pointwise error $\Err_\gen(d)$ using a Monte Carlo procedure based on Definition~\eqref{eqn:pntwiseError} as illustrated in Algorithm~\ref{alg:point-err-estimation}.

\begin{algorithm}[tb]
\caption{Monte Carlo Estimation of $\Err_\gen(d)$}
\label{alg:point-err-estimation}
\textbf{Input}: $\coder$, $\gen$, task $d \in \Descr$, ground truth $\gtfun{d}$, error tolerance $\epsilon > 0$, failure probability $\delta > 0$\\
\textbf{Output}: $\bar{\Err}_\gen(d)$ estimate such that $|\bar{\Err}_\gen(d) - \Err_\gen(d)| \leq \epsilon$ with probability $\geq 1 - \delta$
\begin{algorithmic}[1]
\STATE Let $N = \left\lceil \frac{\log(2/\delta)}{2\epsilon^2} \right\rceil$
\FOR{$i = 1$ to $N$}
    \STATE Sample $\prog \sim \coder(d)$
    \STATE Sample $x \sim \gen(d)$
    \STATE $e_i \gets \mathbb{I}_{\sem{\prog}(x) \neq \gtfun{d}(x)}$
\ENDFOR
\STATE \textbf{return} $\bar{\Err}_\gen(d) = \frac{1}{N} \sum_{i=1}^N e_i$
\end{algorithmic}
\end{algorithm}

\paragraph{Correctness Guarantee.}
Each $e_i$ is a Bernoulli random variable with $\mathbb{E}[e_i] = \Err_\gen(d)$. By Hoeffding’s inequality:
\[
\mathbb{P}(|\bar{\Err}_\gen(d) - \Err_\gen(d)| \geq \epsilon) \leq 2\exp(-2N\epsilon^2).
\]
Thus, with $N \ge \frac{\log(2/\delta)}{2\epsilon^2}$, we obtain the desired PAC guarantee.

\subsection{Monte Carlo Estimation of Pointwise Incoherence}
\label{appendix:estimation-inc-err:monte-carlo-estimation-inc}

Given $\coder$ a code generation system and provided $\gen$ an input generation system, even if the ground truth implementation $\gtfun{d}$ is unavailable, we can estimate the pointwise incoherence $\Inc_\gen(d)$ using a Monte Carlo procedure based on Definition~\eqref{eqn:pntwiseIncoherence} as illustrated in Algorithm~\ref{alg:point-inc-estimation}.

\begin{algorithm}[tb]
\caption{Monte Carlo Estimation of $\Inc_\gen(d)$}
\label{alg:point-inc-estimation}
\textbf{Input}: $\coder$, $\gen$, task $d \in \Descr$, error tolerance $\epsilon > 0$, failure probability $\delta > 0$\\
\textbf{Output}: $\bar{\Inc}_\gen(d)$ estimate such that $|\bar{\Inc}_\gen(d) - \Inc_\gen(d)| \leq \epsilon$ with probability $\geq 1 - \delta$
\begin{algorithmic}[1]
\STATE Let $N = \left\lceil \frac{\log(2/\delta)}{2\epsilon^2} \right\rceil$
\FOR{$i = 1$ to $N$}
    \STATE Sample $\prog_1, \prog_2 \overset{iid}{\sim} \coder(d)$
    \STATE Sample $x \sim \gen(d)$
    \STATE $d_i \gets \mathbb{I}_{\sem{\prog_1}(x) \neq \sem{\prog_2}(x)}$
\ENDFOR
\STATE \textbf{return} $\bar{\Inc}_\gen(d) = \frac{1}{N} \sum_{i=1}^N d_i$
\end{algorithmic}
\end{algorithm}

\paragraph{Correctness Guarantee.}
Each $d_i$ is a Bernoulli random variable with $\mathbb{E}[d_i] = \Inc_\gen(d)$. Applying Hoeffding’s inequality:
\[
\mathbb{P}(|\bar{\Inc}_\gen(d) - \Inc_\gen(d)| \geq \epsilon) \leq 2\exp(-2N\epsilon^2).
\]
Hence, with $N \ge \frac{\log(2/\delta)}{2\epsilon^2}$, we obtain the desired PAC guarantee.

\subsection{PAC Detection of Nonzero Incoherence}
\label{appendix:estimation-inc-err:pac-detection}

Given $\coder$ a code generation system and provided $\gen$ an input generation system, we may want to detect with high confidence whether the model exhibits nonzero pointwise incoherence on a given task $d \in \Descr$. We present a probabilistically sound decision procedure based on repeated disagreement tests, as illustrated in Algorithm~\ref{alg:pac-incoherence-detection}.

\begin{algorithm}[tb]
\caption{PAC Detection of non-zero $\Inc_\gen(d)$}
\label{alg:pac-incoherence-detection}
\textbf{Input}: $\coder$, $\gen$, task $d \in \Descr$, incoherence threshold $\epsilon > 0$, confidence parameter $\delta > 0$\\
\textbf{Output}: \texttt{true} if $\Inc_\gen(d) > 0$ is detected, otherwise \texttt{false}
\begin{algorithmic}[1]
\STATE Let $N = \left\lceil \frac{\log(\delta)}{\log(1 - \epsilon)} \right\rceil$
\FOR{$i = 1$ to $N$}
    \STATE Sample $\prog_1, \prog_2 \overset{iid}{\sim} \coder(d)$
    \STATE Sample $x \sim \gen(d)$
    \IF{$\sem{\prog_1}(x) \neq \sem{\prog_2}(x)$}
        \STATE \textbf{return} \texttt{true}
    \ENDIF
\ENDFOR
\STATE \textbf{return} \texttt{false}
\end{algorithmic}
\end{algorithm}

\paragraph{Correctness Guarantee.}
Let $\epsilon > 0$ and $\delta > 0$. Then Algorithm~\ref{alg:pac-incoherence-detection}, when run with parameters $\epsilon$ and $\delta$, satisfies the following:

\begin{itemize}
    \item If $\Inc_\gen(d) = 0$, the algorithm always returns \texttt{false}.
    \item If $\Inc_\gen(d) \ge \epsilon$, the algorithm returns \texttt{true} with probability at least $1 - \delta$.
\end{itemize}

In other words, the algorithm detects non-zero incoherence with confidence at least $1 - \delta$, and it never returns false positives.

\begin{proof}
Let $\epsilon > 0$ and $\delta > 0$, and let $N = \left\lceil \frac{\log(\delta)}{\log(1 - \epsilon)} \right\rceil$. Then Algorithm~\ref{alg:pac-incoherence-detection} satisfies the following:

\begin{itemize}
    \item \textbf{No false positives.} If $\Inc_\gen(d) = 0$, then all sampled programs agree on all inputs almost surely. Therefore, no disagreement can ever be observed, and the algorithm always returns \texttt{false}.

    \item \textbf{False negative probability $\le \delta$.} Suppose instead that $\Inc_\gen(d) \ge \epsilon$. Then in each trial of the algorithm, the probability of observing a disagreement is at least $\epsilon$. Since the trials are independent, the probability that all $N$ trials fail to detect a disagreement is at most:
    \[
    (1 - \epsilon)^N.
    \]
    By the choice of $N$, this is at most $\delta$:
    \[
    (1 - \epsilon)^N \le \delta.
    \]
    Hence, the probability that the algorithm detects a disagreement and returns \texttt{true} is at least $1 - \delta$.
\end{itemize}
\end{proof}



\paragraph{Implication for Error Detection.}
Although the algorithm only checks for non-zero \emph{incoherence}, we can derive a guarantee for non-zero \emph{error} via Theorem~\ref{theorem:incoherence-inequality}, which states:
\[
\Inc_\gen(d) \le 2 \cdot \Err_\gen(d).
\]
Thus, a detection of $\Inc_\gen(d) \ge \epsilon$ implies that $\Err_\gen(d) \ge \epsilon / 2$. Consequently, this detection method provides a statistically sound way to identify non-zero errors without requiring access to a ground truth implementation.

\section{Functional Incoherence}
\label{appendix:functional-incoherence}

While pointwise incoherence measures this divergence over specific inputs, functional incoherence extends the idea to the full input space. That is, two implementations are functionally incoherent if they disagree on \emph{any} input. This notion aligns with the classic definition of program equivalence.

Let $\ProgRV_1^d, \ProgRV_2^d \overset{iid}{\sim} \coder(d)$ be two independently sampled programs for a task $d \in \Descr$. Let $\sem{\ProgRV^d_1}, \sem{\ProgRV^d_2}$ denote their functional interpretations. We define the \textbf{functional incoherence} of a code generation system $\coder$ for a task $d$ is the probability that two independently sampled implementations are not functionally equivalent:
\begin{equation}
\Inc(d) := \Prob(\sem{\ProgRV_1^d} \neq \sem{\ProgRV_2^d})
\end{equation}

This notion captures global behavioral disagreement between sampled programs. In practice, while direct evaluation of functional equivalence is undecidable in general, functional incoherence may be conservatively approximated via testing or symbolic execution.

Functional incoherence can be seen as the limiting form of pointwise incoherence. Specifically, $\Inc_\gen(d)$ (as defined in the main text) estimates incoherence over a distribution of inputs, whereas $\Inc(d)$ considers disagreement over the entire input space.

Importantly, just as pointwise incoherence lower-bounds pointwise error, we can show that functional incoherence provides a lower bound on functional error.

\subsection{Functional Incoherence as a Lower Bound on Error}
\label{appendix:functional-incoherence:inequality}

\begin{theorem}[Functional Incoherence Inequality]
\label{theorem:functional-incoherence-inequality}
For any task $d \in \Descr$, functional incoherence provides a lower bound on functional error:
\[
\Inc(d) \leq 2 \times \Err(d).
\]
\end{theorem}

\begin{proof}
Let $\gtfun{d}$ denote the ground truth implementation for task $d$.

Let $f_1 := \sem{\ProgRV_1^d}$ and $f_2 := \sem{\ProgRV_2^d}$ be two independently sampled implementations from $\coder(d)$. Then:
\[
\{f_1 \neq f_2\} \subseteq \{f_1 \neq f^\ast_d\} \cup \{f_2 \neq f^\ast_d\}
\]
This holds because if two functions differ, at least one must differ from the ground truth. Taking probabilities:
\begin{align*}
\Prob(f_1 \neq f_2) & \leq \Prob(f_1 \neq f^\ast_d) + \Prob(f_2 \neq f^\ast_d)
\end{align*}
Thus:
\[
\Inc(d) \leq 2 \cdot \Err(d)
\]
\end{proof}

\paragraph{Discussion.}
This result mirrors the pointwise inequality established in the main text (Theorem~\ref{theorem:incoherence-inequality}) and shows that disagreement between implementations is a rigorous signal of potential failure—even in the absence of ground truth.

While $\Err(d)$ requires access to $\gtfun{d}$, $\Inc(d)$ is fully estimable from samples of $\coder$. This makes functional incoherence a valuable unsupervised proxy for reliability, particularly in settings where model outputs must be audited without labeled data.


