Then, in \cite[Theorem 13.15]{JH98} is proved that, for all $n=2,\ldots,q-2$, the set
\[\B=(\T\cup\{D_i, i=1, \ldots, n\})\setminus\{B_i, C_i, i=1, \ldots, n\}\]
is a minimal blocking set of size 
\begin{equation} \label{eq:size}
k=3(q-1)+n-2n=3q-3-n.
\end{equation}
\end{Setup}

Note that for $n=2$ the size of $\B$ is $3q-5$ and for $n=q-2$ the size of $\B$ is $2q-1$, that is, $2q-1\le \vert \B\vert \le 3q-5$.

\begin{Lemma} \label{lem1} Let $\B$ be a minimal blocking set in $\PG(2, q)$, $q\ge 5$, built with a $k$-construction with $2q\le k\le 3q-5$, then $\B$ has the $r_{\infty}$-property with respect to a point $P\in \B$, and it is not a blocking semioval for every $k$.
\end{Lemma}
\begin{proof} Let $2q\le k \le 3q-5$. Then, $2q\le 3q-3-n\le 3q-5$, and consequently, $2\le n\le q-3$. The set $\B$ consists in $q-1$ points of the line $a$, $n$ points of the line $\ell$, and $2(q-n-1)$ points of the lines $b, c$. It follows that the line $c$ contains at least two points of $\B$. Indeed, for $n=q-3$, the line $c$ has $q-n-1=2$ points of $\B$. 

Let $P\in \B\cap c$. We prove that $PC$ is the unique tangent to $\B$ through $P$. Indeed, if $PC\cap \ell=K$, then, $K\notin \{D_i, \, i=1, \ldots, n\}$, since $D_iC\cap c=C_i\notin \B$.

It follows that $PC$ is a tangent since it intersects $\B$ in only one point $P$. Moreover, $PA$ is a secant because $c$ contains two points in $\B$, and all other lines through $P$ meet the line $a$. To prove that $\B$ is not a blocking semioval, it is sufficient to observe that through the points $D_i$ there are two tangents, that is, $BB_i$ and $CC_i$.
\end{proof}

\begin{Lemma} \label{lem2} Let $\B$ be a minimal blocking set in $\PG(2, q)$, $q \ge 4$, built with a $(2q-1)$-construction, then $\B$ does not have the $r_{\infty}$-property.
\end{Lemma}
\begin{proof} A minimal blocking set built with a $(2q-1)$-construction consists in 
$q-1$ points on the line $a$, $q-2$ points on the line $\ell$, one point on the line $b$, and one point on the line $c$. This construction determines the following minimal blocking set:
\[\B = \{a \setminus\{B, C\}\}\cup  \{\ell \setminus\{A,A',T\}\}\cup\{BT\cap AC=X, AB\cap CT=Y\},\]
where $T=\ell\setminus\{D_1,\dots,D_{q-2},A,A'\}$.

Observe that $BT, AC$ are two tangents to $\B$ through $X$, and $CT, AB$ are two tangents to $\B$ through $Y$. Moreover, for every $P\in \B\cap\{a\setminus A'\}$, $PT, PA$ are tangents and for every $P\in \B\cap\{\ell \setminus A'\}$, $PB, PC$ are tangents. Finally, since every line has at least $q+1\ge 5$ points, there exist at least two tangents through $A'$. 
\end{proof}

From Lemmas \ref{lem1} and \ref{lem2}, the next statement follows.
\begin{Theorem} \label{thm:existence}In $\PG(2, q)$, $q\ge 5$, there exists a minimal blocking set of size $k$, for every $2q\le k\le 3q-5$, with the $r_{\infty}$-property which is not a blocking semioval.
\end{Theorem}

\begin{Theorem}\label{Thm:q>=5,k>=2q} In $\PG(2, q)$, $q\ge 5$, every minimal blocking set built with a $k$-construction, with $2q\le k\le 3q-5$, has the $r_{\infty}$-property with respect to every point $P\in \B\cap (\{a\setminus \bigcup_{i,j=1}^{n}\{B_iC_j\cap a\}\}\cup b\cup c)$.
\end{Theorem}
\begin{proof} For every point $P\in \B\cap c$ the only tangent is $PC$, for every point $P\in \B\cap b$ the only tangent is $PB$. For every point $D_i$ there are two tangents, then we must exclude these points and also points $P$ of $\B\cap \{a\setminus A'\}$, which are intersection of the lines $B_iC_j$ with $a$, because for these points we have the tangents $B_iC_j$ and $PA$. Similarly, for $A'$ there are at least two tangents $B_1C_2$ and $B_2C_1$.
\end{proof}

Combining Theorem \ref{thm:existence} with Theorem \ref{thm:size}, we obtain the next result.

\begin{Theorem} \label{thm: 5} If $q\ge5$, then there exists a minimal blocking set with the $r_{\infty}$-property of size $k$ for every $k$ such that $2q\le k\le 3(q-1)$.
\end{Theorem}
\begin{proof}
	From Theorem \ref{thm:existence} the desired blocking sets exist for any $2q\le k\le 3q-5$. For $k=3q-4$ the assertion follows from Theorem \ref{thm:size}(b) together with Remark \ref{Rem:blocksemiovals}. Finally, for $k=3q-3$ we can apply Remark \ref{Rem:vertexlesstriangle}.
\end{proof}

\section{Blocking sets with the $\Pi$-property in the Affine Planes}\label{secPG:4}

We have seen in Theorem \ref{thm:existence} that for $q\ge4$, and any $2q\le k\le 3q-5$, there exists a blocking set of size $k$ in $\PG(2,q)$ having the $r_\infty$-property. The natural question arises whether there exists any blocking set in $\PG(2,q)$, $q\ge4$, with the $r_\infty$-property, having size $k\le 2q-1$. Surprisingly, we have
\begin{Theorem} \label{thm:no} Every blocking set $\B$ in $\PG(2, q)$ with size $k\le 2q-1$ does not verify the $r_{\infty}$-property with respect to any point $P\in \B$.
\end{Theorem}
\begin{Remark} \em Note that Lemma \ref{lem2} is a particular case of Theorem \ref{thm:no}.
\end{Remark}

In order to prove the theorem, firstly we investigate classes of minimal blocking (semiovals) sets in the affine plane $\AG(2, q)$. The next general lemma will be fundamental. It can be considered as a kind of permanence property.

\begin{Lemma} \label{lem:PG(2,q)} Let $\B$ be a minimal blocking set in $\PG(2, q)$, which has the $r_{\infty}$-property with respect to $P\in \B$, then $\B'=\B \setminus P$ is a minimal blocking set of $\AG(2, q) = \PG(2, q)\setminus r_{\infty}$.
\end{Lemma}
\begin{proof} Every line of $\PG(2, q)$ through $P$, which is different from $r_{\infty}$, intersects $\B'$, and every line not through $P$ intersects $\B'$. Thus $\B'$ is a blocking set of $\AG(2, q)$. Let $P'$ be a point of $\B'$, then there is a line $r$ of $\PG(2, q)$ that intersects $\B'$ exactly in $P'$ and consequently a line of $\AG(2, q)$ that intersects $\B'$ exactly in $P'$. Then $\B'$ is minimal.
\end{proof}

\begin{Example} \label{es:2} \em In $\PG(2, 3)$ with the set of points $\{ABCDEFGHIJKLM\}$, we consider the minimal blocking set $\B=\{ABCDFI\}$. Next picture describes $\PG(2,3)$. 
