\section{Appendix}


\subsection{Different representation of deformed unitary matrix model}
\label{formulation}

Collection of all representations.


1) Small $g$ expansion around $1d$ QCD (each order is the corresponding averaged spins of $1d$ QCD as the Schur skew function):
\begin{eqnarray}
&& \Xi (g_{\pm},h_{\pm})= A_{st} \sum_{q} \ e^{ N q \mu} \ \sum_{r,s=0}\frac{ (N g_+)^r (N g_-)^s}{r! s!}  \sum_{l, l^{'}} h_+^l h_-^{l^{'}} \sum_{\nu \vdash r , \mu \vdash s } d(\nu) d(\mu ) \nonumber \\
&& \sum_{\sigma  \vdash r+ l} s_{\sigma /\nu}(1^{N_f}) s_{N^q \sigma/\mu }(1^{N_f}) \, \delta_{r+ l, s+ l^{'}+ q N} \end{eqnarray}

2) Small $m$ expansion .
Expanding in the most symmetrical way:
the partition function (\ref{det_rep}) can be re-expanded by small $m$ expansion .
\begin{eqnarray}
\Xi (g_{\pm},h_{\pm}) \ =  \ \sum_{q} \ e^{ N q \mu} \ Z_0^{N, N_f} (q) \sum_{r, s =0 }^{\infty } \frac{(N g_+)^{r}}{r!} \frac{(N g_-)^{s}}{s!} \sum_{n=0}^{\infty}A_{r,s}(q,n) m^{ 2 n}  \ . \label{PF_form_343}
\end{eqnarray}

General structure of the expansion near $h=1$
$$
\prod_{n = 1}^N e^{- l_n m }  = \prod_{n = 1}^N (1 -  l_n m + \frac{l_n^2}{2!} m^2 - \frac{ l_n^3}{3!} m^3 +...) = 1 - \sum_{k =1}^N l_k m + 
$$
$$
+ \frac{1}{2!} \left (  \sum_{k =1}^N l_k^2 + \sum_{k\neq r =1}^N  l_k l_r  \right) m^2 -  \frac{1}{3!} \left(  \sum_{k =1}^N l_k^3 + 3 \sum_{k\neq r  =1}^N l_k^2 l_r  + \sum_{k\neq r \neq s =1}^N  l_k l_r l_s   \right) m^3 + ... =
$$
$$
= 1+ \frac{1}{2!} T_1 m^2 + \frac{1}{4!} \left ( T_2 + \sum_{k\neq r =1}^N  T_1 T_1 \right) m^4 + O( m^6)
$$
We choose $l \to 2 l- N_f+a$ and $a= -r_i+ s_j -i+j+ q$ to make the most efficient way  of calculation. 
$$
Z = e^{-(2 l - N_f +a ) m} = 1 - (2 l - N_f+ a) m  + \frac{(2 l - N_f + a)^2}{2}  m^2 - \frac{ (2 l - N_f + a)^3}{3!} m^3 + ...
$$
Making summation (denoting )
$$\sum_{l=0}^{N_f} {N_f \choose l} {N_f \choose l+a}  = {2 N_f\choose N_f +a}= T_0,
$$
$$
\sum_{l=0}^{N_f} {N_f \choose l} {N_f \choose l+a} (2 l - N_f + a) = 0, 
$$
$$
\frac{1}{T_0} \sum_{l=0}^{N_f} {N_f \choose l} {N_f \choose l+a}\frac{(2 l - N_f + a )^2}{2!}  = -\frac{(a^2-N_f^2)}{2 (2N_f-1)} = T_1 , 
$$
$$\sum_{l=0}^{N_f} {N_f \choose l} {N_f \choose l+a} \frac{(2 l - N_f + a )^3}{3!}  = 0 ,
$$
$$
\frac{1}{T_0}\sum_{l=0}^{N_f} {N_f \choose l} {N_f \choose l+a}\frac{(2 l - N_f + a )^4}{4!}   = 
\frac{\left(a^2- n^2\right) \left(4 n +3 \left(a^2- n^2\right) \right)}{4!  (2 n -3) (2 n -1)}  = T_2 , 
$$
and so on.
Calculation of determinants:
$$
  \det_{1\le i, j \le N} \ T_0 =  \frac{ G[N+ 2 N_f+1] G[N+1] G[N_f-q+1] G[N_f+q+1] }{ G[2 N_f+1] G[N+ N_f- q+1] G[N+ N_f+ q+1] } = Z_0^{N, N_f} (q)   \ .
$$
and $G(x)$ is Burness G function,
$$
A_{0,0}(q,1)= \frac{1}{ Z_0^{N, N_f} (q) }\sum_{k=1}^N \det_{1\le i,j\le N} \left[ T_1^{i, j} \delta_{k, i}+ (1-\delta_{k, i}) \right] T_0^{i \, j} = \frac{ N (N + 2 N_f) (N_f^2 -q^2) }{2 (4 N_f^2-1)} \ ,
$$
$$
A_{0,0}(q,2)= \frac{1}{ Z_0^{N, N_f} (q) } \left( \sum_{k=1}^N \det_{1\le i,j\le N} \left[ T_2^{i, j}  \delta_{k, i}+ (1-\delta_{k, i}) \right] T_0^{i \, j} + \right.
$$
$$
+ \frac{1}{2}\left. \det_{1\le i,j\le N} \sum_{k\neq r =1}^N \left[ T_1^{i, j} \delta_{k, i}+ (1-\delta_{k, i}) \right] \left[T_1^{i, j}  \delta_{l, i}+ (1-\delta_{l, i}) \right] T_0^{i \, j} \right)
$$
and so on.
For calculation (as example) $A_{1,1}(q,n)$ we need in $A_{0,0}(q,n)$ make a  shift  $-i+j \to -i +\delta_{i,1}- \delta_{j,1} $ (as a "sources" dictated Young tableau) and in general $A_{r,s}(q,n)$ this is looks like a sum by all partition of  both - $r$ (associated with some  $\sum_p t_p\delta_{j,p}$) and  $s$ (associated with some  $\sum_p t^{\prime}_p \delta_{i,p}$) .





