\label{Strict}
{\bf   Case $g_+ = g_-$}

\begin{eqnarray}\label{F2U(N)}
F_2 [\kappa, g, m] =  F_{g=0} [\kappa, m ]-\frac{4 g(\xi-1)}{\xi^2-1}- \nonumber \\
-(\xi-1) \left \{ \frac{G}{(\xi-1)^2(\xi+1)}-\frac{ G^2 \xi^2 }{2 (\xi-1)^2 (\xi+1)^4} +\frac{ G^3 \xi^2 }{3 (\xi+1)^7} -\right. 
