\left. - \frac{G^6 \xi^2 \left(\xi^6-18 \xi^5+88 x\xi^4-150 \xi^3+88 \xi^2-18 \xi+1\right)}{6 (\xi+1)^{16}}  + O(G^7) \right \}  \, .
