\section{SNC-assisted Probabilistic Delay Bound Analysis}
\label{sec:SNC-assisted Probabilistic Delay Bound Analysis}
In this section, we analyze the upper bound of the total end-to-end delay in the proposed system. We begin by examining the queuing delay in the buffer, which is expressed as a function of the queuing delay. Subsequently, we analyze the propagation delay itself and formulate an optimization problem to minimize it. This, in turn, corresponds to minimize the upper bound of the total packet delay in the considered system.

\subsection{Queueing Delay}
In this subsection, we analyze the queuing delay of the data in the buffer. Note that only the queuing delay on the TX-SIM side is considered in this analysis. The upper bound of $D_1$ is given in the following lemma.
\begin{lemma}[Upper Probabilistic Bound of Queueing Delay] 
\label{theorm_barD1}
The queueing upper probabilistic bound is given by 
\begin{align}
 \bar{D}_1 = \epsilon(v_{\text{data}} B t_b),
\end{align}
% \begin{align}
%  \bar{D}_1 = P\{D_1 > t_b\} \leq \epsilon(v_{\text{data}} B t_b)=\bar{D}_1,
% \end{align}
where  $\beta_{\text{data}}(t_b) $ is the service curve, $t_b$ is the expected queuing delay, and $\epsilon(\cdot)$ is the bounding function, in case of Poisson arrival process $\epsilon(x) = e^{-\mu x} $, and $ \mu > 0 $ is a parameter that minimizes the bounding function  $\epsilon(x)$, and
\begin{align}
\beta_{\text{data}}(t) = v_{\text{data}}  B t,
\end{align}
in which $B$ denotes the system bandwidth and $v_{data}$ is the transmission rate in the HMIMO channel.
\end{lemma}
\begin{proof}
    See Appendix \ref{app_barD1}.
\end{proof}

Recall that we assume the arrival process $A(t)$ follows a Poisson distribution, and the packet size follows an exponential distribution with mean $l_d$. Let $\delta_d(t)$ denote the number of packets arriving at the HMIMO channel at time $t$, and let $\delta(t)$ denote the number of packets generated from $S$ sources. In a stable network, we have $\delta_d(t) = \delta(t - D_2)$.

The stochastic arrival curve can then be expressed as~\cite{jiang2010note}:
\begin{equation}
\alpha(t) =\frac{1}{\mu } \log \mathbb{E}[e^{\mu A(t)}]  = \frac{\delta_d l_d t}{1 - \mu l_d},
\end{equation}
and consequently, according to the stability condition \( \alpha(t) \leq \beta(t) \), the optimal value of \( \mu \) is given by:
\begin{equation}
\mu = \frac{v_{\text{data}} B - \delta_d l_d}{v_{\text{data}} B l_d}.
\label{eq:mu}
\end{equation}

\begin{lemma}[Queueing Probabilistic Delay Bound in Case of Poisson Arrival Process]
Combining the bounding function $\epsilon(x)=e^{-\mu x}$ and ~\eqref{eq:mu}, the probabilistic delay bound of \( D_1 \) in case of Poisson arrival process is given by:
\begin{equation}
\bar{D}_1(t_b) = e^{-\mu v_{\text{data}} B t_b} = e^{-\frac{v_{\text{data}} B - \delta_d l_d}{l_d} t_b}.
\label{eq_pdfD1}
\end{equation}
\end{lemma}
\subsection{Transmission delay}
Assume that there are $S$ data streams in total. The TX-SIM consists of $L$ metasurface layers, each containing $M$ meta-atoms, where $M \geq S$. Similarly, the RX-SIM is composed of $K$ metasurface layers, each with $N$ meta-atoms, and $N \geq S$. Under these conditions, the transmission delay $D_2$ can be expressed as\begin{equation}
\begin{split}
\begin{aligned}
% D_2 = \max(\frac{d_{s,\text{TX}}}{v_{\text{TX}}} + \frac{d_{A-\text{TX}}}{v_{\text{TX}}} + \frac{d_{B-\text{RX}}}{v_{\text{RX}}} + \frac{d_{\text{RX},s}}{v_{\text{RX}}} )\\
D_2 = \max(\frac{d_{s,\text{TX}} + d_{A-\text{TX}}}{v_{\text{TX}}} + \frac{d_{B-\text{RX}} + d_{\text{RX},s}}{v_{\text{RX}}}),
\end{aligned}
\end{split}
\label{eq:D_2}
\end{equation}
where $v_{\text{TX}}$ and $v_{\text{RX}}$ denote the electromagnetic wave propagation speeds within the TX-SIM and RX-SIM, respectively. The term $d_{s,\text{TX}}$ represents the distance between the $s$-th data source and the $m$-th meta-atom in the input metasurface layer of the TX-SIM, while $d_{\text{RX},s}$ denotes the distance between the $n$-th meta-atom in the output metasurface layer of the RX-SIM and the $s$-th data source. The total intra-device propagation distances within the TX-SIM and RX-SIM are denoted by $d_{A\text{-}TX}$ and $d_{B\text{-}RX}$, respectively. The values of $d_{s,\text{TX}}$ and $d_{\text{RX},s}$ can be calculated using the following formula
\begin{equation}
\begin{split}
\begin{aligned}
a_{TX} =  \left( m_z - \frac{m_{\text{max}}^r + 1}{2} \right) r_{\text{tx}} - \left( s - \frac{S + 1}{2} \right) \frac{\lambda}{2},
\end{aligned}
\end{split}
\label{eq:a_TX}
\end{equation}
\begin{equation}
\begin{split}
\begin{aligned}
a_{RX} =   \left( n_z - \frac{n_{max}^r + 1}{2} \right) r_{rx} - \left( s - \frac{S + 1}{2} \right) \frac{\lambda}{2},
\end{aligned}
\end{split}
\label{eq:a_RX}
\end{equation}
\begin{equation}
\begin{split}
\begin{aligned}
b_{TX} = m_x - \frac{m_{max}^r + 1}{2}r_{tx}, \ b_{RX} = n_x - \frac{n_{max}^r + 1}{2}r_{rx},
\end{aligned}
\end{split}
\label{eq:b_TX}
\end{equation}
\begin{equation}
\begin{split}
\begin{aligned}
d_{s,\text{TX}} = \sqrt{ a_{TX}^2 
+ b_{TX} ^2 + d_t^2 }, \ d_{\text{RX},s} = \sqrt{a_{RX}^2 
+ b_{RX}^2 + d_r^2 },
\end{aligned}
\end{split}
\label{eq:d_s,TX}
\end{equation}

\noindent where $m_z = \lceil \frac{m}{m_{\max}^r} \rceil$ and $n_z = \lceil \frac{n}{n_{\max}^r} \rceil$ represent the z-axis indices of the $m$-th and $n$-th meta-atoms in the TX-SIM and RX-SIM, respectively. Similarly, let $m_x = \operatorname{mod}(m-1, m_{\max}^r) + 1$ and $n_x = \operatorname{mod}(n-1, n_{\max}^r) + 1$ represent their respective x-axis indices, $m_{\max}^r$ denotes the maximum number of meta-atoms per row on each metasurface layer of the TX-SIM, while $n_{\max}^r$ denotes the same for the RX-SIM. The parameters $r_{\text{tx}}$ and $r_{\text{rx}}$ represent the distances between adjacent meta-atoms on each metasurface layer of the TX-SIM and RX-SIM, respectively. Let $\lambda$ denote the signal wavelength. The vertical spacing between metasurface layers in the TX-SIM is given by $d_t = \frac{D_t}{L}$, where $D_t$ is the total thickness of the TX-SIM and $L$ is the number of metasurface layers. Similarly, $d_r = \frac{D_r}{K}$ denotes the vertical spacing between metasurface layers in the RX-SIM, where $D_r$ is the total thickness and $K$ is the number of layers.

Next, we calculate $d_{\text{A-TX}}$ and $d_{\text{B-RX}}$, where $d_{\text{A-TX}}$ denotes the transmission distance of the $s$-th data stream within the TX-SIM of $eVTOL_A$, and $d_{\text{B-RX}}$ denotes the transmission distance of the $s$-th data stream within the RX-SIM of $eVTOL_B$. The corresponding formulas are given as follows
\begin{equation}
\begin{aligned}
d_{A-RX} =\sum_{l=2}^{\mathrm{L}} d_{A-R X}^{\mathrm{l}}, \ d_{B-RX} =\sum_{k=2}^{\mathrm{K}} d_{B-R X}^{\mathrm{k}},
\end{aligned}
\label{_w_ripuewaigw}
\end{equation}
\begin{equation}
\mathrm{~d}_{\mathrm{A}-\mathrm{TX}}^{\mathrm{l}}=\sqrt{{\mathrm{r}_{\mathrm{m}_{\mathrm{A}}, \mathrm{~m}_{\mathrm{A}}^{\prime}}^l}^2+\mathrm{d}_{\mathrm{t}}^2} \quad  l \in [2,L],
\label{eq:d_B_RX_k}
\end{equation}
\begin{equation}
d_{B-R X}^{\mathrm{k}}=\sqrt{{\mathrm{r}_{\mathrm{n}_{\mathrm{B}}, \mathrm{~n}_{\mathrm{B}}^{\prime}}^k}^2+\mathrm{d}_{\mathrm{r}}^2} \quad k\in[2,K],
\label{_w_ripuewaigw}
\end{equation}
where $d_{A\text{-TX}}^{l}$ denotes the distance between the $m_A$-th meta-atom on the $(l{-}1)$-th layer and the $m_A^{\prime}$-th meta-atom on the $l$-th layer of the TX-SIM in $eVTOL_A$. Similarly, $d_{B\text{-RX}}^{k}$ represents the distance between the $n_B$-th meta-atom on the $(k{-}1)$-th layer and the $n_B^{\prime}$-th meta-atom on the $k$-th layer of the RX-SIM in $eVTOL_B$.
The term $\mathrm{r}_{m_A,m_A^{\prime}}^{1}$ denotes the horizontal spacing between the $m_A$-th and $m_A^{\prime}$-th meta-atoms on the same metasurface layer of $eVTOL_A$. Likewise, $\mathrm{r}_{n_B, n_B^{\prime}}^{k}$ denotes the spacing between the $n_B$-th and $n_B^{\prime}$-th meta-atoms on the same metasurface layer of $eVTOL_B$.
The expressions for $\mathrm{r}_{m_A, m_A^{\prime}}^{1}$ and $\mathrm{r}_{n_B,n_B^{\prime}}^{k}$ are given as follows:
\begin{equation}
% \begin{aligned}
\mathrm{r}_{\mathrm{m_A}, \mathrm{~m_A}^{\prime}}^1=\mathrm{r}_{\mathrm{tx}} \sqrt{\left(\mathrm{~m}_{\mathrm{z}}-\mathrm{m}_{\mathrm{z}}^{\prime}\right)^2+\left(\mathrm{m}_{\mathrm{x}}-\mathrm{m}_{\mathrm{x}}^{\prime}\right)^2},
% \end{aligned}
\label{eq:r_mm_l}
\end{equation}
\begin{equation}
% \begin{aligned}
\mathrm{r}_{\mathrm{n_B}, \mathrm{~n_B}^{\prime}}^k=\mathrm{r}_{\mathrm{rx}} \sqrt{\left(\mathrm{~n}_{\mathrm{z}}-\mathrm{n}_{\mathrm{z}}^{\prime}\right)^2+\left(\mathrm{n}_{\mathrm{x}}-\mathrm{n}_{\mathrm{x}}^{\prime}\right)^2}.   
% \end{aligned}
\label{eq:r_nn_k}
\end{equation}

Finally, we are ready to derive the upper bound which is a fixed constant of the transmission delay, as given in the following lemma.
\begin{lemma}[Upper Bound of Transmission Delay]
The upper bound of the transmission delay is given by:
\begin{equation}
% \begin{split}
\begin{aligned}
 % D_2 &= \max(\frac{d_{\text{TX}, s} + d_{A\text{-TX}}}{v_{\text{TX}}} + \frac{d_{B\text{-RX}} + d_{\text{RX}, s}}{v_{\text{RX}}}) \\
        D_2 &= \max(\frac{\sqrt{a_{TX}^2 
+ b_{TX} ^2 + d_t^2 } 
            + \sum_{l=2}^{L} \sqrt{r_{m_A, m_A'}^1 + d_t^2}}{v_{\text{TX}}} \\
        &\quad + \frac{\sqrt{a_{RX}^2 
+ b_{RX} ^2 + d_r^2 } 
            + \sum_{k=2}^{K} \sqrt{r_{n_B, n_B'}^2 + d_r^2}}{v_{\text{RX}}} ).
\end{aligned}
% \end{split}
\label{eq_pdfD2}
\end{equation}
\end{lemma}
\begin{proof}
The result in (\ref{eq_pdfD2}) is obtained by combining ~\eqref{eq:D_2}--\eqref{eq:r_nn_k}.
\end{proof}


\subsection{Propagation Delay}
The upper probabilistic bound of the propagation delay \( \bar{D}_3(t) \) for transmitting \( S \) packets in the HMIMO channel can be expressed in the following lemma.
\begin{lemma}[Upper Probabilistic Bound of Propagation Delay] The upper probabilistic bound of propagation delay is given by:
\begin{align}
P\{D_3>t_d\}\leq\bar{D}_3(t_d) .
\end{align}
\end{lemma}
\begin{proof}The upper bound of $D_3$ is computed as follows:
\begin{equation}
\begin{aligned}
P\{D_3 > t_d\}= P\left\{ \frac{S l_d}{v_{\text{data}} B} > t_d \right\} 
= P\left\{ l_d > \frac{v_{\text{data}} B t_d}{S} \right\}.
\end{aligned}
\end{equation}
Let \( f_L(l) \) be the probability density function (PDF) of \( l_d \), the bounding function of $t_d$ is
\begin{equation}
\begin{aligned}
\label{eq_pdfD3}
\bar{D}_3(t_d) 
&= \int_{\frac{v_{\text{data}} B t_d}{S}}^{\infty} f_L(l) \, dl =e^{-\frac{v_{\text{data}} B}{S l_d} t_d}.
\end{aligned}
\end{equation}
\end{proof}

Now that the upper probabilistic bounds of \( D_1 \) and \( D_3 \) have been derived, we proceed to present the total upper probabilistic bound of the end-to-end delay in the following theorem. To facilitate the derivation, we first introduce a prerequisite lemma.

\begin{lemma}
Let \( Z = \sum_{i=1}^N X_i \), where \( Z \) and \( X_i \) are random variables. Then, the complementary cumulative distribution function (CCDF) of \( Z \) satisfies the following inequality
\begin{equation}
\bar{F}_Z(x) \leq \bar{F}_{X_1} \otimes \bar{F}_{X_2} \otimes \cdots \otimes \bar{F}_{X_N}(x),
\end{equation}
where \( \bar{F}_Z(x) \) denotes the CCDF of \( Z \) with respect to the variable \( x \), and \( \otimes \) represents the min-plus convolution operator.
\label{lemma_CCDF}
\end{lemma}

Based on Lemma~\ref{lemma_CCDF} and the statistical properties of \( D_1 \), \( D_2 \), and \( D_3 \), we now establish the upper probabilistic bound of the total end-to-end delay as follows.

\begin{theorem}[Upper probabilistic bound of $D$]
According to Lemma~\ref{lemma_CCDF}, the upper probability bound of the total delay is 
\begin{equation}
\begin{split}
\begin{aligned}
& \bar{D} =\inf _{\mathrm{t}_1+\mathrm{t}_3=\mathrm{T}-\mathrm{D}_2}\left\{\mathrm{e^{-\frac{v_{\text{data}} B - \delta_d l_d}{l_d} t_b}+\mathrm{e^{-\frac{v_{\text{data}} B }{S l_d}t_d}}}\right\}.
\end{aligned}
\end{split}
\label{vuyresgdfsuuysdriv}
\end{equation} 
\end{theorem}
\begin{proof}
The upper bound $\bar{D}$ is computed as
\begin{equation}
\begin{split}
\begin{aligned}
& \bar{D} = P\{\mathrm{D}>\mathrm{t}\}=\mathrm{P}\left\{\mathrm{D}_1(\mathrm{t})+\mathrm{D}_3(\mathrm{t})>\mathrm{T}-\mathrm{D}_2\right\} \\& \leq \mathrm{f}_{\mathrm{D}_1}\left(\mathrm{t}_{\mathrm{b}}\right) \otimes \mathrm{f}_{\mathrm{D}_3}\left(\mathrm{t}_{\mathrm{d}}\right),
\end{aligned}
\end{split}
\label{vuyresgdfsuuysdriv}
\end{equation} 
proof completes by substituting the CCDF of $D_1$ and $D_3$, as given in (\ref{eq_pdfD1}) and (\ref{eq_pdfD3}), respectively.
\end{proof}

We now derive the upper probabilistic bound of the delays associated with buffering, radio propagation, and transmission, and express the upper probabilistic bound of the total delay as a function of $v_{\rm data}$ and $t_d$, which are key parameters related to SIM-assisted transmission. In the following section, we analyze the optimal values of $v_{\rm data}$ and $t_d$ that minimize the total delay  $T$ and the total end-to-end probabilistic bound. 


\section{SIM-based Performance Optimization}
\label{sec:SIM Performance Analysis}
Following the derivation of the probabilistic upper bound on the total end-to-end delay $\bar{D}$, a critical aspect remains to be addressed: the determination of the data transmission rate within the HMIMO channel. This transmission rate, denoted by $v_{\text{data}}$, directly influences the propagation delay $t_d$ and serves as a fundamental parameter in the performance evaluation of the proposed communication system. In the subsequent analysis, we derive an analytical expression for $v_{\text{data}}$.

The transmission rate in the HMIMO channel can be characterized to provide a quantitative basis for subsequent delay analysis~\cite{10534211}. Let $\theta_m^l \in [0, 2\pi)$ denote the phase shift of the $m$-th meta-atom in the $l$-th metasurface layer of the TX-SIM, where $m \in [1, M]$ and $l \in [1, L]$. The corresponding transmission coefficient is given by $\phi_m^l = e^{j\theta_m^l}$. The phase shift vector of the $l$-th layer is defined as $\boldsymbol{\phi}^1 = \left[\phi_1^1, \phi_2^1, \ldots, \phi_M^1\right]^{\mathrm{T}} \in \mathbb{C}^{M \times 1},$ and the associated transmission coefficient matrix is expressed as
$\mathbf{\Phi}^1 = \mathrm{diag}[\Phi^1] \in \mathbb{C}^{M \times M}$.
Similarly, let $\xi_n^k \in [0, 2\pi)$ denote the phase shift of the $n$-th meta-atom in the $k$-th layer of the RX-SIM, where $n \in [1, N]$ and $k \in [1, K]$. The corresponding transmission coefficient is given by $\psi_n^k = e^{j\xi_n^k}$. The phase shift vector of the $k$-th layer is defined as $ \boldsymbol{\psi}^k = \begin{bmatrix}
    \psi_1^k, \psi_2^k, ..., \psi_N^k
\end{bmatrix}^T \in \mathbb{C}^{N \times 1}$ and the corresponding transmission coefficient matrix is $\mathbf{\Psi}^1 = \text{diag}[\boldsymbol{\psi}^k] \in \mathbb{C}^{N \times N}$.

According to~\cite{10158690}, the transmission coefficient from the $m_A'$-th meta-atom in the $(l{-}1)$-th layer to the $m_A$-th meta-atom in the $l$-th layer of the TX-SIM carried by $eVTOL_A$ is given by
\begin{equation}
\mathrm{w}_{\mathrm{m}, \mathrm{~m}^{\prime}}^1=\frac{\mathrm{C}_{\mathrm{t}} \cos \chi_{\mathrm{m}, \mathrm{~m}^{\prime}}^1}{d_{A-TX}^l}\left(\frac{1}{2 \pi d_{A-TX}^l}-\mathrm{j} \frac{1}{\lambda}\right) \mathrm{e}^{\frac{\mathrm{j} 2 \pi d_{A-TX}^l }{\lambda} }, 
\end{equation}
%1 \in \mathrm{~L}
where $d_{A\text{-TX}}^l$ denotes the distance between the $m$-th meta-atom in the $l$-th metasurface layer and the $m'$-th meta-atom in the $(l{-}1)$-th layer, with $l \in [2, L]$. Here, $C_t$ is the effective area of each meta-atom in the TX-SIM, and $\chi_{m,, m'}^l$ is the angle between the wave propagation direction from the $(l{-}1)$-th layer and the normal vector of the $l$-th metasurface layer.

