\begin{equation}
\mathbf{X} = \mathbf{\Phi}^L \mathbf{W}^L\mathbf{\Phi}^{L-1} \mathbf{W}^{L-1} \dots \mathbf{\Phi}^2 \mathbf{W}^2 \mathbf{\Phi}^1 \mathbf{W}^1 \in \mathbb{C}^{M \times S}.
