\mathbf{H} 
% &= \mathbf{Y} \mathbf{G} \mathbf{X} \\
&= \mathbf{U}^1 \boldsymbol{\Psi}^1 \cdots \mathbf{U}^K \boldsymbol{\Psi}^K \, 
   \mathbf{G} \, 
   \boldsymbol{\Phi}^L \mathbf{W}^L \cdots \boldsymbol{\Phi}^1 \mathbf{W}^1 \\
&= \boldsymbol{h}_{\mathrm{SIM}, r}^\mathrm{H} \, \boldsymbol{\Omega} \, \boldsymbol{h}_{t, \mathrm{SIM}},
\end{aligned}
\label{eq:H}
\end{equation}
where $\mathbf{h}_{\text{SIM},r}$ denotes the channel coefficient matrix from the $p$-th metasurface layer of the SIM to the receiver, with $p \in \left[1, \max\left(L, K\right)\right]$. The transmission coefficient matrix is defined as $\mathbf{\Omega} = \text{diag}(e^{j\Omega_1}, \dots, e^{j\Omega_{\text{a}}}) \in \mathbb{C}^{\text{a} \times \text{a}}$, where $\Omega_{\mathrm{a}}$ represents the phase shifts of the single-layer SIM subject to optimization. Depending on whether the phase shifts of the TX-SIM or RX-SIM are being optimized, we set $\Omega = \boldsymbol{\phi}$ or $\Omega = \boldsymbol{\psi}$, respectively. The parameter $\mathrm{a}$ denotes the number of meta-atoms in the metasurface layer, which varies according to whether the transmission coefficient matrix corresponds to the TX-SIM or RX-SIM. Furthermore, $\mathbf{h}_{\mathrm{t,SIM}}$ denotes the channel coefficient matrix from the transmitter to the $p$-th metasurface layer of the SIM. The channel coefficient matrices under different optimization objectives are expressed as following two scenarios,

(i) if the phase shifts of TX-SIM is being optimized, then we have
\begin{equation}
\begin{aligned}
\boldsymbol{h}_{S I M, r} &= \mathbf{Y} \mathbf{G} \boldsymbol{\Phi}^L \mathbf{W}^L \cdots \boldsymbol{\Phi}^{p+1} \mathbf{W}^{p+1}, \\
\boldsymbol{h}_{t, SIM} &= \mathbf{W}^p \boldsymbol{\Phi}^{p-1} \mathbf{W}^{p-1} \cdots \boldsymbol{\Phi}^1 \mathbf{W}^1. 
\label{eq:h_SIM_r}
\end{aligned}
\end{equation}

(ii) if the phase shifts of RX-SIM is being optimized, then we have
\begin{equation}
\begin{aligned}
\boldsymbol{h}_{S I M, r} &= \mathbf{U}^1 \boldsymbol{\Psi}^1 \cdots \mathbf{U}^{p-1} \boldsymbol{\Psi}^{p-1} \mathbf{U}^p ,\\
\boldsymbol{h}_{t, SIM} &= \mathbf{U}^{p+1} \boldsymbol{\Psi}^{p+1} \cdots \mathbf{U}^K \boldsymbol{\Psi}^K \mathbf{G} \mathbf{X}.
\label{eq:h_t_SIM}
\end{aligned}
\end{equation}
It is important to note that the phase shift values contained in the matrices $\mathbf{X}$ and $\mathbf{Y}$ are iteratively updated throughout the progression of the BCD algorithm.

Based on the aforementioned channel model, the original optimization problem $\mathcal{P}4$ can be further reformulated as the optimization problem $\mathcal{P}5$
\begin{equation}
\begin{aligned}
\begin{gathered}
\mathcal{P}5: \max _{\Omega} \sum_{s=1}^S| | \boldsymbol{h}_{S I M, r, s}^H \boldsymbol{\Omega} \boldsymbol{h}_{t, S I M}| |^2 \\
\text { s.t. } 0 \leq \Omega_{\text {a }} \leq 2 \pi \quad\text { a } \in[1, \max \{M, N\}],
\end{gathered}
\label{sdfblaer}
\end{aligned}
\end{equation}
where $\boldsymbol{h}_{\text{SIM}, r, s}^H \in \mathbb{C}^{1 \times \text{a}}$ denotes the channel coefficient vector from the $p$-th metasurface layer of the SIM to the receiver for the $s$-th data flow. The vector $\boldsymbol{v} = [v_1, v_2, \ldots, v_{\text{a}}]^T \in \mathbb{C}^{\text{a} \times 1}$ is defined such that each element $v_{\text{a}} = e^{j \Omega_{\text{a}}}$ corresponds to the phase shift of a meta-atom. The constraint on the phase shifts can be equivalently expressed as a unit-modulus constraint, i.e.,
\(|v_{\text{a}}|^2 = 1\), which leads to the following formulation
\begin{equation}
    \sum_{s=1}^S| | \boldsymbol{h}_{S I M, r, s}^H \boldsymbol{\Omega} \boldsymbol{h}_{t, S I M}| |^2=\sum_{s=1}^S| | \boldsymbol{v}^H \boldsymbol{\Lambda}_s| |^2 ,
\end{equation}
where $\boldsymbol{\Lambda}s = \mathrm{diag}\left( \boldsymbol{h}_{\text{SIM}, r, s}^H \right)$ and $\boldsymbol{h}_{t, \text{SIM}} \in \mathbb{C}^{\text{a} \times S}$, thereby leading to the formulation of problem $\mathcal{P}6$ as shown as:
%where \(\boldsymbol{\Lambda}_s = \text{diag}\left( \boldsymbol{h}_{S I M, r, s}^H \right),\boldsymbol{h}_{t, S I M} \in \mathbb{C}^{\text{atom} \times S}\), thus resulting in the above formulation $\mathcal{P}6$.
\begin{equation}
\begin{aligned}
\begin{gathered}
\mathcal{P}6: \quad \max_{\mathbf{v}} \sum_{s=1}^{S} \mathbf{v}^H \boldsymbol{\Lambda}_s \boldsymbol{\Lambda}_s^H \mathbf{v}\\
\text { s.t. }\left|\mathbf{v}_{\text {a }}\right|^2=1, \text { a } \in[1, \max \{M, N\}].
\label{sdfblaer}
\end{gathered}
\end{aligned}
\end{equation}

This transformation results in a Quadratically Constrained Quadratic Programming (QCQP) problem. By introducing an auxiliary variable $i$, the problem can be equivalently reformulated as
\begin{equation}
\begin{aligned}
\begin{gathered}
\mathcal{P}7: \quad \max_{\mathbf{\bar{v}}} \sum_{s=1}^{S} \mathbf{\bar{v}}^H \mathbf{R}_s \mathbf{\bar{v}} \\
\text { s.t. }\left|\mathbf{v}_{\text {a }}\right|^2=1, \text { a } \in[1, \max \{M, N\}],
\end{gathered}
\end{aligned}
\end{equation}
where 
\[ \mathbf{R}_s = \begin{bmatrix}
\mathbf{\Lambda}_s \mathbf{\Lambda}_s^H & 0 \\
0 & 0
\end{bmatrix}, \quad 
\mathbf{\bar{v}} = \begin{bmatrix}
\mathbf{v} \\
i
\end{bmatrix}.
\]

The problem remains non-convex due to the rank-one constraint. Noting that
\( \mathbf{\bar{v}}^H \mathbf{R}_s \mathbf{\bar{v}} = \operatorname{tr}(\mathbf{R}_s \mathbf{\bar{v}} \mathbf{\bar{v}}^H) \),
we define the matrix $\mathbf{V} = \mathbf{\bar{v}} \mathbf{\bar{v}}^H$, which is positive semidefinite and constrained to have $\mathrm{rank}(\mathbf{V}) = 1$. By applying SDR method, we relax the rank-one constraint, thereby reformulating the problem as:
\begin{equation}
\begin{aligned}
\begin{gathered}
\mathcal{P}8: \quad \max_{\mathbf{V}} \sum_{s=1}^{S} \operatorname{tr}\left(\mathbf{R}_s \mathbf{V}\right) \\
\text{s.t.} \quad \mathbf{V}_{\text{a, a}} = 1, \quad \text{i} \in [1, \max\{\mathbf{M}, \mathbf{N}\} + 1], \ \mathbf{V} \succeq 0.    
\end{gathered}
\end{aligned}
\end{equation}

At this stage, problem $\mathcal{P}8$ can be transformed into a convex SDP problem, which can be efficiently solved using existing convex optimization techniques. In this work, the MOSEK solver is employed to numerically obtain the optimal solution to the SDP problem.

Since the optimal solution obtained via the SDR method is generally a positive semidefinite matrix, it is necessary to extract feasible solutions that satisfy the original problem’s constraints in practical SIM phase shift optimization. To this end, the Gaussian randomization method is commonly employed to recover feasible solutions from the relaxed SDR solution. The core idea of Gaussian randomization involves performing eigenvalue decomposition on the SDR solution, followed by random sampling to approximate a rank-one solution that meets the problem constraints. Owing to its relatively low computational complexity and straightforward implementation, the Gaussian randomization method has been widely adopted in various wireless communication optimization problems. In this work, for problem $\mathcal{P}8$, the specific steps of the Gaussian randomization method are outlined as follows.
%Since the optimal solution obtained by the SDR method is typically a positive semidefinite matrix, and in practical SIM phase shifts optimization, we often need to extract feasible solutions that satisfy the constraints, the Gaussian randomization method is widely used to recover feasible solutions from the SDR solution. The core idea of the Gaussian randomization method is to use eigenvalue decomposition to process the SDR solution and combine it with random sampling methods to find the optimal solution. Due to its low computational complexity and ease of implementation, the Gaussian Randomization method is widely applied in various wireless communication optimization problems. In this paper, for problem $\mathcal{P}8$, the specific steps of the Gaussian randomization method are as follows.

%First, perform eigenvalue decomposition in the SDR solution matrix $\mathbf{V}$, obtaining the eigenvalue vector $\boldsymbol{\sigma}$ and the eigenvector matrix $\mathbf{P} \in \mathbb{C}^{\text{atom} \times \text{atom}}$. Then, generate a normalized complex Gaussian random vector,$\mathbf{r} \in \mathbb{C}^{\text{atom} \times 1}$, and use it to construct the optimized phase shifts vector:
First, perform eigenvalue decomposition on the SDR solution matrix $\mathbf{V}$ to obtain the eigenvalue vector $\boldsymbol{\sigma}$ and the eigenvector matrix $\mathbf{P} \in \mathbb{C}^{\text{a} \times \text{a}}$. Next, generate a normalized complex Gaussian random vector $\mathbf{r} \in \mathbb{C}^{\text{a} \times 1}$, which is then used to construct the candidate optimized phase shift vector as follows:
\begin{equation}
\begin{aligned}
\begin{gathered}
\mathbf{v} = \mathbf{P} \, \text{diag}(\sqrt{\boldsymbol{\sigma}}) \, \mathbf{r}.   
\end{gathered}
\end{aligned}
\end{equation}

This vector is then employed to construct the transmission coefficient matrix
\(\boldsymbol{\Omega} = \text{diag}(\mathbf{v})\) which is subsequently substituted into the expression for the transmission rate in the HMIMO channel as follows:
\begin{equation}
\begin{aligned}
\begin{gathered}
\mathrm{v}_{\text {data }}=\log _2 \operatorname{det}\left(\mathbf{I}+\frac{\mathbf{H Z H}^{\mathrm{H}}}{\mathrm{~N}_0 \mathrm{~B}}\right)  .
\end{gathered}
\end{aligned}
\end{equation}

