If we choose $\ket{\hat w} = \ket{0}$, then we have that
%
\begin{equation*}
\mathcal{K}_1 = \{5,6,7,8\}^4.
\end{equation*}

Next, we need to find the indices $(a,b,i,j)$ contained in $\mathcal{K}_1$ for which
${\rm SWAP}_\mathfrak{ll} (\ket{\tilde \psi_a} \otimes \ket{\tilde \psi_i})$ is not orthogonal to
$\ket{\tilde \psi_b} \otimes \ket{\tilde \psi_j}$. First, we compute the action of ${\rm SWAP}_\mathfrak{ll}$
on the tensor products of the asymptotic eigenstates,

\begin{equation*}
\begin{split}
{\rm SWAP}_\mathfrak{ll} (\ket{\tilde \psi_i} \otimes \ket{\tilde \psi_i}) =& \ket{\tilde \psi_i} \otimes \ket{\tilde \psi_i}, \\
{\rm SWAP}_\mathfrak{ll} (\ket{\tilde \psi_i} \otimes \ket{\tilde \psi_j}) =& \ket{\tilde \psi_i} \otimes \ket{\tilde \psi_j}
\text{ if } (i,j) \in \{(5,6), (6,5), (7,8), (8,7)\}, \\
{\rm SWAP}_\mathfrak{ll} (\ket{\tilde \psi_i} \otimes \ket{\tilde \psi_j}) =& \ket{\tilde \psi_j} \otimes \ket{\tilde \psi_i}
 \text{ if } (i,j) \in \{(5,7), (7,5), (6,8), (8,6)\}, \\
{\rm SWAP}_\mathfrak{ll} (\ket{\tilde \psi_5} \otimes \ket{\tilde \psi_8}) =& \ket{\tilde \psi_7} \otimes \ket{\tilde \psi_6}, \\
{\rm SWAP}_\mathfrak{ll} (\ket{\tilde \psi_8} \otimes \ket{\tilde \psi_5}) =& \ket{\tilde \psi_6} \otimes \ket{\tilde \psi_7}, \\
{\rm SWAP}_\mathfrak{ll} (\ket{\tilde \psi_6} \otimes \ket{\tilde \psi_7}) =& \ket{\tilde \psi_8} \otimes \ket{\tilde \psi_5}, \\
{\rm SWAP}_\mathfrak{ll} (\ket{\tilde \psi_7} \otimes \ket{\tilde \psi_6}) =& \ket{\tilde \psi_5} \otimes \ket{\tilde \psi_8}. \\
\end{split}
\end{equation*}

Then, we use these results to find the intersection of $\mathcal{K}_1$ and $\mathcal{K}_2$,

\begin{equation*}
\begin{split}
\mathcal{K}_1 \cap \mathcal{K}_2 =& \{(i,i,i,i), 5 \leq i \leq 8\} \cup \\
& \{(i,i,j,j), (i,j) \in (i,j) \in \{(5,6), (6,5), (7,8), (8,7)\}\} \cup \\
& \{(i,j,j,i), (i,j) \in (i,j) \in \{(5,7), (7,5), (6,8), (8,6)\}\} \cup \\
& \{(5,7,8,6), (8,6,5,7), (6,8,7,5), (7,5,6,8)\}.
\end{split}
\end{equation*}

These are the indices of the terms that do not vanish as $\kappa$ is increased.
The only remaining step is to verify if these indices correspond to constant or oscillatory terms.
Clearly, $\lambda_{iiii} = \lambda_{iijj} = \lambda_{ijji} = 0$ for any quantum system. Therefore, we only to check the value
of $\lambda_{abij}$ for $(a,b,i,j) \in \{(5,7,8,6), (8,6,5,7), (6,8,7,5), (7,5,6,8)\}$.
%
\begin{equation*}
\begin{split}
\lambda_{5,7,8,6} =& -1 + \frac{1}{2 \sqrt{2}} \sqrt{1 + 4 \kappa + 8 \kappa^2} -
\frac{1}{2 \sqrt{2}} \sqrt{5 + 12 \kappa + 8 \kappa^2} + \\
&1 + \frac{1}{2 \sqrt{2}} \sqrt{5 + 12 \kappa + 8 \kappa^2} -
\frac{1}{2 \sqrt{2}} \sqrt{1 + 4 \kappa + 8 \kappa^2} = 0, \\
\lambda_{8,6,5,7} =& - \lambda_{6,8,7,5} = \lambda_{7,5,6,8} = - \lambda_{5,7,8,6} = 0.
\end{split}
\end{equation*}

Therefore,
%
\begin{equation*}
\mathcal{C}_1 \cap \mathcal{K}_1 \cap \mathcal{K}_2 = \varnothing,
\end{equation*}
%
implying that the purity $\gamma_\mathfrak{l}$ can be kept eternally bounded, arbitrarily close to $1$,
with the application of strong Hamiltonian driving on the quantum wall.

Alternatively, we could have applied the results of Corollary \ref{thm:boundcond_noent},
since the asymptotic eigenvectors $\ket{\tilde \psi}$ are of the form $\ket{i} \ket{j} \ket{k}$, where
$\ket{i}, \ket{j}, \ket{k} \in \{\ket{0}, \ket{1}\}$. In order to do so, we need to split the index
$j \in \{5, 6, 7, 8\}$ of $\lambda_j$ into $[j_\mathfrak{l}, \hat w, j_\mathfrak{e}]$, i.e. in
order to apply the results of Corollary \ref{thm:boundcond_noent}, we relabel the eigenvalues
according to the last column of Table \ref{tab:eternbound}, such that
%
\begin{equation*}
\lambda_{[0,0,0]} = \lambda_8, \quad
\lambda_{[0,0,1]} = \lambda_7, \quad
\lambda_{[1,0,0]} = \lambda_6, \quad
\lambda_{[1,0,1]} = \lambda_5.
\end{equation*}
Then, it suffices to show that $\lambda_{[0,0,0]} - \lambda_{[1,0,0]} = \lambda_{[0,0,1]} - \lambda_{[1,0,1]}$
in order to prove that $\mathcal{C}_1 \cap \mathcal{K}_1 \cap \mathcal{K}_2 = \varnothing$.

