\section{Riemannian optimization: Gradient descent on manifolds}
\label{sec:riemannianopt}

In this work we have proposed three optimization problems: \eqref{eq:optprob_sub},
\eqref{eq:optprob_state_full} and \eqref{eq:optprob_state}. The first has an optimization
variable that is constrained to belong to ${\rm SU}(n)$,  whereas the latter two
are constrained to $S^{n_w-1}(\mathbb{C})$. Both ${\rm SU}(n)$ and $S^{n_w-1}(\mathbb{C})$ are
smooth manifolds, and in the following we shall denote such a set as $\mathcal{M}$. By equipping them with a Riemannian metric $g_U(X, Y)$, we may
then define the gradient of a functional $J(U): \mathcal{M} \to \mathbb{R}$ as the unique
vector ${\rm grad} J(U) \in T_U \mathcal{M}$ that satisfies
${\rm D} J(U) [\xi] = g_U({\rm grad} J(U), \xi), \forall \xi \in T_U \mathcal{M}$, where ${\rm D} J(U) [\xi]$
is the directional derivative of $J(U)$ along $\xi$ \cite{satoRiemannianOptimizationIts2021}.

To solve an optimization problem $\min_U J(U)$, one could consider the gradient flow
\begin{equation}
\label{eq:gradflow}
\dot U = -{\rm grad} J(U).
\end{equation}
It is easy to see that this flow follows the direction of steepest descent of the functional $J(U)$ and that it
converges to its local minima. The idea behind the gradient descent algorithm is to approximate this flow by discretizing it.
At each point $U$ there is an exponential map ${\rm exp}_U(-{\rm grad}J(U) \epsilon)$ solving the gradient flow \eqref{eq:gradflow},
where ${\rm exp}_U: T_U \mathcal{M} \to \mathcal{M}$ and $\epsilon > 0$ is the step size of the discretization.

In the case of $\mathcal{M} = {\rm SU}(n)$ and $g_U(A,B) = \tr(A^\dagger B)$, we have that
\begin{equation}
{\rm exp}_U(X) = e^{X U^\dagger} U.
\end{equation}
Then, by taking $X = -{\rm grad J(U)} \epsilon$, we recover the expression given in \eqref{eq:expmap_SUn}.

As for $\mathcal{M} = S^{n_w-1}(\mathbb{C})$ and $g_U(a, b) = a^\dagger (\one - \frac{1}{2} U U^\dagger) b$,
we have that
\begin{equation}
{\rm exp}_U(X) = e^{Q X U^\dagger - U X^\dagger Q} U,
\end{equation}
where $Q = \one - \frac{1}{2} U U^\dagger$. Then, by taking $X = -{\rm grad} J(U) \epsilon$, we recover \eqref{eq:expmap_sph}.

The gradient descent algorithm in its simplest form is given by Algorithm \ref{alg:graddesc}. This algorithm is guaranteed
to converge if the step size $\epsilon$ is chosen small enough. A simple addition that can be made to speed up convergence
and to guarantee the monotonic decrease of the cost functional $J(U)$ at each iteration of the while loop is to use
the backtracking algorithm with Armijo-Wolfe conditions to update the step size at each iteration, instead of using
a fixed one. The explanation of these various techniques is beyond the scope of this paper, but further information
can be found in \cite{satoRiemannianOptimizationIts2021}.

\begin{algorithm}
    \caption{Gradient descent}
    \label{alg:graddesc}
    \begin{algorithmic}[1]
        \REQUIRE $U_0 \in \mathcal{M}$
        \ENSURE $U_f \in \mathcal{M}$

        \STATE $k \gets 0$
        \STATE $U_k \gets U_0$

        \WHILE{ $g_{U_k}({\rm grad} J(U_k), {\rm grad} J(U_k)) > g_{\rm min}$ }
            \STATE $U_{k+1} \gets {\rm exp}_{U_k}(- {\rm grad} J(U_k) \epsilon)$
            \STATE $k \gets k + 1$
        \ENDWHILE

        \STATE $U_f \gets U_k$
    \end{algorithmic}
\end{algorithm}




\section{Proof of Proposition \ref{thm:avg_2nd_deriv}}
\label{sec:avg_2nd_deriv}

We start this section by proving the following lemma on the properties of the uniform distribution of density matrices $\rho$ on the set
of pure states $\mathrm{extr}(\mathfrak{D}(\mathcal{H}_\mathfrak{u}))$.

\begin{lemma}
\label{thm:averages}
Let $\rho_{jk} = \bra{j} \rho \ket{k}$ be the entries of a pure density matrix $\rho \in \mathrm{extr}(\mathfrak{D}(\mathcal{H}_\mathfrak{u}))$, then
%
\begin{enumerate}
\item $\langle \rho_{jk} \rangle_\mathfrak{u} = \frac{1}{n_\mathfrak{u}} \delta_{jk}$.
\item $\langle \rho_{jk} \rho_{cb} \rangle_\mathfrak{u} = \frac{1}{n_\mathfrak{u} (n_\mathfrak{u}+1)} (\delta_{jk} \delta_{bc} + \delta_{jb} \delta_{kc})$
\end{enumerate}
%
Where the average is taken over $\rho$ uniformly distributed on the set of pure states $\mathrm{extr}(\mathfrak{D}(\mathcal{H}_\mathfrak{u}))$.
\end{lemma}
\begin{proof}
Let $\rho = \ketbra{\psi}{\psi}$ with $\ket{\psi} = \sum_{i = 0}^{n_\mathfrak{u} - 1} \alpha_i e^{\iu \phi_i} \ket{i}$,
where $\alpha_i \in [0, 1]$, $\phi_i \in [0, 2\pi)$ and $\sum_i \alpha_i^2 = 1$.
Then, let $\ket{\psi}$ be uniformly distributed on the unit complex-valued $(n_\mathfrak{u}-1)$-sphere. That implies that the
vector collecting square of the amplitudes $[\alpha_i^2]_{i=0}^{n_\mathfrak{u}-1}$ is given by the
uniform Dirichlet distribution $\mathrm{Dir}(1/2)$
\cite{guardiolaSphericalDirichletDistribution2020, lanFlexibleBayesianDynamic2020a},
whereas the complex phases $e^{\iu \phi_i}$ are independent from each other and
from the amplitudes, and (identically) uniformly distributed along the unit circle on the complex plane $\mathbb{C}$.

As a consequence of these facts, we know that
\begin{itemize}
\item $\langle \alpha_i^2 \rangle = \frac{1}{n_\mathfrak{u}}$, which is the first moment of $\mathrm{Dir}(1/2)$.
\item $\langle \alpha_i^4 \rangle = \frac{2}{n_\mathfrak{u} (n_\mathfrak{u} + 1)}$, which is the second moment of $\mathrm{Dir}(1/2)$.
\item $\langle e^{\iu \phi_i} \rangle = 0$, which is the center of the unit circle on $\mathbb{C}$.
\item $\langle e^{\iu (\phi_i - \phi_j)} \rangle = \delta_{ij}$, which comes from the independence between $e^{\iu \phi_i}$ and $e^{-\iu \phi_j}$.
\item $\langle \alpha_j \alpha_k \alpha_b \alpha_c e^{\iu (\phi_j - \phi_k - \phi_b + \phi_c)} \rangle = \langle \alpha_j \alpha_k \alpha_b \alpha_c \rangle (\delta_{jk} \delta_{bc} + \delta_{jb} \delta_{kc} - \delta_{jk} \delta_{bc} \delta_{jb} \delta_{kc})$, which comes from the previous point and the independence between amplitudes and phases.
\end{itemize}

Equipped with the previous points, we can know compute our quantities of interest $\langle \rho_{ij} \rangle_\mathfrak{u}$ and
$\langle \rho_{jk} \rho_{cb} \rangle_\mathfrak{u}$. By denoting $\rho_{ij} = \alpha_i \alpha_j e^{\iu (\phi_i - \phi_j)}$, we have that
%
\begin{equation}
\langle \rho_{ij} \rangle = \langle \alpha_i \alpha_j e^{\iu (\phi_i - \phi_j)} \rangle
= \langle \alpha_i \alpha_j \rangle \delta_{ij}
= \langle \alpha_i^2 \rangle \delta_{ij}
= \frac{1}{n_\mathfrak{u}} \delta_{ij}.
\end{equation}

In order to compute the second quantity of interest, we need to compute $\langle \alpha_i^2 \alpha_j^2\rangle$ for $i \neq j$ first.
This is done by taking advantage of the normalization of the amplitudes,
%
\begin{equation}
\begin{split}
\langle \alpha_i^4 \rangle =& \langle \alpha_i^2 (1 - \sum_{j \neq i} \alpha_j^2) \rangle \\
=& \langle \alpha_i^2 \rangle - (n_\mathfrak{u} - 1) \langle \alpha_i^2 \alpha_j^2\rangle \\
=& \frac{1}{n_\mathfrak{u}} - (n_\mathfrak{u} - 1) \langle \alpha_i^2 \alpha_j^2\rangle = \frac{2}{n_\mathfrak{u} (n_\mathfrak{u} + 1)}.
\end{split}
\end{equation}
%
Then, we have that
%
\begin{equation}
\langle \alpha_i^2 \alpha_j^2 \rangle = \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)}, \ i \neq j.
\end{equation}

Finally, we are able to compute the second quantity
%
\begin{equation}
\begin{split}
\langle \rho_{jk} \rho_{cb} \rangle =&
\langle \alpha_j \alpha_k \alpha_b \alpha_c e^{\iu \phi_j - \iu \phi_k - \iu \phi_b + \iu \phi_c} \rangle \\
=& \langle \alpha_j \alpha_k \alpha_b \alpha_c \rangle (\delta_{jk} \delta_{bc} + \delta_{jb} \delta_{kc} - \delta_{jk} \delta_{bc} \delta_{jb} \delta_{kc}) \\
=& \langle \alpha_j^2 \alpha_c^2 \rangle (\delta_{jk} \delta_{bc} + \delta_{jb} \delta_{kc}) (1 - \delta_{jc}) + \langle \alpha_j^4 \rangle \delta_{jk} \delta_{bc} \delta_{jb} \delta_{kc} \\
=& \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} (\delta_{jk} \delta_{bc} + \delta_{jb} \delta_{kc}) (1 - \delta_{jc}) + \frac{2}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} \delta_{jk} \delta_{bc} \delta_{jb} \delta_{kc} \\
=& \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} (\delta_{jk} \delta_{bc} + \delta_{jb} \delta_{kc}).
\end{split}
\end{equation}
\end{proof}

These results can now be used to compute the values of $\langle \tr(\sigma_i \sigma_a \rho) \rangle$ and
$\langle \tr(\sigma_i \rho \sigma_a \rho) \rangle$, which will be necessary to prove Proposition \ref{thm:avg_2nd_deriv}.
The computation is given in the following lemma.

\begin{lemma}
\label{thm:integral}
Let
$\{\sigma_i\}_{i=0}^{n_\mathfrak{u}^2-1} = \{\frac{1}{\sqrt{n_\mathfrak{u}}} \one\} \cup \{\lambda^s_{jk}\}_{0 \leq k < j \leq n_\mathfrak{u}-1} \cup \{\lambda^a_{jk}\}_{0 \leq j < k \leq {n_\mathfrak{u}}-1} \cup \{\lambda^d_k\}_{1 \leq k \leq n_\mathfrak{u}-1}$,
where $\lambda^s_{jk}$, $\lambda^a_{jk}$ and  $\lambda^d_{jk}$ are the symmetric,
antisymmetric and diagonal generalized $n_\mathfrak{u} \times n_\mathfrak{u}$ Gell-Mann matrices \cite{bertlmannBlochVectorsQudits2008} (normalized to $1$), respectively, i.e.
%
\begin{equation}
\begin{split}
\lambda^s_{jk} =& \frac{1}{\sqrt{2}} (\ketbra{j}{k} + \ketbra{k}{j}) \\
\lambda^a_{jk} =& \frac{1}{\sqrt{2}} (\iu \ketbra{j}{k} - \iu \ketbra{k}{j}) \\
\lambda^d_{k} =& \frac{1}{\sqrt{k (k+1)}} (\sum_{j=0}^{k-1} \ketbra{j}{j} - k \ketbra{k}{k}).
\end{split}
\end{equation}
%
Let in particular $\sigma_0 = \frac{1}{\sqrt{n_\mathfrak{u}}} \one$. Then for $i,j > 0$,
\begin{enumerate}
\item $\langle \tr(\sigma_i \sigma_a \rho) \rangle = \frac{1}{n_\mathfrak{u}} \delta_{ia}$ and
\item $\langle \tr(\sigma_i \rho \sigma_a \rho) \rangle = \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} \delta_{ia}$,
\end{enumerate}
where the average is taken over all pure states $\rho \in \mathrm{extr}(\mathfrak{D}(\mathcal{H}_\mathfrak{u}))$.
\end{lemma}
\begin{proof}
The first point is obtained as a direct application of Lemma \ref{thm:averages} and of the orthonormality of $\{\sigma_i\}_i$,
%
\begin{equation}
\langle \tr(\sigma_i \sigma_a \rho) \rangle = \tr(\sigma_i \sigma_a \langle \rho \rangle) = \frac{1}{n_\mathfrak{u}} \tr(\sigma_i \sigma_a \one) = \frac{1}{n_\mathfrak{u}} \delta_{ia}.
\end{equation}

The second point is proven by cases. First, let
$\sigma_i = \lambda^s_{jk}$ and $\sigma_a = \lambda^s_{bc}$, i.e. $j > k$ and $b > c$, then
%
\begin{equation}
\begin{split}
\langle \tr(\lambda^s_{jk} \rho \lambda^s_{bc} \rho) \rangle =&
\frac{1}{2} \langle \tr((\ketbra{j}{k} + \ketbra{k}{j}) \rho (\ketbra{b}{c} + \ketbra{c}{b}) \rho) \rangle \\
=& \frac{1}{2} (\langle \rho_{kb} \rho_{cj} \rangle + \langle \rho_{jb} \rho_{ck} \rangle + \langle \rho_{kc} \rho_{bj} \rangle + \langle \rho_{jc} \rho_{bk} \rangle).
\end{split}
\end{equation}
%
By applying Lemma \ref{thm:averages}, we know that the first and last terms of this sum are zero, since we have that $k \neq j$ and $c \neq b$, whereas the middle two are equal, resulting in
%
\begin{equation}
\langle \tr(\lambda^s_{jk} \rho \lambda^s_{bc} \rho) \rangle = \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} \delta_{jb} \delta_{kc}.
\end{equation}

If $\sigma_i = \lambda^a_{jk}$ and $\sigma_a = \lambda^a_{bc}$, i.e. $j < k$ and $b < c$, then
%
\begin{equation}
\begin{split}
\langle \tr(\lambda^a_{jk} \rho \lambda^a_{bc} \rho) \rangle =&
\frac{1}{2} \langle \tr((\iu \ketbra{j}{k} - \iu \ketbra{k}{j}) \rho (\iu \ketbra{b}{c} - \iu \ketbra{c}{b}) \rho) \rangle \\
=& \frac{1}{2} (- \langle \rho_{kb} \rho_{cj} \rangle + \langle \rho_{jb} \rho_{ck} \rangle + \langle \rho_{kc} \rho_{bj} \rangle - \langle \rho_{jc} \rho_{bk} \rangle).
\end{split}
\end{equation}
%
The same argument as in the previous case applies here, resulting in
%
\begin{equation}
\langle \tr(\lambda^a_{jk} \rho \lambda^a_{bc} \rho) \rangle = \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} \delta_{jb} \delta_{kc}.
\end{equation}

If $\sigma_i = \lambda^d_{k}$ and $\sigma_a = \lambda^d_{c}$, then
%
\begin{equation}
\begin{split}
\langle \tr(\lambda^d_{k} \rho \lambda^d_{c} \rho) \rangle
=& \frac{1}{\sqrt{k (k+1)}} \frac{1}{\sqrt{c (c+1)}} \\
& \langle \tr((\sum_{j=0}^{k-1} \ketbra{j}{j} - k \ketbra{k}{k}) \rho (\sum_{b=0}^{c-1} \ketbra{b}{b} - c \ketbra{c}{c}) \rho) \rangle \\
=& \frac{1}{\sqrt{k (k+1)}} \frac{1}{\sqrt{c (c+1)}} \\
& (\sum_{j=0}^{k-1} \sum_{b=0}^{c-1} \langle \rho_{jb} \rho_{bj} \rangle
- k \sum_{b=0}^{c-1} \langle \rho_{kb} \rho_{bk} \rangle
- c \sum_{j=0}^{k-1} \langle \rho_{jc} \rho_{cj} \rangle
+ k c \langle \rho_{kc} \rho_{ck} \rangle) \\
=& \frac{1}{\sqrt{k (k+1)}} \frac{1}{\sqrt{c (c+1)}} \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} \\
& (\sum_{j=0}^{k-1} \sum_{b=0}^{c-1} \delta_{jb} - k \sum_{b=0}^{c-1} \delta_{kb} - c \sum_{j=0}^{k-1} \delta_{jc} + k c \delta_{kc}).
\end{split}
\end{equation}

The first term of the sum is equal to $\min\{k, c\}$, whereas the addition of the second and third terms is equal to $-\min\{k, c\} (1 - \delta_{kc})$.
Then, we have that
%
\begin{equation}
\begin{split}
\langle \tr(\lambda^d_{k} \rho \lambda^d_{c} \rho) \rangle
=& \frac{1}{\sqrt{k (k+1)}} \frac{1}{\sqrt{c (c+1)}} \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} \\
& (\min\{k, c\} - \min\{k, c\} (1 - \delta_{kc}) + k c \delta_{kc}) \\
=& \frac{1}{\sqrt{k (k+1)}} \frac{1}{\sqrt{c (c+1)}} \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} (\min\{k, c\} + k c) \delta_{kc} \\
=& \frac{1}{k (k+1)} \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} (k + k^2) \delta_{kc} \\
=& \frac{1}{n_\mathfrak{u} (n_\mathfrak{u} + 1)} \delta_{kc}
\end{split}
\end{equation}

Now we have to prove that whenever $\sigma_i$ and $\sigma_a$ are of different kinds, e.g. one is $\sigma_i$ symmetric
and $\sigma_a$ is diagonal, the average $\langle \tr(\sigma_i \rho \sigma_a \rho) \rangle$ is zero.
If $\sigma_i = \lambda^s_{jk}$ and $\sigma_a = \lambda^a_{bc}$, i.e. $j > k$ and $b < c$, we have that
%
\begin{equation}
\begin{split}
\langle \tr(\lambda^s_{jk} \rho \lambda^a_{bc} \rho) \rangle =& \frac{1}{2} \langle \tr((\ketbra{j}{k} + \ketbra{k}{j}) \rho (\iu \ketbra{b}{c} - \iu \ketbra{c}{b}) \rho) \rangle \\
=& \frac{1}{2} (\iu \langle \rho_{kb} \rho_{cj} \rangle + \iu \langle \rho_{jb} \rho_{ck} \rangle - \iu \langle \rho_{kc} \rho_{bj} \rangle - \iu \langle \rho_{jc} \rho_{bk} \rangle).
\end{split}
\end{equation}

From the first case, we know that the first and last terms are zero, whereas the two in the middle were equal. However, now they appear
with opposite signs, making the entire expression equal to zero. Therefore,
%
\begin{equation}
\langle \tr(\lambda^s_{jk} \rho \lambda^a_{bc} \rho) \rangle = 0.
\end{equation}

If $\sigma_i = \lambda^s_{jk}$ and $\sigma_a = \lambda^d_c$, i.e. $j > k$, we have that
%
\begin{equation}
\begin{split}
\langle \tr(\lambda^s_{jk} \rho \lambda^d_c \rho) \rangle =& \frac{1}{\sqrt{2 c (c+1)}} \langle \tr((\ketbra{j}{k} + \ketbra{k}{j}) \rho (\sum_{b=0}^{c-1} \ketbra{b}{b} - c \ketbra{c}{c}) \rho) \rangle \\
=& \frac{1}{\sqrt{2 c (c+1)}}
(\sum_{b=0}^{c-1} \langle \rho_{kb} \rho_{bj} \rangle + \sum_{b=0}^{c-1} \langle \rho_{jb} \rho_{bk} \rangle
- c \langle \rho_{kc} \rho_{cj} \rangle - c \langle \rho_{jc} \rho_{ck} \rangle).
\end{split}
\end{equation}

Since $j \neq k$, by Lemma \ref{thm:averages} we know that all four terms inside the parenthesis in the previous expression are equal to zero.
Therefore
%
\begin{equation}
\begin{split}
\langle \tr(\lambda^s_{jk} \rho \lambda^d_{bc} \rho) \rangle =& 0.
\end{split}
\end{equation}

Finally, if $\sigma_i = \lambda^a_{jk}$ and $\sigma_a = \lambda^d_{c}$, i.e. $j < k$, we have that
%
\begin{equation}
\begin{split}
\langle \tr(\lambda^a_{jk} \rho \lambda^d_c \rho) \rangle =& \frac{1}{\sqrt{2 c (c+1)}} \langle \tr((\iu \ketbra{j}{k} - \iu \ketbra{k}{j}) \rho (\sum_{b=0}^{c-1} \ketbra{b}{b} - c \ketbra{c}{c}) \rho) \rangle \\
=& \frac{1}{\sqrt{2 c (c+1)}}
(\iu \sum_{b=0}^{c-1} \langle \rho_{kb} \rho_{bj} \rangle - \iu \sum_{b=0}^{c-1} \langle \rho_{jb} \rho_{bk} \rangle
- \iu c \langle \rho_{kc} \rho_{cj} \rangle + \iu c \langle \rho_{jc} \rho_{ck} \rangle),
\end{split}
\end{equation}
%
which is is zero by the same argument as in the previous case. All other cases are automatically verified by the cyclicity of the trace.
\end{proof}

With these results in hand, we can now proceed to prove Proposition \ref{thm:avg_2nd_deriv}.

\begin{proposition*}
Given a tripartite system with Hilbert space $\cal H = H_\mathfrak{l} \otimes H_\mathfrak{w} \otimes H_\mathfrak{e}$
and factorized initial state $\rho_0 = \rho_\mathfrak{l} \otimes \rho_\mathfrak{w} \otimes \rho_\mathfrak{e}$,
which follows Lindbladian dynamics with arbitrary Hamiltonian and noise operators $L_m = \one_\mathfrak{l} \otimes \one_\mathfrak{w} \otimes L^\mathfrak{e}_m$,
the second derivative of the purity $\gamma_\mathfrak{l}(\rho)$ has the following average initial value over all the reduced states $\rho_\mathfrak{l}$,
%
\begin{equation}
\langle \ddot\gamma_\mathfrak{l}(\rho)|_{t=0} \rangle_\mathfrak{l} =
4 \nu_n \sum_{\substack{i > 0 \\ bcjk \geq 0}} g_{ibc} g_{ijk}
(\tau_{c0} \tau_{0k} \tr(\sigma_b^\mathfrak{w} \rho_\mathfrak{w}) \tr(\sigma_j^\mathfrak{w} \rho_\mathfrak{w})
- \tau_{ck} \tr(\sigma_b^\mathfrak{w} \sigma_j^\mathfrak{w} \rho_\mathfrak{w})),
\end{equation}
%
where $\nu_n = \frac{1}{n_\mathfrak{l}} - \frac{1}{n_\mathfrak{l} (n_\mathfrak{l} + 1)}$ and
$\tau_{ck} = \tr(\sigma^\mathfrak{e}_c \sigma^\mathfrak{e}_k \rho_\mathfrak{e})$.
\end{proposition*}
\begin{proof}
If $\rho_0 = \rho_\mathfrak{l} \otimes \rho_\mathfrak{w} \otimes \rho_\mathfrak{e}$, we have that
%
\begin{equation}
\begin{split}
\tr(\tr_\mathfrak{we}([\sigma_{abc}, [\sigma_{ijk}, \rho_0]]) \rho_\mathfrak{l}) =&
\tr(\sigma_b^\mathfrak{w} \sigma_j^\mathfrak{w} \rho_\mathfrak{w}) \tr(\sigma_c^\mathfrak{e} \sigma_k^\mathfrak{e} \rho_\mathfrak{e})
\tr(\sigma_a^\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l}^2 - \sigma_a^\mathfrak{l} \rho_\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l}) + \\
& \tr(\sigma_j^\mathfrak{w} \sigma_b^\mathfrak{w} \rho_\mathfrak{w}) \tr(\sigma_k^\mathfrak{e} \sigma_c^\mathfrak{e} \rho_\mathfrak{e})
\tr(\sigma_i^\mathfrak{l} \sigma_a^\mathfrak{l} \rho_\mathfrak{l}^2 - \sigma_i^\mathfrak{l} \rho_\mathfrak{l} \sigma_a^\mathfrak{l} \rho_\mathfrak{l}),
\end{split}
\end{equation}
%
and that
%
\begin{equation}
\begin{split}
\tr(\tr_\mathfrak{we}([\sigma_{abc}, \rho_0]) \tr_\mathfrak{we}([\sigma_{ijk}, \rho_0])) =&
\tr(\sigma_b^\mathfrak{w} \rho_\mathfrak{w}) \tr(\sigma_j^\mathfrak{w} \rho_\mathfrak{w})
\tr(\sigma_c^\mathfrak{e} \rho_\mathfrak{e}) \tr(\sigma_k^\mathfrak{e} \rho_\mathfrak{e}) \\
&\qquad \tr(2 \sigma_a^\mathfrak{l} \rho_\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l} - \sigma_a^\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l}^2 - \sigma_i^\mathfrak{l} \sigma_a^\mathfrak{l} \rho_\mathfrak{l}^2).
\end{split}
\end{equation}
%
Furthermore, if we also have
$L_m = \one_\mathfrak{l} \otimes \one_\mathfrak{w} \otimes L_m^\mathfrak{e}$,
then
%
\begin{equation}
\tr_\mathfrak{we}({\cal D}_{L_n} \circ {\cal D}_{L_m}(\rho)) = 0,
\end{equation}
%
\begin{equation}
\tr_\mathfrak{we}({\cal D}_{L_m}([\sigma_{ijk}, \rho])) = 0,
\end{equation}
%
and
%
\begin{equation}
\tr(\tr_\mathfrak{we}([\sigma_{ijk}, {\cal D}_{L_m}(\rho)])) = 0.
\end{equation}

Notice that the dissipative terms on the environment have no effect on the second derivative
of the purity $\gamma_\mathfrak{l}$. Using the previous expressions we may write the initial
purity loss acceleration as
%
\begin{equation}
\label{eq:2nd_deriv}
\begin{split}
\ddot\gamma_\mathfrak{l}(\rho)|_{t=0} =&
4 \sum_{\substack{ai > 0 \\ bcjk \geq 0}} g_{abc} g_{ijk} \tr(\sigma_a^\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l}^2 - \sigma_a^\mathfrak{l} \rho_\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l}) \\
&\qquad (\tr(\sigma_b^\mathfrak{w} \rho_\mathfrak{w}) \tr(\sigma_j^\mathfrak{w} \rho_\mathfrak{w})
\tr(\sigma_c^\mathfrak{e} \rho_\mathfrak{e}) \tr(\sigma_k^\mathfrak{e} \rho_\mathfrak{e})
- \tr(\sigma_b^\mathfrak{w} \sigma_j^\mathfrak{w} \rho_\mathfrak{w}) \tr(\sigma_c^\mathfrak{e} \sigma_k^\mathfrak{e} \rho_\mathfrak{e})).
\end{split}
\end{equation}

Notice that the terms with $a = 0$ or $i = 0$ do not contribute to this sum,
since the trace $
\tr(\sigma_a^\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l}^2 - \sigma_a^\mathfrak{l} \rho_\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l})
$ is zero in such cases, i.e.
the local Hamiltonians $H_\mathfrak{w}$, $H_\mathfrak{e}$ and the
interaction Hamiltonian $H_\mathfrak{we}$ do not contribute to the initial
purity loss acceleration.
Therefore we can remove them from the sum, as done above.
This is also the
case when either $b = 0$ or $j = 0$, and at the same time either $c = 0$ or $k = 0$, i.e. when $b = c = 0$, $b = k = 0$, $j = c = 0$ or $j = k = 0$.
In order to find a function that depends only on $\rho_\mathfrak{w}$, we may consider the initial
state of the environment as part of the model of the system, i.e. we may fix an initial state
$\rho_\mathfrak{e}$ which is assumed to be known. Then, we may average the purity loss
acceleration over all the initial pure states of the information subsystem, i.e. we compute
%
\begin{equation}
\langle \ddot \gamma_\mathfrak{l}(\rho)|_{t=0} \rangle_\mathfrak{l} =
\frac{1}{\nu_\mathfrak{l}} \int_{{\rm extr} ({\cal D}({\cal H}_\mathfrak{l}))} \ddot \gamma_\mathfrak{l}(\rho)|_{t=0} d\rho_\mathfrak{l},
\end{equation}
%
where $\nu_\mathfrak{l} = \int_{{\rm extr}({\cal D}({\cal H}_\mathfrak{l}))} d\rho_\mathfrak{l}$.

\noindent The computation of the average consists in solving integrals of the following kind:
%
\begin{equation}
I_{a,i} = \int_{{\rm extr} ({\cal D}({\cal H}_\mathfrak{l}))}
\tr(\sigma_a^\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l}^2 -
\sigma_a^\mathfrak{l} \rho_\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l}) d\rho_\mathfrak{l}.
\end{equation}
%
By linearity, we can split $I_{a, i}$ into two integrals, such that
%
\begin{equation}
I_{a,i} = \nu_\mathfrak{l} (\langle \sigma_a^\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l} \rangle -
\langle \sigma_a^\mathfrak{l} \rho_\mathfrak{l} \sigma_i^\mathfrak{l} \rho_\mathfrak{l} \rangle),
\end{equation}
%
where we have also used the fact that for any pure state $\rho_\mathfrak{l}^2 = \rho_\mathfrak{l}$.
This integral is then solved by applying the results of the previous lemma.

Finally, let $\tau_{ck} = \tr(\sigma_c^\mathfrak{e} \sigma_k^\mathfrak{e} \rho_\mathfrak{e})$ and
$\nu_n = \frac{1}{n_\mathfrak{l}} - \frac{1}{n_\mathfrak{l} (n_\mathfrak{l} + 1)}$.
Putting all the terms together we obtain,
%
\begin{equation}
\langle \ddot\gamma_\mathfrak{l}(\rho)|_{t=0} \rangle_\mathfrak{l} =
4 \nu_n \sum_{\substack{i > 0 \\ bcjk \geq 0}} g_{ibc} g_{ijk}
(\tau_{c0} \tau_{0k} \tr(\sigma_b^\mathfrak{w} \rho_\mathfrak{w}) \tr(\sigma_j^\mathfrak{w} \rho_\mathfrak{w})
- \tau_{ck} \tr(\sigma_b^\mathfrak{w} \sigma_j^\mathfrak{w} \rho_\mathfrak{w})).
\end{equation}
\end{proof}



\section{Proof of Proposition \ref{thm:optimwall}}
\label{sec:qubitproof}

We begin by proving some useful properties of the operators $D_i$ in the special case of $n_\mathfrak{w} = 2$.
For larger wall subsystems, these properties do not apply,
but we can still use the eigenstates of $D_1$ as the initial points of the gradient descent algorithm
to solve \eqref{eq:optprob_state_full} or \eqref{eq:optprob_state}.

\begin{lemma}
\label{thm:qubitprops}
Given a set of Hermitian operators $\{D_i\}_i$ such that $\tr(D_i D_j) = \delta_{ij}$ and $\tr(D_i) = 0$,
let $\{\lambda_k^i\}_k$ and $\{\ket{\psi_k^i}\}_k$ be their eigenvalues and eigenvectors, respectively,
i.e. $D_i \ket{\psi_k^i} = \lambda_k^i \ket{\psi_k^i}$. If they act on qubits, the following properties are
satisfied:

\begin{enumerate}
\item $\lambda_1^i = - \lambda_2^i$
\item $\bra{\psi_k^i} D_j \ket{\psi_k^i} = \lambda_k^j \delta_{ij}$
\item $D_i^2 = \frac{1}{2} \one$
\item $(\lambda_k^i)^2 = \frac{1}{2}$
\end{enumerate}

\end{lemma}
\begin{proof}
Property (1) is a direct consequence of $\tr(D_i) = \lambda_1^i + \lambda_2^i = 0$.
Property (2) is also obtained by direct calculation. Assume $i \neq j$, then
%
\begin{equation*}
\begin{split}
\tr(D_i D_j) =&
\tr(D_j \lambda_1^i \ketbra{\psi_1^i}{\psi_1^i} + D_j \lambda_2^i \ketbra{\psi_2^i}{\psi_2^i}) \\
=& \lambda_1^i \bra{\psi_1^i} D_j \ket{\psi_1^i} + \lambda_2^i \bra{\psi_2^i} D_j \ket{\psi_2^i} \\
=& \lambda_1^i (\bra{\psi_1^i} D_j \ket{\psi_1^i} - \bra{\psi_2^i} D_j \ket{\psi_2^i}) = 0.
\end{split}
\end{equation*}
%
Therefore, $\bra{\psi_1^i} D_j \ket{\psi_1^i} = \bra{\psi_2^i} D_j \ket{\psi_2^i}$. But we also
have that $\tr(D_i) = \bra{\psi_1^i} D_j \ket{\psi_1^i} + \bra{\psi_2^i} D_j \ket{\psi_2^i} = 0$.
This implies that $\bra{\psi_1^i} D_j \ket{\psi_1^i} = \bra{\psi_2^i} D_j \ket{\psi_2^i} = 0$ whenever
$i \neq j$. On the other hand, if $i = j$, we have that $\bra{\psi_k^i} D_i \ket{\psi_k^i} = \lambda_k^i$.
Putting the two cases together proves property (2).

Finally, property (3) is a consequence of $D_i = D_i^\dagger$, property (1) and $\tr(D_i^2) = 1$.

\end{proof}

With these properties in hand, we have the tools necessary to prove Proposition \ref{thm:optimwall}.


\begin{proposition*}
    Given $H_\mathfrak{lw}$ in the OSD form as in (\ref{eq:osd_ham}), $n_\mathfrak{w} = 2$
    and $s_1 > s_i$ for $i > 1$, choosing $\ket{w} \in \mathrm{eigenvectors}(D_1)$
    minimizes $\Gamma_2(\ket{w})$ over $\bigcup_{i = 1}^3 \mathrm{eigenvectors}(D_i)$,
    and locally minimizes $\Gamma_2(\ket{w})$ over the set of pure states of ${\cal H}_\mathfrak{w}$
\end{proposition*}
\begin{proof}


The Riemannian gradient \eqref{eq:osd_gamma_grad} of $\Gamma_2(\ket{w})$ is equal to zero if and only if
%
\begin{equation}
\begin{split}
\sum_i s^2_i (D_i^2
- 2 \bra{w} D_i \ket{w} D_i) \ket{w} =
\sum_i s^2_i (\bra{w} D_i^2 \ket{w}
- 2 (\bra{w} D_i \ket{w})^2) \ket{w},
\end{split}
\end{equation}
%
i.e. if $\ket{w}$ is an eigenstate of $\sum_i s^2_i (D_i^2 - 2 \bra{w} D_i \ket{w} D_i)$.

Since $n_\mathfrak{w} = 2$, i.e. ${\cal H}_\mathfrak{w}$ is a qubit system, we can use the properties given in Lemma \ref{thm:qubitprops}.
By applying property 3 of lemma \ref{thm:qubitprops}, the previous expression simplifies to
%
\begin{equation}
\sum_{i=1}^3 s^2_i \bra{w} D_i \ket{w} D_i \ket{w} =
\sum_{i=1}^3 s^2_i (\bra{w} D_i \ket{w})^2 \ket{w},
\end{equation}
%
i.e. $\ket{w}$ must be an eigenstate of $\sum_i s^2_i \bra{w} D_i \ket{w} D_i$. Consider now property
2 of lemma \ref{thm:qubitprops} and $\ket{w} = \ket{\psi_k^j}$. We get that
$\sum_i s^2_i \bra{w} D_i \ket{w} D_i = s^2_j \lambda_k^j D_j$, i.e. the eigenvectors
of each of the operators $D_i$ are critical points of the function $\Gamma_2(\rho_\mathfrak{w})$ for qubit walls.

In order to test if these critical points are minima of $\Gamma_2(\rho_\mathfrak{w})$, we can
compute the Riemannian Hessian at these points and check that it is positive definite.
The Euclidean Hessian is given by
%
\begin{equation}
\begin{split}
\nabla^2 \Gamma_2(\rho_\mathfrak{w}) =& \sum_i s^2_i (4 D_i^2 - 8 \bra{w} D_i \ket{w} D_i
- 8 D_i \ketbra{w}{w} D_i).
\end{split}
\end{equation}
%
The Riemannian Hessian can be computed as
\[
{\rm Hess } \,\Gamma_2(\rho_\mathfrak{w}) [\vec{\epsilon}] =
(\one - \ketbra{w}{w}) \nabla^2 \Gamma_2(\rho_\mathfrak{w}) \vec{\epsilon} -
\vec{\epsilon} \bra{w} (\ketbra{w}{w} \nabla \Gamma_2(\rho_\mathfrak{w})),
\] where $\vec{\epsilon} \in {\cal T}_{\ket{w}} {\cal M}$, resulting in
%
\begin{equation}
\begin{split}
{\rm Hess}\, \Gamma_2(\rho_\mathfrak{w}) [\vec{\epsilon}] =&
(\one - \ketbra{w}{w}) \\
& (\sum_i s^2_i (4 D_i^2 - 8 \bra{w} D_i \ket{w} D_i
- 8 D_i \ketbra{w}{w} D_i)) \vec{\epsilon} \\
& - \sum_i s^2_i (2 \bra{w} D_i^2 \ket{w} - 4 (\bra{w} D_i \ket{w})^2) \vec{\epsilon}.
\end{split}
\end{equation}

By imposing that the wall be a qubit system and $\ket{w}$ be an eigenstate
of $D_1$, the Hessian simplifies to
%
\begin{equation}
{\rm Hess} \Gamma_2(\rho_\mathfrak{w}) [\vec{\epsilon}] = (10 s^2_1 - 3 \sum_{i=1}^3 s^2_i) \vec{\epsilon}
\geq s^2_1 \vec{\epsilon}.
\end{equation}
%
Since $s^2_1 > 0$, we have that taking $\ket{w}$ as an eigenstate of $D_1$ gives a local
minimum of $\Gamma_2(\rho_\mathfrak{w})$.

Consider now equation (\ref{eq:osd_gamma}), applying properties 2-4 of lemma \ref{thm:qubitprops} and
taking $\ket{w} = \ket{\psi_k^j}$, we get obtain
%
\begin{equation}
\Gamma_2(\ketbra{\psi_k^j}{\psi_k^j}) = 1 - \frac{s^2_j}{2},
\end{equation}
%
which is minimized over all $j$ when $j = 1$.
\end{proof}


