\section{Preliminary material}\label{sec:preli}

\begin{notation}\label{notation:initial}
    Let $R = \BC[x_1,\ldots,x_n]$ be the polynomial ring in $n$ variables with complex coefficients and let $\mathfrak{m} = (x_1,\ldots,x_n)$ be the maximal ideal. Note that we omit the dependence on $n$ as we will take care to not create confusion later in the paper. We endow the polynomial ring $R $ with the standard grading, i.e.~$\deg(x_i)=1$, for $i=1,\ldots,n$. The $k$-th graded piece of $R$ will be denoted $R_k$. 
Similarly, given a  homogeneous ideal $I\subset R$, we denote by $I_k$ and $(R/I)_k$ the $k$-th graded piece of the ideal and the quotient respectively. Finally, we denote by $\rrr_{k}$ the dimension of the vector space $R_k$, i.e.
\[
\rrr_{k}=\dim_{\BC} R_k=\binom{k+n-1}{n-1}.
\]

Whenever not specified, a $\BC$-algebra $A$ will always be of finite type and an $A$-module $M$ will always be finitely generated.
\end{notation}
\subsection{The Hilbert function and the Betti table}\label{subsec:HSfun} In this subsection, we recall some basic invariants attached to a graded $R$-module of finite type.


\begin{definition}
Let $A=\bigoplus_{k\in\BZ} A_k$ be a graded $\BC$-algebra and let $M=\bigoplus_{t\in\BZ} M_t$ be a graded $A$-module. The \emph{Hilbert function} $\bh_M$ associated to $M$ is the function
\[
\begin{array}{rrcl}
\bh_M: & \mathbb{Z} & \to & \mathbb{N} \\ & t & \mapsto & \dim_{\BC} M_t.
\end{array}
\]
 Let $(A,\Fm_A)$ be a local Artinian $\BC$-algebra. The \emph{Hilbert function} $\bh_A$ of $A$ is defined to be the Hilbert function of its associated graded algebra  
\begin{equation}\label{eqn:grading-A-module}
\mathsf{gr}_{\Fm_A}(A) =\bigoplus_{t\geq 0}\, \mathfrak m_A^{t}/\mathfrak m_A^{t+1},
\end{equation}
where $\mathsf{gr}_{\Fm_A}(A)$ is seen as a graded module over itself.  
\end{definition}


Since some notational ambiguity is sometimes present in the literature, we recall now the definition of initial ideal.
\begin{definition}\label{def:initialideal}
    Consider  an element $f\in R$ and write it as a sum of homogeneous pieces $f=f_m+f_{m+1}+\cdots+f_{\deg(f)}$, where $f_i\in R_i$ and $f_m\not=0$. Then, the initial form of $f$ is the homogeneous polynomial $\In f= f_{m}$. Moreover, if $I\subset R $ is any ideal, its initial ideal is $
    \In I =\left(\Set{ \In f | f\in I}\right)$.
\end{definition}

\begin{remark}\label{rmk:gradini}
    When the   $\BC$-algebra $(R/I,\Fm/I)$ is local, there is an isomorphism of graded algebras
    $\mathsf{gr}_{\Fm_A}(A) \cong R/(\In I)$,
     see \cite[\S 5.4]{EISENBUD}.
\end{remark}

\begin{notation}\label{notation:HStutti}
Whenever no confusion is possible, given a homogeneous ideal $I\subset R$, we will write $\oh_{k}$ for the value of the Hilbert function $\bh_I(k)$ of the ideal $I$ and $\uh_{k}$ for the value of the Hilbert function $\bh_{R/I}(k)$ of the quotient $R/I$. To have a compact notation, sometimes we encode the Hilbert function of a graded module $M$ in the so-called Hilbert series $\bH_M(T)=\sum_{t\in \BZ}\bh_M(t)T^t$.
\end{notation}

We recall now the definition and the main properties of the graded Betti numbers, see \cite{SYZYGIES} for more details.  Recall that any finitely generated graded $R$-module $M$ admits a minimal graded free resolution, i.e.~an exact sequence  $\begin{tikzcd}
0& M \arrow[l]&  F_\bullet \arrow[l],    
\end{tikzcd}$
where
\[
\begin{tikzcd}
F_\bullet:&\cdots& F_{i-1} \arrow[l]&  F_{i}\arrow[l,"{\delta_i}"']&\cdots\arrow[l],    
\end{tikzcd}
\]
and each $F_i$ can be written as 
\begin{equation}\label{eq:bettinumber}
    F_i=\bigoplus_j R(-j)^{\oplus\beta_{i,j}(M)},
\end{equation}
and such that $\delta _i(F_i)\subset \Fm F_{i-1}$. Moreover, a resolution with these properties is unique up to canonical, \cite[Section 20.1]{EISENBUD}.
\begin{definition}\label{def:regularity}
The natural numbers $\beta_{i,j}(M)$ in \eqref{eq:bettinumber} are the graded Betti numbers of the module $M$. Usually, they are arranged in the so-called Betti table (see \Cref{fig:bettitable}). The regularity $\reg(I)$ of a homogeneous ideal $I\subset R$ is the integer $\reg(I) = \max\{ j-i\ \vert\ \beta_{ij}(I) \neq 0 \}$. For the sake of brevity, we will omit the dependence on $I$ in the notation of the graded Betti numbers taking care not to cause any possible confusion. Moreover, for a non-homogeneous ideal $I\subset R$, the integer $\beta_{i,j}(I)$ is defined to be the $(i,j)$-th graded Betti number of its initial ideal $\In I$.
\begin{figure}[ht]
    \centering
        \begin{tabular}{c|ccccc}
             &0&  $\cdots$ &$i$ &$\cdots$ & $n$\\ 
             \hline
             $\vdots$&  $\ddots$ &$\cdots$   &$\vdots$ &$\cdots$&$\cdots$\\
             $j$&  $\cdots$   &$\cdots$   &$\beta_{i,i+j}$ &$\cdots$&$\cdots$\\
             $\vdots$&  $\vdots$  &$\cdots$   &$\vdots$ &$\cdots$ &$\ddots$
        \end{tabular}
    \caption{The Betti table}
    \label{fig:bettitable}
\end{figure}
\end{definition}
By convention, all the non-displayed  entries correspond to zero Betti numbers.
The choice of indices in the Betti table and the number of displayed columns are motivated by the following propositions that we shall use implicitly later in the paper.
\begin{prop}[{\cite[Proposition 1.9]{SYZYGIES}}]\label{thmhilbertsyz} Let ${\beta_{i,j}}$, for $i,j\in\BZ$, be the graded Betti numbers of a graded $R$-module. If for a given $i$ there is an integer $d$ such that $\beta_{i,j} = 0$ for all $j < d$, then $\beta_{i+1,j+1} = 0$ for all $j < d$. 
\end{prop}
\begin{prop}[{\cite[Hilbert syzygy theorem]{AproduNagel}}]  
  Any graded finitely generated $\mathbb{C}[x_1,  \ldots,x_n]$-module $M$ has a graded free resolution of length at most $n$.
\end{prop}


\subsection{The nested Hilbert scheme of points and its tangent space}\label{subsec:prlinested}
In this subsection, we recall some well-known facts about classical and nested Hilbert schemes of points and we settle the notation. Although the nested Hilbert scheme is  considered a generalisation of the classical Hilbert scheme defined by Grothendieck, we present here the theory in the nested setting as many of the applications of our results concern this generalisation. The classical case will then be recovered as a special instance of the nested one.

	Let $X$ be a quasi-projective variety, and let $Z\hookrightarrow X$ be a closed subscheme defined by the ideal sheaf $\OI_Z\subset \OO_X$. When $Z$ is a zero-dimensional subscheme, the ring $H^0(Z, \OO_Z)$ is a semilocal Artinian $\BC$-algebra and, as a consequence, it is a finite-dimensional vector space over the field of complex numbers. The complex dimension of $H^0(Z,\OO_Z)$ is called the \textit{length} of $Z$ or the \textit{colength} of $\OI_Z$. We denote it by $d_Z$ (or $d_{\OI_Z}$)
	\[
	d_Z=\length Z=\colen \OI_Z = \dim_\BC H^0(Z, \OO_Z).
	\]


\begin{notation}
    In order to ease the notation, for any vector $\underline{d}\in \BZ^r$ we  denote by $d_i$, for $i=1,\ldots,r$, its entries. Moreover, if $\underline{d}\in \BZ^r$ is a non-decreasing sequence of positive integers, a $\underline{d}$-nesting (or simply $r$-nesting) $\underline{Z}$ in $X$ is a sequence $\underline{Z}=(Z^{(1)},\ldots,Z^{(r)})$ of closed zero-dimensional subschemes $Z^{(1)}\subset\cdots \subset Z^{(r)}\subset X$ such that $\length Z^{(i)}=d_i$, for $i=1,\ldots,r$. Finally, the support of the nesting $   \underline Z$ is the set-theoretic support of the scheme $Z^{(r)}$, i.e.~$\Supp \underline{Z}= \Spec( \OO_X /\sqrt{\OI_{Z^{(r)}}})$.
\end{notation}



	When $Z$ is a zero-dimensional closed subscheme of $X$ and $H^0(Z,\OO_Z)$ is a local $\BC$-algebra, i.e.~the support of $Z$ consists of one point, we  say that $Z$ is a \textit{fat point}. Similarly, given a non-decreasing sequence of positive integers $\underline{d}\in\BZ^r$, a \textit{fat nesting} in $X$ is a nesting $\underline{Z}=(Z^{(i)})_{i=1}^r$ of fat points in $X$.  


Let $X$ be a smooth quasi-projective variety and let $\underline{d} \in \BZ^r$ be a non-decreasing   sequence of positive integers. The $\underline{d}$-nested Hilbert functor  of $X$  is the contravariant functor $\underline{\Hilb}^{\underline{d}}X:\Sch^{\opp}_{\BC} \to \Sets$ defined as follows
\begin{equation}\label{eq:defHilb}
    \left(\underline{\Hilb}^{\underline{d}}X\right)(S)=\Set{\OZ^{(1)}\subset \cdots \subset \OZ^{(r)} \subset X\times S | \OZ^{(i)}  \mbox{ closed },\ S\mbox{-flat, $S$-finite, }  \length_S\OZ^{(i)}=d_i,\mbox{ for }i=1,\ldots,r   }, 
\end{equation}
where $\length_S$ denotes the $S$-relative length. The functor  $\underline{\Hilb}^{\underline{d}}X$ is representable  by a quasi-projective scheme, see \cite[Theorem 4.5.1]{sernesi} and \cite{Kleppe}. We call\footnote{This scheme is sometimes called flag Hilbert scheme.} it the \textit{$\underline{d}$-nested Hilbert scheme}  and we denote it by $\hilbert{\underline{d}}{X}$. Recall that the closed points of $\hilbert{\underline{d}}{X}$ are in bijection with the $\underline{d}$-nestings of closed subschemes of $X$. For this reason, we denote points of the nested Hilbert scheme by $[\underline{Z}]$. Notice that, for  $r=1$, one recovers the classical Hilbert functor, whose representability was proven by Grothendieck in \cite{Grothendieck_Quot}. 

We will often denote by $\Hilb^\bullet X$ the scheme locally of finite type 
\[
\Hilb^\bullet X= \coprod_{r \geqslant 1} \coprod_{\underline{d}\in\BZ^r} \Hilb^{\underline{d}} X.
\]
It is worth mentioning that the scheme $\Hilb^\bullet X$ represents a functor analogous to the one given in \Cref{eq:defHilb}. Precisely, the functor associating to a base scheme $S$, the set of nestings of $S$-families without restriction on the number of nestings and on the  relative lengths. Notice that the connected components of $\Hilb^\bullet X$ are precisely the $\underline{d}$-nested Hilbert schemes of points on $X$, see \cite{FOGARTY,CHEACELLULAR} and therein references.

\begin{remark}\label{rem:closedinprod}
    Notice that the nested condition identifies the nested Hilbert scheme $\hilbert{\underline{d} }{X}$ with the closed subscheme of the product ${\prod}_{i=1}^r \hilbert{d_i}{X}$ cut out by the nesting conditions, see \cite{sernesi}.
\end{remark}



\begin{remark}\label{rem:etale}
     Since the questions we address in this paper are local in nature and our results concern smooth quasi-projective varieties, it is fair to put $X\cong \BA^n$ and hence to work up to \'etale covers. Moreover, whenever not specified, a fat nesting $\underline{Z}=(Z^{(i)})_{i=1}^r$ will be implicitly assumed to be supported at the origin $0\in \BA^n$, i.e.~such that the defining ideal of the scheme $Z^{(r)}$ is $\Fm$-primary.  
 \end{remark}

 As there is a bijection between closed subschemes $Z\subset \BA^n$ and their defining ideals $I_Z\subset R$, we will denote points of the $\underline{d}$-nested Hilbert scheme $\hilbert{\underline{d}}{\BA^n}$ by $[Z^{(1)}\subset \cdots \subset Z^{(r)}]$ or $[I_{Z^{(1)}}\supset \cdots \supset I_{Z^{(r)}}]$ referring to both as $\underline{d}$-nestings (or simply $r$-nestings).

	Recall that the $\underline{d}$-nested Hilbert scheme has always  a distinguished component. Precisely, the \emph{smoothable component}. It is defined as the closure of the open subscheme $U\subset \hilbert{\underline{d}}{\BA^n}$ parametrising $\underline{d}$-nestings $\underline{Z}$ with $ Z^{(r)}$ reduced. We denote it by $\Hilb^{\underline{d}}_{\mathrm{sm}}{ \BA^n} $ and we refer to points in $\Hilb^{\underline{d}}_{\mathrm{sm}}{ \BA^n} $ as \emph{smoothable points}.

	\begin{definition}
		An irreducible component $V\subset   \hilbert{\bullet}{\BA^n}$ is \textit{elementary} if it parametrises just fat nestings, and \textit{composite} otherwise. 
        \end{definition}

In  \Cref{subsec:smallcomp}, we give new examples of  elementary components on $\Hilb{\BA^4}$ of dimension smaller or equal to the dimension of the smoothable one.  This information contributes to the knowledge of the existence of irreducible components on $\hilbert{\bullet}{\BA^4}$ as every irreducible component is generically étale-locally a product of elementary components, see \cite{Iarrocomponent}. 

	We conclude this subsection by reporting on the tangent space of $ \hilbert{ }{\BA^n}$. The following result characterises the tangent space to the classical Hilbert scheme at a given point $[I]\in\hilbert{d}{\BA^n}$.

	\begin{theorem}[{\cite[Corollary~6.4.10]{FGAexplained}}]
		Let $d > 0$ be a positive integer and let $[I]\in \hilbert{d}{\BA^n}$ be any point. Let $\mathsf{T}_{[I]}\hilbert{d}{\BA^n}$ denote the tangent space to $\hilbert{d}{\BA^n}$ at $[I]$. Then, there is a canonical isomorphism
		\begin{equation}\label{eq:isotg}
		    \mathsf{T}_{[I]}\hilbert{d}{\BA^n} \simeq \Hom_{R}(I, R/I)  .
		\end{equation}
	\end{theorem}

    Let us now fix some non-decreasing sequence $\underline{d}\in \BZ^r_{>0 }$  of positive integers  and a point $[\underline{I}] \in \hilbert{\underline{d}}{\BA^n}$. Recall that $\hilbert{\underline{d}}{\BA^n}$ naturally sits inside the product ${\Pi}_{i=1}^r \hilbert{d_i}{\BA^n}$ as a closed subscheme, see \Cref{rem:closedinprod}. This gives a natural identification of the tangent space $\mathsf T_{[\underline{I}]} \hilbert{\underline{d}}{\BA^n}$ with the vector subspace of the direct sum $ \bigoplus_{i=1}^r\mathsf T_{[I^{(i)}]}\hilbert{d_i}{\BA^n}$   consisting of $r$-tuples $(\varphi_i)_{i=1}^r$ making all the squares of the following diagram 
\begin{equation}\label{eq:tangentvector}
    \begin{tikzcd}[row sep=huge,column sep=huge]
     I^{(1)}\arrow[d,"\varphi_1"'] & I^{(2)}\arrow[l,hook']\arrow[d,"\varphi_2"]& I^{(3)}\arrow[l,hook']\arrow[d,"\varphi_3"]& I^{(r-1)}\arrow[d,"\varphi_{r-1}"]\arrow[l,dotted,hook']&I^{(r)}\arrow[l,hook']\arrow[d,"\varphi_r"]\\
     R/I^{(1)} & R/I^{(2)}\arrow[l,two heads]& R/I^{(3)}\arrow[l,two heads]& R/I^{(r-1)}\arrow[l,dotted,two heads]& R/I^{(r)}\arrow[l,two heads],
\end{tikzcd}
\end{equation}
commute {\cite[Section 4.5]{sernesi}}.

\begin{remark}
    Recall that, by the results in  \cite{FOGARTY,CHEACELLULAR}  the connected components of $\Hilb^\bullet \BA^n$ are precisely the $\underline{d}$-nested Hilbert schemes for $\underline{d}\in\BZ^r$ non-decreasing sequence of positive integers (with possibly $r=1$). Therefore, there is a canonical isomorphism
    \begin{equation}\label{eq:tgcc}
        \mathsf{T}_{[\underline{Z}]}\hilbert{\underline{d}}{\BA^n}\cong\mathsf{T}_{[\underline{Z}]}\hilbert{\bullet}{\BA^n}.
    \end{equation}
    In what follows we will intensively adopt the identification in \eqref{eq:tgcc} to ease the notation.
\end{remark}

\subsection{The Bia{\l{}}ynicki--Birula decomposition}\label{subsec:BB}



Let $Z\subset \BA^n$ be a fat point supported at the origin  $0\in\BA^n $ defined by an $\Fm$-primary ideal $I_Z \subset R$. Put 
\[ (I_Z)_{\geqslant k} = I_Z\cap \Fm^k\qquad\mbox{ and }\qquad (R/I_Z)_{\geqslant k}= (\Fm^k + I_Z)/I_Z \subset R/I_Z. \]



\begin{definition}\label{def:negativetangents}
Let $\underline Z = (Z^{(1)}\subset \cdots\subset Z^{(r)}$) be a fat nesting supported at the origin $0\in\BA^n$.
Then, the \textit{non-negative part of the tangent space} $\mathsf T_{ [\underline{Z}]}  \hilbert{\bullet}{\BA^n}$  is the following vector subspace
\[
\mathsf T_{ [\underline{Z}]}^{\geqslant0}  \hilbert{\bullet}{\BA^n} = \left\{\varphi\in\mathsf T_{ [\underline{Z}]} \hilbert{\bullet}{\BA^n}\ \middle\vert\ \varphi\big((I_{Z^{(i)}})_{\geqslant k}\big) \subset (R/I_{Z^{(i)}})_{\geqslant k}\mbox{ for all }k \in\BN\mbox{ and }i=1,\ldots,r\right\}. 
\]
While, the \textit{negative tangent space} at $[\underline{Z}]\in \hilbert{\bullet}{\BA^n}$ is the quotient vector space
\[
\mathsf T_{ [\underline{Z}]}^{< 0}  \hilbert{\bullet}{\BA^n}=\frac{ \mathsf T_{ [\underline{Z}]}  \hilbert{\bullet}{\BA^n}}{ \mathsf T_{ [\underline{Z}]}^{\geqslant0}  \hilbert{\bullet}{\BA^n}}.
\]
\end{definition}

    Note that non-negative tangent vectors can be understood as concatenations of commutative diagrams of the form \eqref{eq:tangentvector}, where $\varphi_i\in \mathsf T_{[Z^{(i)}]}^{\ge0} \hilbert{\bullet}{\BA^n}$, for all $i=1,\ldots,r$. 
The non-negative part of the tangent space can be interpreted as the tangent space to the so-called Bia{\l{}}ynicki--Birula decomposition, whose definition we recall now. Consider the diagonal action of the torus $\mathbb G_m=\Spec \BC[s,s^{-1}]$ on $ \hilbert{\underline{d}}{\BA^n} $ given by homotheties. Then, the Bia{\l{}}ynicki--Birula decomposition is the quasi-projective scheme $\hilbert{\underline{d},+}{\BA^n}$ representing the following functor
\[ 
   \left( \underline{\Hilb}^{\underline{d},+}\BA^n\right)(B) = \left\{\varphi\colon \overline{\mathbb G}_m \times B \rightarrow \hilbert{\underline{d}}{\BA^n} \ \middle\vert\   \varphi \mbox{ is $\mathbb G_m$-equivariant}\right\} 
\]
where, by convention $\overline{\mathbb G}_m= \Spec \BC[ s^{-1}]$. 
\begin{remark}\label{rem:BBdentroHilb}
    Set-theoretically, the Bia{\l{}}ynicki--Birula decomposition is the subset of the nested Hilbert scheme parametrising fat nestings supported at the origin $0\in\BA^n$. Notice that, under this association, every point $[\underline I]\in\Hilb^{\underline{d},+}\BA^n$ has an open neighbourhood that can be interpreted as a locally closed subscheme of $\Hilb^{\bullet}\BA^n$.   
\end{remark}

According to the above notation, we put
\[
\Hilb^{\bullet,+}\BA^n=\coprod_{r\geqslant 1} \coprod_{\underline d\in\BZ^r} \Hilb^{\underline d,+} \BA^n 
\] 

The following proposition from \cite{ELEMENTARY} expresses the tangent space   $\mathsf T_{ [\underline{Z}]}  \Hilb^{+} \BA^n$  in  terms of the non-negative tangent space at $[\underline{Z}]\in \hilbert{\bullet}{\BA^n}$. We adopt the identification on tangent spaces analogous to \Cref{eq:tgcc}.
\begin{prop}[{\cite[Theorem 4.11]{ELEMENTARY}}]\label{rem:nonneg-punctual}
Let $[\underline{Z}]\in \hilbert{\bullet,+}{\BA^n}$ be a fat nesting. Then, we have
\[
    \mathsf T_{ [\underline{Z}]}  \hilbert{\bullet,+}{\BA^n}= \mathsf T_{ [\underline{Z}]}^{\geqslant0}  \hilbert{\bullet}{\BA^n} .
\]    
\end{prop}


\begin{remark}\label{rem:deftheta}
  As shown in \cite{ELEMENTARY}, when $[Z]\in \Hilb^{d,+} \BA^n$ is a fat point,  the tangent space to $\BA^n$ at its support $\{0\}=\Supp Z\subset\BA^n$ maps to the tangent space to $ \Hilb^{d} \BA^n$ at $[Z]$. Similarly, this happens for fat nestings and we give now some details. Let us identify the partial derivatives $\frac{\partial}{\partial x_j}$, for $j=1,\ldots,n$, with a basis of the tangent space $\mathsf T_0\BA^n$ and let us consider a fat nesting $[\underline{Z}]\in \hilbert{\bullet,+}{\BA^n}$. In this setting we have a natural map
  \[
    \begin{tikzcd}
         \mathsf T_{0} \BA^n \arrow[r,"\widetilde\theta"] & \mathsf T_{[\underline{Z}]}\Hilb^{\bullet} \BA^n,
    \end{tikzcd}
  \]
associating tangent vectors to $\BA^n$ at the origin to first order deformations consisting of translations. More precisely, the partial derivative $\frac{\partial}{\partial x_j}$, for $j=1,\ldots,n$, maps to an infinitesimal first order translation of all the schemes $Z^{(i)}$, for $i=1,\ldots,r$, along the $j$-th coordinate axis preserving the nesting conditions.

  We denote by  $\theta : \mathsf T_{0} \BA^n \to \mathsf T_{ [\underline{Z}]}^{< 0} \Hilb^{\bullet} \BA^n
  $ the map defined as  the composition of $\widetilde \theta$ with the canonical projection defining the negative tangent space, see \Cref{def:negativetangents}.
\end{remark}
\begin{definition}\label{def:TNT}
    Let $[\underline{Z}]\in \Hilb^{+} \BA^n$ be a fat nesting. Then, $[\underline{Z}]$ has TNT (Trivial Negative Tangents) if the   map 
\[
         \mathsf T_{0} \BA^n  \xrightarrow{\theta} \mathsf T_{ [\underline{Z}]}^{< 0}  \Hilb^\bullet \BA^n
\]
    is surjective.
\end{definition} 
\Cref{thm:tnt per nested} is a generalisation of {\cite[Theorem 4.9]{ELEMENTARY}} and it relates the existence of ideals having TNT and the existence of generically reduced elementary components. 
\begin{theorem}[{\cite[Theorem 4]{UPDATES}}] \label{thm:tnt per nested} 
Let $V\subset \Hilb^{\bullet} \BA^n$ be an irreducible component.  Suppose that $V$ is generically reduced. Then $V$ is elementary if and only if a general point of $V$ has trivial negative tangents.  
\end{theorem}

Elementary components are considered the building blocks of the Hilbert schemes of points as each irreducible component is proven, in \cite{Iarrocomponent}, to be generically \'etale locally a product of elementary components.  In \Cref{subsec:smallcomp}, we give new examples of elementary components on $\hilbert{\bullet}{\BA^4}$ and, in \Cref{sec:small} we present other examples in dimensions 5 and 6. There are few elementary components known in the literature, see  \cite{Iarrob,ELEMENTARY,Satrianostaal,GALOIS,SomeElementary,MoreElementary,ERMANVELASCO,Sha90,UPDATES}  and references therein for other examples of elementary components. We certify their existence by exhibiting  explicit points having TNT. This information contributes to the knowledge of the growth of the number of irreducible components on $\hilbert{d}{\BA^n}$ as $d$ tends to infinity whose asymptotics have been investigated in \cite{Iarrocomponent}.



\begin{remark}\label{rem:BBHOMOo}  The fixed locus of  the diagonal action of the torus $\mathbb G_m=\Spec \BC[s,s^{-1}]$ on $ \Hilb^{\bullet} \BA^n $ agrees with the locus parametrising nestings of homogeneous ideals. As a consequence, given a nesting $ \underline{I}=( I^{(1)}\supset\cdots\supset I^{(r)}) $ of homogeneous ideals, the  $\mathbb G_m$-action lifts to the tangent space $\mathsf T_{[\underline{I}]} \Hilb^{\bullet}\BA^n$ and it induces an eigenspaces decomposition  
    \[
    \mathsf T_{[\underline{I}]} \Hilb^{ \bullet}\BA^n=\bigoplus_{k\in \BZ } \mathsf T_{[\underline{I}]}^{=k} \Hilb^{\bullet}\BA^n.
    \]
    This direct sum decomposition is consistent with \Cref{def:negativetangents} meaning that
    \[
    \mathsf T_{[\underline{I}]}^{\geqslant 0}\Hilb^{\bullet}\BA^n=\bigoplus_{k\geqslant 0 } \mathsf T_{[\underline{I}]}^{=k} \Hilb^{\bullet}\BA^n\quad \mbox{ and }\quad   \mathsf T_{[\underline{I}]}^{<0} \Hilb^{\bullet}\BA^n=\bigoplus_{k<0 } \mathsf T_{[\underline{I}]}^{=k} \Hilb^{\bullet}\BA^n,
    \]
    see \cite[Section 2]{ELEMENTARY} and \Cref{rem:homobb} for more details.
\end{remark}



\subsection{Hilbert stratification}\label{subsec:HSstrat}

\begin{notation}
 For the ideal $I\subset R$ of a fat point supported at the origin, the function $\bh_{R/I}$ vanishes eventually. For this reason, we represent it as tuples of positive integers. 

    Given a nesting $\underline{I}= (I^{(i)})_{i=1}^r $, of $\Fm$-primary ideals of finite colength $d_i$, for $i=1,\ldots,r$, we denote by $\underline{\bh}_{\underline{I}},\underline{\bh}_{R/\underline{I}}$ the $r$-tuples of Hilbert functions 
    \[
    \underline{\bh}_{\underline{I}}=\left(\bh_{I^{(i)}}\right)_{i=1}^r\quad\mbox{ and }\quad    \underline{\bh}_{R/\underline{I}}= \left(\bh_{R/I^{(i)}}\right)_{i=1}^r.
    \]
\end{notation}
Moreover, we denote by $|\underline{\bh}_{R/\underline{I}}|$ the non-decreasing sequence of positive integers  
\[
\lvert\underline{\bh}_{R/\underline{I}}\rvert=\left(\lvert\bh_{R/I^{(i)}}\rvert\right)_{i=1}^r = (d_1,\ldots,d_r)\in\BZ^r.
\]
The map
\[
    \begin{tikzcd}[row sep=tiny]
         \Hilb ^{\bullet,+}\BA^n \arrow[r]& \BN^r\\
         {\left[\underline{I}\right]}\arrow[r,mapsto]& \underline{\bh}_{R/\underline{I}} ,
    \end{tikzcd}
    \]
is locally constant, see \cite[Prop.~3.1]{ELEMENTARY}. 
Since the locally closed subsets
\begin{equation}\label{eq:defHSStratum}
    H_{\underline{\bh}}^n=\left\{ \left[\underline{I}\right] \in \Hilb^{\bullet,+}  \BA^n \ \middle\vert\ \underline{\bh}_{R/\underline{I}}\equiv \underline{\bh} \right\}\subset \Hilb^\bullet \BA^n ,
\end{equation}
where $\underline{\bh}=(\bh^{(1)},\ldots,\bh^{(r)}):\BZ\to\BN^r$ is an $r$-tuple of Hilbert functions compatible with the conditions imposed by the nestings, agree with the connected components of the Bia{\l{}}ynicki--Birula decomposition, they inherit a canonical scheme structure, see \Cref{rem:BBdentroHilb} and \cite{Iarropunctual}.

\begin{definition}
Given a $r$-tuple  $\underline{\bh}=(\bh^{(1)},\ldots,\bh^{(r)}):\BZ\to\BN^r$ of   functions, the \emph{Hilbert stratum} $ H_{\underline{\bh}}^n\subset \Hilb^\bullet \BA^n $  is the (possibly empty) locally closed subset given in \eqref{eq:defHSStratum}, endowed with the schematic structure induced by the Bia{\l{}}ynicki--Birula decomposition.
\end{definition} 


\begin{remark}
In order to have a non-empty Hilbert stratum $H_{\underline{\bh}}^n$, the $r$-tuple $\underline{\bh}=(\bh^{(1)},\ldots,\bh^{(r)})$ must have finite support and it must satisfy two conditions:
\begin{itemize}
    \item the vector $|\underline{\bh}|$ is non-decreasing, i.e.~$|\bh^{(i)}|\leqslant|\bh^{(j)}| $ for all $1\leqslant i< j\leqslant r$;
    \item the strata $H_{\bh^{(i)}}^n$ are non-empty, for $i=1,\ldots,r$.
 \end{itemize}

    Moreover, recall that the set of functions ${\bh}\colon\mathbb{Z} \to \mathbb{N}$ for which $H^n_{\bh}$ is non-empty is characterised by Macaulay's theorem \cite[Theorem 4.2.10]{CMRings}.
\end{remark}

\begin{remark} \label{rem:homobb}
Let $\underline d\in\BZ^r_{> 0}$ be a non-decreasing sequence of positive integers. Then, there is a surjective morphism of schemes locally of finite type
    \[
    \begin{tikzcd}[row sep=tiny]
         \Hilb ^{\bullet,+}\BA^n \arrow[r,"\pi"]& (\Hilb^{\bullet,+} \BA^n)^{\mathbb G_m},
    \end{tikzcd}
    \] 
        which set-theoretically associates to the point corresponding to a $\underline{d}$-nesting $\underline{I}=(I^{(i)})_{i=1}^r$ the point corresponding to its initial $\underline{d}$-nesting $    \In\underline{I}= (\In I^{(i)})_{i=1}^r$, 
see \Cref{rmk:gradini}.       Recall that the tangent space to the fibre of $\pi $ over ${[}\underline{I}{]}\in(\Hilb ^+\BA^n)^{\mathbb G_m}$ identifies, via \Cref{rem:nonneg-punctual}, with $\mathsf T_{ [\underline{I}]}^{>0}  \Hilb^\bullet  \BA^n$, while the tangent space to $(\Hilb ^+\BA^n)^{\mathbb G_m}$ identifies with $\mathsf{T}_{ [\underline{I}]}^{=0}  \Hilb^\bullet  \BA^n$, see \Cref{rem:BBHOMOo} and \cite{multigraded}. In formulas, we have
    \[
    \mathsf{T}_{[\underline{I}]} \pi^{-1}([\underline I]) \cong  \mathsf T_{ [\underline{I}]}^{>0}  \Hilb^\bullet  \BA^n\quad\mbox{ and }\quad\mathsf T_{ [\underline{I}]}  (\Hilb ^+\BA^n)^{\mathbb G_m} \cong \mathsf T_{ [\underline{I}]}^{=0}  \Hilb^\bullet  \BA^n.
    \]

\end{remark}





\section{A special class of ideals}\label{sec:2-step}
In this section, we introduce the notion of 2-step ideal. This class of ideals is suitable for our purpose of studying irreducibility of $\hilbert{\underline{d}}{\BA^n}$. Indeed, the loci parametrising homogeneous ideals of this kind happen to be very large with respect to the smoothable component. For instance, the compressed algebras of length 78 considered by Iarrobino in \cite{IARRO} are of the form $R/I$ for $I\subset R$ a 2-step ideal, see \Cref{exa:iarrobino}.

\subsection{Definition and general properties of 2-step ideals}\label{subsec:2-stepdef}
We start by giving the definition and the basic properties of 2-step ideals.

\begin{definition}  \label{def:2step}
An ideal $I \subset R$ is \emph{2-step} of order $k > 0$, if  
\[
\mathfrak{m}^{k+2} \subset I \subset \mathfrak{m}^{k}\quad\mbox{ and }\quad I\not \subset \mathfrak{m}^{k+1}.
\] 
In this context we say that the Hilbert function of $I$ (or of $R/I$) is 2-step of order $k$.
\end{definition} 

\begin{remark}
    In terms of Hilbert function, the requirements  in \Cref{def:2step} are equivalent to 
\[
{\bh}_{R/I} (t) :
     \  \begin{cases}
    = \mathsf  r_{t} &\text{for~}t<k,\\
    < \mathsf r_{k} &\text{for~}t=k,\\
      = 0&\text{for~}t\geqslant k+2,
\end{cases}
\] see \Cref{fig:2stpdis} for a pictorial description.
 \end{remark}

