We exploit now the basic properties of 2-step Hilbert functions.  By definition of  2-step ideal of order $k$,  the Hilbert functions $\bh_I$ and $\bh_{R/I}$ of $I$  and of the corresponding quotient algebra are uniquely determined by the values  
\begin{equation}\label{eq:notation}
    \oh_{k} =   \rrr_{k} - \uh_{k}\quad\mbox{and}\quad\oh_{k+1}    = \rrr_{k+1} - \uh_{k+1},
\end{equation}
see  \Cref{notation:initial,notation:HStutti}. In fact, we have
\[
\bh_{I}(t) = \begin{cases}
    0,& 0 \leqslant t \leqslant k-1,\\
    \oh_{k} ,& t= k,\\ 
    \oh_{k+1}& t = k+1,\\
    \rrr_{t},& t \geqslant k+2,
\end{cases}
\quad\mbox{and}\quad
\bh_{R/I}(t) = \begin{cases}
   \rrr_{t},& 0 \leqslant t \leqslant k-1,\\
    \uh_{k} ,& t= k,\\ 
    \uh_{k+1},& t = k+1,\\
    0,& t \geqslant k+2,
\end{cases}
\]
and 
\[
\begin{split}
d_I = \dim_{\BC} (R/I) &{} = \sum_{q=0}^{k-1} \rrr_{q} + \uh_{k} + \uh_{k+1} = \binom{k+n-1}{n} + \uh_{k} + \uh_{k+1} = {}\\
& {} = \sum_{q=0}^{k+1} \rrr_{q} - \oh_{k} - \oh_{k+1} = \binom{k+n+1}{n} - \oh_{k} - \oh_{k+1}.    
\end{split}
\]

We stress that, given $ 0\leqslant \oh_{k} \leqslant \rrr_{k}$, the values of $\oh_{k+1}$ for which the Hilbert function is admissible are bounded from below by Macaulay's theorem, \cite[Theorem 4.2.10]{CMRings}.

In \Cref{lem: general properties Betti}, we list the basic properties of the minimal free resolutions of a homogeneous 2-step ideal.
\begin{lemma} \label{lem: general properties Betti}
Let $I\subset R$ be a homogeneous 2-step ideal of order $k>0$. Then,
\begin{enumerate}[\it (i)]
\item\label{it:bettionei} the regularity of $I$ satisfies $\reg(I)\leqslant k+2$,  
\item\label{it:Bettitwoii} the  Betti table of $I$ is
\begin{equation}\label{eq: betti table general}
\begin{array}{c|ccccc}
& 0& 1 & 2 & \ldots & n-1 \\
\hline
k& \beta_{0,k} & \beta_{1,k+1} & \beta_{2,k+2} & \cdots & \beta_{n-1,k+n-1}\\
k+1& \beta_{0,k+1} & \beta_{1,k+2} & \beta_{2,k+3}  & \cdots & \beta_{n-1,k+n}\\
k+2& \beta_{0,k+2} & \beta_{1,k+3} & \beta_{2,k+4}  & \cdots & \beta_{n-1,k+n+1}\\
\end{array}
\end{equation}
where
\begin{equation}\label{eq:bettitwostep}
\beta_{0,k} = \oh_{k}, \qquad
 \beta_{0,k+1}-\beta_{1,k+1} = \oh_{k+1}-n\oh_{k}, \qquad \beta_{0,k+2}-\beta_{1,k+2}+\beta_{2,k+2} = \rrr_{k+2} - n\oh_{k+1}+\tbinom{n}{2}\oh_{k}.
 %&\textnormal{da scrivere} &&  \forall\ q = k+2,\ldots,k+n-1,\\
 %\beta_{n-2,k+n} - \beta_{n-1,k+n} ={}& n\uh_{k+1} - \uh_{k} &={}& n\tbinom{k+n}{n-1} - \tbinom{k+n-1}{n-1} - n\oh_{k+1} + \oh_{k} , \\
 %\beta_{n-1,k+n+1} ={}& \uh_{k+1} &={}& \tbinom{k+n}{n-1} - \oh_{k+1}.
\end{equation}
\end{enumerate}
\end{lemma}

\begin{proof}
The first part of the statement is a direct consequence of the definition of 2-step ideals and of \cite[Corollary 4.4]{SYZYGIES}. We move now to the proof of the equalities in \eqref{eq:bettitwostep}. Consider the minimal graded free resolution $\begin{tikzcd}
    0&I\arrow[l]&F_\bullet \arrow[l,"d_0"],
\end{tikzcd}$ of $I$, where
\begin{equation}\label{eq: resolution I}
\begin{tikzcd}[column sep=small]
      F_\bullet:&\begin{array}{c}R(-k)^{\oplus\beta_{0,k}}\\[-6pt]\oplus\\[-6pt] R(-k-1)^{\oplus\beta_{0,k+1}} \\[-6pt]\oplus\\[-6pt] R(-k-2)^{\oplus\beta_{0,k+2}} \end{array}  & \begin{array}{c}R(-k-1)^{\oplus\beta_{1,k+1}}\\[-6pt]\oplus\\[-6pt] R(-k-2)^{\oplus\beta_{1,k+2}} \\[-6pt]\oplus\\[-6pt] R(-k-3)^{\oplus\beta_{1,k+3}} \end{array} \arrow[l,"d_1"'] & \quad \cdots\quad   \arrow[l] &  \begin{array}{c}R(-k-n+1)^{\oplus\beta_{n-1,k+n-1}}\\[-6pt]\oplus\\[-6pt] R(-k-n)^{\oplus\beta_{n-1,k+n}} \\[-6pt]\oplus\\[-6pt] R(-k-n-1)^{\oplus\beta_{n-1,k+n+1}} \end{array} \arrow[l,"d_{n-1}"'] &0 .\arrow[l]
\end{tikzcd}
\end{equation}
Then, the Hilbert series of $I$ is
\[
\boldsymbol{H}_I(T) = \sum_{t\geqslant 0} \bh_I(t) T^t = \oh_{k} T^k + \oh_{k+1} T^{k+1} + \sum_{t\geqslant k+2} \rrr_{t} T^t ,
\]
and it can be expressed as
\[
\dfrac{\sum_{i=0}^{n-1} \left( (-1)^{i}\sum_{j=k}^{k+2}\beta_{i,i+j}T^{i+j}\right)}{(1-T)^n},
\]
by \cite[Theorem 1.11]{SYZYGIES}. The equality $(1-T)^n \boldsymbol{H}_I(T) = \sum_{i=0}^{n-1} \left( (-1)^{i}\sum_{j=k}^{k+2}\beta_{i,i+j}T^{i+j}\right)$ in degree $k,k+1,k+2$ leads to \Cref{eq:bettitwostep}.
\end{proof}

\begin{remark}  
We note that the definition of 2-step ideals includes also very compressed algebras, cf. \Cref{def:compressed}.

If we add the assumption $\mathfrak{m}^{k+1} \not\subset I$ we get the equality $\reg(I)=k+2$ at point {\it(\ref{it:bettionei})} of \Cref{lem: general properties Betti}.  This can be verified by considering the minimal graded free resolution of the quotient algebra $R/I$  
\[
\begin{tikzcd} 
    0 &R/I \arrow[l]&R \arrow[l,"\pi"']& F_\bullet\arrow[l,"j\circ d_0"'] 
\end{tikzcd}
\]  
where $F_\bullet$ is the same as \eqref{eq: resolution I}, $j:I\hookrightarrow R$ is the inclusion and $\pi: R \to R/I $ is the canonical projection. Indeed, we have the equality
\[
(1-T)^n \boldsymbol{H}_{R/I}(T) = (1-T)^n\left(\sum_{t=0}^{k-1}\rrr_{t} T^t + \uh_{k} T^k + \uh_{k+1}T^{k+1}\right) = 1 - \sum_{i=0}^{n-1} \left( (-1)^{i}\sum_{j=k}^{k+2}\beta_{i,i+j}T^{i+j}\right),
\]
that in degree $k+1+n$ reads as
\[
(-1)^n\uh_{k+1} = - (-1)^{n-1}\beta_{n-1,k+n+1}.
\]
Hence, the condition $\mathfrak{m}^{k+1}\not\subset I$ implies $\beta_{n-1,k+n+1} = \uh_{k+1} \neq 0$, that is $\reg(I) = k+2$.  
\end{remark}


\begin{remark}
    The minimal graded free resolution of a homogeneous ideal $I\subset R$ encodes several information about the tangent space at the point $[I]$ to the Hilbert scheme $ \Hilb^\bullet \mathbb{A}^n$. Indeed, by  applying the functor $\Hom_R(\_,R/I)$ to the resolution \eqref{eq: resolution I} of $I$, we obtain a sequence exact in the first two terms
\begin{equation}\label{eq:Hom res}
\begin{tikzcd}[column sep = 1em]
    0 \arrow[r]&\textnormal{Hom}_R(I,R/I) \arrow[r]& \textnormal{Hom}_R\left(\begin{array}{l}R(-k)^{\oplus\beta_{0,k}}\\[-6pt]\quad\oplus\\[-6pt] R(-k-1)^{\oplus\beta_{0,k+1}} \\[-6pt]\quad\oplus\\[-6pt] R(-k-2)^{\oplus\beta_{0,k+2}} \end{array}\hspace{-4pt},R/I\right) \arrow[r,"d_1^\vee"]& \textnormal{Hom}_R\left(\begin{array}{l}R(-k-1)^{\oplus\beta_{1,k+1}}\\[-6pt]\quad\oplus\\[-6pt] R(-k-2)^{\oplus\beta_{1,k+2}} \\[-6pt]\quad\oplus\\[-6pt] R(-k-3)^{\oplus\beta_{1,k+3}} \end{array}\hspace{-4pt},R/I\right) \arrow[r]&   \cdots,
\end{tikzcd}
\end{equation}
which implies, together with the isomorphism in \eqref{eq:isotg}, the identification
\[
\mathsf{T}_{[I]} \Hilb^\bullet \mathbb{A}^n \simeq \text{Hom}_R(I,R/I) = \ker d_1^\vee.
\]  
\end{remark}
Recall that the non-negative part $\textsf{T}_{[I]}^{\geqslant 0} \Hilb^\bullet \mathbb{A}^n$ of the tangent space of $ \Hilb^\bullet \mathbb{A}^n$ at $[I]$ can be understood as the tangent space to the Bia{\l{}}ynicki--Birula decomposition, see \Cref{rem:homobb}. In particular, when $\textsf{T}_{[I]}^{\geqslant 0} \Hilb^\bullet \mathbb{A}^n$ happens to be entirely unobstructed, its dimension agrees with the dimension of the unique irreducible component of the Bia{\l{}}ynicki--Birula decomposition containing the point $[I]$, see \Cref{rem:nonneg-punctual}. This observation highlights the role of the non-negative part of the tangent space in finding loci inside the Hilbert scheme of dimension as big as possible, and it motivates the following Lemma.  


\begin{lemma}\label{lem: tangent space}
Let $I \subset R$ be a homogeneous 2-step ideal of order $k>0$. Then, we have
\[
\begin{split}
\dim_{\BC} \mathsf{T}^{=t}_{[I]} \Hilb^\bullet \mathbb{A}^n&{}= 0, \qquad\forall\ t \geqslant 2,\\
\dim _{\BC}\mathsf{T}^{=1}_{[I]} \Hilb^\bullet \mathbb{A}^n &{} = \oh_{k}\uh_{k+1},\\
\dim_{\BC} \mathsf{T}^{=0}_{[I]} \Hilb^\bullet \mathbb{A}^n &{} \geqslant \max\big\{0,\oh_{k}\uh_{k} + (\oh_{k+1}-n\oh_{k})\uh_{k+1}\big\}.
%t_I(-1) &{} \geqslant \max\big\{3,\beta_{0,k}\uh_{k-1} +  (\beta_{0,k+1} - \beta_{1,k+1})\uh_{k} + (\beta_{0,k+2} - \beta_{1,k+2})\uh_{k+1}\}\\
%t_I(-n) &{} \geqslant \max\big\{0,\beta_{0,k}\uh_{k-n} +  (\beta_{0,k+1} - \beta_{1,k+1})\uh_{k-n+1} + (\beta_{0,k+2} - \beta_{1,k+2})\uh_{k-n+2} - \beta_{1,k+3}\uh_{k-n+3}\},\qquad 2 \leqslant n \leqslant k+3\\
%t_I(-n) &{}= 0, \qquad\forall\ n \geqslant k+3,\\
\end{split}
\]
%\todo{aggiungere che per $n>k+3$ $t_I(-n)=0$.\\
%per $n>3, \underline{h}_{k-n+3}$ è un binomiale.
%}
\end{lemma}
\begin{proof}
In degree $t$, the complex \eqref{eq:Hom res} reads as
\[
\begin{tikzcd}[column sep=small]
    0 \arrow[r]&\textnormal{Hom}_R(I,R/I)_t \arrow[r]& \begin{array}{l}\big((R/I)_{k+t}\big)^{\oplus\beta_{0,k}}\\[-6pt]\quad\oplus\\[-6pt] \big((R/I)_{k+1+t}\big)^{\oplus\beta_{0,k+1}} \\[-6pt]\quad\oplus\\[-6pt] \big((R/I)_{k+2+t}\big)^{\oplus\beta_{0,k+2}} \end{array} \arrow[r,"d_1^\vee"]& \begin{array}{l}\big((R/I)_{k+1+t}\big)^{\oplus\beta_{1,k+1}}\\[-6pt]\quad\oplus\\[-6pt] \big((R/I)_{k+2+t}\big)^{\oplus\beta_{1,k+2}} \\[-6pt]\quad\oplus\\[-6pt] \big((R/I)_{k+3+t}\big)^{\oplus\beta_{1,k+3}} \end{array} \arrow[r]&   \cdots,
\end{tikzcd}
\] 
and
\[
\begin{split}
\dim_{\BC} (\ker d_1^\vee)_t \geqslant{}& \sum_{j=0}^{2} \dim_{\BC} \big((R/I)_{k+t+j}\big)^{\oplus\beta_{0,k+j}} - \sum_{j=0}^{2} \dim_{\BC} \big((R/I)_{k+t+1+j}\big)^{\oplus\beta_{1,k+1+j}} = {}\\
& \beta_{0,k}\uh_{k+t} + (\beta_{0,k+1}-\beta_{1,k+1})\uh_{k+t+1} + (\beta_{0,k+2}-\beta_{1,k+2})\uh_{k+t+2} - \beta_{1,k+3}\uh_{k+t+3}.
\end{split}
\]
The statement is then a consequence of point \textit{(\ref{it:Bettitwoii})} in \cref{lem: general properties Betti}.
\end{proof}

The following theorem will be crucial in the rest of the paper, see \Cref{rem:1nonobstruct}.

\begin{theorem}\label{thm:1nonob}
Given a homogeneous 2-step ideal $I \subset R$ of order $k$, there is a canonical isomorphism  
\[
\textnormal{Hom}_R(I,R/I)_1\cong \textnormal{Hom}_{\BC}(I_k,(R/I)_{k+1}).
\] 
Moreover, all tangent vectors of degree 1 are unobstructed.   
\end{theorem} 


\begin{proof}

By definition of 2-step ideal of order $k>0$, we have
\[
\textnormal{Hom}_R(I,R/I)_1=\Set{\varphi\in \textnormal{Hom}_R(I,R/I) | \varphi(I_k)\subseteq (R/I)_{k+1},\ \varphi(I_{k+1})=(0)=(R/I)_{k+2}}.
\]
Hence, we can identify via restriction the space $\textnormal{Hom}_R(I,R/I)_1$ with a complex vector subspace of $\textnormal{Hom}_{\BC}(I_k,(R/I)_{k+1})$. Notice also that, again by definition of 2-step ideal of order $k$, the vector space $(R/I)_{k+1}$ is entirely contained in the socle $(0_{R/I}:\Fm)$ of the local algebra $R/I$. As a consequence any $\BC$-linear homomorphism between $I_k$ and $(R/I)_{k+1}$ lifts to a unique $R$-linear homomorphism of degree $1$ between $I$ and $R/I$. This proves the first part.


We move now to the proof of the unobstructedness of ${\Hom}_R(I,R/I)_1$. Fix a basis $G = \Set{g_1,\ldots,g_{\oh_{k}}} \subset R$ of $I_k$ and consider some element $\varphi\in {\Hom}_R(I,R/I)_1$. Let us denote by $f_i=\varphi(g_i)\in (R/I)_{k+1}$, for $i=1,\ldots,{\oh_{k}}$, the images of the elements $g_i$ under the homomorphism $\varphi$. Note that, as a consequence of the first part of the statement, the homomorphism $\varphi$ is uniquely determined by the elements $f_i$'s. Fix also homogeneous lifts $\widetilde{f}_i\in R_{k+1}$,  for $i=1,\ldots,{\oh_{k}}$. By construction, the ideal $(g_i+\varepsilon \widetilde{f}_i \ |\  i=1,\ldots,{\oh_{k}}) + I_{\geqslant k+1}\subset R [\varepsilon]/\varepsilon^2$ defines a flat family over the spectrum of dual numbers. In order to conclude the proof we show that the ideal  
\[
I^+ = (g_i+t \widetilde{f}_i \ |\  i=1,\ldots,{\oh_{k}}) + I_{\geqslant k+1} \subset R [t]
\]
defines a flat family over the affine line $\BA^1$ with coordinate $t$. Since the scheme $\BA^1$ is reduced it is enough to show that, for any $t_0 \in \BC$ the ideal $I_{t_0}\subset R[t_0]$ obtained via base change has initial ideal $I$. This implies that the length of the fibres of the family defined by $I_t$ is constant along $\BA^1$. 

Clearly, by construction we have $\In I_{t_0}\supseteq I$. Therefore, we focus on the opposite inclusion. Let us fix some element $p\in I_{t_0}$. If $\deg\In p = k+2$, then $\In p\in \Fm^{k+2}=I_{k+2}$. On the other hand, if $\deg\In p = k$ we must have $p=\sum_{i=1}^{\oh_k}(\alpha_i + u_i )(g_i+t_0 \widetilde f_i) +q$, for some $\alpha_1,\ldots,\alpha_{\oh_k}\in\BC$, $u_1,\ldots,u_{\oh_k} \in \mathfrak{m}$ and $q\in I_{\geqslant k+1}$, which gives $\In p=\sum_{i=1}^{\oh_k}\alpha_ig_i\in I$. Finally,  if $\deg\In p = k+1$ we have   $p=\sum_{i=1}^{\oh_k}\ell_i(g_i+t_0 \widetilde f_i) + q + r$, where $\ell_1,\ldots,\ell_{\oh_k}\in R$ have order 1, $q\in I_{k+1}$ and $r\in I_{\geqslant k+2}$ which concludes the proof.  
 \end{proof}




