As a consequence of \Cref{thm:1nonob}, we get the following corollary.

\begin{corollary}\label{rem:1nonobstruct}
 Let $I\subset R$ be a homogeneous 2-step ideal. Then, the fibre $\pi_{\bh_I}^{-1}([I]) $ of the initial ideal morphism $H_{\bh_I}^n\xrightarrow{\pi_{\bh_I}}\OH_{\bh_I}^n$ is an affine space of dimension equal to  $\dim_{\BC}\mathsf{T}_{[I]}^{=1} \Hilb^\bullet \mathbb{A}^n$. 
\end{corollary}
\begin{proof} The statement is a direct consequence of \Cref{thm:1nonob}. Using the notation introduced in the proof of \Cref{thm:1nonob}, let $G = \{g_1,\ldots,g_{\oh_k}\}$ be a set of generators of $I$ of degree $k$, let $\{b_1,\ldots,b_{\uh_{k+1}}\}$ be a basis of $(R/I)_{k+1}$ and $\tilde{b}_j$ a homogeneous lifting of $b_j$ to $R$. The fibre $\pi_{\bh_I}^{-1}([I]) $ is described by the ideal
\[
 \left( g_i + \sum_{j=1}^{\uh_{k+1}} \alpha_{i,j} \widetilde b_j\ \middle\vert\ i=1,\ldots, \oh_{k}\right) + I_{\geqslant k+1}\subset \overline R.
\]
in the polynomial ring
\[ 
\overline{R}=\BC[x_1,\ldots,x_n]\otimes_{\BC}\BC[\alpha_{i,j}\ |\ i=1,\ldots, \oh_{k}\mbox{ and }j=1,\ldots,\uh_{k+1}]
\] 
 where coordinates $\alpha_{i,j}$, for $i=1,\ldots, \oh_{k}$ and $j=1,\ldots,\uh_{k+1}$ are the coordinates of the affine space $\mathbb{A}^{\oh_k \uh_{k+1}}$ that parametrises the fibre.
\end{proof}


\subsection{Nested configurations of 2-step ideals} \label{subsec:nest2stepbase}

Consider a pair of 2-step homogeneous ideals $I,J \subseteq R$ of respective orders $k_I$ and $k_J$,   and assume $k_I \leqslant k_J$. 

If $ k_J \geqslant k_I+2$, then $J$ is automatically contained in $I$. This gives the following isomorphism 
\[
\mathsf{T}_{[I,J]}^{\geqslant 0}\Hilb^{\bullet}\BA^n\quad \cong\quad
\mathsf{T}^{\geqslant 0}_{[I]}\Hilb^{\bullet}\BA^n\oplus\mathsf{T}^{\geqslant 0}_{[J]}\Hilb^{\bullet}\BA^n.
\] 

On the other hand, if $k_J = k_I+1$, then in general $J$ will not be contained in $I$ and the deformations of a nested pair $(I\supset J)$ are given by pairs of deformations of $I$ and $J$ preserving the inclusion. However, the inclusion is guaranteed if we consider deformations corresponding to positive tangent vectors.

\begin{theorem}\label{thm:1nonob-nested}
    Consider a nesting of 2-step homogeneous ideals $J\subset I \subset R$ of order $k_J$ and $k_I$ respectively such that $k_J-k_I>0$. Then,  there is an isomorphism  
\[
\mathsf{T}_{[I,J]}^{>0} \Hilb^\bullet \mathbb{A}^n \quad 
=\quad
\mathsf{T}_{[I,J]}^{=1} \Hilb^\bullet \mathbb{A}^n\quad \cong\quad
\Hom_{R}\big(I,R/I\big)_1 \oplus {\Hom}_{R}\big(J,R/J\big)_1.
\]
Moreover, all the tangent vectors of degree one are unobstructed. 
\end{theorem}

\begin{proof}
The case $k_J-k_I>1$ has been discussed at the beginning of the subsection. Thus, we put $k=k_I=k_J-1$. 

The first equality is a consequence of the identification of the positive tangent space $\mathsf{T}_{[I,J]}\Hilb^{(d_I,d_J)} \mathbb{A}^n$ with a linear subspace of the direct sum $\mathsf{T}_{[I]}^{>0}\Hilb^{d_I} \mathbb{A}^n\oplus \mathsf{T}_{[J]}^{>0} \Hilb^{ d_J } \mathbb{A}^n$ together with \Cref{thm:1nonob}. 

Given a basis $G=\{g_1,\ldots,g_{\oh_k^{(I)}}\}$ of $I_k$ and a basis $G' = \{g'_1,\ldots,g'_{\oh_{k+1}^{(J)}}\}$ of $J_{k+1}$, we associate to every tangent vector $\varphi \in \mathsf{T}_{[I,J]}^{=1} \Hilb^\bullet{\mathbb{A}^n}$ a pair of ideals in $R [\varepsilon]/\varepsilon^2$
\[
 (g_i+\varepsilon \widetilde{f}_i \ |\  i=1,\ldots,{\oh^{(I)}_{k}})+I_{\geqslant k+1},\qquad  (g'_i+\varepsilon \widetilde{f}'_i \ |\  i=1,\ldots,{\oh^{(J)}_{k+1}}) + J_{\geqslant k+2}
\]
where $\widetilde{f}_i \in R$ (resp.~$\widetilde{f}'_i \in R$) is a homogeneous lift of $f_i = \varphi(g_i)$ (resp.~$f'_i = \varphi(g'_i)$). By \Cref{thm:1nonob}, these two tangent vectors are unobstructed and lead to two flat families over $\mathbb{A}^1$ defined by the ideals in $R[t]$
\[
 I^+ = (g_i+t \widetilde{f}_i \ |\  i=1,\ldots,{\oh^{(I)}_{k}}) + I_{\geqslant k+1},\qquad J^+ = (g'_i+t \widetilde{f}'_i \ |\  i=1,\ldots,{\oh^{(J)}_{k+1}}) + J_{\geqslant k+2}.
\]

To prove that the tangent vector in $\varphi \in \mathsf{T}_{[I,J]}^{=1} \Hilb^\bullet{\mathbb{A}^n}$ is unobstructed, we show that the ideal $J^+$ is still contained in $I^+$, that is the nested pair $(I^+,J^+)$ describes a deformation of the nested point $(I,J)$. In fact,
 every $\tilde{f}'_j$ has degree $k+2$, so it is contained in $\mathfrak{m}^{k+2}  \subset I^+$. Moreover, by hypothesis $g'_j$ is contained in $I$ and it has degree $k+1$. Hence, $g_j' \in  I_{\geqslant k+1} \subset I^{+}$.
\end{proof}


    Although \Cref{thm:1nonob-nested} involves only nestings of two 2-step ideals, following the same logic one can show that the analogous statement holds for longer nestings so proving \Cref{thmintro:tgnested} from the introduction.

    \begin{corollary}\label{cor:1nonob-nested}
    Let  $[\underline I ]\in \Hilb^\bullet \BA^n$ be a nesting of 2-step homogeneous ideals. Denote by $k_i>0$ the order of the ideal $I^{(i)}$, for $i=1,\ldots,r$. Suppose that $k_{i+1}-k_i>0$, for all $i=1,\ldots,r-1$.  Then,  there is an isomorphism  
\[
\mathsf{T}_{[\underline I]}^{>0} \Hilb^\bullet \mathbb{A}^n =\mathsf{T}_{[\underline I]}^{=1} \Hilb^\bullet \mathbb{A}^n \cong \bigoplus_{i=1}^r \Hom_{R}\big(I^{(i)},R/I^{(i)}\big)_1.
\]
Moreover, all the tangent vectors of degree one are unobstructed. In particular, the initial ideal morphism is an affine bundle with fibres of dimension $\dim \mathsf{T}_{[\underline I]}^{>0} \Hilb^\bullet \mathbb{A}^n$.
    \end{corollary}


In the rest of the paper, we provide parametrisations of some irreducible components of Hilbert strata $H_{\bh}^n$ whose closed points correspond to 2-step ideals. By \Cref{thm:1nonob} and \Cref{thm:1nonob-nested}, we only need to give a parametrisation of some components of the homogeneous locus $\OH_{\bh}^n$. Moreover, since we are mainly interested in finding a lower bound for the dimension of $H_{\bh}^n$, it is sufficient to parametrise open subsets of $\OH_{\bh}^n$.  For this reason, we look for families of 2-step ideals with \textit{natural first anti-diagonal of the Betti table}, that is, ideals having  at most one non-zero graded Betti number in the first anti-diagonal of the Betti table. This is indeed an open condition on a family of modules having constant Hilbert function, cf.~\cite[Corollary 1.31]{AproduNagel}. Precisely, we focus on the graded Betti numbers $\beta_{0,k+1}$ and $\beta_{1,k+1}$ which are related by the equality
\[
\beta_{0,k+1} - \beta_{1,k+1} =  \oh_{k+1} - n\oh_{k}.
\] 
\begin{notation}\label{explanation-syzygies}
    For the sake of readability from now on, we denote by $\sss_{\bh}$ the quantity
    \[
   \sss_{\bh}= \oh_{k+1} - n\oh_{k}.
    \]
\end{notation}
Hence, if we consider a 2-step Hilbert function $\bh$ of order $k>0$ such that $\sss_{\bh} \geqslant 0$, then we expect the generic ideal in $\mathscr{H}^n_{\bh}$ to admit a minimal generating set consisting of $\beta_{0,k}=\oh_{k}$ elements of degree $k$ having no linear syzygies ($\beta_{1,k+1} = 0$) and $\beta_{0,k+1} = \sss_{\bh}$ generators in degree $k+1$. 
On the other hand, if $\sss_{\bh}< 0$, then the generic homogeneous ideals in $\mathscr{H}^n_{\bh}$ are expected to have $\beta_{0,k}=\oh_{k}$ generators of degree $k$ with $\beta_{1,k+1} =-\sss_{\bh}$ linear syzygies and no generators in degree $k+1$ since $\beta_{0,k+1} = 0$. 


\subsection{The class of 2-step ideals without linear syzygies}\label{subsec:2-stepnosyz}
In this subsection, we study the loci in $\Hilb^{\bullet}\BA^n$ corresponding to 2-step ideals $I\subset R$ with $\sss_{\bh}\geqslant 0$, for some 2-step function $\bh\colon\BZ\to\BN$ having natural first anti-diagonal of the Betti table. In this setting, having at most one non-zero entry of the first anti-diagonal is equivalent to not having linear syzygies. We compute the dimension of these loci in the case they are not empty. We leave questions about the non-emptyness and the irreducibility of $\OH^n_{\bh}$ for further research. Let us consider  Hilbert functions 
\[
\bh = \left(1,n,\rrr_{2},\ldots,\rrr_{k-1},\uh_{k},\uh_{k+1}\right)
\]
such that $\sss_{\bh} \geqslant 0$.

\begin{theorem}\label{thm:homoloco}
Let $\bh = (1,n, \rrr_{2}, \ldots,\rrr_{k-1}, \uh_{k}, \uh_{k+1})$ be a 2-step Hilbert function of order $k>0$ such that $\sss_{\bh} \geqslant 0$.
Assume that there exists an ideal $[I]\in \mathscr{H}_{\bh}^n$ with $\beta_{1,k+1}(I)=0$. 
Then, there is a surjective morphism 
\[
\begin{tikzcd}[row sep=tiny]
 \OH_{\bh}^n\arrow[r,"\varphi"]&\Gr \left(\oh_{k},R_k\right)\\
 {[I]}\arrow[r,mapsto] &{[I_k]},
\end{tikzcd}
\]
whose generic fibre is isomorphic to $\Gr \left(\sss_{\bh},\rrr_{k+1}-n\oh_{k}\right)$.
\end{theorem}
\begin{proof}

    Consider the diagram
    \[
    \begin{tikzcd}
        \OZ_{\bh}^n\arrow[r,hook]\arrow[dr]&\OH_{\bh}^n\times \BA^n\arrow[d,"\pi"]\\&\OH_{\bh}^n.
    \end{tikzcd}
    \]
    where $\OZ_{\bh}^n\subset \OH_{\bh}^n\times \BA^n$ is the universal family of multigraded Hilbert scheme, see \cite{multigraded}.  We  now focus on the degree $k$ part of the push-forward of the universal sequence,
    \[
    \begin{tikzcd}
        0\arrow[r]&(\pi_*\OI_{\OZ_{\bh}^n})_k \arrow[r]& \OO_{\mathscr{H}_{\bh}^n}\otimes R_k\arrow[r]&(\pi_*\OO_{\OZ_{\bh}^n})_k\arrow[r] &0.
    \end{tikzcd}
    \]
This defines a family of  $\uh_{k}$-dimensional quotients of the free sheaf of rank $\rrr_{k}$. Thus, it provides a unique  morphism ${\varphi}\colon \OH_{\bh}^n\to \Gr(\oh_{k},R_{k} )$. 

Let $U\subset \mathscr{H}_{\bh}^n$ be the subset corresponding to ideals $I \subset R$ such that $\beta_{1,k+1}(I) =0$. It is open by the semicontinuity of the Betti numbers and it is not empty by the assumption. In order to show that the map $\varphi $ is surjective, it is enough to show that $\varphi(U)\subset \Gr(\oh_k,\rrr_k)$ is an open non-empty subset. Given a point $[V] \in \Gr(\oh_k,R_k)$, consider the homogeneous ideal $(V) \subset R$ generated by the vector subspace $V\subset R_k$. We have that $\dim_\BC (V)_{k+1} \leqslant \min\{\rrr_{k+1}, n (\dim_\BC (V)_{k} )\} = n\oh_k$. Let $U' \subset \Gr(\oh_k,R_k)$ be the open subset corresponding to points $[V]$  such that $\dim_\BC (V)_{k+1} = n \oh_k$. It is not empty, since $\varphi(U) \subset U'$. Now, given $[V] \in U'$, we have $\dim_\BC (V)_{k+1} = n \oh_k \leqslant \oh_{k+1}$, i.e.~$\dim_{\BC} (R/(V))_{k+1} =\rrr_{k+1}-n\oh_k$. Therefore, the fibre over each $[V]\in U'$ is 
\[
\Gr( \sss_\bh, (R/(V))_{k+1})\cong \Gr(\sss_\bh,\rrr_{k+1}-n\oh_k).\qedhere
\]
\end{proof} 

\begin{remark}\label{rem:disticomp}
Under the assumptions of \Cref{thm:homoloco}, there is an irreducible component $\mathscr{V}_{\bh}^n\subset\OH_{\bh}^n$  birational to a product of Grassmanians such that
\[
\dim \mathscr{V}_{{\bh}}^n=\oh_{k}\left({\mathsf{r}_{k}}-\oh_{k}\right) + \sss_{\bh}\big(\rrr_{k+1}-n\oh_{k} - (\oh_{k+1}-n\oh_{k})\big) = \oh_{k} \uh_{k} + \sss_{\bh}\uh_{k+1}.
\]  
This number agrees with the expected dimension of the tangent space of degree 0 to the Hilbert scheme $\Hilb^\bullet \mathbb{A}^n$, see \Cref{lem: tangent space}. Notice that the Theorem \ref{thm:homoloco} does not exclude the possible existence of  \textit{"exceeding vertical components"} of $\OH_{\bh}^n$, i.e.~components not dominating on the Grassmannian $\Gr \left(\oh_{k},R_k\right)$ via $\varphi$.
\end{remark}

\begin{corollary}\label{cor:full no syz}
Fix a 2-step Hilbert function $\bh$ of order $k$ such that $\sss_{\bh} \geqslant 0$. 
Assume there exists an ideal $[I]\in \mathscr{H}_{\bh}^n$ with $\beta_{1,k+1}(I)=0$. Then, there is a surjective morphism
\[
\begin{tikzcd}
    {H}_{\bh}^n\arrow[r]&\Gr \left(\oh_{k},R_k\right) 
\end{tikzcd}
\]
whose generic fibre is an  $\mathbb{A}^{\oh_{k} \uh_{k+1}}$-bundle over $\Gr \left(\sss_{\bh},\rrr_{k+1}-n\oh_{k}\right)$. 
\end{corollary}
\begin{proof}
    Combine \Cref{rem:1nonobstruct} and \Cref{thm:1nonob}.
\end{proof}
\subsection{The class of 2-step ideals with few linear syzygies}\label{subsec:2-stepfew}

Now, we focus on Hilbert functions 
\[
\bh = \left(1,n,\rrr_{2},\ldots,\rrr_{k-1},\uh_{k},\uh_{k+1}\right)
\]
such that $\sss_{\bh} < 0$. Suppose to have a homogeneous ideal $I\subset R$ with natural first anti-diagonal of the Betti table, i.e.~such that the ideal $I$ is generated in degree $k$ and possibly $k+2$. Fix a pair  $(\varphi,\boldsymbol{p})$,  where $\boldsymbol{p} = \{p_1,\ldots,p_{\oh_{k}}\}$ is a basis of $I_k$ and $\varphi : R(-k-1)^{\oplus-\sss_{\bh}} \to R(-k)^{\oplus\oh_{k}}$ is the syzygy matrix describing the linear syzygies among the generators $p_1, p_2,\ldots, p_{\oh_{k}}$. Let us interpret the map $\varphi$ as a $\BC$-linear homomorphism, and let us consider the restriction
\[
\begin{tikzcd}[column sep = 2cm]
R_k^{\oplus\oh_{k}}\arrow[r,"\varphi^T|_{R_k^{\oplus\oh_{k}}}"]&R_{k+1}^{\oplus-\sss_{\bh}}.
\end{tikzcd}
\]
We abuse of notation and we  denote it with the same symbol $\varphi^T=\varphi^T|_{R_k^{\oplus\oh_{k}}}\in \Hom_{\BC}(R^{\oplus\oh_{k}}_k,R^{\oplus-\sss_{\bh}}_{k+1})$. Note that  the element $\boldsymbol{p} \in R_k^{\oplus\oh_{k}}$ is contained in the kernel of $\varphi^T $ by construction. We want to emulate this argument in order to achieve a lower bound for the dimension of the locus parametrising 2-step ideals whose Hilbert function satisfies $\sss_{\bh}<0$. Recall that there is a natural inclusion $\Hom_R(R(k)^{\oplus\oh_{k}},R (k+1)^{\oplus-\sss_{\bh}})_0\subset \Hom_{\BC}(R^{\oplus\oh_{k}}_k,R^{\oplus-\sss_{\bh}}_{k+1})$ given by forgetting $R$-linearity. Then, we denote by $\mathscr{L}_{\bh} \subseteq \Hom_R(R(k)^{\oplus\oh_{k}},R (k+1)^{\oplus-\sss_{\bh}})_0$ the open subset corresponding to $\BC$-linear homomorphisms with maximal rank.  
Since we want the generic  element $\varphi \in \mathscr{L}_{\bh}$ to have non-trivial kernel, we assume
\begin{equation}\label{eq:fls}
    \oh_{k} > -\sss_{\bh} = n\oh_{k} - \oh_{k+1}\qquad\Leftrightarrow\qquad \oh_{k+1} > (n-1)\oh_{k},
\end{equation}
and we refer to 2-step ideals satisfying \eqref{eq:fls} as 2-step homogeneous ideals with \emph{few linear syzygies}. Note that, under the assumption $\oh_{k} > -\sss_{\bh}$ we have
\[
\dim R_k^{\oplus \oh_k}-\dim R_{k+1}^{\oplus-\sss_{\bh}} = ( \oh_k + \sss_{\bh})\binom{k+n-1}{n-1} - \sss_{\bh}\binom{k+n-1}{n-2}>0.
\] 
This framework is clearly more suitable for our purpose.

