\end{lemma}
\begin{proof}
    Straightforward, by applying row and column operations to the matrix representing $\varphi$ with respect to the canonical basis of the free $R$-module $R^{\oplus\oh_k}$.
\end{proof}

    Let $\bh$ be a 2-step Hilbert function such that $0<-\sss_{\bh}<\oh_k$.   Consider then the incidence correspondence 
\[
\mathscr{K}_{\bh} = \Set{ (\varphi,\boldsymbol{p}) \in \mathscr{L}_{\bh} \times R_k^{\oplus\oh_{k}} | \boldsymbol{p} \in \ker \varphi } \subset \mathscr{L}_{\bh} \times R_k^{\oplus\oh_{k}}.
\]     
Note that  $\mathscr{K}_\bh$ is  integral. Indeed, irreducibility follows from the irreducibility of $\mathscr{L}_{\bh}$ and from the fact that the fibres of the restriction to $\mathscr{K}_{\bh}$ of the projection onto $\mathscr{L}_\bh$ are vector spaces of the same dimension by definition of $\mathscr{L}_{\bh}$. Reducedness is a consequence of the fact that $\mathscr{K}_{\bh}$ is cut out, in $\mathscr{L}_{\bh} \times R_k^{\oplus\oh_{k}}$, by  equations linear  in the coordinates of $R_k^{\oplus\oh_{k}}$.


\begin{theorem}\label{thm: homo loco syz} 
Let $\bh$ be a 2-step Hilbert function such that $0 < -\sss_{\bh} < \oh_{k}$. Assume that the generic morphism $\varphi\in\mathscr{L}_\bh$ is not injective. Then, there exists  a  rational map $\psi_{\bh}:\mathscr{K}_{\bh}\dashrightarrow \mathscr{H}_{\bh}^n$ which, on closed points, associates the generic pair $(\varphi,\boldsymbol{p})$ to the ideal   $I_{\boldsymbol{p}} = \left(\boldsymbol{p}\right) + \Fm^{k+2}$.
\end{theorem}
\begin{proof}
    In a non-empty open subset $U \subset \mathscr{K}_{\bh}$, the polynomials $\boldsymbol{p}=(p_1,\ldots,p_{\oh_{k}})$ are linearly independent and satisfy $-\sss_{\bh}$ independent linear syzygies. Thus
    \[
    \dim_\BC \left(I_{\boldsymbol{p}}\right)_k = \oh_{k} \quad \text{and}\quad \dim_\BC \left(I_{\boldsymbol{p}}\right)_{k+1} = n\oh_{k} -(- \sss_{\bh}) = \oh_{k+1}. 
    \]
     Thus, this is a flat (recall that $\mathscr{K}_{\bh}$ is reduced) family of 2-step ideals with base $U$, so providing the rational map $\psi_{\bh}$.  
\end{proof} 



\begin{remark}\label{rem:veryfwok} We remark that the condition \textit{(\ref{it:1i})} in \Cref{lem:pseudo canonical form} ensures that the generic morphism $\varphi\in\mathscr{L}_\bh$ is surjective  and non-injective. In this case, we can compute the dimension of $\mathscr{K}_\bh$. We have 
\[
\dim \mathscr{K}_{\bh}\ =\ \dim_\BC \mathscr{L}_{\bh} + \dim_{\BC}\ker \varphi\ =\ n(-\sss_{\bh})\oh_{k}  + \dim_{\BC}\ker \varphi,
\]
where $\varphi$ is a generic morphism in $\mathscr{L}_{\bh}$. From the short exact sequence
\[
\begin{tikzcd}
    0 \arrow[r]& \ker \varphi\arrow[r]& R_k^{\oplus\oh_{k}} \arrow[r,"\varphi"]& R_{k+1}^{\oplus-\sss_{\bh}} \arrow[r]& 0
\end{tikzcd}
\]
one has
\[
\dim_{\BC} (\ker \varphi) = \oh_{k}\rrr_{k} + \sss_{\bh}\rrr_{k+1} ,
\]
and hence
\begin{equation}
    \label{eq:dimK}\dim\mathscr{K}_{\bh}=  n(-\sss_{\bh})\oh_{k} +\oh_{k}\rrr_{k} + \sss_{\bh}\rrr_{k+1}. 
\end{equation}

We refer to homogeneous 2-step ideals satisfying \textit{(\ref{it:1i})} as ideals with \emph{very few linear syzygies}. The name is motivated by the fact that
\[
0 < -\sss_{\bh} \leqslant \frac{1}{n}\oh_{k}\quad\Leftrightarrow\quad n\oh_k>\oh_{k+1} \geqslant \dfrac{n^2-1}{n}\oh_{k} .
\] 
Moreover, we underline that in this setting a minimal set of generators of a generic ideal in $\psi_\bh(\mathscr{K}_{\bh})\subset\mathscr{H}_{\bh}^n$ can be obtained as the union of a subset of cardinality $-\sss_{\bh}$ of the kernel of the following morphism 
    \[
        R_k^{\oplus n} \xrightarrow{\ [ x_1\ \cdots\ x_n ]\ } R_{k+1}
    \]
    with $\oh_{k} - n(-\sss_{\bh})$ further independent polynomials of degree $k$.
\end{remark} 

Now, we want to bound from below the dimension of the homogeneous locus $\mathscr{H}^n_{\bh}$ of the Hilbert stratum by   comparing $\dim\mathscr{K}_{\bh}$ and the dimension of the fibre $\psi_{\bh}^{-1}([I])$ at a generic point  $[I]\in \psi_\bh(\mathscr{K}_\bh)$. We do this in the case of very few linear syzygies, where we are able to compute the dimension of the generic fibre of $\psi_{\bh}$ as explained in \Cref{rem:veryfwok}.

\begin{corollary}\label{cor:veryfew}
    Let $\bh$ be a 2-step Hilbert function with very few linear syzygies. Then, the following inequality holds
    \[
    \dim \mathscr{H}^n_{\bh} \geqslant \oh_{k}(\rrr_{k}-\oh_{k}) + \sss_{\bh}( \rrr_{k+1} - \oh_{k+1}).
    \]
\end{corollary}
\begin{proof}    
We start by computing the dimension of the generic fibre of $\psi_{\bh}$. Given $[I]\in\psi_\bh(\mathscr{K}_\bh)\subset \mathscr{H}^n_{\bh}$,  we can act with the linear group $\GL(\oh_{k})$ to change the basis of $I_k$. Explicitly, for every $M \in \GL(\oh_{k})$, the pair $(\varphi,\boldsymbol{p})$ is in the fibre over  $[I]$ if and only if $(\varphi M^{-1},M\boldsymbol{p})$ is. In fact
\[
0 = \varphi\boldsymbol{p} = (\varphi M^{-1}) (M\boldsymbol{p}) \quad \Rightarrow \quad M\boldsymbol{p} \in \ker (\varphi M^{-1}).
\]
In this way, the general linear group acts on $\mathscr{L}_{\bh}$ via column operations of the matrix representing $\varphi$. Nevertheless, we can also act on $\mathscr{L}_{\bh}$ via row operations. Summarising, a pair $(\varphi,\boldsymbol{p})$ belongs to the fibre $\psi_{\bh}^{-1}([I])$  over $[I]$ if and only if, for every pair $(M_1,M_2) \in  \GL(-\sss_{\bh})\times \GL(\oh_{k})$, we also have $(M_1 \varphi M_2^{-1},M_2 \boldsymbol{p})\in\psi_{\bh}^{-1}([I])$, because
\[
0 = \varphi \boldsymbol{p} = M_1 \varphi \boldsymbol{p} = (M_1\varphi M_2^{-1}) (M_2 \boldsymbol{p}).
\]
By the normal form in \Cref{lem:pseudo canonical form}\emph{(\ref{eq: normal form syzygy})} the action of $\GL(-\sss_{\bh})\times \GL(\oh_{k})$ is faithful on some open, hence this gives, for a generic fibre $F\subset \mathscr{K}_{\bh}$ of $\psi_{\bh}$, the equality 
\[
\dim F = \dim  \GL(-\sss_{\bh})+\dim \GL(\oh_{k})=\sss_{\bh}^2  +  \oh_{k}^2,
\]
and we deduce from \eqref{eq:dimK} that 
\begin{equation}
\begin{split}
    \dim \mathscr{H}^n_{\bh} &{} \geqslant   \dim \psi_{\bh}(\mathscr{K}_{\bh})= \dim \mathscr{K}_{\bh} - \dim F = {}\\
    &{}=  n(-\sss_{\bh})\oh_{k} +\oh_{k}\rrr_{k} + \sss_{\bh}\rrr_{k+1} - (\sss_{\bh}^2 +  \oh_{k}^2) ={}\\ 
    &{}= \oh_{k}(\rrr_{k}-\oh_{k}) + \sss_{\bh}( \rrr_{k+1} - \oh_{k+1}). \qedhere
\end{split}    
\end{equation}
\end{proof}

\begin{remark} 
We conclude this subsection by noticing that the bound in \Cref{cor:veryfew} agrees with the lower bound for the dimension of the degree 0 part of the tangent space given in \Cref{lem: tangent space}. This in turn, provides the expected dimension of the homogeneous locus of the Hilbert stratum, see \cite{multigraded}. 

In the case of few linear syzygies, one can still look for a lower bound to the dimension of the corresponding Hilbert stratum. If the generic morphism $\varphi\in\mathscr{L}_{\bh}$ is not surjective, then the dimension of  $\ker\varphi$ cannot be deduced theoretically and it must be computed explicitly. We do this in \Cref{sec:red3fold} to find examples in dimension 3.  
\end{remark}

\subsection{Estimate of the number of \texorpdfstring{$(-1)$}{}-tangent vectors}\label{subsec:TNT2step}
From the proof of \Cref{lem: tangent space} we get, for a homogeneous 2-step ideal $I \subset R$, the inequality
\begin{equation}\label{eq:stima-1}
    \dim_{\BC} \mathsf{T}^{=-1}_{[I]}\Hilb^\bullet \mathbb{A}^n \geqslant \max\left\{0, \beta_{0,k}\rrr_{k-1} + (\beta_{0,k+1}-\beta_{1,k+1})(\rrr_{k}-\oh_{k}) + (\beta_{0,k+2}-\beta_{1,k+2})(\rrr_{k+1}-\oh_{k+1}) \right\},
\end{equation}
where
\[
\beta_{0,k} = \oh_{k}\quad\text{and}\quad \beta_{0,k+1}-\beta_{1,k+1} = \sss_{\bh}.
\]
The third summand involves the difference $\beta_{0,k+2}-\beta_{1,k+2}$ that is only a part of the coefficient in degree $k+2$ of the Hilbert series of the ideal $I$ deduced from the resolution \eqref{eq: resolution I}, see \Cref{lem: general properties Betti}. Let us put
\[
\ttt_{\bh} = \rrr_{k+2} - n \oh_{k+1} + \tbinom{n}{2} \oh_{k}.
\]
Then, we have $\beta_{0,k+2}-\beta_{1,k+2} = \ttt_{\bh} - \beta_{2,k+2}$ and we can rewrite the lower bound in \eqref{eq:stima-1} as
\[
\dim_{\BC} \mathsf{T}^{=-1}_{[I]}\Hilb^\bullet \mathbb{A}^n \geqslant \max\left\{0, \rrr_{k-1}\oh_{k} + \sss_{\bh}(\rrr_{k}-\oh_{k}) + (\ttt_{\bh}-\beta_{2,k+2})(\rrr_{k+1}-\oh_{k+1}) \right\}.
\]

We make the following observations: 
\begin{enumerate}[1.]
    \item for a given pair $(\oh_k,\oh_{k+1})$, the greater the number $\beta_{2,k+2}$ of second-order linear syzygies is, the lower the bound of the dimension of the space of $-1$-tangent vectors is; 
    \item the cases $\oh_{k+1} \geqslant \frac{n^2-1}{2}\oh_{k}$, which are covered by \Cref{thm:homoloco} and \Cref{thm: homo loco syz} (no or very few linear syzygies). In this setting the graded Betti number $\beta_{2,k+2}$ is zero for a generic ideal. In fact, in the no linear syzygies case, the vanishing $\beta_{1,k+1}=0$ implies $\beta_{2,k+2} = 0$. On the other hand, having very few linear syzygies provides injectivity of the morphism differential $ R(-k-1)^{\oplus\beta_{1,k+1}} \to R(-k)^{\oplus\beta_{0,k}}$ in \eqref{eq: resolution I}.
\end{enumerate}
