\begin{remark} 
The generically reduced elementary component of $\hilbert{35}{\mathbb{A}^4}$ detected by Jelisiejew in \cite{ELEMENTARY} corresponds to the 2-step Hilbert function $\bh=(1,4,10,12,8)$. The pair $(\oh_3,\oh_4) = (8,27)$ lies in the few syzygies area, since $\frac{1}{4}\oh_3 < - \sss_\bh = 5 <  \oh_3$, but the generic homomorphism in $\mathscr{L}_{\bh}$ is injective and \Cref{thm: homo loco syz} does not apply. In fact, the resolution of the generic homogeneous element in the component does not have a natural first anti-diagonal as shown below.
\[ \begin{array}{c|cccc}
       & 0 & 1 & 2 & 3\\
       \hline
      3 & 8 & 6 & \centerdot & \centerdot\\[-4pt]
      4 & 1 & 4 & 2 & \centerdot\\[-4pt]
      5 & \centerdot & 12 & 20 & 8\end{array}
 \]

The generically reduced elementary component of $\hilbert{15}{\mathbb{A}^4}$ detected by Satriano and Staal in \cite{Satrianostaal} corresponds to the 2-step Hilbert function $\bh=(1,4,6,4)$. The pair $(\oh_2,\oh_3) = (4,16)$ lies in the no syzygies area, since $ \sss_\bh = 0$. Applying, \Cref{thm:homoloco}, we describe homogeneous 2-step ideals with Betti table
        \[
      \begin{array}{c|cccc}
       & 0 & 1 & 2 & 3\\
       \hline
      2 & 4 & \centerdot & \centerdot & \centerdot\\[-4pt]
      3 & \centerdot & 6 & \centerdot & \centerdot \\[-4pt]
      4 & 1 & 4 & 10 & 4\end{array}
        \]
while the generic homogeneous element in the correspondent elementary component has the following Betti table. 
        \[
      \begin{array}{c|cccc}
       & 0 & 1 & 2 & 3\\
       \hline
      2 & 4 & 4 & 1 & \centerdot \\[-4pt]
      3 & 4 & 6 & 2 & \centerdot \\[-4pt]
      4 & \centerdot  & 6 & 10 & 4\end{array}
        \]
We notice that the homogeneous locus $\mathscr{H}^4_{\bh}$ has at least 2 irreducible components. In fact, by the semicontinuity of the Betti numbers, we cannot obtain a 2-step homogeneous ideal with the first Betti table as (homogeneous) specialization of 2-step homogeneous ideals lying on the elementary component with the second Betti table (and viceversa). Moreover, this implies, together with the existence of the initial ideal morphism $\pi_{\bh}:H^4_{\bh}\to\OH_{\bh}^4$, that the Hilbert stratum $H_{\bh}^4$ is not irreducible.
\end{remark}


\subsection{Nested Hilbert schemes of points on four-folds}\label{subsec:dim4nest}

 In this subsection we prove \Cref{thm:intro B} which shows that, paying the price of considering nestings, the $(3,7)$-nested Hilbert scheme on $\BA^4$ has an elementary component. From this, we also deduce that the $(1,3,7)$-nested Hilbert scheme on $\BA^4$ has a generically non-reduced elementary component.  


 \begin{theorem}\label{thm:redim4nest} 
        The nested Hilbert scheme $\hilbert{(3,7)}{\BA^4}$ has a generically reduced elementary  component $V$ whose closed points correspond to nestings having Hilbert function vector $((1,2),(1,4,2))$. Moreover, we have an isomorphism
    \[
    \begin{tikzcd}
        (V)_{\red}\cong   \Gr(2,4) \times \Gr(2,10)\times \BA^4\cong   H_{(1,2)}^4 \times H_{(1,4,2)}^4 \times \BA^4.
    \end{tikzcd}
    \]
     As a consequence, the nested Hilbert scheme $\hilbert{(1,3,7)}{\BA^4}$ has a generically non-reduced elementary component $V_1$ such that $(V_1)_{\red}=(V)_{\red}$.
\end{theorem}


\begin{proof}
The last part of the statement is a consequence of \cite[Theorem 5]{UPDATES}. Moreover, the second isomorphism is a consequence of the well known description of the Hilbert stratum associated to very compressed algebras. We focus on the first isomorphism. We start by the observation that 
\[
H_{(\bh^{(1)},\bh^{(2)})}^4\cong H_{\bh^{(1)}}^4 \times H_{\bh^{(2)}}^4,
\]
where  $\bh^{(1)}=(1,2), \mbox{ and }\bh^{(2)}=(1,4,2)$. This is true because $H_{(\bh^{(1)},\bh^{(2)})}^4$ is the closed subset of the product $ H_{\bh^{(1)}}^4 \times H_{\bh^{(2)}}^4$ cut out by the nested conditions, but in this setting the nesting is guaranteed by construction and no condition arises.

 In order to conclude the proof we exhibit a nesting $\underline{I}$ in $H^4_{(\bh^{(1)},\bh^{(2)})}$ having TNT.  
The nesting we consider is $\underline{I}=(I^{(1)}\supset I^{(2)})$, where
\[
I^{(2)}=\left(zw,xw,z^2-w^2,yz,xz+yw \right) +\left( x,y\right )^2,\qquad 
\text{~and~}\qquad
I^{(1)}=I^{(2)}+(z,w)
\]
in the polynomial ring $\BC[x,y,z,w]$. 
\end{proof}


\section{Further new  elementary components}\label{sec:small} 

We list now all the generically reduced elementary components of $\Hilb^\bullet \BA^n$, for $n=5,6$, corresponding to 2-step ideals with no or very few linear syzygies of order $k=2$ plus some other sporadic example. Then, in the final part we prove \Cref{thm: intro tantecomp}.


\paragraph{\it Known results.}  
Among the elementary components described in the literature for $n \geqslant 5$, most of them correspond to families of 2-step ideals.
\begin{itemize}
\item The elementary components arising from families of 1-step ideals with Hilbert function $\bh=(1,n,s)$ are treated in \cite{Sha90} where it is stated that for
\[
3 \leqslant s \leqslant \dfrac{(n-1)(n-2)}{6} + 2
\]
the Hilbert stratum $H_{\bh}^n$ gives a generically reduced elementary component.
\item Three generically reduced elementary components in $\Hilb^\bullet{\mathbb{A}^5}$ are Hilbert strata of 2-step ideals of order 2 with Hilbert function $\bh=(1,5,3,4)$ (see \cite{SomeElementary}), $\bh=(1,5,9,7)$ (see \cite{MoreElementary}) and $\bh=(1,5,6,1)$ (see \cite{KleimanKleppe2025}).
\item Four generically reduced elementary components in $\Hilb^\bullet{\mathbb{A}^5}$ are Hilbert strata of 2-step ideals of order 3 with Hilbert function $\bh=(1,5,15,7,9)$, $\bh=(1,5,15,9,12)$, $\bh=(1,5,15,10,12)$ and $\bh=(1,5,15,10,15)$  (see \cite{MoreElementary}).
\item Six generically reduced elementary components in $\Hilb^\bullet{\mathbb{A}^6}$ are Hilbert strata of 2-step ideals of order 2 are obtained via apolarity studying the socle type of the associated algebra (see \Cref{def:compressed}).
There is the inspiring example with Hilbert function $\bh=(1,6,6,1)$ by Iarrobino \cite{Iarrob} generalized in \cite{KleimanKleppe2025} to Hilbert functions $\bh=(1,6,12,2)$ and $\bh=(1,6,6+s,1)$ with $s=2,3,4,5$. Notice that for $s=1$ the 2-step ideals of the Hilbert stratum are smoothable.
\item There are three other generically reduced elementary components in $\Hilb^\bullet{\mathbb{A}^6}$ with Hilbert functions $\bh=(1,6,6,10)$ (see \cite{SomeElementary}), $\bh=(1,6,5,7)$ (see \cite{MoreElementary}) and $\bh=(1,6,12,7)$ (see \cite{UPDATES}).
\item There is one generically reduced elementary components in $\Hilb^\bullet{\mathbb{A}^6}$ with 2-step Hilbert function $\bh=(1,6,21,10,15)$ of order 3 \cite{SomeElementary}.
\item In $\Hilb^\bullet{\mathbb{A}^n}$ with $n \geqslant 7$, there are generically reduced elementary components arising from Hilbert strata with Hilbert function $\bh=(1,7,7,1)$ (see \cite{BertoneCioffiRoggero}), $\bh=(1,7,10,16)$ (see \cite{MoreElementary}), $\bh=(1,7,7+s,1),\ s=1,\ldots,8$, $\bh=(1,8,8+s,1),\ s=1,\ldots,10$ and $\bh=(1,n,2n,2),(1,n,2n+1,2)$ with $n=7,8$ (see \cite{KleimanKleppe2025}).
\end{itemize}


