\section{Figure legend}\label{legenda} 

In Figures \ref{fig:newA3k6}, \ref{fig:newA3k7-8}, \ref{fig:newA4k2}, \ref{fig:newA4k3},\ref{fig:newA5}, \ref{fig:newA6-1}, \ref{fig:newA6-2} and \ref{fig:newA6-3} we draw the subset in $\mathbb{R}^2$ containing the pairs $(\oh_k,\oh_{k+1})$ defining 2-step Hilbert functions of order $k$ with the usual convention (increasing values of $\oh_k$ moving to the right and increasing values of $\oh_{k+1}$ moving upwards).

 The grey areas correspond to 2-step Hilbert functions considered in \Cref{thm:homoloco} and \Cref{thm: homo loco syz}:
 \begin{itemize}
     \item[\raisebox{-3pt}{\tikz{\draw [black!10,fill=black!10] (0,0) rectangle (0.45,0.45);}}] 2-step Hilbert functions with \emph{no} linear syzygies 
     \[\sss_\bh \geqslant 0\quad \Leftrightarrow\quad \oh_{k+1} \geqslant n\oh_k;\]
     \item[\raisebox{-3pt}{\tikz{\draw [black!50,fill=black!50] (0,0) rectangle (0.45,0.45);}}] 2-step Hilbert functions with \emph{very few} linear syzygies 
     \[0 < -\sss_\bh \leqslant \tfrac{1}{n}\oh_k\quad \Leftrightarrow\quad \left(n-\tfrac{1}{n}\right)\oh_k \leqslant \oh_{k+1} < n\oh_k;\]
     \item[\raisebox{-3pt}{\tikz{\draw [black!30,fill=black!30] (0,0) rectangle (0.45,0.45);}}] 2-step Hilbert functions with \emph{few} linear syzygies 
     \[ \tfrac{1}{n}\oh_k < -\sss_\bh < \oh_k\quad \Leftrightarrow\quad (n-1)\oh_k < \oh_{k+1} < \left(n-\tfrac{1}{n}\right)\oh_k.\]
 \end{itemize}

The coloured areas describe the sign of functions $\Delta_{n,1,k}$ and $\Theta_{n,k,0}$:
\begin{center}
    \raisebox{-4pt}{\tikz{\fill [pattern={Lines[angle=45,distance=2pt,line width=0.075pt]},opacity=0.3,pattern color=blue] (0,0) rectangle (0.45,0.45);\draw[NavyBlue,opacity=0.5,thick] (0,0) rectangle (0.45,0.45);}}\quad $\Delta_{n,1,k} \geqslant 0$\qquad\qquad
     \raisebox{-4pt}{\tikz{\fill [pattern={Lines[angle=45,distance=2pt,line width=0.075pt]},opacity=0.3,pattern color=red] (0,0) rectangle (0.45,0.45);}}\quad $\Delta_{n,1,k} < 0$\qquad\qquad
     \raisebox{-4pt}{\tikz{\fill [fill=yellow,opacity=0.4] (0,0) rectangle (0.45,0.45);}}\quad $\Theta_{n,k,0} \leqslant 0$.
 \end{center}
Notice that the function $\Delta_{n,1,k}$ has been defined on the smaller subset $\mathcal{D}\subset \mathbb{R}^2$ but we show its sign on the whole drawn domain. In fact, by direct computation, we find lots of natural points $(\oh_k,\oh_{k+1})$ outside $\mathcal{D}_\BN$ where the dimension of the Hilbert stratum $H_{\bh}^n$ agrees with the expected dimension in $\Delta_{n,1,k}$. The yellow area (if not empty) contains natural points that certainly belong to the potential TNT area $\mathscr{T}^n_k$. There might also be other natural points in the potential TNT area, but we do not display them as they require $\beta_{2,k+2} > 0$ and are not covered by our main results.

The meaning of the symbols denoting natural points is the following.
\begin{itemize}
    \item[\raisebox{-1pt}{\tikz{\node at (0,0)[draw=NavyBlue,very thick,fill=NavyBlue,diamond,inner sep=2pt] {};}}] The navy blue diamond denotes a pair $(\oh_k,\oh_{k+1})$ corresponding to a Hilbert stratum $H_\bh^n$ with $\Delta_{n,1,k}\geqslant 0$, thus certifying the reducibility of $\hilbert{\vert\bh\vert}{\mathbb{A}^n}$. However, the generic element in $\mathscr{H}_\bh^n$ has not trivial negative tangents so $H_\bh^n$ might not describe a full irreducible component of $\hilbert{\vert\bh\vert}{\mathbb{A}^n}$.
    \item[\raisebox{-1pt}{\tikz{\node at (0,0) [draw=blue,very thick,fill=blue,star,star point ratio=2.2,inner sep=1.2pt] {};}}] The blue star denotes a pair $(\oh_k,\oh_{k+1})$ corresponding to a Hilbert stratum $H_\bh^n$ with $\Delta_{n,1,k}\geqslant 0$ such that the generic element in $\mathscr{H}_\bh^n$ has trivial negative tangents, thus identifying a generically reduced elementary component of $\hilbert{\vert\bh\vert}{\mathbb{A}^n}$.
    \item[\raisebox{-1pt}{\tikz{\node at (0,0) [draw=red,very thick,fill=red,star,star point ratio=2.2,inner sep=1.2pt] {};}}] The red star denotes a pair $(\oh_k,\oh_{k+1})$ corresponding to a Hilbert stratum $H_\bh^n$ with $\Delta_{n,1,k}< 0$  such that the generic element in $\mathscr{H}_\bh^n$ has trivial negative tangents, thus identifying a generically reduced elementary $\Delta$-negative component of $\hilbert{\vert\bh\vert}{\mathbb{A}^n}$.
    \item[\raisebox{-1pt}{\tikz{\node at (0,0)[draw=NavyBlue,very thick,fill=white,diamond,inner sep=2pt] {}; \node at (0.4,0) [draw=blue,line width=1,fill=white,star,star point ratio=2.2,inner sep=1.2pt] {}; \node at (0.8,0) [draw=red,line width=1,fill=white,star,star point ratio=2.2,inner sep=1.2pt] {};}}] Empty symbols denote pairs $(\oh_k,\oh_{k+1})$ corresponding to a Hilbert strata covered by the main results of the paper but already known in literature.
    \item[\raisebox{-1pt}{\tikz{\node at (0,0) [draw=red,very thick,fill=white,circle,inner sep=2pt] {}; \node at (0.35,0)[draw=blue,very thick,fill=white,circle,inner sep=2pt] {};}}] Empty circles denote pairs $(\oh_k,\oh_{k+1})$ corresponding to a Hilbert stratum $H_\bh^n$ identifying a generically reduced elementary component known in literature but not covered by the main results of the paper. The color has the same meaning as above.
%\item[\raisebox{-1pt}{\tikz{\node at (0,0) [draw=red,fill=red,very thick,regular polygon, regular polygon sides=5,inner sep=2pt] {}; }}] The red pentagon denoted the pair of the sporadic case discussed in \Cref{ex:final}.
\end{itemize}

